window.psalmsCsOld = {"1": {"number": 1, "cu_numeral": "а҃", "title": "Ѱало́мъ а҃ (1)", "subtitle": "Ѱало́мъ дв҃дꙋ, не надпи́санъ ᲂу҆ є҆врє́й, а҃.", "verses": [{"num": "а҃.", "text": "Бл҃же́нъ мꙋ́жъ, и҆́же не и҆́де на совѣ́тъ нечести́выхъ, и҆ на пꙋтѝ грѣ́шныхъ не ста̀, и҆ на сѣда́лищи гꙋби́телей не сѣ́де:"}, {"num": "в҃.", "text": "Но въ зако́нѣ гдⷭ҇ни во́лѧ є҆гѡ̀, и҆ въ зако́нѣ є҆гѡ̀ поꙋчи́тсѧ де́нь и҆ но́щь."}, {"num": "г҃.", "text": "И҆ бꙋ́детъ ꙗ҆́кѡ дре́во насажде́нное при и҆схо́дищихъ во́дъ, є҆́же пло́дъ сво́й да́стъ во вре́мѧ своѐ: и҆ ли́стъ є҆гѡ̀ не ѿпаде́тъ, и҆ всѧ̑, є҆ли̑ка а҆́ще твори́тъ, ᲂу҆спѣ́етъ."}, {"num": "д҃.", "text": "Не та́кѡ нечести́вїи, не та́кѡ: но ꙗ҆́кѡ пра́хъ, є҆го́же возмета́етъ вѣ́тръ ѿ лица̀ землѝ."}, {"num": "є҃.", "text": "Сегѡ̀ ра́ди не воскре́снꙋтъ нечести́вїи на сꙋ́дъ: нижѐ грѣ̑шницы на совѣ́тъ првⷣныхъ."}, {"num": "ѕ҃.", "text": "Ꙗ҆́кѡ вѣ́сть гдⷭ҇ь пꙋ́ть првⷣныхъ, и҆ пꙋ́ть нечести́выхъ поги́бнетъ."}]}, "2": {"number": 2, "cu_numeral": "в҃", "title": "Ѱало́мъ в҃ (2)", "subtitle": "Ѱало́мъ дв҃дꙋ, в҃.", "verses": [{"num": "а҃.", "text": "Вскꙋ́ю шата́шасѧ ꙗ҆зы́цы, и҆ лю́дїе поꙋчи́шасѧ тщє́тнымъ;"}, {"num": "в҃.", "text": "Предста́ша ца́рїе зе́мстїи, и҆ кнѧ̑зи собра́шасѧ вкꙋ́пѣ на гдⷭ҇а и҆ на хрⷭ҇та̀ є҆гѡ̀."}, {"num": "г҃.", "text": "Расто́ргнемъ ᲂу҆́зы и҆́хъ и҆ ѿве́ржемъ ѿ на́съ и҆́го и҆́хъ."}, {"num": "д҃.", "text": "Живы́й на нб҃сѣ́хъ посмѣе́тсѧ и҆̀мъ, и҆ гдⷭ҇ь порꙋга́етсѧ и҆̀мъ:"}, {"num": "є҃.", "text": "Тогда̀ возглаго́летъ къ ни̑мъ гнѣ́вомъ свои́мъ, и҆ ꙗ҆́ростїю свое́ю смѧте́тъ ѧ҆̀:"}, {"num": "ѕ҃.", "text": "А҆́зъ же поста́вленъ є҆́смь цр҃ь ѿ негѡ̀ над̾ сїѡ́номъ, горо́ю ст҃о́ю є҆гѡ̀,"}, {"num": "з҃.", "text": "Возвѣща́ѧй повелѣ́нїе гдⷭ҇не. гдⷭ҇ь речѐ ко мнѣ̀: сн҃ъ мо́й є҆сѝ ты̀, а҆́зъ дне́сь роди́хъ тѧ̀."}, {"num": "и҃.", "text": "Просѝ ѿ менѐ, и҆ да́мъ тѝ ꙗ҆зы́ки достоѧ́нїе твоѐ, и҆ ѡ҆держа́нїе твоѐ концы̀ землѝ."}, {"num": "ѳ҃.", "text": "Оу҆пасе́ши ѧ҆̀ жезло́мъ желѣ́знымъ, ꙗ҆́кѡ сосꙋ́ды скꙋдє́льничи сокрꙋши́ши ѧ҆̀."}, {"num": "і҃.", "text": "И҆ ны́нѣ, ца́рїе, разꙋмѣ́йте, накажи́тесѧ всѝ сꙋдѧ́щїи землѝ."}, {"num": "а҃і.", "text": "Рабо́тайте гдⷭ҇еви со стра́хомъ, и҆ ра́дꙋйтесѧ є҆мꙋ̀ съ тре́петомъ."}, {"num": "в҃і.", "text": "Прїими́те наказа́нїе, да не когда̀ прогнѣ́ваетсѧ гдⷭ҇ь, и҆ поги́бнете ѿ пꙋтѝ првⷣнагѡ, є҆гда̀ возгори́тсѧ вско́рѣ ꙗ҆́рость є҆гѡ̀: бл҃же́ни всѝ надѣ́ющїисѧ на́нь. а҃ Ѱало́мъ дв҃дꙋ, внегда̀ ѿбѣга́ше ѿ лица̀ а҆вессалѡ́ма сы́на своегѡ̀, г҃."}]}, "3": {"number": 3, "cu_numeral": "г҃", "title": "Ѱало́мъ г҃ (3)", "subtitle": "а҃ Ѱало́мъ дв҃дꙋ, внегда̀ ѿбѣга́ше ѿ лица̀ а҆вессалѡ́ма сы́на своегѡ̀, г҃.", "verses": [{"num": "а҃.", "text": "Гдⷭ҇и, что́ сѧ ᲂу҆мно́жиша стꙋжа́ющїи мѝ; мно́зи востаю́тъ на мѧ̀:"}, {"num": "в҃.", "text": "Мно́зи глаго́лютъ дꙋшѝ мое́й: нѣ́сть сп҃се́нїѧ є҆мꙋ̀ въ бз҃ѣ є҆гѡ̀:"}, {"num": "г҃.", "text": "Ты́ же гдⷭ҇и, застꙋ́пникъ мо́й є҆сѝ, сла́ва моѧ̀, и҆ возносѧ́й главꙋ̀ мою̀."}, {"num": "д҃.", "text": "Гла́сомъ мои́мъ ко гдⷭ҇ꙋ воззва́хъ, и҆ ᲂу҆слы́ша мѧ̀ ѿ горы̀ ст҃ы́ѧ своеѧ̀."}, {"num": "є҃.", "text": "А҆́зъ ᲂу҆снꙋ́хъ, и҆ спа́хъ, воста́хъ, ꙗ҆́кѡ гдⷭ҇ь застꙋ́питъ мѧ̀."}, {"num": "ѕ҃.", "text": "Не ᲂу҆бою́сѧ ѿ тє́мъ люде́й, ѻ҆́крестъ напа́дающихъ на мѧ̀."}, {"num": "з҃.", "text": "Воскрⷭ҇нѝ гдⷭ҇и, сп҃си́ мѧ бж҃е мо́й: ꙗ҆́кѡ ты̀ порази́лъ є҆сѝ всѧ̑ враждꙋ́ющыѧ мѝ всꙋ́е, зꙋ́бы грѣ́шникѡвъ сокрꙋши́лъ є҆сѝ."}, {"num": "и҃.", "text": "Гдⷭ҇не є҆́сть сп҃се́нїе, и҆ на лю́дехъ твои́хъ бл҃гослове́нїе твоѐ. Сла́ва: а҃ Въ коне́цъ, въ пѣ́снехъ, ѱало́мъ дв҃дꙋ, д҃."}]}, "4": {"number": 4, "cu_numeral": "д҃", "title": "Ѱало́мъ д҃ (4)", "subtitle": "а҃ Въ коне́цъ, въ пѣ́снехъ, ѱало́мъ дв҃дꙋ, д҃.", "verses": [{"num": "а҃.", "text": "Внегда̀ призва́ти мѝ, ᲂу҆слы́ша мѧ̀ бг҃ъ пра́вды моеѧ̀, въ ско́рби распространи́лъ мѧ̀ є҆сѝ: ᲂу҆ще́дри мѧ̀, и҆ ᲂу҆слы́ши моли́твꙋ мою̀."}, {"num": "в҃.", "text": "Сы́нове человѣ́честїи, доко́лѣ тѧжкосе́рдїи: вскꙋ́ю лю́бите сꙋетꙋ̀ и҆ и҆́щете лжѝ:"}, {"num": "г҃.", "text": "И҆ ᲂу҆вѣ́дите, ꙗ҆́кѡ ᲂу҆дивѝ гдⷭ҇ь прпⷣбнаго своего̀: гдⷭ҇ь ᲂу҆слы́шитъ мѧ̀, внегда̀ воззва́ти мѝ къ немꙋ̀."}, {"num": "д҃.", "text": "Гнѣ́вайтесѧ, и҆ не согрѣша́йте, ꙗ҆̀же глаго́лете въ сердца́хъ ва́шихъ, на ло́жахъ ва́шихъ ᲂу҆мили́тесѧ."}, {"num": "є҃.", "text": "Пожри́те же́ртвꙋ пра́вды, и҆ ᲂу҆пова́йте на гдⷭ҇а."}, {"num": "ѕ҃.", "text": "Мно́зи глаго́лютъ: кто̀ ꙗ҆ви́тъ на́мъ бл҃га̑ѧ; зна́менасѧ на на́съ свѣ́тъ лица̀ твоегѡ̀, гдⷭ҇и."}, {"num": "з҃.", "text": "Да́лъ є҆сѝ весе́лїе въ се́рдцѣ мое́мъ: ѿ плода̀ пшени́цы, вїна̀ и҆ є҆ле́а своегѡ̀ ᲂу҆мно́жишасѧ."}, {"num": "и҃.", "text": "Въ ми́рѣ вкꙋ́пѣ ᲂу҆снꙋ̀ и҆ почі́ю, ꙗ҆́кѡ ты̀ гдⷭ҇и є҆ди́наго на ᲂу҆пова́нїи всели́лъ мѧ̀ є҆сѝ. а҃ Ѡ҆ наслѣ́дствꙋющемъ, ѱало́мъ дв҃дꙋ, є҃."}]}, "5": {"number": 5, "cu_numeral": "є҃", "title": "Ѱало́мъ є҃ (5)", "subtitle": "а҃ Ѡ҆ наслѣ́дствꙋющемъ, ѱало́мъ дв҃дꙋ, є҃.", "verses": [{"num": "а҃.", "text": "Глаго́лы моѧ̑ внꙋшѝ гдⷭ҇и, разꙋмѣ́й зва́нїе моѐ."}, {"num": "в҃.", "text": "Вонмѝ гла́сꙋ моле́нїѧ моегѡ̀, цр҃ю̀ мо́й и҆ бж҃е мо́й: ꙗ҆́кѡ къ тебѣ̀ помолю́сѧ гдⷭ҇и."}, {"num": "г҃.", "text": "Заꙋ́тра ᲂу҆слы́ши гла́съ мо́й, заꙋ́тра предста́нꙋ тѝ, и҆ ᲂу҆́зриши мѧ̀."}, {"num": "д҃.", "text": "Ꙗ҆́кѡ бг҃ъ не хотѧ́й беззако́нїѧ, ты̀ є҆сѝ: не присели́тсѧ къ тебѣ̀ лꙋка́внꙋѧй,"}, {"num": "є҃.", "text": "Нижѐ пребꙋ́дꙋтъ беззакѡ́нницы пред̾ ѻ҆чи́ма твои́ма: возненави́дѣлъ є҆сѝ всѧ̑ дѣ́лающыѧ беззако́нїе,"}, {"num": "ѕ҃.", "text": "Погꙋби́ши всѧ̑ глаго́лющыѧ лжꙋ̀: мꙋ́жа крове́й и҆ льсти́ва гнꙋша́етсѧ гдⷭ҇ь."}, {"num": "з҃.", "text": "А҆́зъ же мно́жествомъ млⷭ҇ти твоеѧ̀, вни́дꙋ въ до́мъ тво́й, поклоню́сѧ ко хра́мꙋ ст҃о́мꙋ твоемꙋ̀, въ стра́сѣ твое́мъ."}, {"num": "и҃.", "text": "Гдⷭ҇и, наста́ви мѧ̀ ѳ҃ і҃ а҃і в҃і г҃і ́сѧ ко хра́мꙋ ст҃о́мꙋ твоемꙋ̀, въ стра́сѣ твое́мъ. Гдⷭ҇и, наста́ви мѧ̀ пра́вдою твое́ю, вра̑гъ мои́хъ ра́ди и҆спра́ви пред̾ тобо́ю пꙋ́ть мо́й."}, {"num": "ѳ҃.", "text": "Ꙗ҆́кѡ нѣ́сть во ᲂу҆стѣ́хъ и҆́хъ и҆́стины, се́рдце и҆́хъ сꙋ́етно, гро́бъ ѿве́рстъ горта́нь и҆́хъ, ѧ҆зы́ки свои́ми льща́хꙋ."}, {"num": "і҃.", "text": "Сꙋдѝ и҆̀мъ бж҃е, да ѿпадꙋ́тъ ѿ мы́слей свои́хъ: по мно́жествꙋ нече́стїѧ и҆́хъ и҆зри́ни ѧ҆̀, ꙗ҆́кѡ преѡгорчи́ша тѧ̀ гдⷭ҇и."}, {"num": "а҃і.", "text": "И҆ да возвеселѧ́тсѧ всѝ ᲂу҆пова́ющїи на тѧ̀, во вѣ́къ возра́дꙋютсѧ, и҆ всели́шисѧ въ ни́хъ: и҆ похва́лѧтсѧ ѡ҆ тебѣ̀ лю́бѧщїи и҆́мѧ твоѐ."}, {"num": "в҃і.", "text": "Ꙗ҆́кѡ ты̀ бл҃гослови́ши првⷣника гдⷭ҇и, ꙗ҆́кѡ ѻ҆рꙋ́жїемъ бл҃говоле́нїѧ вѣнча́лъ є҆сѝ на́съ. а҃ Въ коне́цъ, въ пѣ́снехъ ѡ҆ ѻ҆смо́мъ, ѱало́мъ дв҃дꙋ, ѕ҃."}]}, "6": {"number": 6, "cu_numeral": "ѕ҃", "title": "Ѱало́мъ ѕ҃ (6)", "subtitle": "а҃ Въ коне́цъ, въ пѣ́снехъ ѡ҆ ѻ҆смо́мъ, ѱало́мъ дв҃дꙋ, ѕ҃.", "verses": [{"num": "а҃.", "text": "Гдⷭ҇и, да не ꙗ҆́ростїю твое́ю ѡ҆бличи́ши менѐ, нижѐ гнѣ́вомъ твои́мъ нака́жеши менѐ."}, {"num": "в҃.", "text": "Поми́лꙋй мѧ̀ гдⷭ҇и, ꙗ҆́кѡ не́мощенъ є҆́смь: и҆сцѣли́ мѧ гдⷭ҇и, ꙗ҆́кѡ смѧто́шасѧ кѡ́сти моѧ̑,"}, {"num": "г҃.", "text": "И҆ дꙋша̀ моѧ̀ смѧте́сѧ ѕѣлѡ̀: и҆ ты̀ гдⷭ҇и доко́лѣ;"}, {"num": "д҃.", "text": "Ѡ҆брати́сѧ гдⷭ҇и, и҆зба́ви дꙋ́шꙋ мою̀, сп҃си́ мѧ ра́ди млⷭ҇ти твоеѧ̀."}, {"num": "є҃.", "text": "Ꙗ҆́кѡ нѣ́сть въ сме́рти помина́ѧй тебѐ, во а҆́дѣ же кто̀ и҆сповѣ́стсѧ тебѣ̀;"}, {"num": "ѕ҃.", "text": "Оу҆трꙋди́хсѧ воздыха́нїемъ мои́мъ, и҆змы́ю на всѧ́кꙋ но́щь ло́же моѐ, слеза́ми мои́ми посте́лю мою̀ ѡ҆мочꙋ̀."}, {"num": "з҃.", "text": "Смѧте́сѧ ѿ ꙗ҆́рости ѻ҆́ко моѐ, ѡ҆бетша́хъ во всѣ́хъ вразѣ́хъ мои́хъ."}, {"num": "и҃.", "text": "Ѿстꙋпи́те ѿ менѐ всѝ дѣ́лающїи беззако́нїе, ꙗ҆́кѡ"}, {"num": "ѳ҃.", "text": "ᲂу҆слы́ша гдⷭ҇ь гла́съ пла́ча моегѡ̀: Оу҆слы́ша гдⷭ҇ь моле́нїе моѐ, гдⷭ҇ь моли́твꙋ мою̀ прїѧ́тъ."}, {"num": "і҃.", "text": "Да постыдѧ́тсѧ и҆ смѧтꙋ́тсѧ всѝ вразѝ моѝ, да возвратѧ́тсѧ, и҆ ᲂу҆стыдѧ́тсѧ ѕѣлѡ̀ вско́рѣ. Сла́ва: а҃ Ѱало́мъ дв҃дꙋ, є҆го́же воспѣ́тъ гдⷭ҇еви ѡ҆ словесѣ́хъ хꙋсі́евыхъ, сы́на і҆емені́ина, з҃."}]}, "7": {"number": 7, "cu_numeral": "з҃", "title": "Ѱало́мъ з҃ (7)", "subtitle": "сы́на і҆емені́ина, з҃.", "verses": [{"num": "а҃.", "text": "Гдⷭ҇и бж҃е мо́й на тѧ̀ ᲂу҆пова́хъ, сп҃си́ мѧ ѿ всѣ́хъ гонѧ́щихъ мѧ̀ и҆ и҆зба́ви мѧ̀:"}, {"num": "в҃.", "text": "Да не когда̀ похи́титъ ꙗ҆́кѡ ле́въ дꙋ́шꙋ мою̀, не сꙋ́щꙋ и҆збавлѧ́ющꙋ, нижѐ спаса́ющꙋ, Гдⷭ҇и"}, {"num": "г҃.", "text": "бж҃е мо́й, а҆́ще сотвори́хъ сїѐ, а҆́ще є҆́сть непра́вда въ рꙋкꙋ̀ моє́ю:"}, {"num": "д҃.", "text": "А҆́ще возда́хъ воздаю́щымъ мѝ ѕла̑, да ѿпадꙋ̀ ᲂу҆̀бо ѿ вра̑гъ мои́хъ то́щъ:"}, {"num": "є҃.", "text": "Да пожене́тъ ᲂу҆́бѡ вра́гъ дꙋ́шꙋ мою̀, и҆ да пости́гнетъ, и҆ попере́тъ въ зе́млю живо́тъ мо́й, и҆ сла́вꙋ мою̀ въ пе́рсть всели́тъ."}, {"num": "ѕ҃.", "text": "Воскрⷭ҇нѝ гдⷭ҇и гнѣ́вомъ твои́мъ, вознеси́сѧ въ конца́хъ вра̑гъ твои́хъ, и҆ воста́ни гдⷭ҇и бж҃е мо́й повелѣ́нїемъ, и҆́мже и҃ ѳ҃ і҃ а҃і в҃і г҃і д҃і є҃і ѕ҃і з҃і и҃і конца́хъ вра̑гъ твои́хъ, и҆ воста́ни гдⷭ҇и бж҃е мо́й повелѣ́нїемъ, и҆́мже заповѣ́далъ є҆сѝ."}, {"num": "з҃.", "text": "И҆ со́нмъ люде́й ѡ҆бы́детъ тѧ̀: и҆ ѡ҆ то́мъ на высотꙋ̀ ѡ҆брати́сѧ."}, {"num": "и҃.", "text": "Гдⷭ҇ь сꙋ́дитъ лю́демъ: сꙋди́ ми гдⷭ҇и по пра́вдѣ мое́й, и҆ по неѕло́бѣ мое́й на мѧ̀."}, {"num": "ѳ҃.", "text": "Да сконча́етсѧ ѕло́ба грѣ́шныхъ, и҆ и҆спра́виши првⷣнаго, и҆спыта́ѧй сердца̀ и҆ ᲂу҆трѡ́бы бж҃е пра́веднѡ."}, {"num": "і҃.", "text": "По́мощь моѧ̀ ѿ"}, {"num": "а҃і.", "text": "бг҃а сп҃са́ющагѡ пра̑выѧ се́рдцемъ. Бг҃ъ сꙋди́тель првⷣнъ, и҆ крѣ́покъ, и҆ долготерпѣли́въ, и҆ не гнѣ́въ наводѧ́й на всѧ́къ де́нь."}, {"num": "в҃і.", "text": "А҆́ще не ѡ҆братите́сѧ, ѻ҆рꙋ́жїе своѐ ѡ҆чи́ститъ, лꙋ́къ сво́й напрѧжѐ, и҆ ᲂу҆гото́ва и҆̀:"}, {"num": "г҃і.", "text": "И҆ въ не́мъ ᲂу҆гото́ва сосꙋ́ды смє́ртныѧ, стрѣ́лы своѧ̑ сгара́ємымъ содѣ́ла."}, {"num": "д҃і.", "text": "Сѐ болѣ̀ непра́вдою, зача́тъ болѣ́знь, и҆ родѝ беззако́нїе."}, {"num": "є҃і.", "text": "Ро́въ и҆зры̀, и҆ и҆скопа̀ и҆̀, и҆ паде́тъ въ ꙗ҆́мꙋ, ю҆́же содѣ́ла."}, {"num": "ѕ҃і.", "text": "Ѡ҆брати́тсѧ болѣ́знь є҆гѡ̀ на главꙋ̀ є҆гѡ̀, и҆ на ве́рхъ є҆гѡ̀ непра́вда є҆гѡ̀ сни́детъ."}, {"num": "з҃і.", "text": "И҆сповѣ́мсѧ гдⷭ҇еви по пра́вдѣ є҆гѡ̀, и҆ пою̀ и҆́мени гдⷭ҇а вы́шнѧгѡ. а҃ Въ коне́цъ, ѡ҆ точи́лѣхъ, ѱало́мъ дв҃дꙋ, и҃."}]}, "8": {"number": 8, "cu_numeral": "и҃", "title": "Ѱало́мъ и҃ (8)", "subtitle": "а҃ Въ коне́цъ, ѡ҆ точи́лѣхъ, ѱало́мъ дв҃дꙋ, и҃.", "verses": [{"num": "а҃.", "text": "Гдⷭ҇и гдⷭ҇ь на́шъ, ꙗ҆́кѡ чꙋ́дно и҆́мѧ твоѐ по все́й землѝ: ꙗ҆́кѡ взѧ́тсѧ великолѣ́пїе твоѐ превы́ше нб҃съ."}, {"num": "в҃.", "text": "И҆з̾ ᲂу҆́стъ младе́нєцъ и҆ ссꙋ́щихъ соверши́лъ є҆сѝ хвалꙋ̀, вра̑гъ твои́хъ ра́ди, є҆́же разрꙋши́ти врага̀ и҆ ме́стника."}, {"num": "г҃.", "text": "Ꙗ҆́кѡ ᲂу҆зрю̀ небеса̀, дѣла̀ пє́рстъ твои́хъ, лꙋнꙋ̀ и҆ ѕвѣ́зды, ꙗ҆̀же ты̀ ѡ҆снова́лъ є҆сѝ."}, {"num": "д҃.", "text": "Что̀ є҆́сть человѣ́къ, ꙗ҆́кѡ по́мниши є҆го̀; и҆лѝ сы́нъ человѣ́чь, ꙗ҆́кѡ посѣща́еши"}, {"num": "є҃.", "text": "є҆го̀; Оу҆ма́лилъ є҆сѝ є҆го̀ ма́лымъ чи́мъ ѿ а҆́гг҃лъ, сла́вою и҆ че́стїю вѣнча́лъ є҆сѝ є҆го̀:"}, {"num": "ѕ҃.", "text": "И҆ поста́вилъ є҆сѝ є҆го̀ над̾ дѣ́лы рꙋкꙋ̀ твоє́ю, всѧ̑ покори́лъ є҆сѝ под̾ но́зѣ є҆гѡ̀:"}, {"num": "з҃.", "text": "о҆́вцы и҆ волы̀ всѧ̑, є҆ще́ же и҆ скоты̀ пѡльскі́ѧ:"}, {"num": "и҃.", "text": "Пти̑цы нбⷭ҇ныѧ, и҆ ры̑бы морскі́ѧ, преходѧ́щыѧ стєзѝ морскі́ѧ."}, {"num": "ѳ҃.", "text": "Гдⷭ҇и гдⷭ҇ь на́шъ, ꙗ҆́кѡ чꙋ́дно и҆́мѧ твоѐ по все́й землѝ. Сла́ва:"}]}, "9": {"number": 9, "cu_numeral": "ѳ҃", "title": "Ѱало́мъ ѳ҃ (9)", "subtitle": "а҃ Въ коне́цъ, ѡ҆ та́йныхъ сы́на, ѱало́мъ дв҃дꙋ, ѳ҃.", "verses": [{"num": "а҃.", "text": "И҆сповѣ́мсѧ тебѣ̀ гдⷭ҇и всѣ́мъ се́рдцемъ мои́мъ, повѣ́мъ всѧ̑ чꙋдеса̀ твоѧ̑."}, {"num": "в҃.", "text": "Возвеселю́сѧ и҆ возра́дꙋюсѧ ѡ҆ тебѣ̀: пою̀ и҆́мени твоемꙋ̀, вы́шнїй."}, {"num": "г҃.", "text": "Внегда̀ возврати́тисѧ врагꙋ̀ моемꙋ̀ вспѧ́ть, и҆знемо́гꙋтъ и҆ поги́бнꙋтъ ѿ лица̀ твоегѡ̀."}, {"num": "д҃.", "text": "Ꙗ҆́кѡ сотвори́лъ є҆сѝ сꙋ́дъ мо́й, и҆ прю̀ мою̀: сѣ́лъ є҆сѝ на прⷭ҇то́лѣ сꙋдѧ́й пра́вдꙋ."}, {"num": "є҃.", "text": "Запрети́лъ є҆сѝ ꙗ҆зы́кѡмъ, и҆ поги́бе нечести́вый, и҆́мѧ є҆гѡ̀ потреби́лъ є҆сѝ въ вѣ́къ, и҆ въ вѣ́къ вѣ́ка."}, {"num": "ѕ҃.", "text": "Врагꙋ̀ ѡ҆скꙋдѣ́ша ѻ҆рꙋ̑жїѧ въ коне́цъ, и҆ гра́ды разрꙋши́лъ є҆сѝ: поги́бе па́мѧть є҆гѡ̀ съ шꙋ́момъ."}, {"num": "з҃.", "text": "И҆ гдⷭ҇ь во вѣ́къ пребыва́етъ, ᲂу҆гото́ва на сꙋ́дъ прⷭ҇то́лъ сво́й."}, {"num": "и҃.", "text": "И҆ то́й сꙋди́ти и҆́мать вселе́ннѣй въ пра́вдꙋ, сꙋди́ти и҆́мать лю́демъ въ правотѣ̀."}, {"num": "ѳ҃.", "text": "И҆ бы́сть гдⷭ҇ь прибѣ́жище ᲂу҆бо́гомꙋ, помо́щникъ во бл҃говре́менїихъ, въ ско́рбехъ."}, {"num": "і҃.", "text": "И҆ да ᲂу҆пова́ютъ на тѧ̀ зна́ющїи и҆́мѧ твоѐ: ꙗ҆́кѡ не ѡ҆ста́вилъ є҆сѝ взыска́ющихъ тѧ̀ гдⷭ҇и."}, {"num": "а҃і.", "text": "По́йте гдⷭ҇еви живꙋ́щемꙋ въ сїѡ́нѣ, возвѣсти́те во ꙗ҆зы́цѣхъ начина̑нїѧ є҆гѡ̀:"}, {"num": "в҃і.", "text": "Ꙗ҆́кѡ взыска́ѧй крѡ́ви и҆́хъ"}, {"num": "г҃і.", "text": "помѧнꙋ̀, не забы̀ зва́нїѧ ᲂу҆бо́гихъ. Поми́лꙋй мѧ̀ гдⷭ҇и, ви́ждь смире́нїе моѐ ѿ вра̑гъ мои́хъ, возносѧ́й мѧ̀ ѿ вра́тъ сме́ртныхъ:"}, {"num": "д҃і.", "text": "Ꙗ҆́кѡ да возвѣщꙋ̀ всѧ̑ хвалы̑ твоѧ̑ во вратѣ́хъ дще́ре сїѡ́ни: возра́дꙋемсѧ ѡ҆ сп҃се́нїи твое́мъ."}, {"num": "є҃і.", "text": "Оу҆глѣбо́ша ꙗ҆зы́цы въ па́гꙋбѣ, ю҆́же сотвори́ша: въ сѣ́ти се́й, ю҆́же скры́ша, ᲂу҆вѧзѐ нога̀ и҆́хъ."}, {"num": "ѕ҃і.", "text": "Зна́емь є҆́сть гдⷭ҇ь, сꙋдьбы̑ творѧ́й, въ дѣ́лѣхъ рꙋкꙋ̀ своє́ю ᲂу҆вѧзѐ грѣ́шникъ."}, {"num": "з҃і.", "text": "Да возвратѧ́тсѧ грѣ̑шницы во а҆́дъ, всѝ ꙗ҆зы́цы забыва́ющїи бг҃а."}, {"num": "и҃і.", "text": "Ꙗ҆́кѡ не до конца̀ забве́нъ бꙋ́детъ ни́щїй, терпѣ́нїе ᲂу҆бо́гихъ не поги́бнетъ до конца̀."}, {"num": "ѳ҃і.", "text": "Воскрⷭ҇нѝ гдⷭ҇и, да не крѣпи́тсѧ человѣ́къ, да сꙋ́дѧтсѧ ꙗ҆зы́цы пред̾ тобо́ю."}, {"num": "к҃.", "text": "Поста́ви гдⷭ҇и законоположи́телѧ над̾ ни́ми, да разꙋмѣ́ютъ ꙗ҆зы́цы ꙗ҆́кѡ человѣ́цы сꙋ́ть."}, {"num": "к҃а.", "text": "Вскꙋ́ю гдⷭ҇и ѿстоѧ̀ дале́че презира́еши во бл҃говре́менїихъ, въ ско́рбехъ;"}, {"num": "к҃в.", "text": "Внегда̀ горди́тисѧ нечести́вомꙋ, возгара́етсѧ ни́щїй: ᲂу҆вѧза́ютъ въ совѣ́тѣхъ, ꙗ҆̀же помышлѧ́ютъ."}, {"num": "к҃г.", "text": "Ꙗ҆́кѡ хвали́мь є҆́сть грѣ́шный въ по́хотехъ дꙋшѝ своеѧ̀, и҆ ѡ҆би́дѧй бл҃гослови́мь є҆́сть."}, {"num": "к҃д.", "text": "Раздражѝ гдⷭ҇а грѣ́шный: по мно́жествꙋ гнѣ́ва своегѡ̀ не взы́щетъ: нѣ́сть бг҃а пред̾ ни́мъ,"}, {"num": "к҃є.", "text": "Ѡ҆сквернѧ́ютсѧ пꙋтїѐ є҆гѡ̀ на всѧ́ко вре́мѧ: ѿе́млютсѧ сꙋдьбы̑ твоѧ̑ ѿ лица̀ є҆гѡ̀: всѣ́ми врагѝ свои́ми ѡ҆блада́етъ."}, {"num": "к҃ѕ.", "text": "Рече́ бо въ се́рдцѣ свое́мъ: не подви́жꙋсѧ ѿ ро́да въ ро́дъ без̾ ѕла̀:"}, {"num": "к҃з.", "text": "Е҆гѡ́же клѧ́твы ᲂу҆ста̀ є҆гѡ̀ пѡ́лна сꙋ́ть, и҆ го́рести и҆ льстѝ: под̾ ѧ҆зы́комъ є҆гѡ̀ трꙋ́дъ и҆ болѣ́знь. Присѣди́тъ к҃ѳ л҃ л҃а л҃в л҃г л҃д л҃є л҃ѕ л҃з л҃҃и л҃ѳ го́рести и҆ льстѝ: под̾ ѧ҆зы́комъ є҆гѡ̀ трꙋ́дъ и҆ болѣ́знь."}, {"num": "к҃и.", "text": "Присѣди́тъ въ лови́тельствѣ съ бога́тыми въ та́йныхъ, є҆́же ᲂу҆би́ти непови́ннаго: ѻ҆́чи є҆гѡ̀ на ни́щаго призира́етѣ."}, {"num": "к҃ѳ.", "text": "Лови́тъ въ та́йнѣ, ꙗ҆́кѡ ле́въ во ѡ҆гра́дѣ свое́й, лови́тъ, є҆́же восхи́тити ни́щаго, восхи́тити ни́щаго внегда̀ привлещѝ и҆̀"}, {"num": "л҃.", "text": "въ сѣ́ти свое́й. Смири́тъ є҆го̀: преклони́тсѧ и҆ паде́тъ, внегда̀ є҆мꙋ̀ ѡ҆блада́ти ᲂу҆бо́гими."}, {"num": "л҃а.", "text": "Рече́ бо въ се́рдцѣ свое́мъ: забы̀ бг҃ъ, ѿвратѝ лицѐ своѐ, да не ви́дитъ до конца̀."}, {"num": "л҃в.", "text": "Воскрⷭ҇нѝ гдⷭ҇и бж҃е мо́й, да вознесе́тсѧ рꙋка̀ твоѧ̀, не забꙋ́ди ᲂу҆бо́гихъ твои́хъ до конца̀."}, {"num": "л҃г.", "text": "Чесѡ̀ ра́ди прогнѣ́ва нечести́вый бг҃а: рече́ бо въ се́рдцѣ свое́мъ: не взы́щетъ."}, {"num": "л҃д.", "text": "Ви́диши, ꙗ҆́кѡ ты̀ болѣ́знь и҆ ꙗ҆́рость смотрѧ́еши, да пре́данъ бꙋ́детъ въ рꙋ́цѣ твоѝ: тебѣ̀ ѡ҆ста́вленъ є҆́сть ни́щїй, си́рꙋ ты̀ бꙋ́ди помо́щникъ."}, {"num": "л҃є.", "text": "Сокрꙋшѝ мы́шцꙋ грѣ́шномꙋ и҆ лꙋка́вомꙋ: взы́щетсѧ грѣ́хъ є҆гѡ̀, и҆ не ѡ҆брѧ́щетсѧ."}, {"num": "л҃ѕ.", "text": "Гдⷭ҇ь цр҃ь во вѣ́къ и҆ въ вѣ́къ вѣ́ка: поги́бнете ꙗ҆зы́цы ѿ землѝ є҆гѡ̀."}, {"num": "л҃з.", "text": "Жела́нїе ᲂу҆бо́гихъ ᲂу҆слы́шалъ є҆сѝ гдⷭ҇и: ᲂу҆гото́ванїю се́рдца и҆́хъ внѧ́тъ ᲂу҆́хо твоѐ."}, {"num": "л҃и.", "text": "Сꙋдѝ си́рꙋ, и҆ смире́нꙋ, да не приложи́тъ ктомꙋ̀ велича́тисѧ человѣ́къ на землѝ."}]}, "10": {"number": 10, "cu_numeral": "і҃", "title": "Ѱало́мъ і҃ (10)", "subtitle": "Въ коне́цъ, ѱало́мъ дв҃дꙋ, і҃.", "verses": [{"num": "а҃.", "text": "На гдⷭ҇а ᲂу҆пова́хъ, ка́кѡ рече́те дꙋшѝ мое́й: превита́й по гора́мъ, ꙗ҆́кѡ пти́ца;"}, {"num": "в҃.", "text": "Ꙗ҆́кѡ сѐ грѣ̑шницы налѧко́ша лꙋ́къ, ᲂу҆гото́ваша стрѣ́лы въ тꙋ́лѣ, сострѣлѧ́ти во мра́цѣ пра̑выѧ се́рдцемъ."}, {"num": "г҃.", "text": "Занѐ ꙗ҆̀же ты̀ соверши́лъ є҆сѝ, ѻ҆нѝ разрꙋши́ша: првⷣникъ же что̀ сотворѝ; гдⷭ҇ь во хра́мѣ ст҃ѣ́мъ свое́мъ."}, {"num": "д҃.", "text": "Гдⷭ҇ь, на нб҃сѝ прⷭ҇то́лъ є҆гѡ̀: ѻ҆́чи є҆гѡ̀ на ни́щаго призира́етѣ, вѣ́жди"}, {"num": "є҃.", "text": "є҆гѡ̀ и҆спыта́етѣ сы́ны человѣ́чєскїѧ. Гдⷭ҇ь и҆спыта́етъ првⷣнаго и҆ нечести́ваго: любѧ́й же непра́вдꙋ, ненави́дитъ свою̀ дꙋ́шꙋ."}, {"num": "ѕ҃.", "text": "Ѡ҆дожди́тъ на грѣ́шники сѣ̑ти, ѻ҆́гнь и҆ жꙋ́пелъ, и҆ дꙋ́хъ бꙋ́ренъ, ча́сть ча́ши и҆́хъ."}, {"num": "з҃.", "text": "Ꙗ҆́кѡ првⷣнъ гдⷭ҇ь: и҆ пра̑вды возлюби:, правѡты̀ ви́дѣ лицѐ є҆гѡ̀. Сла́ва: а҃ Въ коне́цъ, ѡ҆ ѻ҆смѣ́й, ѱало́мъ дв҃дꙋ, а҃і."}]}, "11": {"number": 11, "cu_numeral": "а҃і", "title": "Ѱало́мъ а҃і (11)", "subtitle": "а҃ Въ коне́цъ, ѡ҆ ѻ҆смѣ́й, ѱало́мъ дв҃дꙋ, а҃і.", "verses": [{"num": "а҃.", "text": "Сп҃си́ мѧ гдⷭ҇и, ꙗ҆́кѡ ѡ҆скꙋдѣ̀ прпⷣбный, ꙗ҆́кѡ ᲂу҆ма́лишасѧ и҆́стины ѿ сынѡ́въ человѣ́ческихъ."}, {"num": "в҃.", "text": "Сꙋ́єтнаѧ глаго́ла кі́йждо ко и҆́скреннемꙋ своемꙋ̀: ᲂу҆стнѣ̀ льсти̑выѧ въ се́рдцѣ, и҆ въ се́рдцѣ глаго́лаша ѕла̑ѧ."}, {"num": "г҃.", "text": "Потреби́тъ гдⷭ҇ь всѧ̑ ᲂу҆стны̀ льсти̑выѧ, ѧ҆зы́къ велерѣ́чивый,"}, {"num": "д҃.", "text": "Ре́кшыѧ: ѧ҆зы́къ на́шъ возвели́чимъ, ᲂу҆стны̀ на̑ша при на́съ сꙋ́ть: кто̀ на́мъ гдⷭ҇ь є҆́сть;"}, {"num": "є҃.", "text": "Стра́сти ра́ди ни́щихъ, и҆ воздыха́нїѧ ᲂу҆бо́гихъ, ны́нѣ воскрⷭ҇нꙋ̀, глаго́летъ гдⷭ҇ь: положꙋ́сѧ во сп҃се́нїе, не ѡ҆биню́сѧ ѡ҆ не́мъ."}, {"num": "ѕ҃.", "text": "Словеса̀ гдⷭ҇нѧ, словеса̀ чи̑ста, сребро̀ разжже́но, и҆скꙋше́но землѝ, ѡ҆чище́но седмери́цею."}, {"num": "з҃.", "text": "Ты̀ гдⷭ҇и сохрани́ши ны̀, и҆ соблюде́ши ны̀ ѿ ро́да сегѡ̀ и҆ во вѣ́къ."}, {"num": "и҃.", "text": "Ѻ҆́крестъ нечести́вїи хо́дѧтъ: по высотѣ̀ твое́й ᲂу҆мно́жилъ є҆сѝ сы́ны человѣ́чєскїѧ. а҃ Въ коне́цъ, ѱало́мъ дв҃дꙋ, в҃і."}]}, "12": {"number": 12, "cu_numeral": "в҃і", "title": "Ѱало́мъ в҃і (12)", "subtitle": "а҃ Въ коне́цъ, ѱало́мъ дв҃дꙋ, в҃і.", "verses": [{"num": "а҃.", "text": "Доко́лѣ гдⷭ҇и, забꙋ́деши мѧ̀ до конца̀; доко́лѣ ѿвраща́еши лицѐ твоѐ ѿ менѐ̀;"}, {"num": "в҃.", "text": "Доко́лѣ положꙋ̀ совѣ́ты въ дꙋшѝ мое́й, бѡлѣ́зни въ се́рдцѣ мое́мъ де́нь и҆ но́щь; доко́лѣ вознесе́тсѧ вра́гъ мо́й на мѧ̀;"}, {"num": "г҃.", "text": "При́зри, ᲂу҆слы́ши мѧ̀ гдⷭ҇и бж҃е мо́й, просвѣтѝ ѻ҆́чи моѝ,"}, {"num": "д҃.", "text": "да не когда̀ ᲂу҆снꙋ̀ въ сме́рть. Да не когда̀ рече́тъ вра́гъ мо́й: ᲂу҆крѣпи́хсѧ на него̀."}, {"num": "є҃.", "text": "Стꙋжа́ющїи мѝ возра́дꙋютсѧ, а҆́ще подви́жꙋсѧ."}, {"num": "ѕ҃.", "text": "А҆́зъ же на млⷭ҇ть твою̀ ᲂу҆пова́хъ: возра́дꙋетсѧ се́рдце моѐ ѡ҆ сп҃се́нїи твое́мъ: воспою̀ гдⷭ҇еви бл҃годѣ́ѧвшемꙋ мнѣ̀, и҆ пою̀ и҆́мени гдⷭ҇а вы́шнѧгѡ."}]}, "13": {"number": 13, "cu_numeral": "г҃і", "title": "Ѱало́мъ г҃і (13)", "subtitle": "Въ коне́цъ, ѱало́мъ дв҃дꙋ, г҃і.", "verses": [{"num": "а҃.", "text": "Речѐ безꙋ́менъ въ се́рдцѣ свое́мъ: нѣ́сть бг҃ъ. растлѣ́ша и҆ ѡ҆мерзи́шасѧ въ начина́нїихъ: нѣ́сть творѧ́й бл҃госты́ню."}, {"num": "в҃.", "text": "Гдⷭ҇ь съ нб҃сѐ прини́че на сы́ны человѣ́чєскїѧ: ви́дѣти, а҆́ще є҆́сть разꙋмѣва́ѧй и҆лѝ взыска́ѧй бг҃а."}, {"num": "г҃.", "text": "Всѝ ᲂу҆клони́шасѧ, вкꙋ́пѣ неключи́ми бы́ша: нѣ́сть творѧ́й бл҃госты́ню, нѣ́сть до є҆ди́нагѡ."}, {"num": "д҃.", "text": "Ни лѝ ᲂу҆разꙋмѣ́ютъ всѝ дѣ́лающїи беззако́нїе, снѣда́ющїи лю́ди моѧ̑ въ снѣ́дь хлѣ́ба; гдⷭ҇а не призва́ша."}, {"num": "є҃.", "text": "Та́мѡ ᲂу҆боѧ́шасѧ стра́ха, и҆дѣ́же не бѣ̀ стра́хъ, ꙗ҆́кѡ гдⷭ҇ь въ ро́дѣ првⷣныхъ."}, {"num": "ѕ҃.", "text": "Совѣ́тъ ни́щагѡ посрами́сте, гдⷭ҇ь же ᲂу҆пова́нїе є҆гѡ̀ є҆́сть."}, {"num": "з҃.", "text": "Кто̀ да́стъ ѿ сїѡ́на спⷭ҇нїе і҆и҃лево;"}, {"num": "и҃.", "text": "Внегда̀ возврати́тъ гдⷭ҇ь плѣне́нїе люде́й свои́хъ, возра́дꙋетсѧ і҆а́кѡвъ, и҆ возвесели́тсѧ і҆и҃ль. Сла́ва:"}]}, "14": {"number": 14, "cu_numeral": "д҃і", "title": "Ѱало́мъ д҃і (14)", "subtitle": "Въ коне́цъ, ѱало́мъ дв҃дꙋ, д҃і.", "verses": [{"num": "а҃.", "text": "Гдⷭ҇и, кто̀ ѡ҆бита́етъ въ жили́щи твое́мъ; и҆лѝ кто̀ всели́тсѧ во ст҃ꙋ́ю го́рꙋ твою̀;"}, {"num": "в҃.", "text": "Ходѧ́й непоро́ченъ, и҆ дѣ́лаѧй пра́вдꙋ, глаго́лѧй и҆́стинꙋ въ се́рдцѣ свое́мъ:"}, {"num": "г҃.", "text": "И҆́же не ᲂу҆льстѝ ѧ҆зы́комъ свои́мъ, и҆ не сотворѝ и҆́скреннемꙋ своемꙋ̀ ѕла̀, и҆ поноше́нїѧ не прїѧ́тъ на бли̑жнїѧ своѧ̑."}, {"num": "д҃.", "text": "Оу҆ничиже́нъ є҆́сть пред̾ ни́мъ лꙋка́внꙋѧй, боѧ́щыѧ же сѧ гдⷭ҇а сла́витъ: клены́йсѧ и҆́скреннемꙋ своемꙋ̀, и҆ не ѿмета́ѧсѧ:"}, {"num": "є҃.", "text": "Сребра̀ своегѡ̀ не дадѐ въ ли́хвꙋ, и҆ мзды̀ на непови́нныхъ не прїѧ́тъ. творѧ́й сїѧ̑ не подви́житсѧ во вѣ́къ. Столпописа́нїе, дв҃дꙋ, є҃і."}]}, "15": {"number": 15, "cu_numeral": "є҃і", "title": "Ѱало́мъ є҃і (15)", "subtitle": "Столпописа́нїе, дв҃дꙋ, є҃і.", "verses": [{"num": "а҃.", "text": "Сохрани́ мѧ гдⷭ҇и, ꙗ҆́кѡ на тѧ̀ ᲂу҆пова́хъ, Рѣ́хъ гдⷭ҇еви: гдⷭ҇ь мо́й є҆сѝ ты̀:"}, {"num": "в҃.", "text": "ꙗ҆́кѡ благи́хъ мои́хъ не тре́бꙋеши."}, {"num": "г҃.", "text": "Ст҃ы̑мъ, и҆̀же сꙋ́ть на землѝ є҆гѡ̀, ᲂу҆дивѝ гдⷭ҇ь всѧ̑ хотѣ̑нїѧ своѧ̑ въ ни́хъ."}, {"num": "д҃.", "text": "Оу҆мно́жишасѧ не́мѡщи и҆́хъ, по си́хъ ᲂу҆скори́ша. не соберꙋ̀ собо́ры и҆́хъ ѿ крове́й, ни помѧнꙋ́ же и҆ме́нъ и҆́хъ ᲂу҆стна́ма мои́ма."}, {"num": "є҃.", "text": "Гдⷭ҇ь ча́сть достоѧ́нїѧ моегѡ̀, и҆ ча́ши моеѧ̀: ты̀ є҆сѝ ᲂу҆строѧ́ѧй достоѧ́нїе моѐ мнѣ̀."}, {"num": "ѕ҃.", "text": "Оу҆́жѧ нападо́ша мѝ въ держа́вныхъ мои́хъ: и҆́бо достоѧ́нїе моѐ держа́вно є҆́сть мнѣ̀."}, {"num": "з҃.", "text": "Бл҃гословлю̀ гдⷭ҇а вразꙋми́вшаго мѧ̀: є҆ще́ же и҆ до но́щи наказа́ша мѧ̀ ᲂу҆трѡ́бы моѧ̑."}, {"num": "и҃.", "text": "Предзрѣ́хъ гдⷭ҇а предо мно́ю вы́нꙋ, ꙗ҆́кѡ ѡ҆деснꙋ́ю менє̀ є҆́сть, да не подви́жꙋсѧ."}, {"num": "ѳ҃.", "text": "Сегѡ̀ ра́ди возвесели́сѧ се́рдце моѐ, и҆ возра́довасѧ ѧ҆зы́къ мо́й, є҆ще́ же и҆ пло́ть моѧ̀ всели́тсѧ на ᲂу҆пова́нїи."}, {"num": "і҃.", "text": "Ꙗ҆́кѡ не ѡ҆ста́виши дꙋ́шꙋ мою̀ во а҆́дѣ, нижѐ да́си прпⷣбномꙋ твоемꙋ̀ ви́дѣти и҆стлѣ́нїѧ."}, {"num": "а҃і.", "text": "Сказа́лъ мѝ є҆сѝ пꙋти̑ живота̀: и҆спо́лниши мѧ̀ весе́лїѧ съ лице́мъ твои́мъ: красота̀ въ десни́цѣ твое́й въ коне́цъ. Моли́тва дв҃дꙋ, ѕ҃і."}]}, "16": {"number": 16, "cu_numeral": "ѕ҃і", "title": "Ѱало́мъ ѕ҃і (16)", "subtitle": "Моли́тва дв҃дꙋ, ѕ҃і.", "verses": [{"num": "а҃.", "text": "Оу҆слы́ши гдⷭ҇и пра́вдꙋ мою̀, вонмѝ моле́нїю моемꙋ̀, внꙋшѝ моли́твꙋ мою̀ не во ᲂу҆стна́хъ льсти́выхъ."}, {"num": "в҃.", "text": "Ѿ лица̀ твоегѡ̀ сꙋдьба̀ моѧ̀ и҆зы́детъ: ѻ҆́чи моѝ да ви́дита правоты̀."}, {"num": "г҃.", "text": "И҆скꙋси́лъ є҆сѝ се́рдце моѐ, посѣти́лъ є҆сѝ но́щїю: и҆скꙋси́лъ мѧ̀ є҆сѝ, и҆ не ѡ҆брѣ́тесѧ во мнѣ̀ д҃ є҃ ѕ҃ з҃ и҃ ѳ҃ і҃ а҃і в҃і г҃і д҃і є҃і посѣти́лъ є҆сѝ но́щїю: и҆скꙋси́лъ мѧ̀ є҆сѝ, и҆ не ѡ҆брѣ́тесѧ во мнѣ̀ непра́вда."}, {"num": "д҃.", "text": "Ꙗ҆́кѡ да не возглаго́лютъ ᲂу҆ста̀ моѧ̑ дѣ́лъ человѣ́ческихъ, за словеса̀ ᲂу҆сте́нъ твои́хъ а҆́зъ сохрани́хъ пꙋти̑ же́стѡки."}, {"num": "є҃.", "text": "Совершѝ стѡпы̀ моѧ̑ во стезѧ́хъ твои́хъ, да не подви́жꙋтсѧ стѡпы̀ моѧ̑."}, {"num": "ѕ҃.", "text": "А҆́зъ воззва́хъ, ꙗ҆́кѡ ᲂу҆слы́шалъ мѧ̀ є҆сѝ бж҃е:"}, {"num": "з҃.", "text": "приклонѝ ᲂу҆́хо твоѐ мнѣ̀, и҆ ᲂу҆слы́ши глаго́лы моѧ̑. Оу҆дивѝ млⷭ҇ти твоѧ̑, сп҃са́ѧй ᲂу҆пова́ющыѧ на тѧ̀ ѿ проти́вѧщихсѧ десни́цѣ твое́й:"}, {"num": "и҃.", "text": "Сохрани́ мѧ, гдⷭ҇и, ꙗ҆́кѡ зѣ́ницꙋ ѻ҆́ка: въ кро́вѣ крилꙋ̑ твоє́ю покры́еши мѧ̀,"}, {"num": "ѳ҃.", "text": "Ѿ лица̀ нечести́выхъ ѡ҆стра́стшихъ мѧ̀, вразѝ моѝ дꙋ́шꙋ мою̀ ѡ҆держа́ша,"}, {"num": "і҃.", "text": "Тꙋ́къ сво́й затвори́ша: ᲂу҆ста̀ и҆́хъ глаго́лаша горды́ню."}, {"num": "а҃і.", "text": "И҆згонѧ́щїи мѧ̀ ны́нѣ ѡ҆быдо́ша мѧ̀, ѻ҆́чи своѝ возложи́ша ᲂу҆клони́ти на зе́млю."}, {"num": "в҃і.", "text": "Ѡ҆б̾ѧ́ша мѧ̀ ꙗ҆́кѡ ле́въ гото́въ на ло́въ, и҆ ꙗ҆́кѡ скѵ́менъ ѡ҆бита́ѧй въ та́йныхъ."}, {"num": "г҃і.", "text": "Воскрⷭ҇нѝ, гдⷭ҇и, предварѝ ѧ҆̀, и҆ запнѝ и҆̀мъ, и҆зба́ви дꙋ́шꙋ мою̀ ѿ нечести́вагѡ, ѻ҆рꙋ́жїе твоѐ ѿ вра̑гъ рꙋкѝ твоеѧ̀,"}, {"num": "д҃і.", "text": "Гдⷭ҇и, ѿ ма́лыхъ ѿ землѝ: раздѣлѝ ѧ҆̀ въ животѣ̀ и҆́хъ, и҆ сокрове́нныхъ твои́хъ и҆спо́лнисѧ чре́во и҆́хъ: насы́тишасѧ сынѡ́въ, и҆ ѡ҆ста́виша ѡ҆ста́нки младе́нцємъ свои̑мъ."}, {"num": "є҃і.", "text": "А҆́зъ же пра́вдою ꙗ҆влю́сѧ лицꙋ̀ твоемꙋ̀, насы́щꙋсѧ внегда̀ ꙗ҆ви́ти ми сѧ сла́вѣ твое́й. Сла́ва:"}]}, "17": {"number": 17, "cu_numeral": "з҃і", "title": "Ѱало́мъ з҃і (17)", "subtitle": "и҆ и҆з̾ рꙋкѝ саꙋ́ли, и҆ речѐ: з҃і.", "verses": [{"num": "а҃.", "text": "Возлюблю́ тѧ, гдⷭ҇и, крѣ́посте моѧ̀:"}, {"num": "в҃.", "text": "Гдⷭ҇ь ᲂу҆твержде́нїе моѐ, и҆ прибѣ́жище моѐ, и҆ и҆зба́витель мо́й, бг҃ъ мо́й, помо́щникъ мо́й, и҆ ᲂу҆пова́ю на него̀: защи́титель мо́й, и҆ ро́гъ сп҃сенїѧ моегѡ̀, и҆ застꙋ́пникъ мо́й."}, {"num": "г҃.", "text": "Хвалѧ̀ призовꙋ̀ гдⷭ҇а, и҆ ѿ вра̑гъ мои́хъ спасꙋ́сѧ."}, {"num": "д҃.", "text": "Ѡ҆держа́ша мѧ̀ бѡлѣ́зни смє́ртныѧ, и҆ пото́цы беззако́нїѧ смѧто́ша мѧ̀:"}, {"num": "є҃.", "text": "Бѡлѣ́зни а҆́дѡвы ѡ҆быдо́ша мѧ̀, предвари́ша мѧ̀ сѣ̑ти смє́ртныѧ."}, {"num": "ѕ҃.", "text": "И҆ внегда̀ скорбѣ́ти мѝ, призва́хъ гдⷭ҇а, и҆ къ бг҃ꙋ моемꙋ̀ воззва́хъ: ᲂу҆слы́ша ѿ хра́ма ст҃а́гѡ своегѡ̀ гла́съ мо́й, и҆ во́пль мо́й пред̾ ни́мъ вни́детъ во ᲂу҆́ши є҆гѡ̀."}, {"num": "з҃.", "text": "И҆ подви́жесѧ, и҆ тре́петна бы́сть землѧ̀, и҆ ѡ҆снова̑нїѧ го́ръ смѧто́шасѧ и҆ подвиго́шасѧ,"}, {"num": "и҃.", "text": "ꙗ҆́кѡ прогнѣ́васѧ на нѧ̀ бг҃ъ. Взы́де ды́мъ гнѣ́вомъ є҆гѡ̀, и҆ ѻ҆́гнь ѿ лица̀ є҆гѡ̀ воспла́менитсѧ, ᲂу҆́глїе возгорѣ́сѧ ѿ негѡ̀."}, {"num": "ѳ҃.", "text": "И҆ приклонѝ нб҃са̀ и҆ сни́де: и҆ мра́къ под̾ нога́ма є҆гѡ̀."}, {"num": "і҃.", "text": "И҆ взы́де на херꙋві́мы, и҆ летѣ̀, летѣ̀ на крилꙋ̑ вѣ́трєню."}, {"num": "а҃і.", "text": "И҆ положѝ тьмꙋ̀ закро́въ сво́й, ѡ҆́крестъ є҆гѡ̀ селе́нїе є҆гѡ̀, темна̀ вода̀ во ѡ҆́блацѣхъ воздꙋ́шныхъ."}, {"num": "в҃і.", "text": "Ѿ ѡ҆блиста́нїѧ пред̾ ни́мъ ѡ҆́блацы проидо́ша, гра́дъ и҆ ᲂу҆́глїе ѻ҆́гненное:"}, {"num": "г҃і.", "text": "И҆ возгремѣ̀ съ небесѐ гдⷭ҇ь, и҆ вы́шнїй дадѐ гла́съ сво́й."}, {"num": "д҃і.", "text": "Низпосла̀ стрѣ́лы, и҆ разгна̀ ѧ҆̀, и҆ мѡ́лнїи ᲂу҆мно́жи, и҆ смѧтѐ ѧ҆̀."}, {"num": "є҃і.", "text": "И҆ ꙗ҆ви́шасѧ и҆сто́чницы водні́и, и҆ ѿкры́шасѧ ѡ҆снова̑нїѧ вселе́нныѧ, ѿ запреще́нїѧ твоегѡ̀, гдⷭ҇и, ѿ дохнове́нїѧ дꙋ́ха гнѣ́ва твоегѡ̀."}, {"num": "ѕ҃і.", "text": "Низпосла̀ съ высоты̀, и҆ прїѧ́тъ мѧ̀, воспрїѧ́тъ мѧ̀ ѿ во́дъ мно́гихъ."}, {"num": "з҃і.", "text": "И҆зба́витъ мѧ̀ ѿ врагѡ́въ мои́хъ си́льныхъ, и҆ ѿ ненави́дѧщихъ мѧ̀: ꙗ҆́кѡ ᲂу҆тверди́шасѧ па́че менѐ."}, {"num": "и҃і.", "text": "Предвари́ша мѧ̀ въ де́нь ѡ҆ѕлобле́нїѧ моегѡ̀: и҆ бы́сть гдⷭ҇ь ᲂу҆твержде́нїе моѐ."}, {"num": "ѳ҃і.", "text": "И҆ и҆зведе́ мѧ на широтꙋ̀: и҆зба́витъ мѧ̀, ꙗ҆́кѡ восхотѣ́ мѧ."}, {"num": "к҃.", "text": "И҆ возда́стъ мѝ гдⷭ҇ь по пра́вдѣ мое́й, и҆ по чистотѣ̀ рꙋкꙋ̀ моє́ю возда́стъ мѝ:"}, {"num": "к҃а.", "text": "Ꙗ҆́кѡ сохрани́хъ пꙋти̑ гдⷭ҇ни, и҆ не нече́ствовахъ ѿ бг҃а моегѡ̀."}, {"num": "к҃в.", "text": "Ꙗ҆́кѡ всѧ̑ сꙋдьбы̑ є҆гѡ̀ предо мно́ю, и҆ ѡ҆правда̑нїѧ є҆гѡ̀ не ѿстꙋпи́ша ѿ менѐ."}, {"num": "к҃г.", "text": "И҆ бꙋ́дꙋ непоро́ченъ съ ни́мъ, и҆ сохраню́сѧ ѿ беззако́нїѧ моегѡ̀."}, {"num": "к҃д.", "text": "И҆ возда́стъ мѝ гдⷭ҇ь по пра́вдѣ мое́й, и҆ по чистотѣ̀ рꙋкꙋ̀ моє́ю, пред̾ ѻ҆чи́ма є҆гѡ̀."}, {"num": "к҃є.", "text": "Съ прпⷣбнымъ прпⷣбнъ бꙋ́деши, и҆ съ мꙋ́жемъ непови́ннымъ непови́ненъ бꙋ́деши:"}, {"num": "к҃ѕ.", "text": "И҆ со и҆збра́ннымъ и҆збра́нъ бꙋ́деши, и҆ со стропти́вымъ разврати́шисѧ."}, {"num": "к҃з.", "text": "Ꙗ҆́кѡ ты̀ лю́ди смирє́нныѧ сп҃се́ши, и҆ к҃и к҃ѳ л҃ л҃а л҃в л҃г л҃д л҃є л҃ѕ л҃з л҃҃и л҃ѳ м҃ м҃а м҃в м҃г м҃д м҃є м҃ѕ м҃з м҃҃и м҃ѳ н҃ н҃҃а стропти́вымъ разврати́шисѧ. Ꙗ҆́кѡ ты̀ лю́ди смирє́нныѧ сп҃се́ши, и҆ ѻ҆́чи го́рдыхъ смири́ши."}, {"num": "к҃и.", "text": "Ꙗ҆́кѡ ты̀ просвѣти́ши свѣти́лникъ мо́й, гдⷭ҇и: бж҃е мо́й, просвѣти́ши тьмꙋ̀ мою̀."}, {"num": "к҃ѳ.", "text": "Ꙗ҆́кѡ тобо́ю и҆зба́влюсѧ ѿ и҆скꙋше́нїѧ, и҆ бг҃омъ мои́мъ прейдꙋ̀ стѣ́нꙋ."}, {"num": "л҃.", "text": "Бг҃ъ мо́й, непоро́ченъ пꙋ́ть є҆гѡ̀, словеса̀ гдⷭ҇нѧ разжжє́нна: защи́титель є҆́сть всѣ́хъ ᲂу҆пова́ющихъ на него̀."}, {"num": "л҃а.", "text": "Ꙗ҆́кѡ кто̀ бг҃ъ, ра́звѣ гдⷭ҇а; и҆лѝ кто̀ бг҃ъ, ра́звѣ бг҃а на́шегѡ;"}, {"num": "л҃в.", "text": "Бг҃ъ препоѧсꙋ́ѧй мѧ̀ си́лою, и҆ положѝ непоро́ченъ пꙋ́ть мо́й:"}, {"num": "л҃г.", "text": "Соверша́ѧй но́зѣ моѝ ꙗ҆́кѡ є҆ле́ни, и҆ на высо́кихъ поставлѧ́ѧй мѧ̀:"}, {"num": "л҃д.", "text": "Наꙋча́ѧй рꙋ́цѣ моѝ на бра́нь, и҆ положи́лъ є҆сѝ лꙋ́къ мѣ́дѧнъ мы̑шца моѧ̑."}, {"num": "л҃є.", "text": "И҆ да́лъ мѝ є҆сѝ защище́нїе сп҃сенїѧ, и҆ десни́ца твоѧ̀ воспрїѧ́тъ мѧ̀: и҆ наказа́нїе твоѐ и҆спра́витъ мѧ̀ въ коне́цъ, и҆ наказа́нїе твоѐ то̀ мѧ̀ наꙋчи́тъ."}, {"num": "л҃ѕ.", "text": "Оу҆шири́лъ є҆сѝ стѡпы̀ моѧ̑ подо мно́ю, и҆ не и҆знемого́стѣ плеснѣ̑ моѝ."}, {"num": "л҃з.", "text": "Поженꙋ̀ врагѝ моѧ̑, и҆ пости́гнꙋ ѧ҆̀, и҆ не возвращꙋ́сѧ, до́ндеже сконча́ютсѧ."}, {"num": "л҃и.", "text": "Ѡ҆скорблю̀ и҆̀хъ, и҆ не возмо́гꙋтъ ста́ти, падꙋ́тъ под̾ нога́ма мои́ма."}, {"num": "л҃ѳ.", "text": "И҆ препоѧ́салъ мѧ̀ є҆сѝ си́лою на бра́нь, спѧ́лъ є҆сѝ всѧ̑ востаю́щыѧ на мѧ̀ под̾ мѧ̀."}, {"num": "м҃.", "text": "И҆ врагѡ́въ мои́хъ да́лъ мѝ є҆сѝ хребе́тъ, и҆ ненави́дѧщыѧ мѧ̀ потреби́лъ є҆сѝ."}, {"num": "м҃а.", "text": "Воззва́ша, и҆ не бѣ̀ спаса́ѧй: ко гдⷭ҇ꙋ, и҆ не ᲂу҆слы́ша и҆́хъ."}, {"num": "м҃в.", "text": "И҆ и҆стню̀ ѧ҆̀, ꙗ҆́кѡ пра́хъ пред̾ лице́мъ вѣ́тра, ꙗ҆́кѡ бре́нїе пꙋте́й погла́ждꙋ ѧ҆̀."}, {"num": "м҃г.", "text": "И҆зба́виши мѧ̀ ѿ прерѣка́нїѧ люде́й, поста́виши мѧ̀ во главꙋ̀ ꙗ҆зы́кѡвъ. лю́дїе, и҆́хже не вѣ́дѣхъ, рабо́таша мѝ,"}, {"num": "м҃д.", "text": "Въ слꙋ́хъ ᲂу҆́ха послꙋ́шаша мѧ̀: сы́нове чꙋжді́и солга́ша мѝ,"}, {"num": "м҃є.", "text": "Сы́нове чꙋжді́и ѡ҆бетша́ша, и҆ ѡ҆хромо́ша ѿ сте́зь свои́хъ."}, {"num": "м҃ѕ.", "text": "Жи́въ гдⷭ҇ь, и҆ бл҃гослове́нъ бг҃ъ, и҆ да вознесе́тсѧ бг҃ъ сп҃се́нїѧ моегѡ̀:"}, {"num": "м҃з.", "text": "Бг҃ъ даѧ́й ѿмще́нїе мнѣ̀, и҆ покори́вый лю́ди под̾ мѧ̀."}, {"num": "м҃и.", "text": "И҆зба́витель мо́й ѿ вра̑гъ мои́хъ гнѣвли́выхъ, ѿ востаю́щихъ на мѧ̀ вознесе́ши мѧ̀, ѿ мꙋ́жа непра́ведна и҆зба́виши мѧ̀."}, {"num": "м҃ѳ.", "text": "Сегѡ̀ ра́ди и҆сповѣ́мсѧ тебѣ̀ во ꙗ҆зы́цѣхъ гдⷭ҇и, и҆ и҆́мени твоемꙋ̀ пою̀:"}, {"num": "н҃.", "text": "Велича́ѧй сп҃сє́нїѧ цр҃є́ва, и҆ творѧ́й млⷭ҇ть хрїстꙋ̀ своемꙋ̀ дв҃дꙋ, и҆ сѣ́мени є҆гѡ̀ до вѣ́ка. Сла́ва: а҃ Въ коне́цъ, ѱало́мъ дв҃дꙋ, и҃і."}]}, "18": {"number": 18, "cu_numeral": "и҃і", "title": "Ѱало́мъ и҃і (18)", "subtitle": "а҃ Въ коне́цъ, ѱало́мъ дв҃дꙋ, и҃і.", "verses": [{"num": "а҃.", "text": "Нб҃са̀ повѣ́даютъ сла́вꙋ бж҃їю, творе́нїе же рꙋкꙋ̀ є҆гѡ̀ возвѣща́етъ тве́рдь."}, {"num": "в҃.", "text": "Де́нь днѝ ѿрыга́етъ глаго́лъ, и҆ но́щь но́щи возвѣща́етъ ра́зꙋмъ."}, {"num": "г҃.", "text": "Не сꙋ́ть рѣ̑чи, нижѐ словеса̀, и҆́хже не слы́шатсѧ гла́си и҆́хъ."}, {"num": "д҃.", "text": "Во всю̀ зе́млю и҆зы́де вѣща́нїе и҆́хъ, и҆ въ концы̑ вселе́нныѧ глаго́лы є҃ ѕ҃ з҃ и҃ ѳ҃ і҃ а҃і в҃і г҃і д҃і є҃і Во всю̀ зе́млю и҆зы́де вѣща́нїе и҆́хъ, и҆ въ концы̑ вселе́нныѧ глаго́лы и҆́хъ. въ со́лнцѣ положѝ селе́нїе своѐ:"}, {"num": "є҃.", "text": "И҆ то́й ꙗ҆́кѡ жени́хъ и҆сходѧ́й ѿ черто́га своегѡ̀, возра́дꙋетсѧ ꙗ҆́кѡ и҆споли́нъ тещѝ пꙋ́ть."}, {"num": "ѕ҃.", "text": "Ѿ кра́ѧ нб҃сѐ и҆схо́дъ є҆гѡ̀, и҆ срѣ́тенїе є҆гѡ̀ до кра́ѧ небесѐ: и҆ нѣ́сть, и҆́же ᲂу҆кры́етсѧ теплоты̀ є҆гѡ̀."}, {"num": "з҃.", "text": "Зако́нъ гдⷭ҇ень непоро́ченъ, ѡ҆браща́ѧй дꙋ́шы: свидѣ́тельство гдⷭ҇не вѣ́рно, ᲂу҆мꙋдрѧ́ющее младе́нцы."}, {"num": "и҃.", "text": "Ѡ҆правда̑нїѧ гдⷭ҇нѧ пра̑ва, веселѧ̑щаѧ се́рдце: за́повѣдь гдⷭ҇нѧ свѣтла̀, просвѣща́ющаѧ ѻ҆́чи."}, {"num": "ѳ҃.", "text": "Стра́хъ гдⷭ҇ень чи́стъ, пребыва́ѧй въ вѣ́къ вѣ́ка: сꙋдьбы̑ гдⷭ҇ни и҆́стинны, ѡ҆правда̑нны вкꙋ́пѣ:"}, {"num": "і҃.", "text": "Вожделѣ̑нны па́че зла́та и҆ ка́мене че́стна мно́га, и҆ сла́ждшѧ па́че ме́да и҆ со́та."}, {"num": "а҃і.", "text": "И҆́бо ра́бъ тво́й храни́тъ ѧ҆̀, внегда̀ сохрани́ти ѧ҆̀ воздаѧ́нїе мно́го."}, {"num": "в҃і.", "text": "Грѣхопадє́нїѧ кто̀ разꙋмѣ́етъ; ѿ та́йныхъ мои́хъ ѡ҆чи́сти мѧ̀,"}, {"num": "г҃і.", "text": "И҆ ѿ чꙋжди́хъ пощадѝ раба̀ твоего̀: а҆́ще не ѡ҆блада́ютъ мно́ю, тогда̀ непоро́ченъ бꙋ́дꙋ, и҆ ѡ҆чи́щꙋсѧ ѿ грѣха̀ вели́ка,"}, {"num": "д҃і.", "text": "И҆ бꙋ́дꙋтъ во бл҃говоле́нїе словеса̀ ᲂу҆́стъ мои́хъ, и҆ поꙋче́нїе се́рдца моегѡ̀ пред̾ тобо́ю вы́нꙋ, гдⷭ҇и помо́щниче мо́й и҆ и҆зба́вителю мо́й. а҃ Въ коне́цъ, ѱало́мъ дв҃дꙋ, ѳ҃і."}]}, "19": {"number": 19, "cu_numeral": "ѳ҃і", "title": "Ѱало́мъ ѳ҃і (19)", "subtitle": "а҃ Въ коне́цъ, ѱало́мъ дв҃дꙋ, ѳ҃і.", "verses": [{"num": "а҃.", "text": "Оу҆слы́шитъ тѧ̀ гдⷭ҇ь въ де́нь печа́ли, защи́титъ тѧ̀ и҆́мѧ бг҃а і҆а́кѡвлѧ."}, {"num": "в҃.", "text": "По́слетъ тѝ по́мощь ѿ ст҃а́гѡ, и҆ ѿ сїѡ́на застꙋ́питъ тѧ̀."}, {"num": "г҃.", "text": "Помѧне́тъ всѧ́кꙋ же́ртвꙋ твою̀, и҆ всесожже́нїе твоѐ тꙋ́чно бꙋ́ди."}, {"num": "д҃.", "text": "Да́стъ тѝ гдⷭ҇ь по се́рдцꙋ твоемꙋ̀, и҆ ве́сь совѣ́тъ тво́й и҆спо́лнитъ."}, {"num": "є҃.", "text": "Возра́дꙋемсѧ ѡ҆ сп҃се́нїи твое́мъ, и҆ во и҆́мѧ гдⷭ҇а бг҃а на́шегѡ возвели́чимсѧ. и҆спо́лнитъ гдⷭ҇ь всѧ̑ прошє́нїѧ твоѧ̑."}, {"num": "ѕ҃.", "text": "Ны́нѣ позна́хъ, ꙗ҆́кѡ сп҃сѐ гдⷭ҇ь хрїста̀ своего̀: ᲂу҆слы́шитъ є҆го̀ съ нб҃сѐ ст҃а́гѡ своегѡ̀: въ си́лахъ сп҃се́нїе десни́цы є҆гѡ̀."}, {"num": "з҃.", "text": "Сі́и на колесни́цахъ и҆ сі́и на ко́нехъ: мы́ же во и҆́мѧ гдⷭ҇а бг҃а"}, {"num": "и҃.", "text": "на́шегѡ призове́мъ. Ті́и спѧ́ти бы́ша и҆ падо́ша, мы́ же воста́хомъ и҆ и҆спра́вихомсѧ."}, {"num": "ѳ҃.", "text": "Гдⷭ҇и, спасѝ царѧ̀, и҆ ᲂу҆слы́ши ны̀, во́ньже а҆́ще де́нь призове́мъ тѧ̀. а҃ Ѱало́мъ дв҃дꙋ, к҃."}]}, "20": {"number": 20, "cu_numeral": "к҃", "title": "Ѱало́мъ к҃ (20)", "subtitle": "а҃ Ѱало́мъ дв҃дꙋ, к҃.", "verses": [{"num": "а҃.", "text": "Гдⷭ҇и, си́лою твое́ю возвесели́тсѧ ца́рь, и҆ ѡ҆ сп҃се́нїи твое́мъ возра́дꙋетсѧ ѕѣлѡ̀."}, {"num": "в҃.", "text": "Жела́нїе се́рдца є҆гѡ̀ да́лъ є҆сѝ є҆мꙋ̀, и҆ хотѣ́нїѧ ᲂу҆стнꙋ̀ є҆гѡ̀ нѣ́си лиши́лъ є҆го̀."}, {"num": "г҃.", "text": "Ꙗ҆́кѡ предвари́лъ є҆сѝ є҆го̀ бл҃гослове́нїемъ бл҃госты́ннымъ, положи́лъ є҆сѝ на главѣ̀ є҆гѡ̀ вѣне́цъ ѿ ка́мене че́стна."}, {"num": "д҃.", "text": "Живота̀ проси́лъ є҆́сть ᲂу҆ тебѐ, и҆ да́лъ є҆сѝ є҆мꙋ̀ долготꙋ̀ дні́й во є҃ ѕ҃ з҃ и҃ ѳ҃ і҃ а҃і в҃і г҃і д҃і Живота̀ проси́лъ є҆́сть ᲂу҆ тебѐ, и҆ да́лъ є҆сѝ є҆мꙋ̀ долготꙋ̀ дні́й во вѣ́къ вѣ́ка."}, {"num": "є҃.", "text": "Ве́лїѧ сла́ва є҆гѡ̀ сп҃се́нїемъ твои́мъ: сла́вꙋ и҆ велелѣ́пїе возложи́ши на него̀."}, {"num": "ѕ҃.", "text": "Ꙗ҆́кѡ да́си є҆мꙋ̀ бл҃гослове́нїе во вѣ́къ вѣ́ка, возвесели́ши є҆гѡ̀ ра́достїю съ лице́мъ твои́мъ."}, {"num": "з҃.", "text": "Ꙗ҆́кѡ ца́рь ᲂу҆пова́етъ на гдⷭ҇а: и҆ млⷭ҇тїю вы́шнѧгѡ не подви́житсѧ."}, {"num": "и҃.", "text": "Да ѡ҆брѧ́щетсѧ рꙋка̀ твоѧ̀ всѣ̑мъ врагѡ́мъ твои̑мъ, десни́ца твоѧ̀ да ѡ҆брѧ́щетъ всѧ̑ ненави́дѧщыѧ тебѐ."}, {"num": "ѳ҃.", "text": "Ꙗ҆́кѡ положи́ши и҆̀хъ ꙗ҆́кѡ пе́щь ѻ҆́гненнꙋю во вре́мѧ лица̀ твоегѡ̀: гдⷭ҇ь гнѣ́вомъ свои́мъ смѧте́тъ ѧ҆̀, и҆ снѣ́сть и҆̀хъ ѻ҆́гнь."}, {"num": "і҃.", "text": "Пло́дъ и҆́хъ ѿ землѝ погꙋби́ши, и҆ сѣ́мѧ и҆́хъ ѿ сынѡ́въ человѣ́ческихъ."}, {"num": "а҃і.", "text": "Ꙗ҆́кѡ ᲂу҆клони́ша на тѧ̀ ѕла̑ѧ, помы́слиша совѣ́ты, и҆̀хже не возмо́гꙋтъ соста́вити."}, {"num": "в҃і.", "text": "Ꙗ҆́кѡ положи́ши ѧ҆̀ хребе́тъ, во и҆збы́тцѣхъ твои́хъ ᲂу҆гото́виши лицѐ и҆́хъ."}, {"num": "г҃і.", "text": "Вознеси́сѧ, гдⷭ҇и, си́лою твое́ю: воспое́мъ и҆ пое́мъ си̑лы твоѧ̑. Сла́ва: а҃ Въ коне́цъ, ѡ҆ застꙋпле́нїи ᲂу҆́треннемъ, ѱало́мъ дв҃дꙋ, к҃а."}]}, "21": {"number": 21, "cu_numeral": "к҃а", "title": "Ѱало́мъ к҃а (21)", "subtitle": "а҃ Въ коне́цъ, ѡ҆ застꙋпле́нїи ᲂу҆́треннемъ, ѱало́мъ дв҃дꙋ, к҃а.", "verses": [{"num": "а҃.", "text": "Бж҃е бж҃е мо́й, вонми́ ми, вскꙋ́ю ѡ҆ста́вилъ мѧ̀ є҆сѝ; дале́че ѿ сп҃се́нїѧ моегѡ̀ словеса̀ грѣхопаде́нїй мои́хъ."}, {"num": "в҃.", "text": "Бж҃е мо́й, воззовꙋ̀ во днѝ, и҆ не ᲂу҆слы́шиши, и҆ въ нощѝ, и҆ не въ безꙋ́мїе мнѣ̀."}, {"num": "г҃.", "text": "Ты́ же во ст҃ѣ́мъ живе́ши, хвало̀ і҆и҃лева."}, {"num": "д҃.", "text": "На тѧ̀ ᲂу҆пова́ша ѻ҆тцы̀ на́ши: ᲂу҆пова́ша, и҆ и҆зба́вилъ є҆сѝ ѧ҆̀."}, {"num": "є҃.", "text": "Къ тебѣ̀ воззва́ша, и҆ спасо́шасѧ: на тѧ̀ ᲂу҆пова́ша, и҆ не постыдѣ́шасѧ."}, {"num": "ѕ҃.", "text": "А҆́зъ же є҆́смь че́рвь, а҆ не человѣ́къ, поноше́нїе человѣ́кѡвъ и҆ ᲂу҆ничиже́нїе люде́й."}, {"num": "з҃.", "text": "Всѝ ви́дѧщїи мѧ̀ порꙋга́ша ми сѧ, глаго́лаша ᲂу҆стна́ми, покива́ша главо́ю:"}, {"num": "и҃.", "text": "Оу҆пова̀ на гдⷭ҇а, да и҆зба́витъ є҆го̀, да сп҃се́тъ є҆го̀,"}, {"num": "ѳ҃.", "text": "ꙗ҆́кѡ хо́щетъ є҆го̀. Ꙗ҆́кѡ ты̀ є҆сѝ и҆сто́ргїй мѧ̀ и҆з̾ чре́ва, ᲂу҆пова́нїе моѐ ѿ сѡсцꙋ̀ ма́тере моеѧ̀:"}, {"num": "і҃.", "text": "Къ тебѣ̀ приве́рженъ є҆́смь ѿ ложе́снъ, ѿ чре́ва ма́тере моеѧ̀ бг҃ъ мо́й є҆сѝ ты̀."}, {"num": "а҃і.", "text": "Да не ѿстꙋ́пиши ѿ менѐ̀, ꙗ҆́кѡ ско́рбь бли́з̾, ꙗ҆́кѡ нѣ́сть помога́ѧй мѝ."}, {"num": "в҃і.", "text": "Ѡ҆быдо́ша мѧ̀ тельцы̀ мно́зи, ю҆нцы̀ тꙋ́чнїи ѡ҆держа́ша мѧ̀:"}, {"num": "г҃і.", "text": "Ѿверзо́ша на мѧ̀ ᲂу҆ста̀ своѧ̑, ꙗ҆́кѡ ле́въ, восхища́ѧй и҆ рыка́ѧй."}, {"num": "д҃і.", "text": "Ꙗ҆́кѡ вода̀ и҆злїѧ́хсѧ, и҆ разсы́пашасѧ всѧ̑ кѡ́сти моѧ̑, бы́сть се́рдце моѐ ꙗ҆́кѡ во́скъ та́ѧй посредѣ̀ чре́ва моегѡ̀."}, {"num": "є҃і.", "text": "И҆́зсше ꙗ҆́кѡ скꙋде́ль крѣ́пость моѧ̀, и҆ ѧ҆зы́къ мо́й прильпѐ горта́ни моемꙋ̀, и҆ въ пе́рсть сме́рти све́лъ мѧ̀ є҆сѝ."}, {"num": "ѕ҃і.", "text": "Ꙗ҆́кѡ ѡ҆быдо́ша мѧ̀ псѝ мно́зи, со́нмъ лꙋка́выхъ ѡ҆держа́ша мѧ̀: и҆скопа́ша рꙋ́цѣ моѝ и҆ но́зѣ мои:"}, {"num": "з҃і.", "text": "И҆счето́ша всѧ̑ кѡ́сти моѧ̑: ті́и же смотри́ша и҆ презрѣ́ша мѧ̀. Раздѣли́ша ѳ҃і к҃ к҃а к҃в к҃г к҃д к҃є к҃ѕ к҃з к҃и к҃ѳ л҃ л҃а л҃в всѧ̑ кѡ́сти моѧ̑: ті́и же смотри́ша и҆ презрѣ́ша мѧ̀."}, {"num": "и҃і.", "text": "Раздѣли́ша ри̑зы моѧ̑ себѣ̀, и҆ ѡ҆ ѻ҆де́жди мое́й мета́ша жре́бїй."}, {"num": "ѳ҃і.", "text": "Ты́ же, гдⷭ҇и, не ᲂу҆далѝ по́мощь твою̀ ѿ менѐ, на застꙋпле́нїе моѐ вонмѝ."}, {"num": "к҃.", "text": "И҆зба́ви ѿ ѻ҆рꙋ́жїѧ дꙋ́шꙋ мою̀, и҆ и҆з̾ рꙋкѝ пе́сїи є҆диноро́днꙋю мою̀:"}, {"num": "к҃а.", "text": "Спаси́ мѧ ѿ ᲂу҆́стъ льво́выхъ, и҆ ѿ рѡ́гъ є҆динорѡ́жъ смире́нїе моѐ."}, {"num": "к҃в.", "text": "Повѣ́мъ и҆́мѧ твоѐ бра́тїи мое́й, посредѣ̀ цр҃кве воспою̀ тѧ̀."}, {"num": "к҃г.", "text": "Боѧ́щїисѧ гдⷭ҇а, восхвали́те є҆го̀, всѐ сѣ́мѧ і҆а́кѡвле просла́вите є҆го̀, да ᲂу҆бои́тсѧ же ѿ негѡ̀ всѐ сѣ́мѧ і҆и҃лево:"}, {"num": "к҃д.", "text": "Ꙗ҆́кѡ не ᲂу҆ничижѝ, нижѐ негодова̀ моли́твы ни́щагѡ, нижѐ ѿвратѝ лицѐ своѐ ѿ менѐ, и҆ є҆гда̀ воззва́хъ къ немꙋ̀, ᲂу҆слы́ша мѧ̀."}, {"num": "к҃є.", "text": "Ѿ тебѐ похвала̀ моѧ̀, въ цр҃кви вели́цѣй и҆сповѣ́мсѧ тебѣ̀, моли̑твы моѧ̑ возда́мъ пред̾ боѧ́щимисѧ є҆гѡ̀."}, {"num": "к҃ѕ.", "text": "Ꙗ҆дѧ́тъ ᲂу҆бо́зїи, и҆ насы́тѧтсѧ, и҆ восхва́лѧтъ гдⷭ҇а взыска́ющїи є҆го̀: жива̑ бꙋ́дꙋтъ сердца̀ и҆́хъ въ вѣ́къ вѣ́ка."}, {"num": "к҃з.", "text": "Помѧнꙋ́тсѧ и҆ ѡ҆братѧ́тсѧ къ гдⷭ҇ꙋ всѝ концы̑ землѝ, и҆ покло́нѧтсѧ пред̾ ни́мъ всѧ̑ ѻ҆те́чєствїѧ ꙗ҆зы̑къ."}, {"num": "к҃и.", "text": "Ꙗ҆́кѡ гдⷭ҇не є҆́сть црⷭ҇твїе, и҆ то́й ѡ҆блада́етъ ꙗ҆зы̑ки."}, {"num": "к҃ѳ.", "text": "Ꙗ҆до́ша, и҆ поклони́шасѧ всѝ тꙋ́чнїи землѝ: пред̾ ни́мъ припадꙋ́тъ всѝ низходѧ́щїи въ зе́млю:"}, {"num": "л҃.", "text": "и҆ дꙋша̀ моѧ̀ томꙋ̀ живе́тъ. И҆ сѣ́мѧ моѐ порабо́таетъ є҆мꙋ̀: возвѣсти́тъ гдⷭ҇еви ро́дъ грѧдꙋ́щїй."}, {"num": "л҃а.", "text": "И҆ возвѣстѧ́тъ пра́вдꙋ є҆гѡ̀ лю́дѧмъ ро́ждшымсѧ, ꙗ҆̀же сотворѝ гдⷭ҇ь."}]}, "22": {"number": 22, "cu_numeral": "к҃в", "title": "Ѱало́мъ к҃в (22)", "subtitle": "Ѱало́мъ дв҃дꙋ, к҃в.", "verses": [{"num": "а҃.", "text": "Гдⷭ҇ь пасе́тъ м ѧ̀, и҆ ничто́же м ѧ̀ лиши́тъ."}, {"num": "в҃.", "text": "На мѣ́сте ѕла́чнѣ , т а́ мѡ в с е л и́ мѧ : н а в о д ѣ̀ п о к о́ й н ѣ в о с п и та́ мѧ . Д ꙋ́ ш ꙋ м"}, {"num": "г҃.", "text": "о ю̀ ѡ҆братѝ, наста́ви м ѧ̀ на стези ̀ пра́вды и҆́мене р а́ди своег ѡ̀."}, {"num": "д҃.", "text": "А҆́ще бо и ҆ пойдꙋ̀ посредѣ̀ сѣ́ни сме́ртны ѧ, не ᲂу҆бою́сѧ ѕла̀, ꙗ҆́кѡ ты̀ со мно́ю є҆сѝ: же́злъ тво́й и҆ па́лица твоѧ̀, та̑ мѧ̀ ᲂу҆тѣ́шиста."}, {"num": "є҃.", "text": "Оу҆гото́валъ є҆сѝ предо мно́ю трапе́зꙋ сопроти́въ стꙋжа́ющымъ мнѣ̀: ᲂу҆ма́стилъ є҆сѝ є҆ле́омъ главꙋ̀ мою̀,"}, {"num": "ѕ҃.", "text": "и҆ ча́ша твоѧ̀ ᲂу҆поѧва́ющи мѧ̀ ꙗ҆́кѡ держа́вна. И҆ млⷭ҇ть твоѧ̀ пожене́тъ мѧ̀ всѧ̑ дни̑ живота̀ моегѡ̀: и҆ є҆́же всели́ти ми сѧ въ до́мъ гдⷭ҇ень въ долготꙋ̀ дні́й."}]}, "23": {"number": 23, "cu_numeral": "к҃г", "title": "Ѱало́мъ к҃г (23)", "subtitle": "Ѱало́мъ дв҃дꙋ, є҆ди́ныѧ ѿ сꙋббѡ́тъ, к҃г.", "verses": [{"num": "а҃.", "text": "Гдⷭ҇нѧ землѧ̀, и҆ и҆сполне́нїе є҆ѧ̀, вселе́ннаѧ и҆ всѝ живꙋ́щїи на не́й."}, {"num": "в҃.", "text": "То́й на морѧ́хъ ѡ҆снова́лъ ю҆̀ є҆́сть, и҆ на рѣка́хъ ᲂу҆гото́валъ ю҆̀ є҆́сть."}, {"num": "г҃.", "text": "Кто̀ взы́детъ на го́рꙋ гдⷭ҇ню; и҆лѝ кто̀ ста́нетъ на мѣ́стѣ ст҃ѣ́мъ є҆гѡ̀;"}, {"num": "д҃.", "text": "Непови́ненъ рꙋка́ма, и҆ чи́стъ се́рдцемъ, и҆́же"}, {"num": "є҃.", "text": "не прїѧ́тъ всꙋ́е дꙋ́шꙋ свою̀, и҆ не клѧ́тсѧ ле́стїю и҆́скреннемꙋ своемꙋ̀. Се́й прїи́метъ бл҃гослове́нїе ѿ гдⷭ҇а, и҆ млⷭ҇тыню ѿ бг҃а сп҃са своегѡ̀."}, {"num": "ѕ҃.", "text": "Се́й ро́дъ и҆́щꙋщихъ гдⷭ҇а, и҆́щꙋщихъ лицѐ бг҃а і҆а́кѡвлѧ."}, {"num": "з҃.", "text": "Возми́те врата̀ кнѧ̑зи ва̑ша, и҆ возми́тесѧ врата̀ вѣ̑чнаѧ: и҆ вни́детъ цр҃ь сла́вы."}, {"num": "и҃.", "text": "Кто́ є҆сть се́й цр҃ь сла́вы; гдⷭ҇ь крѣ́покъ и҆ си́ленъ, гдⷭ҇ь си́ленъ въ бра́ни."}, {"num": "ѳ҃.", "text": "Возми́те врата̀ кнѧ̑зи ва̑шѧ, и҆ возми́тесѧ врата̀ вѣ̑чнаѧ: и҆ вни́детъ цр҃ь сла́вы."}, {"num": "і҃.", "text": "Кто́ є҆сть се́й цр҃ь сла́вы; гдⷭ҇ь си́лъ, то́й є҆́сть цр҃ь сла́вы. Сла́ва:"}]}, "24": {"number": 24, "cu_numeral": "к҃д", "title": "Ѱало́мъ к҃д (24)", "subtitle": "Ѱало́мъ дв҃дꙋ, к҃д.", "verses": [{"num": "а҃.", "text": "Къ тебѣ̀, гдⷭ҇и, воздвиго́хъ дꙋ́шꙋ мою̀. бж҃е мо́й, на тѧ̀ ᲂу҆пова́хъ, да не постыжꙋ́сѧ во вѣ́къ, нижѐ да посмѣю́т ми сѧ вразѝ моѝ:"}, {"num": "в҃.", "text": "И҆́бо всѝ терпѧ́щїи тѧ̀ не постыдѧ́тсѧ."}, {"num": "г҃.", "text": "Да постыдѧ́тсѧ беззако́ннꙋющїи вотщѐ."}, {"num": "д҃.", "text": "Пꙋти̑ твоѧ̑, гдⷭ҇и, скажи́ ми, и҆ стезѧ́мъ твои̑мъ наꙋчи́ мѧ."}, {"num": "є҃.", "text": "Наста́ви мѧ̀ на и҆́стинꙋ твою̀, и҆ наꙋчи́ мѧ, ꙗ҆́кѡ ты̀ є҆сѝ бг҃ъ сп҃съ мо́й, и҆ тебѐ терпѣ́хъ ве́сь де́нь."}, {"num": "ѕ҃.", "text": "Помѧнѝ щедрѡ́ты твоѧ̑ гдⷭ҇и, и҆ млⷭ҇ти твоѧ̑, ꙗ҆́кѡ ѿ вѣ́ка"}, {"num": "з҃.", "text": "сꙋ́ть. Грѣ̑хъ ю҆́ности моеѧ̀, и҆ невѣ́дѣнїѧ моегѡ̀ не помѧнѝ: по млⷭ҇ти твое́й помѧни́ мѧ ты̀, ра́ди бл҃гости твоеѧ̀ гдⷭ҇и."}, {"num": "и҃.", "text": "Бл҃гъ и҆ пра́въ гдⷭ҇ь, сегѡ̀ ра́ди законоположи́тъ согрѣша́ющымъ на пꙋтѝ."}, {"num": "ѳ҃.", "text": "Наста́витъ крѡ́ткїѧ на сꙋ́дъ, наꙋчи́тъ крѡ́ткїѧ пꙋтє́мъ свои̑мъ."}, {"num": "і҃.", "text": "Всѝ пꙋтїѐ гдⷭ҇ни млⷭ҇ть и҆ и҆́стина, взыска́ющымъ завѣ́та є҆гѡ̀, и҆ свидѣ́нїѧ є҆гѡ̀."}, {"num": "а҃і.", "text": "Ра́ди и҆́мене твоегѡ,̀ гдⷭ҇и, и҆ ѡ҆чисти грѣ́хъ мо́й: мно́гъ бо є҆́сть."}, {"num": "в҃і.", "text": "Кто́ є҆сть человѣ́къ боѧ́йсѧ гдⷭ҇а; законоположи́тъ є҆мꙋ̀ на пꙋтѝ, є҆го́же и҆зво́ли."}, {"num": "г҃і.", "text": "Дꙋша̀ є҆гѡ̀ во бл҃ги́хъ водвори́тсѧ, и҆ сѣ́мѧ є҆гѡ̀ наслѣ́дитъ зе́млю."}, {"num": "д҃і.", "text": "Держа́ва гдⷭ҇ь боѧ́щихсѧ є҆гѡ̀, и҆ завѣ́тъ є҆гѡ̀ ꙗ҆ви́тъ и҆̀мъ. Ѻ҆́чи"}, {"num": "є҃і.", "text": "моѝ вы́нꙋ ко гдⷭ҇ꙋ, ꙗ҆́кѡ то́й и҆сто́ргнетъ ѿ сѣ́ти но́зѣ моѝ."}, {"num": "ѕ҃і.", "text": "При́зри на мѧ̀ и҆ поми́лꙋй мѧ̀, ꙗ҆́кѡ є҆диноро́дъ и҆ ни́щь є҆́смь а҆́зъ."}, {"num": "з҃і.", "text": "Скѡ́рби се́рдца моегѡ̀ ᲂу҆мно́жишасѧ, ѿ нꙋ́ждъ мои́хъ и҆зведи́ мѧ."}, {"num": "и҃і.", "text": "Ви́ждь смире́нїе моѐ, и҆ трꙋ́дъ мо́й, и҆ ѡ҆ста́ви всѧ̑ грѣхѝ моѧ̑."}, {"num": "ѳ҃і.", "text": "Ви́ждь врагѝ моѧ̑, ꙗ҆́кѡ ᲂу҆мно́жишасѧ, и҆ ненавидѣ́нїемъ непра́веднымъ возненави́дѣша мѧ̀."}, {"num": "к҃.", "text": "Сохранѝ дꙋ́шꙋ мою̀, и҆ и҆зба́ви мѧ̀, да не постыжꙋ́сѧ, ꙗ҆́кѡ ᲂу҆пова́хъ на тѧ̀."}, {"num": "к҃а.", "text": "Неѕло́бивїи и҆ пра́вїи прилѣплѧ́хꙋсѧ мнѣ̀, ꙗ҆́кѡ потерпѣ́хъ тѧ̀ гдⷭ҇и."}, {"num": "к҃в.", "text": "И҆зба́ви, бж҃е, і҆и҃лѧ ѿ всѣ́хъ скорбе́й є҆гѡ̀."}]}, "25": {"number": 25, "cu_numeral": "к҃є", "title": "Ѱало́мъ к҃є (25)", "subtitle": "Ѱало́мъ дв҃дꙋ, к҃є.", "verses": [{"num": "а҃.", "text": "Сꙋди́ ми, гдⷭ҇и, ꙗ҆́кѡ а҆́зъ неѕло́бою мое́ю ходи́хъ: и҆ на гдⷭ҇а ᲂу҆пова́ѧ не и҆знемогꙋ̀."}, {"num": "в҃.", "text": "И҆скꙋси́ мѧ, гдⷭ҇и, и҆ и҆спыта́й мѧ̀, разжжѝ ᲂу҆трѡ́бы моѧ̑ и҆ се́рдце моѐ."}, {"num": "г҃.", "text": "Ꙗ҆́кѡ млⷭ҇ть твоѧ̀ пред̾ ѻ҆чи́ма мои́ма є҆́сть, и҆ бл҃гоꙋгоди́хъ во и҆́стинѣ твое́й."}, {"num": "д҃.", "text": "Не сѣдо́хъ съ со́нмомъ сꙋ́етнымъ, и҆ со законопрестꙋ́пными не вни́дꙋ."}, {"num": "є҃.", "text": "Возненави́дѣхъ це́рковь лꙋка́внꙋющихъ, и҆ съ нечести́выми не сѧ́дꙋ."}, {"num": "ѕ҃.", "text": "Оу҆мы́ю въ непови́нныхъ рꙋ́цѣ моѝ, и҆ ѡ҆бы́дꙋ же́ртвенникъ тво́й, гдⷭ҇и:"}, {"num": "з҃.", "text": "Е҆́же ᲂу҆слы́шати мѝ гла́съ з҃ и҃ ѳ҃ і҃ а҃і в҃і моѝ, и҆ ѡ҆бы́дꙋ же́ртвенникъ тво́й, гдⷭ҇и: Е҆́же ᲂу҆слы́шати мѝ гла́съ хвалы̀ твоеѧ̀, и҆ повѣ́дати всѧ̑ чꙋдеса̀ твоѧ̑."}, {"num": "и҃.", "text": "Гдⷭ҇и, возлюби́хъ бл҃голѣ́пїе до́мꙋ твоегѡ̀, и҆ мѣ́сто селе́нїѧ сла́вы твоеѧ̀."}, {"num": "ѳ҃.", "text": "Да не погꙋби́ши съ нечести́выми дꙋ́шꙋ мою̀ и҆ съ мꙋ̑жи крове́й живо́тъ мо́й,"}, {"num": "і҃.", "text": "И҆́хже въ рꙋкꙋ̀ беззакѡ́нїѧ, десни́ца и҆́хъ и҆спо́лнисѧ мзды̀."}, {"num": "а҃і.", "text": "А҆́зъ же неѕло́бою мое́ю ходи́хъ: и҆зба́ви мѧ̀, гдⷭ҇и, и҆ поми́лꙋй мѧ̀."}, {"num": "в҃і.", "text": "Нога̀ моѧ̀ ста̀ на правотѣ̀: въ цр҃квахъ бл҃гословлю́ тѧ гдⷭ҇и."}]}, "26": {"number": 26, "cu_numeral": "к҃ѕ", "title": "Ѱало́мъ к҃ѕ (26)", "subtitle": "Ѱало́мъ дв҃дꙋ, пре́жде пома́занїѧ, к҃ѕ.", "verses": [{"num": "а҃.", "text": "Гдⷭ҇ь просвѣще́нїе моѐ и҆ сп҃си́тель мо́й, когѡ̀ ᲂу҆бою́сѧ; гдⷭ҇ь защи́титель живота̀ моегѡ̀, ѿ когѡ̀ ᲂу҆страшꙋ́сѧ;"}, {"num": "в҃.", "text": "Внегда̀ приближа́тисѧ на мѧ̀ ѕло́бꙋющымъ, є҆́же снѣ́сти плѡ́ти моѧ̑, ѡ҆скорблѧ́ющїи мѧ̀ и҆ вразѝ моѝ, ті́и и҆знемого́ша и҆ падо́ша."}, {"num": "г҃.", "text": "А҆́ще ѡ҆полчи́тсѧ на мѧ̀ по́лкъ, не ᲂу҆бои́тсѧ се́рдце моѐ: а҆́ще воста́нетъ на мѧ̀ бра́нь, на него̀ а҆́зъ ᲂу҆пова́ю."}, {"num": "д҃.", "text": "Е҆ди́но проси́хъ ѿ гдⷭ҇а, то̀ взыщꙋ̀: є҆́же жи́ти мѝ въ домꙋ̀ гдⷭ҇ни всѧ̑ дни̑ живота̀ моегѡ̀, зрѣ́ти мѝ красотꙋ̀ гдⷭ҇ню, и҆ посѣща́ти хра́мъ ст҃ы́й є҆гѡ̀."}, {"num": "є҃.", "text": "Ꙗ҆́кѡ скры́ мѧ въ селе́нїи свое́мъ, въ де́нь ѕѡ́лъ мои́хъ, покры́ мѧ въ та́йнѣ селе́нїѧ своегѡ̀, на ка́мень вознесе́ мѧ:"}, {"num": "ѕ҃.", "text": "И҆ ны́нѣ, сѐ вознесѐ главꙋ̀ мою̀ на врагѝ моѧ̑: ѡ҆быдо́хъ, и҆ пожро́хъ въ селе́нїи є҆гѡ̀ же́ртвꙋ хвале́нїѧ и҆ воскликнове́нїѧ: пою̀ и҆ воспою̀ гдⷭ҇еви."}, {"num": "з҃.", "text": "Оу҆слы́ши, гдⷭ҇и, гла́съ мо́й, и҆́мже воззва́хъ, поми́лꙋй мѧ̀, и҆ ᲂу҆слы́ши мѧ̀."}, {"num": "и҃.", "text": "Тебѣ̀ речѐ се́рдце моѐ: гдⷭ҇а взыщꙋ̀, взыска̀ тебѐ лицѐ моѐ, лица̀ твоегѡ̀, гдⷭ҇и, взыщꙋ̀."}, {"num": "ѳ҃.", "text": "Не ѿвратѝ лица̀ твоегѡ̀ ѿ менѐ, и҆ не ᲂу҆клони́сѧ гнѣ́вомъ ѿ раба̀ твоегѡ̀: помо́щникъ мо́й бꙋ́ди, не ѿри́ни менѐ, и҆ не ѡ҆ста́ви менѐ бж҃е сп҃си́телю мо́й."}, {"num": "і҃.", "text": "Ꙗ҆́кѡ ѻ҆те́цъ мо́й и҆ ма́ти моѧ̀ ѡ҆ста́виста мѧ̀, гдⷭ҇ь же воспрїѧ́тъ мѧ̀."}, {"num": "а҃і.", "text": "Законоположи́ ми, гдⷭ҇и, въ пꙋтѝ твое́мъ, и҆ наста́ви мѧ̀ на стезю̀ пра́вꙋю вра̑гъ мои́хъ ра́ди."}, {"num": "в҃і.", "text": "Не преда́ждь менѐ въ дꙋ́шы стꙋжа́ющихъ мѝ: ꙗ҆́кѡ воста́ша на мѧ̀ свидѣ́телє непра́веднїи, и҆ солга̀ непра́вда себѣ̀."}, {"num": "г҃і.", "text": "Вѣ́рꙋю ви́дѣти бл҃га̑ѧ гдⷭ҇нѧ на землѝ живы́хъ."}, {"num": "д҃і.", "text": "Потерпѝ гдⷭ҇а, мꙋжа́йсѧ, и҆ да крѣпи́тсѧ се́рдце твоѐ, и҆ потерпѝ гдⷭ҇а. Сла́ва:"}]}, "27": {"number": 27, "cu_numeral": "к҃з", "title": "Ѱало́мъ к҃з (27)", "subtitle": "Ѱало́мъ дв҃дꙋ, к҃з.", "verses": [{"num": "а҃.", "text": "Къ тебѣ̀, гдⷭ҇и, воззовꙋ̀, бж҃е мо́й, да не премолчи́ши ѿ менѐ: да не когда̀ премолчи́ши ѿ менѐ̀, и҆ ᲂу҆подо́блюсѧ низходѧ́щымъ въ ро́въ."}, {"num": "в҃.", "text": "Оу҆слы́ши, гдⷭ҇и, гла́съ моле́нїѧ моегѡ̀, внегда̀ моли́ти ми сѧ къ тебѣ̀, внегда̀ воздѣ́ти мѝ рꙋ́цѣ моѝ ко хра́мꙋ ст҃о́мꙋ твоемꙋ̀."}, {"num": "г҃.", "text": "Не привлецы̀ менѐ со грѣ̑шники, и҆ съ дѣ́лающими непра́вдꙋ не погꙋбѝ менѐ, глаго́лющими ми́ръ съ бли́жними свои́ми, ѕла̑ѧ же въ сердца́хъ свои́хъ."}, {"num": "д҃.", "text": "Да́ждь и҆̀мъ гдⷭ҇и, по дѣлѡ́мъ и҆́хъ, и҆ по лꙋка́вствꙋ начина́нїй и҆́хъ, по дѣлѡ́мъ рꙋкꙋ̀ и҆́хъ да́ждь и҆̀мъ, возда́ждь воздаѧ́нїе и҆́хъ и҆̀мъ."}, {"num": "є҃.", "text": "Ꙗ҆́кѡ не разꙋмѣ́ша въ дѣла̀ гдⷭ҇нѧ, и҆ въ дѣла̀ рꙋкꙋ̀ є҆гѡ̀: разори́ши ѧ҆̀, и҆ не сози́ждеши ѧ҆̀."}, {"num": "ѕ҃.", "text": "Бл҃гослове́нъ гдⷭ҇ь, ꙗ҆́кѡ ᲂу҆слы́ша гла́съ моле́нїѧ моегѡ̀."}, {"num": "з҃.", "text": "Гдⷭ҇ь помо́щникъ мо́й, и҆ защи́титель мо́й: на него̀ ᲂу҆пова̀ се́рдце моѐ, и҆ помо́же мѝ, и҆ процвѣтѐ пло́ть моѧ̀: и҆ во́лею мое́ю и҆сповѣ́мсѧ є҆мꙋ̀."}, {"num": "и҃.", "text": "Гдⷭ҇ь ᲂу҆твержде́нїе люде́й свои́хъ, и҆ защи́титель сп҃се́нїй хрїста̀ своегѡ̀ є҆́сть."}, {"num": "ѳ҃.", "text": "Сп҃сѝ лю́ди твоѧ̑, и҆ бл҃гословѝ достоѧ́нїе твоѐ, и҆ ᲂу҆пасѝ ѧ҆̀, и҆ возмѝ ѧ҆̀ до вѣ́ка."}]}, "28": {"number": 28, "cu_numeral": "к҃и", "title": "Ѱало́мъ к҃и (28)", "subtitle": "Ѱало́мъ дв҃дꙋ, и҆схо́да ски́нїи, к҃і.", "verses": [{"num": "а҃.", "text": "Принеси́те гдⷭ҇еви сы́нове бж҃їи, принеси́те гдⷭ҇еви сы́ны ѡ҆́вни:"}, {"num": "в҃.", "text": "принеси́те гдⷭ҇еви сла́вꙋ и҆ че́сть. Принеси́те гдⷭ҇еви сла́вꙋ и҆́мени є҆гѡ̀: поклони́тесѧ гдⷭ҇еви во дворѣ̀ ст҃ѣ́мъ є҆гѡ̀."}, {"num": "г҃.", "text": "Гла́съ гдⷭ҇ень на вода́хъ: бг҃ъ сла́вы возгремѣ̀, гдⷭ҇ь на вода́хъ мно́гихъ."}, {"num": "д҃.", "text": "Гла́съ гдⷭ҇ень въ крѣ́пости, гла́съ гдⷭ҇ень въ великолѣ́пїи."}, {"num": "є҃.", "text": "Гла́съ гдⷭ҇а сокрꙋша́ющагѡ ке́дры, и҆ стры́етъ гдⷭ҇ь ке́дры лїва̑нскїѧ."}, {"num": "ѕ҃.", "text": "И҆ и҆стни́тъ ѧ҆̀ ꙗ҆́кѡ тельца̀ лїва́нска: и҆ возлю́бленный ꙗ҆́кѡ сы́нъ є҆диноро́жь."}, {"num": "з҃.", "text": "Гла́съ гдⷭ҇а пресѣца́ющагѡ пла́мень ѻ҆гнѧ̀."}, {"num": "и҃.", "text": "Гла́съ гдⷭ҇а стрѧса́ющагѡ пꙋсты́ню: и҆ стрѧсе́тъ гдⷭ҇ь пꙋсты́ню кадді́йскꙋю."}, {"num": "ѳ҃.", "text": "Гла́съ гдⷭ҇ень сверша́ющїй є҆ле́ни, и҆ ѿкры́етъ дꙋбра̑вы: и҆ въ хра́мѣ є҆гѡ̀ всѧ́кїй глаго́летъ сла́вꙋ."}, {"num": "і҃.", "text": "Гдⷭ҇ь пото́пъ населѧ́етъ, и҆ сѧ́детъ гдⷭ҇ь цр҃ь въ вѣ́къ. Гдⷭ҇ь крѣ́пость лю́демъ свои̑мъ"}, {"num": "а҃і.", "text": "да́стъ, гдⷭ҇ь бл҃гослови́тъ лю́ди своѧ̑ ми́ромъ. а҃ Ѱало́мъ пѣ́сни ѡ҆бновле́нїѧ до́мꙋ дв҃дова, к҃ѳ."}]}, "29": {"number": 29, "cu_numeral": "к҃ѳ", "title": "Ѱало́мъ к҃ѳ (29)", "subtitle": "а҃ Ѱало́мъ пѣ́сни ѡ҆бновле́нїѧ до́мꙋ дв҃дова, к҃ѳ.", "verses": [{"num": "а҃.", "text": "Вознесꙋ́ тѧ, гдⷭ҇и, ꙗ҆́кѡ под̾ѧ́лъ мѧ̀ є҆сѝ, и҆ не возвесели́лъ є҆сѝ врагѡ́въ мои́хъ"}, {"num": "в҃.", "text": "ѡ҆ мнѣ̀. Гдⷭ҇и бж҃е мо́й, воззва́хъ къ тебѣ̀, и҆ и҆зцѣли́лъ мѧ̀ є҆сѝ."}, {"num": "г҃.", "text": "Гдⷭ҇и возве́лъ є҆сѝ ѿ а҆́да дꙋ́шꙋ мою̀, спа́слъ мѧ̀ є҆сѝ ѿ низходѧ́щихъ въ ро́въ."}, {"num": "д҃.", "text": "По́йте гдⷭ҇еви прпⷣбнїи є҆гѡ̀, и҆ и҆сповѣ́дайте па́мѧть ст҃ы́ни є҆гѡ̀."}, {"num": "є҃.", "text": "Ꙗ҆́кѡ гнѣ́въ въ ꙗ҆́рости є҆гѡ̀, и҆ живо́тъ въ во́ли є҆гѡ̀: ве́черъ водвори́тсѧ пла́чь, и҆ заꙋ́тра ра́дость."}, {"num": "ѕ҃.", "text": "А҆́зъ же рѣ́хъ во ѻ҆би́лїи мое́мъ: не подви́жꙋсѧ во вѣ́къ."}, {"num": "з҃.", "text": "Гдⷭ҇и, во́лею твое́ю пода́ждь добро́тѣ мое́й си́лꙋ. ѿврати́лъ же є҆сѝ лицѐ твоѐ, и҆ бы́хъ смꙋще́нъ."}, {"num": "и҃.", "text": "Къ тебѣ̀, гдⷭ҇и, воззовꙋ̀, и҆ къ бг҃ꙋ моемꙋ̀ помолю́сѧ."}, {"num": "ѳ҃.", "text": "Ка́ѧ по́льза въ кро́ви мое́й, внегда̀ сходи́ти мѝ во и҆стлѣ́нїе; є҆да̀ и҆сповѣ́стсѧ тебѣ̀ пе́рсть; и҆лѝ возвѣсти́тъ и҆́стинꙋ твою̀;"}, {"num": "і҃.", "text": "Слы́ша гдⷭ҇ь, и҆ поми́лова мѧ̀: гдⷭ҇ь бы́сть помо́щникъ мо́й."}, {"num": "а҃і.", "text": "Ѡ҆брати́лъ є҆сѝ пла́чь мо́й въ ра́дость мнѣ̀, растерза́лъ є҆сѝ вре́тище моѐ, и҆ препоѧ́салъ мѧ̀ є҆сѝ весе́лїемъ:"}, {"num": "в҃і.", "text": "Ꙗ҆́кѡ да воспое́тъ тебѣ̀ сла́ва моѧ̀, и҆ не ᲂу҆милю́сѧ. гдⷭ҇и бж҃е мо́й, во вѣ́къ и҆сповѣ́мсѧ тебѣ̀. Сла́ва: а҃ Въ коне́цъ, ѱало́мъ дв҃дꙋ, и҆зстꙋпле́нїѧ, л҃."}]}, "30": {"number": 30, "cu_numeral": "л҃", "title": "Ѱало́мъ л҃ (30)", "subtitle": "а҃ Въ коне́цъ, ѱало́мъ дв҃дꙋ, и҆зстꙋпле́нїѧ, л҃.", "verses": [{"num": "а҃.", "text": "На тѧ̀, гдⷭ҇и, ᲂу҆пова́хъ, да не постыжꙋ́сѧ во вѣ́къ: пра́вдою твое́ю и҆зба́ви мѧ̀ и҆ и҆зми́ мѧ."}, {"num": "в҃.", "text": "Приклонѝ ко мнѣ̀ ᲂу҆́хо твоѐ, ᲂу҆скорѝ и҆з̾ѧ́ти мѧ̀: бꙋ́ди мѝ въ бг҃а защи́тителѧ, и҆ въ до́мъ прибѣ́жища, є҆́же сп҃сти́ мѧ."}, {"num": "г҃.", "text": "Ꙗ҆́кѡ держа́ва моѧ̀, и҆ прибѣ́жище моѐ є҆сѝ ты̀, и҆ и҆́мене твоегѡ̀ ра́ди наста́виши мѧ̀, и҆ препита́еши мѧ̀."}, {"num": "д҃.", "text": "И҆зведе́ши мѧ̀ ѿ сѣ́ти сеѧ̀, ю҆́же скры́ша мѝ: ꙗ҆́кѡ ты̀ є҆сѝ защи́титель мо́й гдⷭ҇и:"}, {"num": "є҃.", "text": "Въ рꙋ́цѣ твоѝ предложꙋ̀ дꙋ́хъ мо́й: и҆зба́вилъ мѧ̀ є҆сѝ гдⷭ҇и бж҃е и҆́стины."}, {"num": "ѕ҃.", "text": "Возненави́дѣлъ є҆сѝ хранѧ́щыѧ сꙋєты̀ вотщѐ: а҆́зъ же на гдⷭ҇а ᲂу҆пова́хъ."}, {"num": "з҃.", "text": "Возра́дꙋюсѧ и҆ возвеселю́сѧ ѡ҆ млⷭ҇ти твое́й, ꙗ҆́кѡ призрѣ́лъ є҆сѝ на смире́нїе моѐ, спа́слъ є҆сѝ ѿ нꙋ́ждъ дꙋ́шꙋ мою̀:"}, {"num": "и҃.", "text": "И҆ нѣ́си менѐ затвори́лъ въ рꙋка́хъ вра́жїихъ, поста́вилъ є҆сѝ на простра́ннѣ но́зѣ моѝ."}, {"num": "ѳ҃.", "text": "Поми́лꙋй мѧ̀, гдⷭ҇и, ꙗ҆́кѡ скорблю̀: смѧте́сѧ ꙗ҆́ростїю ѻ҆́ко моѐ, дꙋша̀ моѧ̀ и҆ ᲂу҆тро́ба моѧ̀."}, {"num": "і҃.", "text": "Ꙗ҆́кѡ и҆зчезѐ въ болѣ́зни живо́тъ мо́й, и҆ лѣ̑та моѧ̑ въ воздыха́нїихъ: и҆знемо́же нището́ю крѣ́пость моѧ̀, и҆ кѡ́сти моѧ̑ смѧто́шасѧ."}, {"num": "а҃і.", "text": "Ѿ всѣ́хъ вра̑гъ мои́хъ бы́хъ поноше́нїе, и҆ сосѣ́дѡмъ мои̑мъ ѕѣлѡ̀, и҆ стра́хъ зна́ємымъ мои̑мъ: ви́дѧщїи мѧ̀ во́нъ бѣжа́ша ѿ менѐ. Забве́нъ бы́хъ, г҃і д҃і є҃і ѕ҃і з҃і и҃і ѳ҃і к҃ к҃а к҃в к҃г к҃д к҃є мымъ мои̑мъ: ви́дѧщїи мѧ̀ во́нъ бѣжа́ша ѿ менѐ."}, {"num": "в҃і.", "text": "Забве́нъ бы́хъ, ꙗ҆́кѡ ме́ртвъ ѿ се́рдца: бы́хъ ꙗ҆́кѡ сосꙋ́дъ погꙋбле́нъ."}, {"num": "г҃і.", "text": "Ꙗ҆́кѡ слы́шахъ гажде́нїе мно́гихъ живꙋ́щихъ ѻ҆́крестъ: внегда̀ собра́тисѧ и҆̀мъ вкꙋ́пѣ на мѧ̀, прїѧ́ти дꙋ́шꙋ мою̀ совѣща́ша."}, {"num": "д҃і.", "text": "А҆́зъ же на тѧ̀, гдⷭ҇и, ᲂу҆пова́хъ, рѣ́хъ: ты̀ є҆сѝ бг҃ъ мо́й."}, {"num": "є҃і.", "text": "Въ рꙋкꙋ̀ твоє́ю жрє́бїи моѝ. и҆зба́ви мѧ̀ и҆з̾ рꙋкѝ вра̑гъ мои́хъ, и҆ ѿ гонѧ́щихъ мѧ̀."}, {"num": "ѕ҃і.", "text": "Просвѣтѝ лицѐ твоѐ на раба̀ твоего̀, сп҃си́ мѧ млⷭ҇тїю твое́ю."}, {"num": "з҃і.", "text": "Гдⷭ҇и, да не постыжꙋ́сѧ, ꙗ҆́кѡ призва́хъ тѧ̀: да постыдѧ́тсѧ нечести́вїи, и҆ сни́дꙋтъ во а҆́дъ."}, {"num": "и҃і.", "text": "Нѣ́мы да бꙋ́дꙋтъ ᲂу҆стны̀ льсти̑выѧ, глаго́лющыѧ на првⷣнаго беззако́нїе, горды́нею и҆ ᲂу҆ничиже́нїемъ."}, {"num": "ѳ҃і.", "text": "Ко́ль мно́гое мно́жество бл҃гости твоеѧ̀, гдⷭ҇и, ю҆́же скры́лъ є҆сѝ боѧ́щымсѧ тебѐ, содѣ́лалъ є҆сѝ ᲂу҆пова́ющымъ на тѧ̀ пред̾ сы̑ны человѣ́ческими."}, {"num": "к҃.", "text": "Скры́еши и҆̀хъ въ та́йнѣ лица̀ твоегѡ̀ ѿ мѧте́жа человѣ́ческа, покры́еши и҆̀хъ въ кро́вѣ ѿ прерѣка́нїѧ ꙗ҆зы̑къ."}, {"num": "к҃а.", "text": "Бл҃гослове́нъ гдⷭ҇ь, ꙗ҆́кѡ ᲂу҆дивѝ млⷭ҇ть свою̀ во гра́дѣ ѡ҆гражде́нїѧ."}, {"num": "к҃в.", "text": "А҆́зъ же рѣ́хъ во и҆зстꙋпле́нїи мое́мъ: ѿве́рженъ є҆́смь ѿ лица̀ ѻ҆́чїю твоє́ю: сегѡ̀ ра́ди ᲂу҆слы́шалъ є҆сѝ гла́съ мл҃твы моеѧ̀, внегда̀ воззва́хъ къ тебѣ̀."}, {"num": "к҃г.", "text": "Возлюби́те гдⷭ҇а всѝ прпⷣбнїи є҆гѡ̀, ꙗ҆́кѡ и҆́стины взыска́етъ гдⷭ҇ь, и҆ воздае́тъ и҆зли́ше творѧ́щымъ горды́ню."}, {"num": "к҃д.", "text": "Мꙋжа́йтесѧ, и҆ да крѣпи́тсѧ се́рдце ва́ше, всѝ ᲂу҆пова́ющїи на гдⷭ҇а."}]}, "31": {"number": 31, "cu_numeral": "л҃а", "title": "Ѱало́мъ л҃а (31)", "subtitle": "Ѱало́мъ дв҃дꙋ, ра́зꙋма, л҃а.", "verses": [{"num": "а҃.", "text": "Бл҃же́ни, и҆́хже ѡ҆ста́вишасѧ беззакѡ́нїѧ, и҆ и҆́хже прикры́шасѧ грѣсѝ."}, {"num": "в҃.", "text": "Бл҃же́нъ мꙋ́жъ, є҆мꙋ́же не вмѣни́тъ гдⷭ҇ь грѣха̀, нижѐ є҆́сть во ᲂу҆стѣ́хъ є҆гѡ̀ ле́сть."}, {"num": "г҃.", "text": "Ꙗ҆́кѡ ᲂу҆молча́хъ, ѡ҆бетша́ша кѡ́сти моѧ̑, ѿ є҆́же зва́ти мѝ ве́сь де́нь:"}, {"num": "д҃.", "text": "Ꙗ҆́кѡ де́нь и҆ но́щь ѡ҆тѧготѣ̀ на мнѣ̀ рꙋка̀ твоѧ̀, возврати́хсѧ на стра́сть, є҆гда̀ ᲂу҆нзе́ ми те́рнъ."}, {"num": "є҃.", "text": "Беззако́нїе моѐ позна́хъ и҆ грѣха̀ моегѡ̀ не покры́хъ, рѣ́хъ: и҆сповѣ́мъ на мѧ̀ беззако́нїе моѐ гдⷭ҇еви: и҆ ты̀ ѡ҆ста́вилъ є҆сѝ нече́стїе се́рдца моегѡ̀."}, {"num": "ѕ҃.", "text": "За то̀ помо́литсѧ къ тебѣ̀ всѧ́къ прпⷣбный во вре́мѧ бл҃гопотре́бно: ѻ҆ба́че въ пото́пѣ во́дъ мно́гихъ къ"}, {"num": "з҃.", "text": "немꙋ̀ не прибли́жатсѧ. Ты̀ є҆сѝ прибѣ́жище моѐ ѿ ско́рби ѡ҆бдержа́щїѧ мѧ̀: ра́досте моѧ̀, и҆зба́ви мѧ̀ ѿ ѡ҆быше́дшихъ мѧ̀."}, {"num": "и҃.", "text": "Вразꙋмлю́ тѧ, и҆ наста́влю тѧ̀ на пꙋ́ть се́й, во́ньже по́йдеши: ᲂу҆твержꙋ̀ на тѧ̀ ѻ҆́чи моѝ."}, {"num": "ѳ҃.", "text": "Не бꙋ́дите ꙗ҆́кѡ ко́нь и҆ ме́скъ, и҆́мже нѣ́сть ра́зꙋма: брозда́ми и҆ ᲂу҆здо́ю чє́люсти и҆́хъ востѧ́гнеши, не приближа́ющихсѧ къ тебѣ̀."}, {"num": "і҃.", "text": "Мнѡ́ги ра̑ны грѣ́шномꙋ: і҃ а҃і востѧ́гнеши, не приближа́ющихсѧ къ тебѣ̀. Мнѡ́ги ра̑ны грѣ́шномꙋ: ᲂу҆пова́ющаго же на гдⷭ҇а млⷭ҇ть ѡ҆бы́детъ."}, {"num": "а҃і.", "text": "Весели́тесѧ ѡ҆ гдⷭ҇ѣ, и҆ ра́дꙋйтесѧ првⷣнїи, и҆ хвали́тесѧ всѝ пра́вїи срⷣцемъ. Сла́ва:"}]}, "32": {"number": 32, "cu_numeral": "л҃в", "title": "Ѱало́мъ л҃в (32)", "subtitle": "Ѱало́мъ дв҃дꙋ, не надпи́санъ ᲂу҆ є҆врє́й, л҃в.", "verses": [{"num": "а҃.", "text": "Ра́дꙋйтесѧ првⷣнїи, ѡ҆ гдⷭ҇ѣ, пра̑вымъ подоба́етъ похвала̀."}, {"num": "в҃.", "text": "И҆сповѣ́дайтесѧ гдⷭ҇еви въ гꙋ́слехъ, во ѱалти́ри десѧтострꙋ́ннѣмъ по́йте є҆мꙋ̀:"}, {"num": "г҃.", "text": "Воспо́йте є҆мꙋ̀ пѣ́снь но́вꙋ, до́брѣ по́йте є҆мꙋ̀ со восклица́нїемъ:"}, {"num": "д҃.", "text": "Ꙗ҆́кѡ пра́во"}, {"num": "є҃.", "text": "сло́во гдⷭ҇не, и҆ всѧ̑ дѣла̀ є҆гѡ̀ въ вѣ́рѣ. Лю́битъ млⷭ҇тыню и҆ сꙋ́дъ гдⷭ҇ь, млⷭ҇ти гдⷭ҇ни и҆спо́лнь землѧ̀."}, {"num": "ѕ҃.", "text": "Сло́вомъ гдⷭ҇нимъ нб҃са̀ ᲂу҆тверди́шасѧ, и҆ дх҃омъ ᲂу҆́стъ є҆гѡ̀ всѧ̀ си́ла и҆́хъ."}, {"num": "з҃.", "text": "Собира́ѧй ꙗ҆́кѡ мѣ́хъ во́ды морскі̑ѧ, полага́ѧй въ сокро́вищихъ бе́здны."}, {"num": "и҃.", "text": "Да ᲂу҆бои́тсѧ гдⷭ҇а всѧ̀ землѧ̀, ѿ негѡ́же да подви́жꙋтсѧ всѝ живꙋ́щїи по вселе́ннѣй:"}, {"num": "ѳ҃.", "text": "Ꙗ҆́кѡ то́й речѐ, и҆ бы́ша: то́й повелѣ̀, и҆ созда́шасѧ."}, {"num": "і҃.", "text": "Гдⷭ҇ь разорѧ́етъ совѣ́ты ꙗ҆зы́кѡвъ, ѿмета́етъ же мы̑сли люде́й, и҆ ѿмета́етъ совѣ́ты кнѧзе́й."}, {"num": "а҃і.", "text": "Совѣ́тъ же гдⷭ҇ень во вѣ́къ пребыва́етъ, помышлє́нїѧ се́рдца є҆гѡ̀ въ ро́дъ и҆ ро́дъ."}, {"num": "в҃і.", "text": "Бл҃же́нъ ꙗ҆зы́къ, є҆мꙋ́же є҆́сть гдⷭ҇ь бг҃ъ є҆гѡ̀, лю́ди, ꙗ҆̀же и҆збра̀ въ наслѣ́дїе себѣ̀."}, {"num": "г҃і.", "text": "Съ нб҃сѐ призрѣ̀ гдⷭ҇ь, ви́дѣ всѧ̑ сы́ны человѣ́чєскїѧ:"}, {"num": "д҃і.", "text": "Ѿ гото́вагѡ жили́ща своегѡ̀ призрѣ̀ на всѧ̑ живꙋ́щыѧ на землѝ:"}, {"num": "є҃і.", "text": "Созда́вый на є҆ди́нѣ сердца̀ и҆́хъ, разꙋмѣва́ѧй на всѧ̑ дѣла̀ и҆́хъ."}, {"num": "ѕ҃і.", "text": "Не спаса́етсѧ ца́рь мно́гою си́лою, и҆ и҆споли́нъ не спасе́тсѧ мно́жествомъ крѣ́пости своеѧ̀:"}, {"num": "з҃і.", "text": "Ло́жь ко́нь во спасе́нїе, во мно́жествѣ же си́лы своеѧ̀ не спасе́тсѧ."}, {"num": "и҃і.", "text": "Сѐ, ѻ҆́чи гдⷭ҇ни на боѧ́щыѧсѧ є҆гѡ̀, ᲂу҆пова́ющыѧ на млⷭ҇ть є҆гѡ̀:"}, {"num": "ѳ҃і.", "text": "И҆зба́вити ѿ сме́рти дꙋ́шы и҆́хъ, и҆ препита́ти ѧ҆̀ въ гла́дъ."}, {"num": "к҃.", "text": "Дꙋша́ же на́ша ча́етъ гдⷭ҇а, ꙗ҆́кѡ помо́щникъ и҆ защи́титель на́шъ є҆́сть:"}, {"num": "к҃а.", "text": "Ꙗ҆́кѡ ѡ҆ не́мъ возвесели́тсѧ се́рдце на́ше, и҆ во и҆́мѧ ст҃о́е є҆гѡ̀ ᲂу҆пова́хомъ."}, {"num": "к҃в.", "text": "Бꙋ́ди, гдⷭ҇и, млⷭ҇ть твоѧ̀ на на́съ, ꙗ҆́коже ᲂу҆пова́хомъ на тѧ̀. а҃ Ѱало́мъ дв҃дꙋ, внегда̀ и҆змѣнѝ лицѐ своѐ пред̾ а҆вїмеле́хомъ: и҆ ѿпꙋстѝ є҆го̀, и҆ ѿи́де, л҃г."}]}, "33": {"number": 33, "cu_numeral": "л҃г", "title": "Ѱало́мъ л҃г (33)", "subtitle": "и҆ ѿпꙋстѝ є҆го̀, и҆ ѿи́де, л҃г.", "verses": [{"num": "а҃.", "text": "Благословлю̀ гдⷭ҇а на всѧ́кое вре́мѧ, вы́нꙋ хвала̀ є҆гѡ̀ во ᲂу҆стѣ́хъ мои́хъ."}, {"num": "в҃.", "text": "Ѡ҆ гдⷭ҇ѣ похва́литсѧ дꙋша̀ моѧ̀: да ᲂу҆слы́шатъ кро́тцыи, и҆ возвеселѧ́тсѧ."}, {"num": "г҃.", "text": "Возвели́чите гдⷭ҇а"}, {"num": "д҃.", "text": "со мно́ю, и҆ вознесе́мъ и҆́мѧ є҆гѡ̀ вкꙋ́пѣ. Взыска́хъ гдⷭ҇а, и҆ ᲂу҆слы́ша мѧ̀, и҆ ѿ всѣ́хъ скорбе́й мои́хъ и҆зба́ви мѧ̀."}, {"num": "є҃.", "text": "Пристꙋпи́те къ немꙋ̀, и҆ просвѣти́тесѧ, и҆ ли́ца ва̑ша не постыдѧ́тсѧ."}, {"num": "ѕ҃.", "text": "Се́й ни́щїй воззва̀, и҆ гдⷭ҇ь ᲂу҆слы́ша и҆̀, и҆ ѿ всѣ́хъ скорбе́й є҆гѡ̀ спасѐ и҆̀."}, {"num": "з҃.", "text": "Ѡ҆полчи́тсѧ а҆́гг҃лъ гдⷭ҇ень ѻ҆́крестъ боѧ́щихсѧ и҃ ѳ҃ і҃ а҃і в҃і г҃і д҃і є҃і ѕ҃і з҃і и҃і ѳ҃і к҃ к҃а к҃в к҃г скорбе́й є҆гѡ̀ спасѐ и҆̀. Ѡ҆полчи́тсѧ а҆́гг҃лъ гдⷭ҇ень ѻ҆́крестъ боѧ́щихсѧ є҆гѡ̀, и҆ и҆зба́витъ и҆̀хъ."}, {"num": "и҃.", "text": "Вкꙋси́те и҆ ви́дите, ꙗ҆́кѡ бл҃гъ гдⷭ҇ь: бл҃же́нъ мꙋ́жъ, и҆́же ᲂу҆пова́етъ"}, {"num": "ѳ҃.", "text": "на́нь. Бо́йтесѧ гдⷭ҇а, всѝ ст҃і́и є҆гѡ̀, ꙗ҆́кѡ нѣ́сть лише́нїѧ боѧ́щымсѧ є҆гѡ̀."}, {"num": "і҃.", "text": "Бога́тїи ѡ҆бнища́ша и҆ взалка́ша: взыска́ющїи же гдⷭ҇а не лиша́тсѧ всѧ́кагѡ бл҃га."}, {"num": "а҃і.", "text": "Прїиди́те, ча̑да, послꙋ́шайте менѐ, стра́хꙋ гдⷭ҇ню наꙋчꙋ̀ ва́съ."}, {"num": "в҃і.", "text": "Кто́ є҆сть человѣ́къ хотѧ́й живо́тъ, любѧ́й дни̑ ви́дѣти бл҃ги;"}, {"num": "г҃і.", "text": "Оу҆держѝ ѧ҆зы́къ"}, {"num": "д҃і.", "text": "тво́й ѿ ѕла̀, и҆ ᲂу҆стнѣ̀ твоѝ, є҆́же не глаго́лати льстѝ. Оу҆клони́сѧ ѿ ѕла̀, и҆ сотворѝ бл҃го: взыщѝ ми́ра, и҆ поженѝ и҆̀."}, {"num": "є҃і.", "text": "Ѻ҆́чи гдⷭ҇ни на првⷣныѧ, и҆ ᲂу҆́ши є҆гѡ̀ въ мл҃́твꙋ и҆́хъ:"}, {"num": "ѕ҃і.", "text": "Лице́ же гдⷭ҇не на творѧ́щыѧ ѕла̑ѧ, є҆́же потреби́ти ѿ землѝ па́мѧть и҆́хъ."}, {"num": "з҃і.", "text": "Воззва́ша првⷣнїи, и҆ гдⷭ҇ь ᲂу҆слы́ша и҆̀хъ, и҆ ѿ всѣ́хъ скорбе́й и҆́хъ и҆зба́ви и҆̀хъ."}, {"num": "и҃і.", "text": "Бли́з̾ гдⷭ҇ь сокрꙋше́нныхъ се́рдцемъ, и҆ смирє́нныѧ дꙋ́хомъ сп҃се́тъ."}, {"num": "ѳ҃і.", "text": "Мнѡ́ги скѡ́рби првⷣнымъ, и҆ ѿ всѣ́хъ и҆́хъ и҆зба́витъ ѧ҆̀ гдⷭ҇ь."}, {"num": "к҃.", "text": "Храни́тъ гдⷭ҇ь всѧ̑ кѡ́сти и҆́хъ, ни є҆ди́на ѿ ни́хъ сокрꙋши́тсѧ."}, {"num": "к҃а.", "text": "Сме́рть грѣ́шникѡвъ люта̀, и҆ ненави́дѧщїи првⷣнаго прегрѣша́тъ."}, {"num": "к҃в.", "text": "И҆зба́витъ гдⷭ҇ь дꙋ́шы ра̑бъ свои́хъ, и҆ не прегрѣша́тъ всѝ ᲂу҆пова́ющїи на него̀. Сла́ва:"}]}, "34": {"number": 34, "cu_numeral": "л҃д", "title": "Ѱало́мъ л҃д (34)", "subtitle": "Ѱало́мъ дв҃дꙋ, л҃д.", "verses": [{"num": "а҃.", "text": "Сꙋдѝ, гдⷭ҇и, ѡ҆би́дѧщыѧ мѧ̀, поборѝ борю́щыѧ мѧ̀."}, {"num": "в҃.", "text": "Прїимѝ ѡ҆рꙋ́жїе и҆ щи́тъ и҆ воста́ни въ по́мощь мою̀:"}, {"num": "г҃.", "text": "И҆зсꙋ́ни ме́чь, и҆ заключѝ сопроти́въ гонѧ́щихъ мѧ̀: рцы̀ дꙋшѝ мое́й, сп҃се́нїе твоѐ є҆́смь а҆́зъ."}, {"num": "д҃.", "text": "Да постыдѧ́тсѧ и҆ посра́мѧтсѧ и҆́щꙋщїи дꙋ́шꙋ мою̀, да возвратѧ́тсѧ вспѧ́ть, и҆ постыдѧ́тсѧ мы́слѧщїи мѝ ѕла̑ѧ."}, {"num": "є҃.", "text": "Да бꙋ́дꙋтъ ꙗ҆́кѡ пра́хъ пред̾ лице́мъ вѣ́тра, и҆ а҆́гг҃лъ гдⷭ҇ень ѡ҆скорблѧ́ѧ и҆̀хъ:"}, {"num": "ѕ҃.", "text": "Да бꙋ́детъ пꙋ́ть и҆́хъ тьма̀ и҆ по́лзокъ, и҆ а҆́гг҃лъ гдⷭ҇ень погонѧ́ѧй и҆̀хъ."}, {"num": "з҃.", "text": "Ꙗ҆́кѡ тꙋ́не скры́ша мѝ па́гꙋбꙋ сѣ́ти своеѧ̀, всꙋ́е поноси́ша дꙋшѝ мое́й."}, {"num": "и҃.", "text": "Да прїи́детъ є҆мꙋ̀ сѣ́ть, ю҆́же не вѣ́сть, и҆ лови́тва, ю҆́же скры̀, да ѡ҆бы́метъ и҆̀, и҆ въ сѣ́ть да впаде́тъ въ ню̀."}, {"num": "ѳ҃.", "text": "Дꙋша́ же моѧ̀ возра́дꙋетсѧ ѡ҆ гдⷭ҇ѣ, возвесели́тсѧ ѡ҆ сп҃се́нїи є҆гѡ̀."}, {"num": "і҃.", "text": "Всѧ̑ кѡ́сти моѧ̑ рекꙋ́тъ: гдⷭ҇и, гдⷭ҇и, кто̀ подо́бенъ тебѣ̀, и҆збавлѧ́ѧй ни́ща и҆з̾ рꙋкѝ крѣ́пльшихъ є҆гѡ̀, и҆ ни́ща и҆ ᲂу҆бо́га ѿ расхища́ющихъ є҆го̀."}, {"num": "а҃і.", "text": "Воста́вше на мѧ̀ свидѣ́телє непра́веднїи, ꙗ҆̀же не вѣ́дѧхъ, вопроша́хꙋ мѧ̀."}, {"num": "в҃і.", "text": "Возда́ша мѝ, лꙋка̑ваѧ воз̾ бл҃га̑ѧ, и҆ безча́дїе дꙋшѝ мое́й."}, {"num": "г҃і.", "text": "А҆́зъ же, внегда̀ ѻ҆нѝ стꙋжа́хꙋ мѝ, ѡ҆блача́хсѧ во вре́тище, и҆ смирѧ́хъ посто́мъ дꙋ́шꙋ мою̀, и҆ моли́тва д҃і є҃і ѕ҃і з҃і и҃і ѳ҃і к҃ к҃а к҃в к҃г к҃д к҃є к҃ѕ к҃з к҃и ѡ҆блача́хсѧ во вре́тище, и҆ смирѧ́хъ посто́мъ дꙋ́шꙋ мою̀, и҆ моли́тва моѧ̀ въ нѣ́дро моѐ возврати́тсѧ."}, {"num": "д҃і.", "text": "Ꙗ҆́кѡ бли́жнемꙋ, ꙗ҆́кѡ бра́тꙋ на́шемꙋ, та́кѡ ᲂу҆гожда́хъ: ꙗ҆́кѡ пла́чѧ и҆ сѣ́тꙋѧ, та́кѡ смирѧ́хсѧ."}, {"num": "є҃і.", "text": "И҆ на мѧ̀ возвесели́шасѧ и҆ собра́шасѧ: собра́шасѧ на мѧ̀ ра̑ны, и҆ не позна́хъ, раздѣли́шасѧ, и҆ не ᲂу҆мили́шасѧ."}, {"num": "ѕ҃і.", "text": "И҆скꙋси́ша мѧ̀, подражни́ша мѧ̀ подражне́нїемъ, поскрежета́ша на мѧ̀ зꙋбы̀ свои́ми."}, {"num": "з҃і.", "text": "Гдⷭ҇и, когда̀ ᲂу҆́зриши, ᲂу҆стро́й дꙋ́шꙋ мою̀ ѿ ѕлодѣ́йства и҆́хъ, ѿ лє́въ є҆диноро́днꙋю мою̀."}, {"num": "и҃і.", "text": "И҆сповѣ́мсѧ тебѣ̀ въ цр҃кви мно́зѣ, въ лю́дехъ тѧ́жцѣхъ восхвалю́ тѧ."}, {"num": "ѳ҃і.", "text": "Да не возра́дꙋютсѧ ѡ҆ мнѣ̀ враждꙋ́ющїи мѝ непра́веднѡ, ненави́дѧщїи мѧ̀ тꙋ́не, и҆ помиза́ющїи ѻ҆чи́ма."}, {"num": "к҃.", "text": "Ꙗ҆́кѡ мнѣ̀ ᲂу҆́бѡ ми̑рнаѧ глаго́лахꙋ,"}, {"num": "к҃а.", "text": "и҆ на гнѣ́въ ле́сти помышлѧ́хꙋ. Расшири́ша на мѧ̀ ᲂу҆ста̀ своѧ̑, рѣ́ша: бла́гоже бла́гоже,"}, {"num": "к҃в.", "text": "ви́дѣша ѻ҆́чи на́ши. Ви́дѣлъ є҆сѝ, гдⷭ҇и, да не премолчи́ши: гдⷭ҇и, не ѿстꙋпѝ ѿ менѐ."}, {"num": "к҃г.", "text": "Воста́ни, гдⷭ҇и, и҆ вонмѝ сꙋдꙋ̀ моемꙋ̀, бж҃е мо́й, и҆ гдⷭ҇и мо́й, на прю̀ мою̀."}, {"num": "к҃д.", "text": "Сꙋди́ ми, гдⷭ҇и, по пра́вдѣ твое́й, гдⷭ҇и бж҃е мо́й, и҆ да не возра́дꙋютсѧ ѡ҆ мнѣ̀."}, {"num": "к҃є.", "text": "Да не рекꙋ́тъ въ сердца́хъ свои́хъ: бла́гоже бла́гоже дꙋшѝ на́шей, нижѐ да рекꙋ́тъ: пожро́хомъ є҆го̀."}, {"num": "к҃ѕ.", "text": "Да постыдѧ́тсѧ и҆ посра́мѧтсѧ вкꙋ́пѣ ра́дꙋющїисѧ ѕлѡ́мъ мои̑мъ: да ѡ҆блекꙋ́тсѧ въ стꙋ́дъ и҆ сра́мъ велерѣ́чꙋющїи на мѧ̀."}, {"num": "к҃з.", "text": "Да возра́дꙋютсѧ"}, {"num": "к҃и.", "text": "и҆ возвеселѧ́тсѧ хотѧ́щїи пра́вды моеѧ̀: и҆ да рекꙋ́тъ вы́нꙋ, да возвели́читсѧ гдⷭ҇ь, хотѧ́щїи ми́ра рабꙋ̀ є҆гѡ̀. И҆ ѧ҆зы́къ мо́й поꙋчи́тсѧ пра́вдѣ твое́й, ве́сь де́нь хвалѣ̀ твое́й. а҃ Въ коне́цъ, ѻ҆́трокꙋ гдⷭ҇ню дв҃дꙋ, л҃є."}]}, "35": {"number": 35, "cu_numeral": "л҃є", "title": "Ѱало́мъ л҃є (35)", "subtitle": "а҃ Въ коне́цъ, ѻ҆́трокꙋ гдⷭ҇ню дв҃дꙋ, л҃є.", "verses": [{"num": "а҃.", "text": "Глаго́летъ пребеззако́нный согрѣша́ти въ себѣ̀: нѣ́сть стра́ха бж҃їѧ пред̾ ѻ҆чи́ма є҆гѡ̀."}, {"num": "в҃.", "text": "Ꙗ҆́кѡ ᲂу҆льстѝ пред̾ ни́мъ ѡ҆брѣстѝ беззако́нїе своѐ, и҆ возненави́дѣти."}, {"num": "г҃.", "text": "Глаго́лы ᲂу҆́стъ є҆гѡ̀ беззако́нїе и҆ ле́сть: не восхотѣ̀ разꙋмѣ́ти є҆́же ᲂу҆блажи́ти."}, {"num": "д҃.", "text": "Беззако́нїе помы́сли на ло́жи свое́мъ: предста̀ всѧ́комꙋ пꙋтѝ небла́гꙋ, ѡ҆ ѕло́бѣ же не негодова̀."}, {"num": "є҃.", "text": "Гдⷭ҇и, на нб҃сѝ млⷭ҇ть твоѧ̀, и҆ и҆́стина твоѧ̀ до ѡ҆́блакъ:"}, {"num": "ѕ҃.", "text": "Пра́вда твоѧ̀ ꙗ҆́кѡ го́ры бж҃їѧ, сꙋдьбы̑ твоѧ̑ бе́здна мно́га: человѣ́ки и҆ скоты̀ сп҃се́ши, гдⷭ҇и."}, {"num": "з҃.", "text": "Ꙗ҆́кѡ ᲂу҆мно́жилъ є҆сѝ млⷭ҇ть твою̀, бж҃е: сы́нове же человѣ́честїи въ кро́вѣ крилꙋ̑ твоє́ю надѣ́ѧтисѧ и҆́мꙋтъ."}, {"num": "и҃.", "text": "Оу҆пїю́тсѧ ѿ тꙋ́ка до́мꙋ твоегѡ̀, и҆ пото́комъ сла́дости твоеѧ̀ напои́ши ѧ҆̀."}, {"num": "ѳ҃.", "text": "Ꙗ҆́кѡ ᲂу҆ тебѐ̀ и҆сто́чникъ живота̀, во свѣ́тѣ твое́мъ ᲂу҆́зримъ свѣ́тъ."}, {"num": "і҃.", "text": "Проба́ви млⷭ҇ть твою̀ вѣ́дꙋщымъ тѧ̀, и҆ пра́вдꙋ твою̀ пра̑вымъ се́рдцемъ."}, {"num": "а҃і.", "text": "Да не прїи́детъ мнѣ̀ нога̀ горды́ни, и҆ рꙋка̀ грѣ́шнича да не в҃і г҃і се́рдцемъ. Да не прїи́детъ мнѣ̀ нога̀ горды́ни, и҆ рꙋка̀ грѣ́шнича да не подви́житъ менѐ."}, {"num": "в҃і.", "text": "Та́мѡ падо́ша всѝ дѣ́лающїи беззако́нїе, и҆зринове́ни бы́ша, и҆ не возмо́гꙋтъ ста́ти. Сла́ва:"}]}, "36": {"number": 36, "cu_numeral": "л҃ѕ", "title": "Ѱало́мъ л҃ѕ (36)", "subtitle": "Ѱало́мъ дв҃дꙋ, л҃ѕ.", "verses": [{"num": "а҃.", "text": "Не ревнꙋ́й лꙋка́внꙋющымъ, нижѐ зави́ди творѧ́щымъ беззако́нїе."}, {"num": "в҃.", "text": "Занѐ ꙗ҆́кѡ трава̀ ско́рѡ и҆́зсшꙋтъ и҆ ꙗ҆́кѡ ѕе́лїе ѕла́ка ско́рѡ ѿпадꙋ́тъ. Оу҆пова́й на гдⷭ҇а, и҆ творѝ бл҃госты́ню, и҆ населѝ зе́млю, и҆ ᲂу҆пасе́шисѧ въ бога́тствѣ є҆ѧ̀. Наслади́сѧ гдⷭ҇еви, и҆ да́стъ тѝ прошє́нїѧ се́рдца твоегѡ̀. Ѿкры́й ко гдⷭ҇ꙋ пꙋ́ть тво́й, и҆"}, {"num": "г҃.", "text": "ᲂу҆пова́й на него̀, и҆ то́й сотвори́тъ. И҆ и҆зведе́тъ ꙗ҆́кѡ свѣ́тъ пра́вдꙋ твою̀, и҆ сꙋдьбꙋ̀ твою̀ ꙗ҆́кѡ полꙋ́дне. Повини́сѧ гдⷭ҇еви, и҆ ᲂу҆молѝ є҆го̀. не ревнꙋ́й спѣ́ющемꙋ въ пꙋтѝ свое́мъ, человѣ́кꙋ творѧ́щемꙋ законопрестꙋпле́нїе. Преста́ни ѿ гнѣ́ва, и҆ ѡ҆ста́ви ꙗ҆́рость, не ревнꙋ́й, є҆́же лꙋка́вновати. Занѐ лꙋка́внꙋющїи потребѧ́тсѧ: терпѧ́щїи же гдⷭ҇а, ті́и"}, {"num": "д҃.", "text": "наслѣ́дѧтъ зе́млю. И҆ є҆щѐ ма́лѡ, и҆ не бꙋ́детъ грѣ́шника: и҆"}, {"num": "є҃.", "text": "взы́щеши мѣ́сто є҆гѡ̀,"}, {"num": "ѕ҃.", "text": "и҆ не ѡ҆брѧ́щеши. Кро́тцыи же"}, {"num": "з҃.", "text": "наслѣ́дѧтъ зе́млю, и҆ насладѧ́тсѧ ѡ҆ мно́жествѣ ми́ра. Назира́етъ грѣ́шный првⷣнаго,"}, {"num": "и҃.", "text": "и҆ поскреже́щетъ на́нь зꙋбы̀ свои́ми. Гдⷭ҇ь же посмѣе́тсѧ є҆мꙋ̀,"}, {"num": "ѳ҃.", "text": "занѐ прозира́етъ, ꙗ҆́кѡ прїи́детъ де́нь є҆гѡ̀. Ме́чь и҆звлеко́ша грѣ̑шницы, напрѧго́ша лꙋ́къ сво́й, низложи́ти ᲂу҆бо́га"}, {"num": "і҃.", "text": "и҆ ни́ща, закла́ти пра̑выѧ се́рдцемъ. Ме́чь и҆́хъ да вни́детъ въ сердца̀ и҆́хъ, и҆ лꙋ́цы и҆́хъ да сокрꙋша́тсѧ. Лꙋ́чше ма́лое првⷣникꙋ, па́че бога́тства грѣ́шныхъ мно́га. Занѐ мы̑шцы грѣ́шныхъ сокрꙋша́тсѧ,"}, {"num": "а҃і.", "text": "ᲂу҆твержда́етъ же првⷣныѧ гдⷭ҇ь. Вѣ́сть гдⷭ҇ь пꙋти̑ непоро́чныхъ, и҆"}, {"num": "в҃і.", "text": "достоѧ́нїе и҆́хъ въ вѣ́къ бꙋ́детъ. Не постыдѧ́тсѧ во вре́мѧ лю́тое, и҆ во дне́хъ гла́да насы́тѧтсѧ: ꙗ҆́кѡ грѣ̑шницы поги́бнꙋтъ."}, {"num": "г҃і.", "text": "Врази́ же гдⷭ҇ни, кꙋ́пнѡ просла́витисѧ и҆̀мъ и҆ вознести́сѧ, и҆зчеза́юще"}, {"num": "д҃і.", "text": "ꙗ҆́кѡ ды́мъ и҆зчезо́ша. Зае́млетъ грѣ́шный, и҆ не возврати́тъ, првⷣный"}, {"num": "є҃і.", "text": "же ще́дритъ, и҆ дае́тъ. Ꙗ҆́кѡ бл҃гословѧ́щїи є҆го̀ наслѣ́дѧтъ зе́млю,"}, {"num": "ѕ҃і.", "text": "кленꙋ́щїи же є҆го̀ потребѧ́тсѧ. Ѿ гдⷭ҇а стѡпы̀ человѣ́кꙋ и҆справлѧ́ютсѧ,"}, {"num": "з҃і.", "text": "и҆ пꙋтѝ є҆гѡ̀ восхо́щетъ ѕѣлѡ̀. Е҆гда̀ паде́тъ, не разбїе́тсѧ,"}, {"num": "и҃і.", "text": "ꙗ҆́кѡ гдⷭ҇ь подкрѣплѧ́етъ рꙋ́кꙋ є҆гѡ̀. Ю҆нѣ́йшїй бы́хъ, и҆́бо состарѣ́хсѧ, и҆"}, {"num": "ѳ҃і.", "text": "не ви́дѣхъ првⷣника ѡ҆ста́влена, нижѐ сѣ́мене є҆гѡ̀ просѧ́ща хлѣ́бы."}, {"num": "к҃.", "text": "Ве́сь де́нь ми́лꙋетъ, и҆ взаи́мъ"}, {"num": "к҃а.", "text": "дае́тъ првⷣный, и҆ сѣ́мѧ є҆гѡ̀ во бл҃гослове́нїе бꙋ́детъ. Оу҆клони́сѧ ѿ ѕла̀, и҆ сотворѝ бл҃го, и҆ к҃з к҃и к҃ѳ л҃ л҃а л҃в л҃г л҃д л҃є л҃ѕ л҃з л҃҃и л҃ѳ м҃ є҆гѡ̀ во бл҃гослове́нїе бꙋ́детъ. Оу҆клони́сѧ ѿ ѕла̀, и҆ сотворѝ бл҃го, и҆ всели́сѧ въ вѣ́къ вѣ́ка."}, {"num": "к҃в.", "text": "Ꙗ҆́кѡ гдⷭ҇ь лю́битъ сꙋ́дъ, и҆ не ѡ҆ста́витъ прпⷣбныхъ свои́хъ, во вѣ́къ сохранѧ́тсѧ: беззакѡ́нницы же и҆зженꙋ́тсѧ, и҆ сѣ́мѧ нечести́выхъ потреби́тсѧ. Првⷣницы же наслѣ́дѧтъ зе́млю, и҆ вселѧ́тсѧ въ вѣ́къ вѣ́ка на не́й. Оу҆ста̀ првⷣнагѡ поꙋча́тсѧ премⷣрости, и҆ ѧ҆зы́къ є҆гѡ̀ возглаго́летъ сꙋ́дъ. Зако́нъ бг҃а є҆гѡ̀ се́рдцѣ є҆гѡ̀, и҆"}, {"num": "к҃г.", "text": "не за́пнꙋтсѧ стѡпы̀ є҆гѡ̀. Сматрѧ́етъ грѣ́шный првⷣнаго, и҆ и҆́щетъ є҆́же ᲂу҆мертви́ти є҆го̀:"}, {"num": "к҃д.", "text": "Гдⷭ҇ь же не ѡ҆ста́витъ є҆гѡ̀ въ"}, {"num": "к҃є.", "text": "рꙋкꙋ̀ є҆гѡ̀, нижѐ ѡ҆сꙋ́дитъ є҆го̀, є҆гда̀"}, {"num": "к҃ѕ.", "text": "сꙋ́дитъ є҆мꙋ̀. Потерпѝ гдⷭ҇а, и҆ сохранѝ"}, {"num": "к҃з.", "text": "пꙋ́ть є҆гѡ̀, и҆ вознесе́тъ тѧ̀, є҆́же наслѣ́дити зе́млю: внегда̀ потреблѧ́тисѧ грѣ́шникѡмъ, ᲂу҆́зриши. Ви́дѣхъ нечести́ваго превозносѧ́щасѧ, и҆ вы́сѧщасѧ,"}, {"num": "к҃и.", "text": "ꙗ҆́кѡ ке́дры лїва̑нскїѧ: И҆ мимоидо́хъ, и҆ сѐ не бѣ̀, и҆ взыска́хъ є҆го̀, и҆ не ѡ҆брѣ́тесѧ мѣ́сто є҆гѡ̀. Хранѝ неѕло́бїе, и҆ ви́ждь правотꙋ̀, ꙗ҆́кѡ є҆́сть ѡ҆ста́нокъ человѣ́кꙋ ми́рнꙋ."}, {"num": "к҃ѳ.", "text": "Беззакѡ́нницы же потребѧ́тсѧ"}, {"num": "л҃.", "text": "вкꙋ́пѣ, ѡ҆ста́нцы же"}, {"num": "л҃а.", "text": "нечести́выхъ потребѧ́тсѧ. Сп҃се́нїе"}, {"num": "л҃в.", "text": "же првⷣныхъ ѿ"}, {"num": "л҃г.", "text": "гдⷭ҇а, и҆ защи́титель и҆́хъ є҆́сть во"}, {"num": "л҃д.", "text": "вре́мѧ ско́рби: И҆"}, {"num": "л҃є.", "text": "помо́жетъ и҆̀мъ гдⷭ҇ь,"}, {"num": "л҃ѕ.", "text": "и҆ и҆зба́витъ и҆̀хъ, и҆ и҆́зметъ и҆̀хъ"}, {"num": "л҃з.", "text": "ѿ грѣ̑шникъ"}, {"num": "л҃и.", "text": "и҆ сп҃се́тъ"}, {"num": "л҃ѳ.", "text": "и҆̀хъ, ꙗ҆́кѡ ᲂу҆пова́ша"}, {"num": "м҃.", "text": "на него̀. Сла́ва:"}]}, "37": {"number": 37, "cu_numeral": "л҃з", "title": "Ѱало́мъ л҃з (37)", "subtitle": "а҃ Ѱало́мъ дв҃дꙋ, въ воспомина́нїе ѡ҆ сꙋббѡ́тѣ, л҃з.", "verses": [{"num": "а҃.", "text": "Гдⷭ҇и, да не ꙗ҆́ростїю твое́ю ѡ҆бличи́ши менѐ, нижѐ гнѣ́вомъ твои́мъ нака́жеши менѐ:"}, {"num": "в҃.", "text": "Ꙗ҆́кѡ стрѣ́лы твоѧ̑ ᲂу҆нзо́ша во мнѣ̀, и҆ ᲂу҆тверди́лъ є҆сѝ на мнѣ̀ рꙋ́кꙋ твою̀."}, {"num": "г҃.", "text": "Нѣ́сть и҆сцѣле́нїѧ въ пло́ти мое́й ѿ лица̀ гнѣ́ва твоегѡ̀, нѣ́сть ми́ра въ косте́хъ мои́хъ, ѿ лица̀ грѣ̑хъ мои́хъ."}, {"num": "д҃.", "text": "Ꙗ҆́кѡ беззакѡ́нїѧ моѧ̑ превзыдо́ша главꙋ̀ мою̀, ꙗ҆́кѡ бре́мѧ тѧ́жкое ѡ҆тѧготѣ́ша на мнѣ̀."}, {"num": "є҃.", "text": "Возсмердѣ́ша и҆ согни́ша ра̑ны моѧ̑, ѿ лица̀ безꙋ́мїѧ моегѡ̀."}, {"num": "ѕ҃.", "text": "Пострада́хъ и҆ слѧко́хсѧ до конца̀, ве́сь де́нь сѣ́тꙋѧ хожда́хъ:"}, {"num": "з҃.", "text": "Ꙗ҆́кѡ лѧ́двїѧ моѧ̑"}, {"num": "и҃.", "text": "напо́лнишасѧ порꙋга́нїй, и҆ нѣ́сть и҆зцѣле́нїѧ въ пло́ти мое́й. Ѡ҆ѕло́бленъ бы́хъ и҆ смири́хсѧ до ѕѣла̀, рыка́хъ ѿ воздыха́нїѧ се́рдца моегѡ̀."}, {"num": "ѳ҃.", "text": "Гдⷭ҇и, пред̾ тобо́ю всѐ жела́нїе моѐ, и҆ воздыха́нїе моѐ ѿ тебѐ не ᲂу҆таи́сѧ."}, {"num": "і҃.", "text": "Се́рдце моѐ смѧте́сѧ, ѡ҆ста́ви мѧ̀ си́ла моѧ̀, и҆ свѣ́тъ ѻ҆́чїю моє́ю, и҆ то́й нѣ́сть со мно́ю."}, {"num": "а҃і.", "text": "Дрꙋ́зи моѝ и҆ и҆́скреннїи моѝ прѧ́мѡ мнѣ̀ прибли́жишасѧ, и҆ ста́ша:"}, {"num": "в҃і.", "text": "И҆ бли́жнїи моѝ ѿдале́че менѐ̀ ста́ша, и҆ нꙋжда́хꙋсѧ и҆́щꙋщїи дꙋ́шꙋ мою̀, и҆ и҆́щꙋщїи ѕла̑ѧ мнѣ̀, глаго́лахꙋ сꙋ́єтнаѧ, и҆ льсти̑внымъ ве́сь де́нь поꙋча́хꙋсѧ."}, {"num": "г҃і.", "text": "А҆́зъ же ꙗ҆́кѡ глꙋ́хъ не слы́шахъ, и҆ ꙗ҆́кѡ нѣ́мъ не ѿверза́ѧй ᲂу҆́стъ свои́хъ:"}, {"num": "д҃і.", "text": "И҆ бы́хъ ꙗ҆́кѡ человѣ́къ не слы́шай, и҆ не и҆мы́й во ᲂу҆стѣ́хъ свои́хъ ѡ҆бличе́нїѧ."}, {"num": "є҃і.", "text": "Ꙗ҆́кѡ на тѧ̀, гдⷭ҇и, ᲂу҆пова́хъ, ты̀ ᲂу҆слы́шиши, гдⷭ҇и бж҃е мо́й."}, {"num": "ѕ҃і.", "text": "Ꙗ҆́кѡ рѣ́хъ, да не когда̀ пора́дꙋютъ ми сѧ вразѝ моѝ: и҆ внегда̀ подвижа́тисѧ нога́мъ мои̑мъ, на мѧ̀ велерѣ́чеваша."}, {"num": "з҃і.", "text": "Ꙗ҆́кѡ а҆́зъ на ра̑ны гото́въ, и҆ болѣ́знь моѧ̀ предо мно́ю є҆́сть вы́нꙋ."}, {"num": "и҃і.", "text": "Ꙗ҆́кѡ беззако́нїе моѐ а҆́зъ возвѣщꙋ̀, и҆ попекꙋ́сѧ ѡ҆ грѣсѣ̀ мое́мъ."}, {"num": "ѳ҃і.", "text": "Врази́ же моѝ живꙋ́тъ, и҆ ᲂу҆крѣпи́шасѧ па́че менѐ, и҆ ᲂу҆мно́жишасѧ ненави́дѧщїи мѧ̀ без̾ пра́вды:"}, {"num": "к҃.", "text": "Воздаю́щїи мѝ ѕла̑ѧ воз̾ бл҃га̑ѧ ѡ҆болга́хꙋ мѧ̀, занѐ гонѧ́хъ благосты́ню."}, {"num": "к҃а.", "text": "Не ѡ҆ста́ви менѐ, гдⷭ҇и бж҃е мо́й, не ѿстꙋпѝ ѿ менѐ."}, {"num": "к҃в.", "text": "Вонмѝ въ по́мощь мою̀, гдⷭ҇и сп҃се́нїѧ моегѡ̀. а҃ Въ коне́цъ, і҆дїѳꙋ́мꙋ, пѣ́снь дв҃дꙋ, л҃и."}]}, "38": {"number": 38, "cu_numeral": "л҃и", "title": "Ѱало́мъ л҃и (38)", "subtitle": "а҃ Въ коне́цъ, і҆дїѳꙋ́мꙋ, пѣ́снь дв҃дꙋ, л҃и.", "verses": [{"num": "а҃.", "text": "Рѣ́хъ: сохраню̀ пꙋти̑ моѧ̑, є҆́же не согрѣша́ти мѝ ѧ҆зы́комъ мои́мъ: положи́хъ ᲂу҆стѡ́мъ мои̑мъ храни́ло, внегда̀ воста́ти грѣ́шномꙋ предо мно́ю."}, {"num": "в҃.", "text": "Ѡ҆нѣмѣ́хъ и҆ смири́хсѧ, и҆ ᲂу҆молча́хъ ѿ бла̑гъ, и҆ болѣ́знь моѧ̀ ѡ҆бнови́сѧ."}, {"num": "г҃.", "text": "Согрѣ́ѧсѧ се́рдце моѐ во мнѣ̀, и҆ въ поꙋче́нїи мое́мъ разгори́тсѧ ѻ҆́гнь: глаго́лахъ ѧ҆зы́комъ мои́мъ:"}, {"num": "д҃.", "text": "Скажи́ ми, гдⷭ҇и, кончи́нꙋ мою̀ и҆ число̀ дне́й мои́хъ ко́е є҆́сть, да разꙋмѣ́ю, что̀ лиша́юсѧ а҆́зъ;"}, {"num": "є҃.", "text": "Сѐ пѧ̑ди положи́лъ є҆сѝ дни̑ моѧ̑, и҆ соста́въ мо́й ꙗ҆́кѡ ничто́же пред̾ тобо́ю: ѻ҆ба́че всѧ́чєскаѧ сꙋета̀, всѧ́къ человѣ́къ живы́й."}, {"num": "ѕ҃.", "text": "Оу҆̀бо ѡ҆́бразомъ хо́дитъ человѣ́къ, ѻ҆ба́че всꙋ́е мѧте́тсѧ: сокро́вищствꙋетъ, и҆ не вѣ́сть, комꙋ̀ собере́тъ ѧ҆̀."}, {"num": "з҃.", "text": "И҆ ны́нѣ кто̀ терпѣ́нїе моѐ; не гдⷭ҇ь ли; и҆ соста́въ мо́й ѿ тебѐ є҆́сть."}, {"num": "и҃.", "text": "Ѿ всѣ́хъ беззако́нїй мои́хъ и҆зба́ви мѧ̀: поноше́нїе безꙋ́мномꙋ да́лъ мѧ̀ є҆сѝ."}, {"num": "ѳ҃.", "text": "Ѡ҆нѣмѣ́хъ и҆ не ѿверзо́хъ ᲂу҆́стъ мои́хъ, ꙗ҆́кѡ ты̀ сотвори́лъ є҆сѝ."}, {"num": "і҃.", "text": "Ѿста́ви ѿ менє̀ ра̑ны твоѧ̑: ѿ крѣ́пости бо рꙋкѝ твоеѧ̀ а҆́зъ и҆зчезо́хъ."}, {"num": "а҃і.", "text": "Во ѡ҆бличе́нїихъ ѡ҆ беззако́нїи наказа́лъ є҆сѝ человѣ́ка, и҆ и҆ста́ѧлъ є҆сѝ ꙗ҆́кѡ паꙋчи́нꙋ дꙋ́шꙋ є҆гѡ̀: ѻ҆ба́че всꙋ́е всѧ́къ человѣ́къ. Оу҆слы́ши мл҃́твꙋ мою̀, гдⷭ҇и,"}, {"num": "в҃і.", "text": "и҆ моле́нїе моѐ внꙋшѝ, сле́зъ мои́хъ не премолчѝ: ꙗ҆́кѡ пресе́льникъ а҆́зъ є҆́смь ᲂу҆ тебѐ и҆ пришле́цъ, ꙗ҆́коже всѝ ѻ҆тцы̀ моѝ."}, {"num": "г҃і.", "text": "Ѡ҆сла́би мѝ, да почі́ю, пре́жде да́же не ѿидꙋ̀, и҆ ктомꙋ̀ не бꙋ́дꙋ. а҃ Въ коне́цъ, ѱало́мъ дв҃дꙋ, л҃ѳ."}]}, "39": {"number": 39, "cu_numeral": "л҃ѳ", "title": "Ѱало́мъ л҃ѳ (39)", "subtitle": "а҃ Въ коне́цъ, ѱало́мъ дв҃дꙋ, л҃ѳ.", "verses": [{"num": "а҃.", "text": "Терпѧ̀ потерпѣ́хъ гдⷭ҇а, и҆ внѧ́тъ мѝ, и҆ ᲂу҆слы́ша мл҃твꙋ мою̀:"}, {"num": "в҃.", "text": "И҆ возведѐ мѧ ѿ ро́ва страсте́й и҆ ѿ бре́нїѧ ти́ны, и҆ поста́ви на ка́мени но́зѣ моѝ, и҆ и҆спра́ви стѡпы̀ моѧ̑:"}, {"num": "г҃.", "text": "И҆ вложѝ во ᲂу҆ста̀ моѧ̑ пѣ́снь но́вꙋ, пѣ́нїе бг҃ꙋ на́шемꙋ. ᲂу҆зрѧтъ мно́зи и҆ ᲂу҆боѧ́тсѧ, и҆ ᲂу҆пова́ютъ на гдⷭ҇а."}, {"num": "д҃.", "text": "Бл҃же́нъ мꙋ́жъ, є҆мꙋ́же є҆́сть и҆́мѧ гдⷭ҇не ᲂу҆пова́нїе є҆гѡ̀, и҆ не призрѣ̀ въ сꙋєты̀ и҆ неистовлє́нїѧ лѡ́жнаѧ."}, {"num": "є҃.", "text": "Мнѡ́га сотвори́лъ є҆сѝ ты̀, гдⷭ҇и бж҃е мо́й, чꙋдеса̀ твоѧ̑, и҆ помышле́нїємъ твои̑мъ нѣ́сть кто̀ ᲂу҆подо́битсѧ тебѣ̀: возвѣсти́хъ и҆ глаго́лахъ, ᲂу҆мно́жишасѧ па́че числа̀."}, {"num": "ѕ҃.", "text": "Же́ртвы и҆ приноше́нїѧ не восхотѣ́лъ є҆сѝ, тѣ́ло же сверши́лъ мѝ є҆сѝ: всесожже́нїй и҆ ѡ҆ грѣсѣ̀ не взыска́лъ є҆сѝ."}, {"num": "з҃.", "text": "Тогда̀ рѣ́хъ: сѐ прїидꙋ̀. въ глави́знѣ кни́жнѣ пи́сано є҆́сть ѡ҆ мнѣ̀:"}, {"num": "и҃.", "text": "Е҆́же сотвори́ти во́лю твою̀, бж҃е мо́й, восхотѣ́хъ, и҆ зако́нъ тво́й посредѣ̀ чре́ва моегѡ̀."}, {"num": "ѳ҃.", "text": "Бл҃говѣсти́хъ пра́вдꙋ въ цр҃кви вели́цѣй, сѐ і҃ а҃і в҃і г҃і д҃і є҃і ѕ҃і з҃і и҃і посредѣ̀ чре́ва моегѡ̀. Бл҃говѣсти́хъ пра́вдꙋ въ цр҃кви вели́цѣй, сѐ ᲂу҆стна́мъ мои̑мъ не возбраню̀: гдⷭ҇и, ты̀ разꙋмѣ́лъ є҆сѝ."}, {"num": "і҃.", "text": "Пра́вдꙋ твою̀ не скры́хъ въ се́рдцѣ мое́мъ, и҆́стинꙋ твою̀ и҆ сп҃се́нїе твоѐ рѣ́хъ, не скры́хъ млⷭ҇ть твою̀ и҆ и҆́стинꙋ твою̀ ѿ со́нма мно́га."}, {"num": "а҃і.", "text": "Ты́ же, гдⷭ҇и, не ᲂу҆далѝ щедро́тъ твои́хъ ѿ менѐ: млⷭ҇ть твоѧ̀ и҆ и҆́стина твоѧ̀ вы́нꙋ да застꙋ́питѣ мѧ̀."}, {"num": "в҃і.", "text": "Ꙗ҆́кѡ ѡ҆держа́ша мѧ̀ ѕла̑ѧ, и҆̀мже нѣ́сть числа̀. постиго́ша мѧ̀ беззакѡ́нїѧ моѧ̑, и҆ не возмого́хъ зрѣ́ти: ᲂу҆мно́жишасѧ па́че вла̑съ главы̀ моеѧ̀, и҆ се́рдце моѐ ѡ҆ста́ви мѧ̀."}, {"num": "г҃і.", "text": "Бл҃говолѝ, гдⷭ҇и, и҆зба́вити мѧ̀: гдⷭ҇и, во є҆́же помощи́ ми вонмѝ."}, {"num": "д҃і.", "text": "Да постыдѧ́тсѧ и҆ посра́мѧтсѧ вкꙋ́пѣ и҆́щꙋщїи дꙋ́шꙋ мою̀, и҆з̾ѧ́ти ю҆̀: да возвратѧ́тсѧ вспѧ́ть, и҆ постыдѧ́тсѧ хотѧ́щїи мѝ ѕла̑ѧ."}, {"num": "є҃і.", "text": "Да прїи́мꙋтъ а҆́бїе стꙋ́дъ сво́й глаго́лющїи мѝ: бла́гоже, бла́гоже."}, {"num": "ѕ҃і.", "text": "Да возра́дꙋютсѧ и҆ возвеселѧ́тсѧ ѡ҆ тебѣ̀ всѝ и҆́щꙋщїи тебѐ, гдⷭ҇и: и҆ да рекꙋ́тъ вы́нꙋ, да возвели́читсѧ гдⷭ҇ь, лю́бѧщїи сп҃се́нїе твоѐ."}, {"num": "з҃і.", "text": "А҆́зъ же ни́щъ є҆́смь и҆ ᲂу҆бо́гъ, гдⷭ҇ь попече́тсѧ ѡ҆ мнѣ̀: помо́щникъ мо́й и҆ защи́титель мо́й є҆сѝ ты̀, бж҃е мо́й, не закоснѝ. Сла́ва: а҃ Въ коне́цъ, ѱало́мъ дв҃дꙋ, м҃."}]}, "40": {"number": 40, "cu_numeral": "м҃", "title": "Ѱало́мъ м҃ (40)", "subtitle": "а҃ Въ коне́цъ, ѱало́мъ дв҃дꙋ, м҃.", "verses": [{"num": "а҃.", "text": "Бл҃же́нъ разꙋмѣва́ѧй на ни́ща и҆ ᲂу҆бо́га, въ де́нь лю́тъ и҆зба́витъ є҆го̀ гдⷭ҇ь:"}, {"num": "в҃.", "text": "Гдⷭ҇ь да сохрани́тъ є҆го̀, и҆ живи́тъ є҆го̀, и҆ да ᲂу҆бл҃жи́тъ є҆го̀ на землѝ, и҆ да не преда́стъ є҆гѡ̀ въ рꙋ́ки врагѡ́въ є҆гѡ̀."}, {"num": "г҃.", "text": "Гдⷭ҇ь да помо́жетъ є҆мꙋ̀ на ѻ҆дрѣ̀ болѣ́зни є҆гѡ̀: всѐ ло́же є҆гѡ̀ ѡ҆брати́лъ є҆сѝ въ болѣ̑зни є҆гѡ̀."}, {"num": "д҃.", "text": "А҆́зъ рѣ́хъ: гдⷭ҇и, поми́лꙋй мѧ̀, и҆зцѣлѝ дꙋ́шꙋ мою̀, ꙗ҆́кѡ согрѣши́хъ тѝ."}, {"num": "є҃.", "text": "Вразѝ моѝ рѣ́ша мнѣ̀ ѕла̑ѧ: когда̀ ᲂу҆́мретъ, и҆ поги́бнетъ и҆́мѧ є҆гѡ̀;"}, {"num": "ѕ҃.", "text": "И҆ вхожда́ше ви́дѣти, всꙋ́е глаго́лаше се́рдце є҆гѡ̀, собра̀ беззако́нїе себѣ̀, и҆схожда́ше во́нъ, и҆ глаго́лаше вкꙋ́пѣ."}, {"num": "з҃.", "text": "На мѧ̀ шепта́хꙋ всѝ вразѝ моѝ, на мѧ̀ помышлѧ́хꙋ ѕла̑ѧ мнѣ̀."}, {"num": "и҃.", "text": "Сло́во законопрестꙋ́пное возложи́ша на мѧ̀: є҆да̀ спѧ́й не приложи́тъ воскрⷭ҇снꙋ́ти;"}, {"num": "ѳ҃.", "text": "И҆́бо человѣ́къ ми́ра моегѡ̀, на него́же ᲂу҆пова́хъ, ꙗ҆ды́й хлѣ́бы моѧ̑, возвели́чи на мѧ̀ запина́нїе."}, {"num": "і҃.", "text": "Ты́ же, гдⷭ҇и, поми́лꙋй мѧ̀, и҆ возста́ви мѧ̀, и҆ возда́мъ и҆̀мъ."}, {"num": "а҃і.", "text": "Въ се́мъ позна́хъ, ꙗ҆́кѡ восхотѣ́лъ мѧ̀ є҆сѝ, ꙗ҆́кѡ не возра́дꙋетсѧ вра́гъ мо́й ѡ҆ мнѣ̀."}, {"num": "в҃і.", "text": "Мене́ же за неѕло́бїе прїѧ́лъ, и҆ ᲂу҆тверди́лъ мѧ̀ є҆сѝ пред̾ тобо́ю въ вѣ́къ. Бл҃гослове́нъ гдⷭ҇ь бг҃ъ і҆и҃левъ ѿ вѣ́ка"}, {"num": "г҃і.", "text": "и҆ до вѣ́ка: бꙋ́ди, бꙋ́ди. а҃ Въ коне́цъ, въ ра́зꙋмъ сынѡ́въ коре́овыхъ, ѱало́мъ дв҃дꙋ, не надпи́санъ ᲂу҆ є҆врє́й, м҃а."}]}, "41": {"number": 41, "cu_numeral": "м҃а", "title": "Ѱало́мъ м҃а (41)", "subtitle": "не надпи́санъ ᲂу҆ є҆врє́й, м҃а.", "verses": [{"num": "а҃.", "text": "И҆́мже ѡ҆́бразомъ жела́етъ є҆ле́нь на и҆сто́чники водны̑ѧ: си́це жела́етъ дꙋша̀ моѧ̀ къ тебѣ̀, бж҃е."}, {"num": "в҃.", "text": "Возжада̀ дꙋша̀ моѧ̀ къ бг҃ꙋ крѣ́пкомꙋ живо́мꙋ: когда̀ прїидꙋ̀ и҆ ꙗ҆влю́сѧ лицꙋ̀ бж҃їю;"}, {"num": "г҃.", "text": "Бы́ша сле́зы моѧ̑ мнѣ̀ хлѣ́бъ де́нь и҆ но́щь, внегда̀ глаго́латисѧ мнѣ̀ на всѧ́къ де́нь: гдѣ̀ є҆́сть бг҃ъ тво́й;"}, {"num": "д҃.", "text": "Сїѧ̑ помѧнꙋ́хъ, и҆ и҆злїѧ́хъ на мѧ̀ дꙋ́шꙋ мою̀: ꙗ҆́кѡ пройдꙋ̀ въ мѣ́сто селе́нїѧ ди́вна да́же до до́мꙋ бж҃їѧ, во гла́сѣ ра́дованїѧ и҆ и҆сповѣ́данїѧ, шꙋ́ма пра́зднꙋющагѡ."}, {"num": "є҃.", "text": "Вскꙋ́ю приско́рбна є҆сѝ, дꙋшѐ моѧ̀; и҆ вскꙋ́ю смꙋща́еши мѧ̀; ᲂу҆пова́й на бг҃а, ꙗ҆́кѡ и҆сповѣ́мсѧ є҆мꙋ̀, сп҃се́нїе лица̀ моегѡ̀, и҆ бг҃ъ мо́й."}, {"num": "ѕ҃.", "text": "Ко мнѣ̀ самомꙋ̀ дꙋша̀ моѧ̀ смѧте́сѧ: сегѡ̀ ра́ди помѧнꙋ́хъ тѧ̀ ѿ землѝ і҆ѻрда́нски и҆ є҆рмѡнїи́мски, ѿ горы̀ ма́лыѧ."}, {"num": "з҃.", "text": "Бе́здна бе́зднꙋ призыва́етъ во гла́сѣ хлѧ́бїй твои́хъ: всѧ̑ высѡты̑ твоѧ̑ и҆ во́лны твоѧ̑ на мнѣ̀ прїидо́ша."}, {"num": "и҃.", "text": "Въ де́нь заповѣ́сть гдⷭ҇ь млⷭ҇ть свою̀: и҆ но́щїю пѣ́снь є҆гѡ̀ ѿ менѐ, мл҃тва бг҃ꙋ живота̀ моегѡ̀."}, {"num": "ѳ҃.", "text": "Рекꙋ̀ бг҃ꙋ: застꙋ́пникъ мо́й є҆сѝ, почто̀ мѧ̀ забы́лъ є҆сѝ; и҆ вскꙋ́ю сѣ́тꙋѧ хождꙋ̀, внегда̀ ѡ҆скорблѧ́етъ вра́гъ;"}, {"num": "і҃.", "text": "Внегда̀ сокрꙋша́тисѧ косте́мъ мои̑мъ, поноша́хꙋ мѝ вразѝ моѝ, внегда̀ глаго́лати и҆̀мъ мнѣ̀ на всѧ́къ де́нь: гдѣ̀ є҆́сть бг҃ъ тво́й;"}, {"num": "а҃і.", "text": "Вскꙋ́ю приско́рбна є҆сѝ, дꙋшѐ моѧ̀; и҆ вскꙋ́ю смꙋща́еши мѧ̀; ᲂу҆пова́й на бг҃а, ꙗ҆́кѡ и҆сповѣ́мсѧ є҆мꙋ̀, сп҃се́нїе лица̀ моегѡ̀ и҆ бг҃ъ мо́й."}]}, "42": {"number": 42, "cu_numeral": "м҃в", "title": "Ѱало́мъ м҃в (42)", "subtitle": "Ѱало́мъ дв҃дꙋ, не надпи́санъ ᲂу҆ є҆врє́й, м҃в.", "verses": [{"num": "а҃.", "text": "Сꙋди́ ми, бж҃е, и҆ разсꙋдѝ прю̀ мою̀: ѿ ꙗ҆зы́ка не преподо́бна, ѿ человѣ́ка непра́ведна и҆ льсти́ва и҆зба́ви мѧ̀."}, {"num": "в҃.", "text": "Занѐ ты̀ є҆сѝ, бж҃е, крѣ́пость моѧ̀, вскꙋ́ю ѿри́нꙋлъ мѧ̀ є҆сѝ; и҆ вскꙋ́ю сѣ́тꙋѧ хождꙋ̀, внегда̀ ѡ҆скорблѧ́етъ вра́гъ;"}, {"num": "г҃.", "text": "Послѝ свѣ́тъ тво́й, и҆ и҆́стинꙋ твою̀: та̑ мѧ̀ наста́виста, и҆ введо́ста мѧ̀ въ го́рꙋ ст҃ꙋ́ю твою̀ и҆ въ селє́нїѧ твоѧ̑."}, {"num": "д҃.", "text": "И҆ вни́дꙋ къ же́ртвенникꙋ бж҃їю, къ бг҃ꙋ веселѧ́щемꙋ ю҆́ность мою̀: и҆сповѣ́мсѧ тебѣ̀ въ гꙋ́слехъ, бж҃е, бж҃е мо́й."}, {"num": "є҃.", "text": "Вскꙋ́ю приско́рбна є҆сѝ, дꙋшѐ моѧ̀; и҆ вскꙋ́ю смꙋща́еши мѧ̀; ᲂу҆пова́й на бг҃а, ꙗ҆́кѡ и҆сповѣ́мсѧ є҆мꙋ̀, сп҃се́нїе лица̀ моегѡ̀, и҆ бг҃ъ мо́й. Сла́ва: а҃ Въ коне́цъ, сынѡ́въ коре́овыхъ, въ ра́зꙋмъ, ѱало́мъ м҃г."}]}, "43": {"number": 43, "cu_numeral": "м҃г", "title": "Ѱало́мъ м҃г (43)", "subtitle": "а҃ Въ коне́цъ, сынѡ́въ коре́овыхъ, въ ра́зꙋмъ, ѱало́мъ м҃г.", "verses": [{"num": "а҃.", "text": "Бж҃е, ᲂу҆ши́ма на́шима ᲂу҆слы́шахомъ, и҆ ѻ҆тцы̀ на́ши возвѣсти́ша на́мъ дѣ́ло, є҆́же содѣ́лалъ є҆сѝ во дне́хъ и҆́хъ, во дне́хъ дре́внихъ."}, {"num": "в҃.", "text": "Рꙋка̀ твоѧ̀ ꙗ҆зы́ки потребѝ, и҆ насади́лъ ѧ҆̀ є҆сѝ: ѡ҆ѕло́билъ є҆сѝ лю́ди, и҆ и҆згна́лъ є҆сѝ ѧ҆̀."}, {"num": "г҃.", "text": "Не бо мече́мъ свои́мъ наслѣ́диша зе́млю, и҆ мы́шца и҆́хъ не спасѐ и҆́хъ: но десни́ца твоѧ̀, и҆ мы́шца твоѧ̀, и҆ просвѣще́нїе лица̀ твоегѡ̀, ꙗ҆́кѡ бл҃говоли́лъ є҆сѝ въ ни́хъ."}, {"num": "д҃.", "text": "Ты̀ є҆сѝ са́мъ цр҃ь мо́й и҆ бг҃ъ мо́й, заповѣ́даѧй сп҃се́нїѧ і҆а̑кѡвлѧ."}, {"num": "є҃.", "text": "Ѡ҆ тебѣ̀ врагѝ на́шѧ и҆збоде́мъ ро́ги, и҆ ѡ҆ и҆́мени твое́мъ ᲂу҆ничижи́мъ востаю́щыѧ на ны̀."}, {"num": "ѕ҃.", "text": "Не на лꙋ́къ бо мо́й ᲂу҆пова́ю, и҆ ме́чь мо́й не спасе́тъ менѐ:"}, {"num": "з҃.", "text": "Спа́слъ бо є҆сѝ на́съ ѿ стꙋжа́ющихъ на́мъ, и҆ ненави́дѧщихъ на́съ посрами́лъ є҆сѝ."}, {"num": "и҃.", "text": "Ѡ҆ бз҃ѣ похва́лимсѧ ве́сь де́нь, и҆ ѡ҆ и҆́мени твое́мъ и҆сповѣ́мысѧ во вѣ́къ."}, {"num": "ѳ҃.", "text": "Ны́нѣ же ѿри́нꙋлъ є҆сѝ и҆ посрами́лъ є҆сѝ на́съ, и҆ не и҆зы́деши, бж҃е: въ си́лахъ на́шихъ."}, {"num": "і҃.", "text": "Возврати́лъ є҆сѝ на́съ вспѧ́ть при вразѣ́хъ на́шихъ, и҆ ненави́дѧщїи на́съ расхища́хꙋ себѣ̀."}, {"num": "а҃і.", "text": "Да́лъ є҆сѝ на́съ ꙗ҆́кѡ ѻ҆́вцы снѣ́ди, и҆ во ꙗ҆зы́цѣхъ разсѣ́ѧлъ ны̀ є҆сѝ."}, {"num": "в҃і.", "text": "Ѿда́лъ є҆сѝ лю́ди твоѧ̑ без̾ цѣны̀, и҆ не бѣ̀ мно́жество въ восклица́нїихъ на́шихъ."}, {"num": "г҃і.", "text": "Положи́лъ є҆сѝ на́съ поноше́нїе сосѣ́дѡмъ на́шымъ, подражне́нїе и҆ порꙋга́нїе сꙋ́щымъ ѻ҆́крестъ на́съ."}, {"num": "д҃і.", "text": "Положи́лъ є҆сѝ на́съ въ при́тчꙋ во ꙗ҆зы́цѣхъ, покива́нїю главы̀ въ лю́дехъ."}, {"num": "є҃і.", "text": "Ве́сь де́нь сра́мъ мо́й предо мно́ю є҆́сть, и҆ стꙋ́дъ лица̀ моегѡ̀ покры́ мѧ,"}, {"num": "ѕ҃і.", "text": "Ѿ гла́са поноша́ющагѡ и҆ ѡ҆клевета́ющагѡ, ѿ лица̀ вра́жїѧ и҆ и҆згонѧ́щагѡ."}, {"num": "з҃і.", "text": "Сїѧ̑ всѧ̑ прїидо́ша на ны̀, и҆ не забы́хомъ тебѐ, и҆ не непра́вдовахомъ въ завѣ́тѣ твое́мъ,"}, {"num": "и҃і.", "text": "И҆ не ѿстꙋпѝ вспѧ́ть се́рдце на́ше: и҆ ᲂу҆клони́лъ є҆сѝ стезѝ на́шѧ ѿ пꙋтѝ твоегѡ̀."}, {"num": "ѳ҃і.", "text": "Ꙗ҆́кѡ смири́лъ є҆сѝ на́съ на мѣ́стѣ ѡ҆ѕлобле́нїѧ, и҆ прикры́ ны сѣ́нь сме́ртнаѧ."}, {"num": "к҃.", "text": "А҆́ще забы́хомъ и҆́мѧ бг҃а на́шегѡ, и҆ а҆́ще воздѣ́хомъ рꙋ́ки на́шѧ къ бо́гꙋ чꙋжде́мꙋ,"}, {"num": "к҃а.", "text": "Не бг҃ъ ли взы́щетъ си́хъ; то́й бо вѣ́сть та̑йнаѧ се́рдца."}, {"num": "к҃в.", "text": "Занѐ тебѐ ра́ди ᲂу҆мерщвлѧ́емсѧ ве́сь де́нь, вмѣни́хомсѧ ꙗ҆́кѡ ѻ҆́вцы заколе́нїѧ."}, {"num": "к҃г.", "text": "Воста́ни, вскꙋ́ю спи́ши, гдⷭ҇и; воскрⷭ҇нѝ, и҆ не ѿри́ни до конца̀."}, {"num": "к҃д.", "text": "Вскꙋ́ю лицѐ твоѐ ѿвраща́еши; забыва́еши нищетꙋ̀ на́шꙋ и҆ ско́рбь на́шꙋ;"}, {"num": "к҃є.", "text": "Ꙗ҆́кѡ смири́сѧ въ пе́рсть дꙋша̀ на́ша, прильпѐ землѝ ᲂу҆тро́ба на́ша."}, {"num": "к҃ѕ.", "text": "Воскрⷭ҇нѝ, гдⷭ҇и, помозѝ на́мъ, и҆ и҆зба́ви на́съ и҆́мене ра́ди твоегѡ̀. а҃ Въ коне́цъ, ѡ҆ и҆змѣнѧ́емыхъ, сынѡ́мъ коре́ѡвымъ: въ ра́зꙋмъ, пѣ́снь ѡ҆ возлю́бленнѣмъ, м҃д."}]}, "44": {"number": 44, "cu_numeral": "м҃д", "title": "Ѱало́мъ м҃д (44)", "subtitle": "пѣ́снь ѡ҆ возлю́бленнѣмъ, м҃д.", "verses": [{"num": "а҃.", "text": "Ѿры́гнꙋ се́рдце моѐ сло́во бл҃го, глаго́лю а҆́зъ дѣла̀ моѧ̑ цр҃е́ви: ѧ҆зы́къ мо́й тро́сть кни́жника скоропи́сца."}, {"num": "в҃.", "text": "Красе́нъ добро́тою па́че сынѡ́въ человѣ́ческихъ, и҆злїѧ́сѧ бл҃года́ть во ᲂу҆стна́хъ твои́хъ: сегѡ̀ ра́ди бл҃гослови́ тѧ бг҃ъ во вѣ́къ."}, {"num": "г҃.", "text": "Препоѧ́ши ме́чь тво́й по бедрѣ̀ твое́й, си́льне,"}, {"num": "д҃.", "text": "Красото́ю твое́ю и҆ добро́тою твое́ю: и҆ налѧцы̀, и҆ ᲂу҆спѣва́й, и҆ црⷭ҇твꙋй и҆́стины ра́ди, и҆ кро́тости и҆ пра́вды: и҆ наста́витъ тѧ̀ ди́внѡ десни́ца твоѧ̀."}, {"num": "є҃.", "text": "Стрѣ́лы твоѧ̑ и҆з̾ѡщрє́ны, си́льне: лю́дїе под̾ тобо́ю падꙋ́тъ въ се́рдцы вра̑гъ цр҃е́выхъ."}, {"num": "ѕ҃.", "text": "Прⷭ҇то́лъ тво́й, бж҃е, въ вѣ́къ вѣ́ка: же́злъ пра́вости, же́злъ црⷭ҇твїѧ твоегѡ̀."}, {"num": "з҃.", "text": "Возлюби́лъ є҆сѝ пра́вдꙋ, и҆ возненави́дѣлъ є҆сѝ беззако́нїе: сегѡ̀ ра́ди пома́за тѧ̀, бж҃е, бг҃ъ тво́й, є҆ле́емъ ра́дости па́че прича̑стникъ твои́хъ."}, {"num": "и҃.", "text": "Смѵ́рна, и҆ ста́кти, и҆ касі́а ѿ ри́зъ твои́хъ, ѿ тѧ́жестей слоно́выхъ, и҆з̾ ни́хже возвесели́ша тѧ̀."}, {"num": "ѳ҃.", "text": "Дщє́ри царе́й въ че́сти твое́й: предста̀ цр҃и́́ца ѡ҆деснꙋ́ю тебѐ, въ ри́захъ позлаще́нныхъ ѡ҆дѣ́ѧна"}, {"num": "і҃.", "text": "преиспещре́на. Слы́ши, дщѝ, и҆ ви́ждь, и҆ приклонѝ ᲂу҆́хо твоѐ, и҆ забꙋ́ди лю́ди твоѧ̑ и҆ до́мъ ѻ҆тца̀ твоегѡ̀:"}, {"num": "а҃і.", "text": "И҆ возжела́етъ цр҃ь добро́ты твоеѧ̀, занѐ то́й є҆́сть гдⷭ҇ь тво́й, и҆ поклони́шисѧ є҆мꙋ̀,"}, {"num": "в҃і.", "text": "И҆ дщѝ тѵ́рова съ да̑ры: лицꙋ̀ твоемꙋ̀ помо́лѧтсѧ бога́тїи лю́дстїи."}, {"num": "г҃і.", "text": "Всѧ̀ сла́ва дще́ре цр҃е́вы внꙋ́трь: рѧ̑сны златы́ми ѡ҆дѣ́ѧна и҆ преиспещре́на."}, {"num": "д҃і.", "text": "Приведꙋ́тсѧ цр҃ю̀ дѣ̑вы в̾слѣ́дъ є҆ѧ̀, и҆́скреннїѧ є҆ѧ̀ приведꙋ́тсѧ тебѣ̀:"}, {"num": "є҃і.", "text": "Приведꙋ́тсѧ въ весе́лїи и҆ ра́дованїи, введꙋ́тсѧ въ хра́мъ цр҃е́въ."}, {"num": "ѕ҃і.", "text": "Вмѣ́стѡ ѻ҆тє́цъ твои́хъ бы́ша сы́нове твоѝ: поста́виши ѧ҆̀ кнѧ́зи по все́й землѝ."}, {"num": "з҃і.", "text": "Помѧнꙋ̀ и҆́мѧ твоѐ во всѧ́комъ ро́дѣ и҆ ро́дѣ: сегѡ̀ ра́ди лю́дїе и҆сповѣ́дѧтсѧ тебѣ̀ въ вѣ́къ, и҆ во вѣ́къ вѣ́ка. а҃ Въ коне́цъ, ѡ҆ сынѣ́хъ коре́овыхъ, ѡ҆ та́йныхъ, ѱало́мъ м҃є."}]}, "45": {"number": 45, "cu_numeral": "м҃є", "title": "Ѱало́мъ м҃є (45)", "subtitle": "а҃ Въ коне́цъ, ѡ҆ сынѣ́хъ коре́овыхъ, ѡ҆ та́йныхъ, ѱало́мъ м҃є.", "verses": [{"num": "а҃.", "text": "Бг҃ъ на́мъ прибѣ́жище и҆ си́ла, помо́щникъ въ ско́рбехъ ѡ҆брѣ́тшихъ ны̀ ѕѣлѡ̀,"}, {"num": "в҃.", "text": "Сегѡ̀ ра́ди не ᲂу҆бои́мсѧ, внегда̀ смꙋща́етсѧ землѧ̀, и҆ прелага́ютсѧ го́ры въ сердца̀ морска̑ѧ."}, {"num": "г҃.", "text": "Возшꙋмѣ́ша и҆ смѧто́шасѧ во́ды и҆́хъ, смѧто́шасѧ го́ры крѣ́постїю є҆гѡ̀."}, {"num": "д҃.", "text": "Рѣ̑чнаѧ ᲂу҆стремлє́нїѧ веселѧ́тъ гра́дъ бж҃їй: ѡ҆ст҃и́лъ є҆́сть селе́нїе своѐ вы́шнїй."}, {"num": "є҃.", "text": "Бг҃ъ посредѣ̀ є҆гѡ̀, и҆ не подви́житсѧ, помо́жетъ є҆мꙋ̀ бг҃ъ ᲂу҆́трѡ заꙋ́тра."}, {"num": "ѕ҃.", "text": "Смѧто́шасѧ ꙗ҆зы́цы, ᲂу҆клони́шасѧ ца̑рствїѧ: дадѐ гла́съ сво́й з҃ и҃ ѳ҃ і҃ а҃і в҃і Смѧто́шасѧ ꙗ҆зы́цы, ᲂу҆клони́шасѧ ца̑рствїѧ: дадѐ гла́съ сво́й вы́шнїй, подви́жесѧ землѧ̀."}, {"num": "з҃.", "text": "Гдⷭ҇ь си́лъ съ на́ми, застꙋ́пникъ на́шъ бг҃ъ і҆а́кѡвль."}, {"num": "и҃.", "text": "Прїиди́те и҆ ви́дите дѣла̀ бж҃їѧ, ꙗ҆̀же положѝ чꙋдеса̀ на землѝ:"}, {"num": "ѳ҃.", "text": "Ѿе́млѧ бра̑ни до конє́цъ землѝ, лꙋ́къ сокрꙋши́тъ и҆ сло́митъ ѻ҆рꙋ́жїе, и҆ щиты̀ сожже́тъ ѻ҆гне́мъ."}, {"num": "і҃.", "text": "Оу҆праздни́тесѧ и҆ разꙋмѣ́йте, ꙗ҆́кѡ а҆́зъ є҆́смь бг҃ъ: вознесꙋ́сѧ во ꙗ҆зы́цѣхъ, вознесꙋ́сѧ на землѝ."}, {"num": "а҃і.", "text": "Гдⷭ҇ь си́лъ съ на́ми, застꙋ́пникъ на́шъ бг҃ъ і҆а́кѡвль. Сла́ва:"}]}, "46": {"number": 46, "cu_numeral": "м҃ѕ", "title": "Ѱало́мъ м҃ѕ (46)", "subtitle": "а҃ Въ коне́цъ, ѡ҆ сынѣ́хъ коре́овыхъ, ѱало́мъ м҃ѕ.", "verses": [{"num": "а҃.", "text": "Всѝ ꙗ҆зы́цы восплещи́те рꙋка́ми, воскли́кните бг҃ꙋ гла́сомъ ра́дованїѧ."}, {"num": "в҃.", "text": "Ꙗ҆́кѡ гдⷭ҇ь вы́шнїй стра́шенъ, цр҃ь ве́лїй по все́й землѝ."}, {"num": "г҃.", "text": "Покорѝ лю́ди на́мъ, и҆ ꙗ҆зы́ки под̾ но́ги на́ша:"}, {"num": "д҃.", "text": "И҆збра̀ на́мъ достоѧ́нїѧ своѐ, добро́тꙋ і҆а́кѡвлю, ю҆́же возлюбѝ. Взы́де бг҃ъ въ"}, {"num": "є҃.", "text": "воскликнове́нїи, гдⷭ҇ь во гла́сѣ трꙋ́бнѣ."}, {"num": "ѕ҃.", "text": "По́йте бг҃ꙋ на́шемꙋ, по́йте, по́йте цр҃е́ви на́шемꙋ, по́йте:"}, {"num": "з҃.", "text": "Ꙗ҆́кѡ цр҃ь всеѧ̀ землѝ бг҃ъ, по́йте разꙋ́мнѡ."}, {"num": "и҃.", "text": "Воцр҃и́сѧ бг҃ъ над̾ ꙗ҆зы̑ки: бг҃ъ сѣди́тъ на прⷭ҇то́лѣ ст҃ѣ́мъ свое́мъ."}, {"num": "ѳ҃.", "text": "Кнѧ̑зи лю́дстїи собра́шасѧ съ бг҃омъ а҆враа́млимъ: ꙗ҆́кѡ бж҃їи держа́внїи землѝ ѕѣлѡ̀ вознесо́шасѧ. а҃ Ѱало́мъ пѣ́сни сынѡ́въ коре́овыхъ, вторы́ѧ сꙋббѡ́ты, м҃з."}]}, "47": {"number": 47, "cu_numeral": "м҃з", "title": "Ѱало́мъ м҃з (47)", "subtitle": "а҃ Ѱало́мъ пѣ́сни сынѡ́въ коре́овыхъ, вторы́ѧ сꙋббѡ́ты, м҃з.", "verses": [{"num": "а҃.", "text": "Ве́лїй гдⷭ҇ь и҆ хва́ленъ ѕѣлѡ,̀ во гра́дѣ бг҃а на́шегѡ, въ горѣ̀ ст҃ѣ́й є҆гѡ̀,"}, {"num": "в҃.", "text": "Бл҃гокоре́ннымъ ра́дованїемъ всеѧ̀ землѝ. го́ры сїѡ́нскїѧ, рє́бра сѣ́верѡва, гра́дъ цр҃ѧ̀ вели́кагѡ. Бг҃ъ въ тѧ́жестѣхъ є҆гѡ̀ зна́емь є҆́сть, є҆гда̀ застꙋпа́етъ и҆̀. Ꙗ҆́кѡ сѐ ца́рїе зе́мстїи собра́шасѧ, снидо́шасѧ вкꙋ́пѣ. Ті́и ви́дѣвше та́кѡ, ᲂу҆диви́шасѧ, смѧто́шасѧ, подвиго́шасѧ: Тре́петъ прїѧ́тъ ѧ҆̀: та́мѡ бѡлѣ́зни ꙗ҆́кѡ рожда́ющїѧ. Дꙋ́хомъ бꙋ́рнымъ сокрꙋши́ши корабли̑ ѳарсі̑йскїѧ. Ꙗ҆́коже слы́шахомъ, та́кѡ и҆"}, {"num": "г҃.", "text": "ви́дѣхомъ во гра́дѣ гдⷭ҇а си́лъ, во гра́дѣ бг҃а"}, {"num": "д҃.", "text": "на́шегѡ: бг҃ъ ѡ҆снова̀ и҆̀ въ вѣ́къ. Прїѧ́хомъ, бж҃е, млⷭ҇ть твою̀ посредѣ̀ люде́й твои́хъ. По и҆́мени"}, {"num": "є҃.", "text": "твоемꙋ̀, бж҃е, та́кѡ и҆ хвала̀ твоѧ̀ на"}, {"num": "ѕ҃.", "text": "конца́хъ землѝ: пра́вды и҆спо́лнь десни́ца твоѧ̀. Да"}, {"num": "з҃.", "text": "возвесели́тсѧ гора̀ сїѡ́нскаѧ, и҆ да возра́дꙋютсѧ дщє́ри і҆ꙋдє́йскїѧ, сꙋде́бъ ра́ди твои́хъ, гдⷭ҇и. Ѡ҆быди́те сїѡ́нъ, и҆ ѡ҆быми́те є҆го̀, повѣ́дите въ столпѣ́хъ є҆гѡ̀: Положи́те сердца̀ ва̑ша въ си́лꙋ є҆гѡ̀, и҆ раздѣли́те до́мы є҆гѡ̀,"}, {"num": "и҃.", "text": "ꙗ҆́кѡ да повѣ́сте въ"}, {"num": "ѳ҃.", "text": "ро́дѣ и҆но́мъ. Ꙗ҆́кѡ то́й"}, {"num": "і҃.", "text": "є҆́сть бг҃ъ на́шъ во"}, {"num": "а҃і.", "text": "вѣ́къ, и҆ въ вѣ́къ"}, {"num": "в҃і.", "text": "вѣ́ка, то́й ᲂу҆пасе́тъ на́съ"}, {"num": "г҃і.", "text": "во вѣ́ки. а҃ Въ"}, {"num": "д҃і.", "text": "коне́цъ, сынѡ́мъ коре́ѡвымъ, ѱало́мъ м҃и."}]}, "48": {"number": 48, "cu_numeral": "м҃и", "title": "Ѱало́мъ м҃и (48)", "subtitle": "а҃ Въ коне́цъ, сынѡ́мъ коре́ѡвымъ, ѱало́мъ м҃и.", "verses": [{"num": "а҃.", "text": "Оу҆слы́шите сїѧ̑ всѝ ꙗ҆зы́цы, внꙋши́те всѝ живꙋ́щїи по вселе́ннѣй,"}, {"num": "в҃.", "text": "Земноро́днїи же и҆ сы́нове человѣ́честїи, вкꙋ́пѣ бога́тъ и҆ ᲂу҆бо́гъ."}, {"num": "г҃.", "text": "Оу҆ста̀ моѧ̑ возглаго́лютъ премꙋ́дрость, и҆ поꙋче́нїе се́рдца моегѡ̀ ра́зꙋмъ."}, {"num": "д҃.", "text": "Приклоню̀ въ при́тчꙋ ᲂу҆́хо моѐ, ѿве́рзꙋ во ѱалти́ри гана́нїе моѐ."}, {"num": "є҃.", "text": "Вскꙋ́ю бою́сѧ въ де́нь лю́тъ; беззако́нїе пѧты̀ моеѧ̀ ѡ҆бы́детъ мѧ̀."}, {"num": "ѕ҃.", "text": "Надѣ́ющїисѧ на си́лꙋ свою̀, и҆ ѡ҆ мно́жествѣ бога́тства своегѡ̀ хва́лѧщїисѧ:"}, {"num": "з҃.", "text": "Бра́тъ не и҆зба́витъ, и҆зба́витъ ли человѣ́къ; не да́стъ бг҃ꙋ и҆змѣ́ны за сѧ̀,"}, {"num": "и҃.", "text": "И҆ цѣ́нꙋ и҆збавле́нїѧ дꙋшѝ своеѧ̀: и҆ ᲂу҆трꙋди́тсѧ въ вѣ́къ,"}, {"num": "ѳ҃.", "text": "И҆ жи́въ бꙋ́детъ до конца̀, не ᲂу҆́зритъ па́гꙋбы. Е҆гда̀ ᲂу҆ви́дитъ премꙋ̑дрыѧ ᲂу҆мира́ющыѧ,"}, {"num": "і҃.", "text": "вкꙋ́пѣ безꙋ́менъ и҆ несмы́сленъ поги́бнꙋтъ, и҆ ѡ҆ста́вѧтъ чꙋжди̑мъ бога́тство своѐ."}, {"num": "а҃і.", "text": "И҆ гро́би и҆́хъ жили̑ща и҆́хъ во вѣ́къ, селє́нїѧ и҆́хъ въ ро́дъ и҆ ро́дъ, нареко́ша и҆мена̀ своѧ̑ на землѧ́хъ."}, {"num": "в҃і.", "text": "И҆ человѣ́къ въ че́сти сы́й не разꙋмѣ̀, приложи́сѧ скотѡ́мъ несмы́слєннымъ, и҆ ᲂу҆подо́бисѧ и҆̀мъ."}, {"num": "г҃і.", "text": "Се́й пꙋ́ть и҆́хъ собла́знъ и҆̀мъ, и҆ по си́хъ во ᲂу҆стѣ́хъ свои́хъ бл҃говолѧ́тъ."}, {"num": "д҃і.", "text": "Ꙗ҆́кѡ ѻ҆́вцы во а҆́дѣ положе́ни сꙋ́ть, сме́рть ᲂу҆пасе́тъ ѧ҆̀: и҆ ѡ҆блада́ютъ и҆́ми пра́вїи заꙋ́тра, и҆ по́мощь и҆́хъ ѡ҆бетша́етъ во а҆́дѣ, ѿ сла́вы своеѧ̀ и҆зринове́ни бы́ша."}, {"num": "є҃і.", "text": "Ѻ҆ба́че бг҃ъ и҆зба́витъ дꙋ́шꙋ мою̀ и҆з̾ рꙋкѝ а҆́довы, є҆гда̀ прїе́млетъ мѧ̀."}, {"num": "ѕ҃і.", "text": "Не ᲂу҆бо́йсѧ, є҆гда̀ разбогатѣ́етъ человѣ́къ, и҆лѝ є҆гда̀ ᲂу҆мно́житсѧ сла́ва до́мꙋ є҆гѡ̀:"}, {"num": "з҃і.", "text": "Ꙗ҆́кѡ внегда̀ ᲂу҆мре́ти є҆мꙋ̀, не во́зметъ всѧ̑, нижѐ сни́детъ съ ни́мъ сла́ва є҆гѡ̀."}, {"num": "и҃і.", "text": "Ꙗ҆́кѡ дꙋша̀ є҆гѡ̀ въ животѣ̀ є҆гѡ̀ бл҃гослови́тсѧ: и҆сповѣ́стсѧ тебѣ̀, є҆гда̀ бл҃госотвори́ши є҆мꙋ̀."}, {"num": "ѳ҃і.", "text": "Вни́детъ да́же до ро́да ѻ҆тє́цъ свои́хъ, да́же до вѣ́ка не ᲂу҆́зритъ свѣ́та."}, {"num": "к҃.", "text": "И҆ человѣ́къ въ че́сти сы́й не разꙋмѣ̀, приложи́сѧ скотѡ́мъ несмы́слєннымъ, и҆ ᲂу҆подо́бисѧ и҆̀мъ. Сла́ва:"}]}, "49": {"number": 49, "cu_numeral": "м҃ѳ", "title": "Ѱало́мъ м҃ѳ (49)", "subtitle": "Ѱало́мъ а҆са́фꙋ, м҃ѳ.", "verses": [{"num": "а҃.", "text": "Бг҃ъ богѡ́въ гдⷭ҇ь глаго́ла, и҆ призва̀ зе́млю, ѿ востѡ́къ со́лнца до за̑падъ."}, {"num": "в҃.", "text": "Ѿ сїѡ́на бл҃голѣ́пїе красоты̀ є҆гѡ̀."}, {"num": "г҃.", "text": "Бг҃ъ ꙗ҆́вѣ"}, {"num": "д҃.", "text": "прїи́детъ, бг҃ъ на́шъ, и҆ не премолчи́тъ: ѻ҆́гнь пред̾ ни́мъ возгори́тсѧ, и҆ ѻ҆́крестъ є҆гѡ̀ бꙋ́рѧ ѕѣ́льна. Призове́тъ нб҃о свы́ше и҆ зе́млю, разсꙋди́ти лю́ди своѧ̑."}, {"num": "є҃.", "text": "Собери́те є҆мꙋ̀ прпⷣбныѧ є҆гѡ̀, завѣща́ющыѧ завѣ́тъ є҆гѡ̀ ѡ҆ є҃ ѕ҃ з҃ и҃ ѳ҃ і҃ а҃і в҃і г҃і д҃і є҃і ѕ҃і з҃і и҃і ѳ҃і к҃ к҃а к҃в к҃г своѧ̑. Собери́те є҆мꙋ̀ прпⷣбныѧ є҆гѡ̀, завѣща́ющыѧ завѣ́тъ є҆гѡ̀ ѡ҆ же́ртвахъ."}, {"num": "ѕ҃.", "text": "И҆ возвѣстѧ́тъ нб҃са̀ пра́вдꙋ є҆гѡ̀, ꙗ҆́кѡ бг҃ъ сꙋдїѧ̀ є҆́сть. Оу҆слы́шите, лю́дїе моѝ,"}, {"num": "з҃.", "text": "и҆ возглаго́лю ва́мъ і҆и҃лю, и҆ засвидѣ́тельствꙋю тебѣ̀: бг҃ъ, бг҃ъ тво́й є҆́смь а҆́зъ."}, {"num": "и҃.", "text": "Не ѡ҆ же́ртвахъ твои́хъ ѡ҆бличꙋ̀ тѧ̀: всесожжє́нїѧ же твоѧ̑ предо мно́ю сꙋ́ть вы́нꙋ."}, {"num": "ѳ҃.", "text": "Не прїимꙋ̀ ѿ до́мꙋ твоегѡ̀ тельцо́въ, нижѐ ѿ ста́дъ твои́хъ козлѡ́въ."}, {"num": "і҃.", "text": "Ꙗ҆́кѡ моѝ сꙋ́ть всѝ ѕвѣ́рїе дꙋбра́внїи, ско́ти въ гора́хъ и҆ воло́ве:"}, {"num": "а҃і.", "text": "Позна́хъ всѧ̑ пти̑цы нбⷭ҇ныѧ, и҆ красота̀ се́льнаѧ со мно́ю є҆́сть."}, {"num": "в҃і.", "text": "А҆́ще вза́лчꙋ, не рекꙋ̀ тебѣ̀: моѧ́ бо є҆́сть вселе́ннаѧ и҆ и҆сполне́нїе є҆ѧ̀."}, {"num": "г҃і.", "text": "Е҆да̀ ꙗ҆́мъ мѧса̀ ю҆́нча; и҆лѝ кро́вь козлѡ́въ пїю̀;"}, {"num": "д҃і.", "text": "Пожрѝ бг҃ови же́ртвꙋ хвалы̀ и҆ возда́ждь вы́шнемꙋ мл҃твы твоѧ̑:"}, {"num": "є҃і.", "text": "И҆ призови́ мѧ въ де́нь ско́рби твоеѧ̀, и҆ и҆змꙋ́ тѧ, и҆ просла́виши мѧ̀."}, {"num": "ѕ҃і.", "text": "Грѣ́шникꙋ же речѐ бг҃ъ: вскꙋ́ю ты̀ повѣ́даеши ѡ҆правда̑нїѧ моѧ̑, и҆ воспрїе́млеши завѣ́тъ мо́й ᲂу҆сты̀ твои́ми;"}, {"num": "з҃і.", "text": "Ты́ же возненави́дѣлъ є҆сѝ наказа́нїе, и҆ ѿве́рглъ є҆сѝ словеса̀ моѧ̑ вспѧ́ть."}, {"num": "и҃і.", "text": "А҆́ще ви́дѣлъ є҆сѝ та́тѧ, те́клъ є҆сѝ съ ни́мъ, и҆ съ прелюбодѣ́емъ ᲂу҆ча́стїе твоѐ полага́лъ є҆сѝ."}, {"num": "ѳ҃і.", "text": "Оу҆ста̀ твоѧ̑ ᲂу҆мно́жиша ѕло́бꙋ, и҆ ѧ҆зы́къ тво́й сплета́ше льщє́нїѧ:"}, {"num": "к҃.", "text": "Сѣдѧ̀ на бра́та твоего̀ клевета́лъ є҆сѝ и҆ на сы́на ма́тере твоеѧ̀ полага́лъ є҆сѝ собла́знъ."}, {"num": "к҃а.", "text": "Сїѧ̑ сотвори́лъ є҆сѝ, и҆ ᲂу҆молча́хъ: вознепщева́лъ є҆сѝ беззако́нїе, ꙗ҆́кѡ бꙋ́дꙋ тебѣ̀ подо́бенъ: ѡ҆бличꙋ́ тѧ и҆ предста́влю пред̾ лице́мъ твои́мъ грѣхѝ твоѧ̑."}, {"num": "к҃в.", "text": "Разꙋмѣ́йте ᲂу҆́бѡ сїѧ̑, забыва́ющїи бг҃а, да не когда̀ похи́титъ, и҆ не бꙋ́детъ и҆збавлѧ́ѧй."}, {"num": "к҃г.", "text": "Же́ртва хвалы̀ просла́витъ мѧ̀, и҆ та́мѡ пꙋ́ть и҆́мже ꙗ҆влю̀ є҆мꙋ̀ сп҃се́нїе моѐ. а҃ в҃"}]}, "50": {"number": 50, "cu_numeral": "н҃", "title": "Ѱало́мъ н҃ (50)", "subtitle": "є҆гда̀ вни́де къ вирсаві́и, женѣ̀ ᲂу҆рі́евѣ, н҃.", "verses": [{"num": "а҃.", "text": "Поми́лꙋй мѧ̀, бж҃е, по вели́цѣй млⷭ҇ти твое́й, и҆ по мно́жествꙋ щедро́тъ твои́хъ ѡ҆чи́сти беззако́нїе"}, {"num": "в҃.", "text": "моѐ. Наипа́че ѡ҆мы́й мѧ̀ ѿ беззако́нїѧ моегѡ̀ и҆ ѿ грѣха̀ моегѡ̀ ѡ҆чи́сти мѧ̀:"}, {"num": "г҃.", "text": "Ꙗ҆́кѡ беззако́нїе моѐ а҆́зъ зна́ю, и҆ грѣ́хъ мо́й предо мно́ю є҆́сть вы́нꙋ."}, {"num": "д҃.", "text": "Тебѣ̀ є҆ди́номꙋ согрѣши́хъ, и҆ лꙋка́вое пред̾ тобо́ю сотвори́хъ: ꙗ҆́кѡ да ѡ҆правди́шисѧ во словесѣ́хъ твои́хъ, и҆ побѣди́ши, внегда̀ сꙋди́ти тѝ."}, {"num": "є҃.", "text": "Се́ бо въ беззако́нїихъ зача́тъ є҆́смь, и҆ во грѣсѣ́хъ роди́ мѧ ма́ти моѧ̀."}, {"num": "ѕ҃.", "text": "Се́ бо и҆́стинꙋ возлюби́лъ є҆сѝ, безвѣ̑стнаѧ и҆ та̑йнаѧ премꙋ́дрости твоеѧ̀ ꙗ҆ви́лъ мѝ є҆сѝ."}, {"num": "з҃.", "text": "Ѡ҆кропи́ши мѧ̀ ѵ҆ссѡ́помъ, и҆ ѡ҆чи́щꙋсѧ: ѡ҆мы́еши мѧ̀, и҆ па́че снѣ́га ᲂу҆бѣлю́сѧ."}, {"num": "и҃.", "text": "Слꙋ́хꙋ моемꙋ̀ да́си ра́дость и҆ весе́лїе, возра́дꙋютсѧ кѡ́сти смирє́нныѧ."}, {"num": "ѳ҃.", "text": "Ѿвратѝ лицѐ твоѐ ѿ а҃і в҃і г҃і д҃і є҃і ѕ҃і з҃і и҃і ѳ҃і к҃ к҃а весе́лїе, возра́дꙋютсѧ кѡ́сти смирє́нныѧ. Ѿвратѝ лицѐ твоѐ ѿ грѣ̑хъ мои́хъ, и҆ всѧ̑ беззакѡ́нїѧ моѧ̑ ѡ҆чи́сти."}, {"num": "і҃.", "text": "Се́рдце чи́сто сози́жди во мнѣ̀, бж҃е, и҆ дꙋ́хъ пра́въ ѡ҆бновѝ во ᲂу҆тро́бѣ мое́й."}, {"num": "а҃і.", "text": "Не ѿве́ржи менѐ̀ ѿ лица̀ твоегѡ̀, и҆ дх҃а твоегѡ̀ ст҃а́гѡ не ѿимѝ ѿ менѐ."}, {"num": "в҃і.", "text": "Возда́ждь мѝ ра́дость сп҃се́нїѧ твоегѡ̀ и҆ дх҃омъ влⷣчнимъ ᲂу҆тверди́ мѧ."}, {"num": "г҃і.", "text": "Наꙋчꙋ̀ беззакѡ́нныѧ пꙋтє́мъ твои̑мъ, и҆ нечести́вїи къ тебѣ̀ ѡ҆братѧ́тсѧ."}, {"num": "д҃і.", "text": "И҆зба́ви мѧ̀ ѿ крове́й, бж҃е, бж҃е сп҃се́нїѧ моегѡ̀: возра́дꙋетсѧ ѧ҆зы́къ мо́й пра́вдѣ твое́й."}, {"num": "є҃і.", "text": "Гдⷭ҇и, ᲂу҆стнѣ̀ моѝ ѿве́рзеши, и҆ ᲂу҆ста̀ моѧ̑ возвѣстѧ́тъ хвалꙋ̀ твою̀."}, {"num": "ѕ҃і.", "text": "Ꙗ҆́кѡ а҆́ще бы восхотѣ́лъ є҆сѝ же́ртвы, да́лъ бы́хъ ᲂу҆́бѡ: всесожже́нїѧ не бл҃говоли́ши."}, {"num": "з҃і.", "text": "Же́ртва бг҃ꙋ дꙋ́хъ сокрꙋше́нъ: се́рдце сокрꙋше́нно и҆ смире́нно бг҃ъ не ᲂу҆ничижи́тъ: Оу҆бл҃жѝ, гдⷭ҇и, бл҃говоле́нїемъ твои́мъ сїѡ́на и҆ да сози́ждꙋтсѧ"}, {"num": "и҃і.", "text": "стѣ́ны і҆ерⷭ҇ли̑мскїѧ."}, {"num": "ѳ҃і.", "text": "Тогда̀ бл҃говоли́ши же́ртвꙋ пра́вды, возноше́нїе и҆ всесожега́ємаѧ: тогда̀ возложа́тъ на ѻ҆лта́рь тво́й тельцы̀. Сла́ва: а҃ в҃ Въ коне́цъ, ра́зꙋма дв҃дꙋ, Внегда̀ прїитѝ дѡи́кꙋ і҆дꙋме́йскꙋ, и҆ возвѣсти́ти саꙋ́лꙋ, и҆ рещѝ є҆мꙋ̀: прїи́де дв҃дъ въ до́мъ а҆вїмеле́ховъ, н҃а."}]}, "51": {"number": 51, "cu_numeral": "н҃а", "title": "Ѱало́мъ н҃а (51)", "subtitle": "саꙋ́лꙋ, и҆ рещѝ є҆мꙋ̀: прїи́де дв҃дъ въ до́мъ а҆вїмеле́ховъ, н҃а.", "verses": [{"num": "а҃.", "text": "Что̀ хва́лишисѧ во ѕло́бѣ, си́льне; беззако́нїе ве́сь де́нь,"}, {"num": "в҃.", "text": "Непра́вдꙋ ᲂу҆мы́сли ѧ҆зы́къ тво́й: ꙗ҆́кѡ бри́твꙋ и҆з̾ѡщре́нꙋ сотвори́лъ є҆сѝ ле́сть."}, {"num": "г҃.", "text": "Возлюби́лъ є҆сѝ ѕло́бꙋ па́че бл҃госты́ни, непра́вдꙋ, не́же глаго́лати пра́вдꙋ:"}, {"num": "д҃.", "text": "Возлюби́лъ є҆сѝ всѧ̑ глаго́лы потѡ́пныѧ, ѧ҆зы́къ льсти́въ."}, {"num": "є҃.", "text": "Сегѡ̀ ра́ди бг҃ъ разрꙋши́тъ тѧ̀ до конца̀,"}, {"num": "ѕ҃.", "text": "восто́ргнетъ тѧ̀, и҆ пресели́тъ тѧ̀ ѿ селе́нїѧ твоегѡ̀, и҆ ко́рень тво́й ѿ землѝ живы́хъ. Оу҆́зрѧтъ првⷣнїи, и҆ ᲂу҆боѧ́тсѧ, и҆ ѡ҆ не́мъ возсмѣю́тсѧ, и҆ рекꙋ́тъ:"}, {"num": "з҃.", "text": "Сѐ человѣ́къ, и҆́же не положѝ бг҃а помо́щника себѣ̀: но ᲂу҆пова̀ на мно́жество бога́тства своегѡ̀, и҆ возмо́же сꙋето́ю свое́ю."}, {"num": "и҃.", "text": "А҆́зъ же ꙗ҆́кѡ ма́слина плодови́та въ домꙋ̀ бж҃їи: ᲂу҆пова́хъ на млⷭ҇ть бж҃їю во вѣ́къ, и҆ въ вѣ́къ вѣ́ка."}, {"num": "ѳ҃.", "text": "И҆сповѣ́мсѧ тебѣ̀ въ вѣ́къ, ꙗ҆́кѡ сотвори́лъ є҆сѝ: и҆ терплю̀ и҆́мѧ твоѐ, ꙗ҆́кѡ бл҃го пред̾ прпⷣбными твои́ми. а҃ Въ коне́цъ, ѡ҆ маеле́ѳѣ, ра́зꙋма дв҃дꙋ, н҃в."}]}, "52": {"number": 52, "cu_numeral": "н҃в", "title": "Ѱало́мъ н҃в (52)", "subtitle": "а҃ Въ коне́цъ, ѡ҆ маеле́ѳѣ, ра́зꙋма дв҃дꙋ, н҃в.", "verses": [{"num": "а҃.", "text": "Речѐ безꙋ́менъ въ се́рдцѣ свое́мъ: нѣ́сть бг҃ъ. растлѣ́ша и҆ ѡ҆мерзи́шасѧ въ беззако́нїихъ, нѣ́сть творѧ́й бл҃го́е:"}, {"num": "в҃.", "text": "Бг҃ъ съ нб҃сѐ прини́че на сы́ны человѣ́чєскїѧ, ви́дѣти: а҆́ще є҆́сть разꙋмѣва́ѧй, и҆лѝ взыска́ѧй д҃ є҃ ѕ҃ з҃ сы́ны человѣ́чєскїѧ, ви́дѣти: а҆́ще є҆́сть разꙋмѣва́ѧй, и҆лѝ взыска́ѧй бг҃а."}, {"num": "г҃.", "text": "Всѝ ᲂу҆клони́шасѧ, вкꙋ́пѣ непотре́бни бы́ша: нѣ́сть творѧ́й бл҃го́е, нѣ́сть до є҆ди́нагѡ."}, {"num": "д҃.", "text": "Ни лѝ ᲂу҆разꙋмѣ́ютъ всѝ дѣ́лающїи беззако́нїе, снѣда́ющїи лю́ди моѧ̑ въ снѣ́дь хлѣ́ба; гдⷭ҇а не призва́ша."}, {"num": "є҃.", "text": "Та́мѡ ᲂу҆страши́шасѧ стра́ха, и҆дѣ́же не бѣ̀ стра́хъ:"}, {"num": "ѕ҃.", "text": "ꙗ҆́кѡ бг҃ъ разсы́па кѡ́сти человѣкоꙋго́дникѡвъ: постыдѣ́шасѧ, ꙗ҆́кѡ бг҃ъ ᲂу҆ничижѝ и҆̀хъ."}, {"num": "з҃.", "text": "Кто̀ да́стъ ѿ сїѡ́на сп҃се́нїе і҆и҃лево; внегда̀ возврати́тъ бг҃ъ плѣне́нїе люде́й свои́хъ, возра́дꙋетсѧ і҆а́кѡвъ, и҆ возвесели́тсѧ і҆и҃ль. а҃ в҃ Въ коне́цъ, въ пѣ́снехъ ра́зꙋма дв҃дꙋ, Внегда̀ прїитѝ зїфе́ємъ, и҆ рещѝ саꙋ́лови: не се́ ли дв҃дъ скры́сѧ въ на́съ; н҃г."}]}, "53": {"number": 53, "cu_numeral": "н҃г", "title": "Ѱало́мъ н҃г (53)", "subtitle": "и҆ рещѝ саꙋ́лови: не се́ ли дв҃дъ скры́сѧ въ на́съ; н҃г.", "verses": [{"num": "а҃.", "text": "Бж҃е, во и҆́мѧ твоѐ сп҃си́ мѧ, и҆ въ си́лѣ твое́й сꙋди́ ми."}, {"num": "в҃.", "text": "Бж҃е, ᲂу҆слы́ши моли́твꙋ мою̀, внꙋшѝ глаго́лы ᲂу҆́стъ мои́хъ:"}, {"num": "г҃.", "text": "Ꙗ҆́кѡ чꙋ́ждїи воста́ша на мѧ̀, и҆ крѣ́пцыи взыска́ша дꙋ́шꙋ мою̀: и҆ не предложи́ша бг҃а пред̾ собо́ю."}, {"num": "д҃.", "text": "Се́ бо бг҃ъ помога́етъ мѝ, и҆ гдⷭ҇ь застꙋ́пникъ дꙋшѝ мое́й:"}, {"num": "є҃.", "text": "Ѿврати́тъ ѕла̑ѧ врагѡ́мъ мои̑мъ: и҆́стиною твое́ю потребѝ и҆̀хъ."}, {"num": "ѕ҃.", "text": "Во́лею пожрꙋ̀ тебѣ̀, и҆сповѣ́мсѧ и҆́мени твоемꙋ̀ гдⷭ҇и, ꙗ҆́кѡ бла́го:"}, {"num": "з҃.", "text": "Ꙗ҆́кѡ ѿ всѧ́кїѧ печа́ли и҆зба́вилъ мѧ̀ є҆сѝ, и҆ на врагѝ моѧ̑ воззрѣ̀ ѻ҆́ко моѐ. а҃ Въ коне́цъ, въ пѣ́снехъ ра́зꙋма, а҆са́фꙋ, ѱало́мъ н҃д."}]}, "54": {"number": 54, "cu_numeral": "н҃д", "title": "Ѱало́мъ н҃д (54)", "subtitle": "а҃ Въ коне́цъ, въ пѣ́снехъ ра́зꙋма, а҆са́фꙋ, ѱало́мъ н҃д.", "verses": [{"num": "а҃.", "text": "Внꙋшѝ, бж҃е, мл҃твꙋ мою̀, и҆ не пре́зри моле́нїѧ моегѡ̀:"}, {"num": "в҃.", "text": "Вонми́ ми, и҆ ᲂу҆слы́ши мѧ̀: возскорбѣ́хъ печа́лїю мое́ю, и҆ смѧто́хсѧ"}, {"num": "г҃.", "text": "Ѿ гла́са вра́жїѧ и҆ ѿ стꙋже́нїѧ грѣ́шнича: ꙗ҆́кѡ ᲂу҆клони́ша на мѧ̀ беззако́нїе, и҆ во гнѣ́вѣ враждова́хꙋ мѝ."}, {"num": "д҃.", "text": "Се́рдце моѐ смѧте́сѧ во мнѣ̀, и҆ боѧ́знь сме́рти нападѐ на мѧ̀:"}, {"num": "є҃.", "text": "Стра́хъ и҆ тре́петъ прїи́де на мѧ̀, и҆ покры́ мѧ тьма̀. И҆ рѣ́хъ: кто̀ да́стъ мѝ крилѣ̑ ꙗ҆́кѡ голꙋби̑нѣ; и҆ полещꙋ̀, и҆ почі́ю."}, {"num": "ѕ҃.", "text": "Сѐ ᲂу҆дали́хсѧ бѣ́гаѧ, и҆ водвори́хсѧ въ пꙋсты́ни."}, {"num": "з҃.", "text": "Ча́ѧхъ бг҃а спаса́ющагѡ мѧ̀ ѿ малодꙋ́шїѧ и҆ ѿ бꙋ́ри."}, {"num": "и҃.", "text": "Потопѝ, гдⷭ҇и, и҆ раздѣлѝ ѧ҆зы́ки и҆́хъ: ꙗ҆́кѡ ви́дѣхъ беззако́нїе и҆ пререка́нїе во гра́дѣ."}, {"num": "ѳ҃.", "text": "Дне́мъ и҆ но́щїю ѡ҆бы́детъ и҆̀ по стѣна́мъ є҆гѡ̀: беззако́нїе и҆ трꙋ́дъ посредѣ̀ є҆гѡ̀, и҆ непра́вда:"}, {"num": "і҃.", "text": "И҆ не ѡ҆скꙋдѣ̀ ѿ сто́гнъ є҆гѡ̀ ли́хва и҆ ле́сть."}, {"num": "а҃і.", "text": "Ꙗ҆́кѡ а҆́ще бы вра́гъ поноси́лъ мѝ, претерпѣ́лъ бы́хъ ᲂу҆́бѡ: и҆ а҆́ще бы ненави́дѧй мѧ̀ на мѧ̀ велерѣ́чевалъ, ᲂу҆кры́лъ быхъ сѧ ѿ негѡ̀."}, {"num": "в҃і.", "text": "Ты́ же человѣ́че равнодꙋ́шне, влады́ко мо́й и҆ зна́емый мо́й,"}, {"num": "г҃і.", "text": "И҆́же кꙋ́пнѡ наслажда́лсѧ є҆сѝ со мно́ю бра́шенъ: въ домꙋ̀ бж҃їи є҃і ѕ҃і з҃і и҃і ѳ҃і к҃ к҃а к҃в к҃г к҃д И҆́же кꙋ́пнѡ наслажда́лсѧ є҆сѝ со мно́ю бра́шенъ: въ домꙋ̀ бж҃їи ходи́хомъ є҆диномышле́нїемъ."}, {"num": "д҃і.", "text": "Да прїи́детъ же сме́рть на нѧ̀, и҆ да сни́дꙋтъ во а҆́дъ жи́ви: ꙗ҆́кѡ лꙋка́вство въ жили́щихъ и҆́хъ посредѣ̀ и҆́хъ."}, {"num": "є҃і.", "text": "А҆́зъ къ бг҃ꙋ воззва́хъ, и҆ гдⷭ҇ь ᲂу҆слы́ша мѧ̀."}, {"num": "ѕ҃і.", "text": "Ве́черъ и҆ заꙋ́тра и҆ полꙋ́дне повѣ́мъ, и҆ возвѣщꙋ̀, и҆ ᲂу҆слы́шитъ гла́съ мо́й."}, {"num": "з҃і.", "text": "И҆зба́витъ ми́ромъ дꙋ́шꙋ мою̀ ѿ приближа́ющихсѧ мнѣ̀: ꙗ҆́кѡ во мно́зѣ бѧ́хꙋ со мно́ю."}, {"num": "и҃і.", "text": "Оу҆слы́шитъ бг҃ъ, и҆ смири́тъ ѧ҆̀, сы́й пре́жде вѣ̑къ. нѣ́сть бо и҆̀мъ и҆змѣне́нїѧ, ꙗ҆́кѡ не ᲂу҆боѧ́шасѧ бг҃а."}, {"num": "ѳ҃і.", "text": "Прострѐ рꙋ́кꙋ свою̀ на воздаѧ́нїе: ѡ҆скверни́ша завѣ́тъ є҆гѡ̀."}, {"num": "к҃.", "text": "Раздѣли́шасѧ ѿ гнѣ́ва лица̀ є҆гѡ̀, и҆ прибли́жишасѧ сердца̀ и҆́хъ: ᲂу҆мѧ́кнꙋша словеса̀ и҆́хъ па́че є҆ле́а и҆ та̑ сꙋ́ть стрѣ́лы."}, {"num": "к҃а.", "text": "Возве́рзи на гдⷭ҇а печа́ль твою̀, и҆ то́й тѧ̀ препита́етъ: не да́стъ въ вѣ́къ молвы̀ првⷣникꙋ."}, {"num": "к҃в.", "text": "Ты́ же, бж҃е, низведе́ши и҆̀хъ въ стꙋдене́цъ и҆стлѣ́нїѧ: мꙋ́жїе крове́й и҆ льстѝ не преполовѧ́тъ дне́й свои́хъ. а҆́зъ же, гдⷭ҇и, ᲂу҆пова́ю на тѧ̀. Сла́ва:"}]}, "55": {"number": 55, "cu_numeral": "н҃є", "title": "Ѱало́мъ н҃є (55)", "subtitle": "внегда̀ ᲂу҆держа́ша и҆̀ и҆ноплемє́нницы въ ге́ѳѣ, ѱало́мъ н҃є.", "verses": [{"num": "а҃.", "text": "Поми́лꙋй мѧ̀, бж҃е, ꙗ҆́кѡ попра́ мѧ человѣ́къ: ве́сь де́нь борѧ̀ стꙋжи́ ми."}, {"num": "в҃.", "text": "Попра́ша мѧ̀ вразѝ моѝ ве́сь де́нь: ꙗ҆́кѡ мно́зи борю́щїи мѧ̀ съ высоты̀."}, {"num": "г҃.", "text": "Въ де́нь не ᲂу҆бою́сѧ, а҆́зъ же ᲂу҆пова́ю на тѧ̀."}, {"num": "д҃.", "text": "Ѡ҆ бз҃ѣ похвалю̀ словеса̀ моѧ̑: на бг҃а ᲂу҆пова́хъ, не ᲂу҆бою́сѧ, что̀ сотвори́тъ мнѣ̀ пло́ть."}, {"num": "є҃.", "text": "Ве́сь де́нь слове́съ мои́хъ гнꙋша́хꙋсѧ: на мѧ̀ всѧ̑ помышлє́нїѧ и҆́хъ на ѕло̀."}, {"num": "ѕ҃.", "text": "Вселѧ́тсѧ и҆ скры́ютъ: ті́и пѧ́тꙋ мою̀ сохранѧ́тъ, ꙗ҆́коже потерпѣ́ша дꙋ́шꙋ мою̀."}, {"num": "з҃.", "text": "Ни ѡ҆ чесо́мъ же ѿри́неши ѧ҆̀, гнѣ́вомъ лю́ди низведе́ши."}, {"num": "и҃.", "text": "Бж҃е, живо́тъ мо́й возвѣсти́хъ тебѣ̀: положи́лъ є҆сѝ сле́зы моѧ̑ пред̾ тобо́ю, ꙗ҆́кѡ и҆ во ѡ҆бѣтова́нїи твое́мъ."}, {"num": "ѳ҃.", "text": "Да возвратѧ́тсѧ вразѝ моѝ вспѧ́ть, во́ньже а҆́ще де́нь призовꙋ́ тѧ: сѐ позна́хъ, ꙗ҆́кѡ бг҃ъ мо́й є҆сѝ ты̀."}, {"num": "і҃.", "text": "Ѡ҆ бз҃ѣ похвалю̀ глаго́лъ, ѡ҆ гдⷭ҇ѣ похвалю̀ сло́во."}, {"num": "а҃і.", "text": "На бг҃а ᲂу҆пова́хъ, не ᲂу҆бою́сѧ, что̀ сотвори́тъ мнѣ̀ человѣ́къ;"}, {"num": "в҃і.", "text": "Во мнѣ̀, бж҃е, мл҃твы, ꙗ҆̀же возда́мъ хвалы̀ твоеѧ̀:"}, {"num": "г҃і.", "text": "Ꙗ҆́кѡ и҆зба́вилъ є҆сѝ дꙋ́шꙋ мою̀ ѿ сме́рти, ѻ҆́чи моѝ ѿ сле́зъ, и҆ но́зѣ моѝ ѿ поползнове́нїѧ: бл҃гоꙋгождꙋ̀ пред̾ гдⷭ҇емъ во свѣ́тѣ живы́хъ. а҃ Въ коне́цъ, да не растли́ши, дв҃дꙋ въ столпописа́нїе, внегда̀ є҆мꙋ̀ ѿбѣга́ти ѿ лица̀ саꙋ́лова въ пеще́рꙋ, н҃ѕ."}]}, "56": {"number": 56, "cu_numeral": "н҃ѕ", "title": "Ѱало́мъ н҃ѕ (56)", "subtitle": "внегда̀ є҆мꙋ̀ ѿбѣга́ти ѿ лица̀ саꙋ́лова въ пеще́рꙋ, н҃ѕ.", "verses": [{"num": "а҃.", "text": "Поми́лꙋй мѧ̀, бж҃е, поми́лꙋй мѧ̀: ꙗ҆́кѡ на тѧ̀ ᲂу҆пова̀ дꙋша̀ моѧ̀, и҆ на сѣ́нь крилꙋ̑ твоє́ю надѣ́юсѧ, до́ндеже пре́йдетъ беззако́нїе."}, {"num": "в҃.", "text": "Воззовꙋ̀ къ бг҃ꙋ вы́шнемꙋ, бг҃ꙋ бл҃годѣ́ѧвшемꙋ мнѣ̀."}, {"num": "г҃.", "text": "Посла̀ съ нб҃сѐ и҆ сп҃се́ мѧ, дадѐ въ поноше́нїе попира́ющыѧ мѧ̀: посла̀ бг҃ъ млⷭ҇ть свою̀ и҆ и҆́стинꙋ свою̀,"}, {"num": "д҃.", "text": "И҆ и҆зба́ви дꙋ́шꙋ мою̀ ѿ среды̀ скѵ́мнѡвъ: поспа́хъ смꙋще́нъ. сы́нове человѣ́честїи, зꙋ́бы и҆́хъ ѻ҆рꙋ̑жїѧ и҆ стрѣ́лы, и҆ ѧ҆зы́къ и҆́хъ ме́чь ѻ҆́стръ."}, {"num": "є҃.", "text": "Вознеси́сѧ на нб҃са̀, бж҃е, и҆ по все́й землѝ сла́ва твоѧ̀."}, {"num": "ѕ҃.", "text": "Сѣ́ть ᲂу҆гото́ваша нога́мъ мои̑мъ, и҆ слѧко́ша дꙋ́шꙋ мою̀: и҆скопа́ша пред̾ лице́мъ мои́мъ ꙗ҆́мꙋ, и҆ впадо́ша въ ню̀."}, {"num": "з҃.", "text": "Гото́во се́рдце моѐ, бж҃е, гото́во се́рдце моѐ: воспою̀ и҆ пою̀ во сла́вѣ мое́й."}, {"num": "и҃.", "text": "Воста́ни сла́ва моѧ̀, воста́ни ѱалти́рю и҆ гꙋ́сли: воста́нꙋ ра́нѡ."}, {"num": "ѳ҃.", "text": "И҆сповѣ́мсѧ тебѣ̀ въ лю́дехъ, гдⷭ҇и, воспою̀ тебѣ̀ во ꙗ҆зы́цѣхъ: Ꙗ҆́кѡ возвели́чисѧ а҃і в҃і тебѣ̀ въ лю́дехъ, гдⷭ҇и, воспою̀ тебѣ̀ во ꙗ҆зы́цѣхъ:"}, {"num": "і҃.", "text": "Ꙗ҆́кѡ возвели́чисѧ до небе́съ млⷭ҇ть твоѧ̀ и҆ да́же до ѻ҆́блакъ и҆́стина твоѧ̀."}, {"num": "а҃і.", "text": "Вознеси́сѧ на нб҃са̀, бж҃е, и҆ по все́й землѝ сла́ва твоѧ̀. а҃ Въ коне́цъ, да не растли́ши, дв҃дꙋ въ столпописа́нїе, н҃з."}]}, "57": {"number": 57, "cu_numeral": "н҃з", "title": "Ѱало́мъ н҃з (57)", "subtitle": "а҃ Въ коне́цъ, да не растли́ши, дв҃дꙋ въ столпописа́нїе, н҃з.", "verses": [{"num": "а҃.", "text": "А҆́ще вои́стиннꙋ ᲂу҆́бѡ пра́вдꙋ глаго́лете, пра̑ваѧ сꙋди́те, сы́нове человѣ́честїи."}, {"num": "в҃.", "text": "И҆́бо въ се́рдцѣ беззако́нїе дѣ́лаете на землѝ, непра́вдꙋ рꙋ́ки ва́шѧ сплета́ютъ."}, {"num": "г҃.", "text": "Ѡ҆чꙋжди́шасѧ грѣ̑шницы ѿ ложе́снъ, заблꙋди́ша ѿ чре́ва, глаго́лаша лжꙋ̀."}, {"num": "д҃.", "text": "Ꙗ҆́рость и҆́хъ по подо́бїю ѕмїинꙋ̀, ꙗ҆́кѡ а҆́спїда глꙋ́ха и҆ затыка́ющагѡ ᲂу҆́ши своѝ,"}, {"num": "є҃.", "text": "И҆́же не ᲂу҆слы́шитъ гла́са ѡ҆бава́ющихъ, ѡ҆бава́емь ѡ҆бава́етсѧ ѿ премꙋ́дра."}, {"num": "ѕ҃.", "text": "Бг҃ъ сокрꙋши́тъ зꙋ́бы и҆́хъ во ᲂу҆стѣ́хъ и҆́хъ: членѡ́вныѧ львѡ́въ сокрꙋши́лъ є҆́сть гдⷭ҇ь."}, {"num": "з҃.", "text": "Оу҆ничижа́тсѧ ꙗ҆́кѡ вода̀ мимотекꙋ́щаѧ: напрѧже́тъ лꙋ́къ сво́й, до́ндеже и҆знемо́гꙋтъ."}, {"num": "и҃.", "text": "Ꙗ҆́кѡ во́скъ раста́ѧвъ ѿи́мꙋтсѧ: падѐ ѻ҆́гнь на ни́хъ, и҆ не ви́дѣша со́лнца."}, {"num": "ѳ҃.", "text": "Пре́жде є҆́же разꙋмѣ́ти те́рнїѧ ва́шегѡ ра́мна, ꙗ҆́кѡ жи̑вы, ꙗ҆́кѡ во гнѣ́вѣ пожре́тъ ѧ҆̀."}, {"num": "і҃.", "text": "Возвесели́тсѧ првⷣникъ, є҆гда̀ ᲂу҆ви́дитъ ѿмще́нїе, рꙋ́цѣ своѝ ᲂу҆мы́етъ въ кро́ви грѣ́шника."}, {"num": "а҃і.", "text": "И҆ рече́тъ человѣ́къ: а҆́ще ᲂу҆́бѡ є҆́сть пло́дъ првⷣникꙋ, ᲂу҆̀бо є҆́сть бг҃ъ сꙋдѧ̀ и҆̀мъ на землѝ. Сла́ва: а҃ Въ коне́цъ, да не растли́ши, дв҃дꙋ въ столпописа́нїе, внегда̀ посла̀ саꙋ́лъ, и҆ стрежѐ до́мъ є҆гѡ̀, є҆́же ᲂу҆мертви́ти є҆го̀, н҃и."}]}, "58": {"number": 58, "cu_numeral": "н҃и", "title": "Ѱало́мъ н҃и (58)", "subtitle": "внегда̀ посла̀ саꙋ́лъ, и҆ стрежѐ до́мъ є҆гѡ̀, є҆́же ᲂу҆мертви́ти є҆го̀, н҃и.", "verses": [{"num": "а҃.", "text": "И҆зми́ мѧ ѿ вра̑гъ мои́хъ, бж҃е, и҆ ѿ востаю́щихъ на мѧ̀ и҆зба́ви мѧ̀."}, {"num": "в҃.", "text": "И҆зба́ви мѧ̀ ѿ дѣ́лающихъ беззако́нїе, и҆ ѿ мꙋ̑жъ крове́й сп҃си́ мѧ."}, {"num": "г҃.", "text": "Ꙗ҆́кѡ сѐ ᲂу҆лови́ша дꙋ́шꙋ мою̀, нападо́ша на мѧ̀ крѣ́пцыи: нижѐ беззако́нїе моѐ, нижѐ грѣ́хъ мо́й, гдⷭ҇и."}, {"num": "д҃.", "text": "Без̾ беззако́нїѧ теко́хъ"}, {"num": "є҃.", "text": "и҆ и҆спра́вихъ: воста́ни въ срѣ́тенїе моѐ, и҆ ви́ждь. И҆ ты̀, гдⷭ҇и бж҃е си́лъ, бж҃е і҆и҃левъ, вонмѝ посѣти́ти всѧ̑ ꙗ҆зы́ки: да не ᲂу҆ще́дриши всѧ̑ дѣ́лающыѧ беззако́нїе."}, {"num": "ѕ҃.", "text": "Возвратѧ́тсѧ на ве́черъ, и҆ вза́лчꙋтъ ꙗ҆́кѡ пе́съ, и҆ ѡ҆бы́дꙋтъ гра́дъ."}, {"num": "з҃.", "text": "Сѐ ті́и ѿвѣща́ютъ ᲂу҆сты̑ свои́ми,"}, {"num": "и҃.", "text": "и҆ ме́чь во ᲂу҆стна́хъ и҆́хъ, ꙗ҆́кѡ кто̀ слы́ша; И҆ ты̀, гдⷭ҇и, посмѣе́шисѧ и҆̀мъ, ᲂу҆ничижи́ши всѧ̑ ꙗ҆зы́ки."}, {"num": "ѳ҃.", "text": "Держа́вꙋ мою̀ къ тебѣ̀ сохраню̀: ꙗ҆́кѡ ты̀, бж҃е, застꙋ́пникъ мо́й є҆сѝ. Бг҃ъ мо́й, млⷭ҇ть є҆гѡ̀ предвари́тъ мѧ̀:"}, {"num": "і҃.", "text": "бг҃ъ мо́й, ꙗ҆ви́тъ мнѣ̀ на вразѣ́хъ мои́хъ."}, {"num": "а҃і.", "text": "Не ᲂу҆бі́й и҆̀хъ, да не когда̀ в҃і г҃і д҃і є҃і ѕ҃і з҃і и҃і мо́й, ꙗ҆ви́тъ мнѣ̀ на вразѣ́хъ мои́хъ. Не ᲂу҆бі́й и҆̀хъ, да не когда̀ забꙋ́дꙋтъ зако́нъ тво́й: расточѝ ѧ҆̀ си́лою твое́ю, и҆ низведѝ ѧ҆̀, защи́тниче мо́й, гдⷭ҇и."}, {"num": "в҃і.", "text": "Грѣ́хъ ᲂу҆́стъ и҆́хъ, сло́во ᲂу҆сте́нъ и҆́хъ: и҆ ꙗ҆́ти да бꙋ́дꙋтъ въ горды́ни свое́й, и҆ ѿ клѧ́твы и҆ лжѝ возвѣстѧ́тсѧ въ кончи́нѣ."}, {"num": "г҃і.", "text": "Во гнѣ́вѣ кончи́ны, и҆ не бꙋ́дꙋтъ: и҆ ᲂу҆вѣ́дѧтъ, ꙗ҆́кѡ бг҃ъ влⷣчествꙋетъ і҆а́кѡвомъ, и҆ концы̑ землѝ."}, {"num": "д҃і.", "text": "Возвратѧ́тсѧ на ве́черъ, и҆ вза́лчꙋтъ ꙗ҆́кѡ пе́съ, и҆ ѡ҆бы́дꙋтъ гра́дъ."}, {"num": "є҃і.", "text": "Ті́и разы́дꙋтсѧ ꙗ҆́сти, а҆́ще ли же не насы́тѧтсѧ, и҆ поро́пщꙋтъ."}, {"num": "ѕ҃і.", "text": "А҆́зъ же воспою̀ си́лꙋ твою̀ и҆ возра́дꙋюсѧ заꙋ́тра ѡ҆ млⷭ҇ти твое́й: ꙗ҆́кѡ бы́лъ є҆сѝ застꙋ́пникъ мо́й, и҆ прибѣ́жище моѐ въ де́нь ско́рби моеѧ̀."}, {"num": "з҃і.", "text": "Помо́щникъ мо́й є҆сѝ, тебѣ̀ пою̀, ꙗ҆́кѡ бг҃ъ застꙋ́пникъ мо́й є҆сѝ, бж҃е мо́й, млⷭ҇ть моѧ̀. а҃ в҃"}]}, "59": {"number": 59, "cu_numeral": "н҃ѳ", "title": "Ѱало́мъ н҃ѳ (59)", "subtitle": "и҆ поразѝ є҆дѡ́ма въ де́бри соле́й, двана́десѧть ты́сѧщъ, н҃ѳ.", "verses": [{"num": "а҃.", "text": "Бж҃е, ѿри́нꙋлъ ны̀ є҆сѝ и҆ низложи́лъ є҆сѝ на́съ, разгнѣ́валсѧ є҆си,̀ и҆ ᲂу҆ще́дрилъ є҆сѝ на́съ."}, {"num": "в҃.", "text": "Стрѧ́слъ є҆сѝ зе́млю, и҆ смꙋти́лъ є҆сѝ ю҆̀: и҆зцѣлѝ сокрꙋше́нїе є҆ѧ̀, ꙗ҆́кѡ подви́жесѧ."}, {"num": "г҃.", "text": "Показа́лъ є҆сѝ лю́демъ твои̑мъ жестѡ́каѧ: напои́лъ є҆сѝ на́съ вїно́мъ ᲂу҆миле́нїѧ."}, {"num": "д҃.", "text": "Да́лъ є҆сѝ боѧ́щымсѧ тебѐ зна́менїе, є҆́же ᲂу҆бѣжа́ти ѿ лица̀ лꙋ́ка."}, {"num": "є҃.", "text": "Ꙗ҆́кѡ да и҆зба́вѧтсѧ возлю́бленнїи твоѝ, спасѝ десни́цею твое́ю, и҆ ᲂу҆слы́ши мѧ̀."}, {"num": "ѕ҃.", "text": "Бг҃ъ возглаго́ла во ст҃ѣ́мъ свое́мъ: возра́дꙋюсѧ, и҆ раздѣлю̀ сїки́мꙋ, и҆ ю҆до́ль жили́щъ размѣ́рю."}, {"num": "з҃.", "text": "Мо́й є҆́сть галаа́дъ, и҆ мо́й є҆́сть манассі́й, є҆фре́мъ крѣ́пость главы̀ моеѧ̀, і҆ꙋ́да ца́рь мо́й."}, {"num": "и҃.", "text": "Мѡа́въ коно́бъ ᲂу҆пова́нїѧ моегѡ̀: на і҆дꙋме́ю прострꙋ̀ сапо́гъ мо́й: мнѣ̀ и҆ноплемє́нницы покори́шасѧ."}, {"num": "ѳ҃.", "text": "Кто̀ введе́тъ мѧ̀ во гра́дъ ѡ҆гражде́нїѧ; и҆лѝ кто̀ наста́витъ мѧ̀ до і҆дꙋме́и;"}, {"num": "і҃.", "text": "Не ты́ ли бж҃е, ѿри́нꙋвый на́съ; и҆ не и҆зы́деши, бж҃е, въ си́лахъ на́шихъ;"}, {"num": "а҃і.", "text": "Да́ждь на́мъ по́мощь ѿ ско́рби, и҆ сꙋ́етно сп҃се́нїе человѣ́ческо."}, {"num": "в҃і.", "text": "Ѡ҆ бз҃ѣ сотвори́мъ си́лꙋ: и҆ то́й ᲂу҆ничижи́тъ стꙋжа́ющыѧ на́мъ. а҃ Въ коне́цъ, въ пѣ́снехъ, дв҃дꙋ ѱало́мъ ѯ҃."}]}, "60": {"number": 60, "cu_numeral": "ѯ҃", "title": "Ѱало́мъ ѯ҃ (60)", "subtitle": "а҃ Въ коне́цъ, въ пѣ́снехъ, дв҃дꙋ ѱало́мъ ѯ҃.", "verses": [{"num": "а҃.", "text": "Оу҆слы́ши, бж҃е, моле́нїе моѐ, вонмѝ мл҃твѣ мое́й:"}, {"num": "в҃.", "text": "Ѿ коне́цъ землѝ къ тебѣ̀ воззва́хъ, внегда̀ ᲂу҆ны̀ се́рдце моѐ, на ка́мень возне́слъ мѧ̀ є҆сѝ, наста́вилъ мѧ̀ є҆сѝ."}, {"num": "г҃.", "text": "Ꙗ҆́кѡ бы́лъ є҆сѝ ᲂу҆пова́нїе моѐ, сто́лпъ крѣ́пости ѿ лица̀ вра́жїѧ."}, {"num": "д҃.", "text": "Вселю́сѧ въ селе́нїи твое́мъ во вѣ́ки, покры́юсѧ въ кро́вѣ кри́лъ твои́хъ."}, {"num": "є҃.", "text": "Ꙗ҆́кѡ ты̀, бж҃е, ᲂу҆слы́шалъ є҆сѝ ѕ҃ з҃ и҃ ѳ҃ покры́юсѧ въ кро́вѣ кри́лъ твои́хъ. Ꙗ҆́кѡ ты̀, бж҃е, ᲂу҆слы́шалъ є҆сѝ мл҃твы моѧ̑, да́лъ є҆сѝ достоѧ́нїе боѧ́щымсѧ и҆́мене твоегѡ̀."}, {"num": "ѕ҃.", "text": "Дни̑ на дни̑ царє́вы приложи́ши, лѣ̑та є҆гѡ̀ до днѐ ро́да и҆ ро́да."}, {"num": "з҃.", "text": "Пребꙋ́детъ въ вѣ́къ пред̾ бг҃омъ: млⷭ҇ть и҆ и҆́стинꙋ є҆гѡ̀ кто̀ взы́щетъ;"}, {"num": "и҃.", "text": "Та́кѡ воспою̀ и҆́мени твоемꙋ̀ во вѣ́ки, возда́ти мѝ мл҃твы моѧ̑ де́нь ѿ днѐ. Сла́ва: а҃ Въ коне́цъ, ѡ҆ і҆дїѳꙋ́мѣ, ѱало́мъ дв҃дꙋ, ѯ҃а."}]}, "61": {"number": 61, "cu_numeral": "ѯ҃а", "title": "Ѱало́мъ ѯ҃а (61)", "subtitle": "а҃ Въ коне́цъ, ѡ҆ і҆дїѳꙋ́мѣ, ѱало́мъ дв҃дꙋ, ѯ҃а.", "verses": [{"num": "а҃.", "text": "Не бг҃ꙋ ли повине́тсѧ дꙋша̀ моѧ̀; ѿ тогѡ́ бо сп҃се́нїе моѐ."}, {"num": "в҃.", "text": "И҆́бо то́й бг҃ъ мо́й, и҆ сп҃съ мо́й, застꙋ́пникъ мо́й, не подви́жꙋсѧ наипа́че."}, {"num": "г҃.", "text": "Доко́лѣ належитѐ на человѣ́ка; ᲂу҆бива́ете всѝ вы̀, ꙗ҆́кѡ стѣнѣ̀ преклоне́нѣ, и҆ ѡ҆пло́тꙋ возринове́нꙋ."}, {"num": "д҃.", "text": "Ѻ҆ба́че цѣ́нꙋ мою̀ совѣща́ша ѿри́нꙋти: теко́ша въ жа́жди: ᲂу҆сты̑ свои́ми бл҃гословлѧ́хꙋ, и҆ се́рдцемъ свои́мъ кленѧ́хꙋ."}, {"num": "є҃.", "text": "Ѻ҆ба́че бг҃ови повини́сѧ дꙋшѐ моѧ̀: ꙗ҆́кѡ ѿ тогѡ̀ терпѣ́нїе моѐ."}, {"num": "ѕ҃.", "text": "И҆́бо то́й бг҃ъ мо́й и҆ сп҃съ мо́й, застꙋ́пникъ мо́й, не преселю́сѧ."}, {"num": "з҃.", "text": "Ѡ҆ бз҃ѣ сп҃се́нїе моѐ, и҆ сла́ва моѧ̀. бг҃ъ по́мощи моеѧ̀, и҆ ᲂу҆пова́нїе моѐ на бг҃а. Оу҆пова́йте на него̀ ве́сь со́нмъ люде́й: и҆злїѧ́йте пред̾ ни́мъ сердца̀ ва̑ша: ꙗ҆́кѡ бг҃ъ помо́щникъ на́шъ. Ѻ҆ба́че сꙋ́етни сы́нове человѣ́честїи, лжи́ви сы́нове человѣ́честїи въ мѣ́рилѣхъ є҆́же непра́вдовати: ті́и ѿ сꙋеты̀ вкꙋ́пѣ, Не"}, {"num": "и҃.", "text": "ᲂу҆пова́йте на непра́вдꙋ, и҆ на восхище́нїе не жела́йте:"}, {"num": "ѳ҃.", "text": "бога́тство а҆́ще тече́тъ,"}, {"num": "і҃.", "text": "не прилага́йте се́рдца. Е҆ди́ною гл҃а бг҃ъ, дво́ѧ сїѧ̑ слы́шахъ: занѐ держа́ва"}, {"num": "а҃і.", "text": "бж҃їѧ, И҆ твоѧ̀ гдⷭ҇и млⷭ҇ть: ꙗ҆́кѡ ты̀ возда́си комꙋ́ждо по дѣлѡ́мъ"}, {"num": "в҃і.", "text": "є҆гѡ̀. а҃ Ѱало́мъ дв҃дꙋ, внегда̀ бы́ти є҆мꙋ̀ въ пꙋсты́ни і҆ꙋде́йстѣй, ѯ҃в."}]}, "62": {"number": 62, "cu_numeral": "ѯ҃в", "title": "Ѱало́мъ ѯ҃в (62)", "subtitle": "а҃ Ѱало́мъ дв҃дꙋ, внегда̀ бы́ти є҆мꙋ̀ въ пꙋсты́ни і҆ꙋде́йстѣй, ѯ҃в.", "verses": [{"num": "а҃.", "text": "Бж҃е, бж҃е мо́й, къ тебѣ̀ ᲂу҆́тренюю, возжада̀ тебѐ дꙋша̀ моѧ̀, ко́ль мно́жицею тебѣ̀ пло́ть моѧ̀, въ землѝ пꙋ́стѣ и҆ непрохо́днѣ и҆ безво́днѣ."}, {"num": "в҃.", "text": "Та́кѡ во ст҃ѣ́мъ ꙗ҆ви́хсѧ тебѣ̀, ви́дѣти си́лꙋ твою̀ и҆ сла́вꙋ твою̀."}, {"num": "г҃.", "text": "Ꙗ҆́кѡ лꙋ́чши млⷭ҇ть твоѧ̀ па́че живѡ́тъ: ᲂу҆стнѣ̀ моѝ похвали́тѣ тѧ̀."}, {"num": "д҃.", "text": "Та́кѡ бл҃гословлю́ тѧ въ животѣ̀ мое́мъ, ѡ҆ и҆́мени твое́мъ воздѣжꙋ̀ рꙋ́цѣ моѝ."}, {"num": "є҃.", "text": "Ꙗ҆́кѡ ѿ тꙋ́ка и҆ ма́сти да и҆спо́лнитсѧ дꙋша̀ моѧ̀, и҆ ᲂу҆стна́ма ра́дости восхва́лѧтъ тѧ̀ ᲂу҆ста̀ моѧ̑."}, {"num": "ѕ҃.", "text": "А҆́ще помина́хъ тѧ̀ на посте́ли мое́й, на ᲂу҆́треннихъ поꙋча́хсѧ въ тѧ̀:"}, {"num": "з҃.", "text": "Ꙗ҆́кѡ бы́лъ є҆сѝ помо́щникъ мо́й и҆ въ кро́вѣ крилꙋ̑ твоє́ю возра́дꙋюсѧ."}, {"num": "и҃.", "text": "Прильпѐ дꙋша̀ моѧ̀ по тебѣ̀: менѐ же прїѧ́тъ десни́ца ѳ҃ і҃ а҃і в҃і возра́дꙋюсѧ. Прильпѐ дꙋша̀ моѧ̀ по тебѣ̀: менѐ же прїѧ́тъ десни́ца твоѧ̀."}, {"num": "ѳ҃.", "text": "Ті́и же всꙋ́е и҆ска́ша дꙋ́шꙋ мою̀, вни́дꙋтъ въ преиспѡ́днѧѧ землѝ:"}, {"num": "і҃.", "text": "Предадѧ́тсѧ въ рꙋ́ки ѻ҆рꙋ́жїѧ, ча̑сти ли́совѡмъ бꙋ́дꙋтъ."}, {"num": "а҃і.", "text": "Ца́рь же возвесели́тсѧ ѡ҆ бз҃ѣ: похва́литсѧ всѧ́къ клены́йсѧ и҆́мъ, ꙗ҆́кѡ загради́шасѧ ᲂу҆ста̀ глаго́лющихъ непра́вєднаѧ. а҃ Въ коне́цъ, ѱало́мъ дв҃дꙋ, ѯ҃г."}]}, "63": {"number": 63, "cu_numeral": "ѯ҃г", "title": "Ѱало́мъ ѯ҃г (63)", "subtitle": "а҃ Въ коне́цъ, ѱало́мъ дв҃дꙋ, ѯ҃г.", "verses": [{"num": "а҃.", "text": "Оу҆слы́ши, бж҃е, гла́съ мо́й, внегда̀ моли́ти ми сѧ къ тебѣ̀, ѿ стра́ха вра́жїѧ и҆змѝ дꙋ́шꙋ мою̀."}, {"num": "в҃.", "text": "Покры́й мѧ̀ ѿ со́нма лꙋка́внꙋющихъ, ѿ мно́жества дѣ́лающихъ непра́вдꙋ:"}, {"num": "г҃.", "text": "И҆̀же и҆з̾ѡстри́ша ꙗ҆́кѡ ме́чь ѧ҆зы́ки своѧ̑, напрѧго́ша лꙋ́къ сво́й, ве́щь го́рькꙋ,"}, {"num": "д҃.", "text": "Сострѣлѧ́ти въ та́йныхъ непоро́чна: внеза́пꙋ сострѣлѧ́ютъ є҆го̀, и҆ не ᲂу҆боѧ́тсѧ."}, {"num": "є҃.", "text": "Оу҆тверди́ша себѣ̀ сло́во лꙋка́вое: повѣ́даша скры́ти сѣ́ть, рѣ́ша: кто̀ ᲂу҆́зритъ и҆̀хъ;"}, {"num": "ѕ҃.", "text": "И҆спыта́ша беззако́нїе: и҆зчезо́ша и҆спыта́ющїи и҆спыта̑нїѧ: пристꙋ́питъ человѣ́къ, и҆ се́рдце глꙋбоко̀."}, {"num": "з҃.", "text": "И҆ вознесе́тсѧ бг҃ъ. стрѣ́лы младе́нєцъ бы́ша ꙗ҆́звы и҆́хъ,"}, {"num": "и҃.", "text": "И҆ и҆знемого́ша на нѧ̀ ꙗ҆зы́цы и҆́хъ. смꙋти́шасѧ всѝ ви́дѧщїи и҆̀хъ."}, {"num": "ѳ҃.", "text": "И҆ ᲂу҆боѧ́сѧ всѧ́къ человѣ́къ: и҆ возвѣсти́ша дѣла̀ бж҃їѧ, и҆ творє́́нїѧ є҆гѡ̀ разꙋмѣ́ша."}, {"num": "і҃.", "text": "Возвесели́тсѧ првⷣникъ ѡ҆ гдⷭ҇ѣ, и҆ ᲂу҆пова́етъ на него̀: и҆ похва́лѧтсѧ всѝ пра́вїи сердце́мъ. Сла́ва:"}]}, "64": {"number": 64, "cu_numeral": "ѯ҃д", "title": "Ѱало́мъ ѯ҃д (64)", "subtitle": "люді́й преселе́нїѧ, є҆гда̀ хотѧ́хꙋ и҆сходи́ти, ѯ҃д.", "verses": [{"num": "а҃.", "text": "Тебѣ̀ подоба́етъ пѣ́снь, бж҃е, въ сїѡ́нѣ, и҆ тебѣ̀ возда́стсѧ мл҃тва во і҆ерⷭ҇ли́мѣ. Оу҆слы́ши мл҃твꙋ мою̀, къ тебѣ̀ всѧ́ка пло́ть прїи́детъ. Словеса̀ беззакѡ́нникъ премого́ша на́съ, и҆ нечє́стїѧ на̑ша ты̀ ѡ҆чи́стиши. Бл҃же́нъ є҆го́же и҆збра́лъ є҆сѝ и҆ прїѧ́лъ, всели́тсѧ во дво́рѣхъ твои́хъ. и҆спо́лнимсѧ во бл҃ги́хъ до́мꙋ твоегѡ̀: ст҃ъ хра́мъ тво́й, Ди́венъ въ пра́вдѣ."}, {"num": "в҃.", "text": "ᲂу҆слы́ши ны̀, бж҃е сп҃си́телю на́шъ, ᲂу҆пова́нїе всѣ́хъ конце́й землѝ, и҆ сꙋ́щихъ въ мо́ри дале́че: Оу҆готовлѧ́ѧй го́ры"}, {"num": "г҃.", "text": "крѣ́постїю свое́ю, препоѧ́санъ си́лою: Смꙋща́ѧй глꙋбинꙋ̀ морскꙋ́ю, шꙋ́мꙋ"}, {"num": "д҃.", "text": "во́лнъ є҆гѡ̀ кто̀ постои́тъ; смѧтꙋ́тсѧ ꙗ҆зы́цы, И҆ ᲂу҆боѧ́тсѧ"}, {"num": "є҃.", "text": "живꙋ́щїи въ конца́хъ ѿ зна́менїй твои́хъ: и҆схо́ды ᲂу҆́тра и҆ ве́чера ᲂу҆краси́ши. Посѣти́лъ є҆сѝ зе́млюⷱ҇ и҆ ᲂу҆пои́лъ є҆сѝ ю҆̀, ᲂу҆мно́жилъ є҆сѝ ѡ҆богати́ти ю҆̀: рѣка̀ бж҃їѧ напо́лнисѧ вѡ́дъ:"}, {"num": "ѕ҃.", "text": "ᲂу҆гото́валъ є҆сѝ пи́щꙋ и҆̀мъ, ꙗ҆́кѡ та́кѡ"}, {"num": "з҃.", "text": "[є҆́сть] ᲂу҆гото́ванїе. Бразды̑ є҆ѧ̀ ᲂу҆по́й, ᲂу҆мно́жи жи̑та є҆ѧ̀: въ ка́плѧхъ є҆ѧ̀ возвесели́тсѧ возсїѧ́ющи. Бл҃гослови́ши вѣне́цъ лѣ́та бл҃гости твоеѧ̀,"}, {"num": "и҃.", "text": "и҆ полѧ̀ твоѧ̑ и҆спо́лнѧтсѧ"}, {"num": "ѳ҃.", "text": "тꙋ́ка: Разботѣ́ютъ кра̑снаѧ пꙋсты́ни, и҆"}, {"num": "і҃.", "text": "ра́достїю хо́лми препоѧ́шꙋтсѧ. Ѡ҆дѣ́ѧшасѧ ѻ҆́вни"}, {"num": "а҃і.", "text": "ѻ҆́вчїи, и҆ ᲂу҆дѡ́лїѧ ᲂу҆мно́жатъ пшени́цꙋ:"}, {"num": "в҃і.", "text": "воззовꙋ́тъ, и҆́бо воспою́тъ. а҃ Въ"}, {"num": "г҃і.", "text": "коне́цъ, пѣ́снь ѱалма̀ воскрⷭ҇нїѧ, ѯ҃є."}]}, "65": {"number": 65, "cu_numeral": "ѯ҃є", "title": "Ѱало́мъ ѯ҃є (65)", "subtitle": "а҃ Въ коне́цъ, пѣ́снь ѱалма̀ воскрⷭ҇нїѧ, ѯ҃є.", "verses": [{"num": "а҃.", "text": "Воскли́кните гдⷭ҇еви всѧ̀ землѧ̀, по́йте же и҆́мени є҆гѡ̀, дади́те сла́вꙋ хвалѣ̀ є҆гѡ̀, Рцы́те бг҃ꙋ: ко́ль стра̑шна дѣла̀ твоѧ̑; во мно́жествѣ си́лы твоеѧ̀ со́лжꙋтъ тебѣ̀ вразѝ твоѝ. Всѧ̀ землѧ̀ да покло́нитсѧ тебѣ̀, и҆ пое́тъ тебѣ̀, да пое́тъ же и҆́мени твоемꙋ̀, вы́шнїй. Прїиди́те, и҆ ви́дите дѣла̀ бж҃їѧ, ко́ль стра́шенъ въ совѣ́тѣхъ па́че сынѡ́въ человѣ́ческихъ. Ѡ҆браща́ѧй мо́ре въ сꙋ́шꙋ, въ"}, {"num": "в҃.", "text": "рѣцѣ̀ про́йдꙋтъ нога́ми: та́мѡ возвесели́мсѧ ѡ҆ не́мъ, Влⷣчествꙋющемъ си́лою свое́ю вѣ́комъ. ѻ҆́чи є҆гѡ̀ на ꙗ҆зы́ки"}, {"num": "г҃.", "text": "призира́етѣ: преѡгорчева́ющїи да не возно́сѧтсѧ въ себѣ̀. Благослови́те ꙗ҆зы́цы бг҃а"}, {"num": "д҃.", "text": "на́шего, и҆ ᲂу҆слы́шанъ сотвори́те гла́съ хвалы̀ є҆гѡ̀, Поло́жшагѡ"}, {"num": "є҃.", "text": "дꙋ́шꙋ мою̀ въ живо́тъ, и҆ не да́вшаго ѳ҃ і҃ а҃і в҃і"}, {"num": "ѕ҃.", "text": "г҃і д҃і є҃і ѕ҃і з҃і и҃і ѳ҃і к҃ гла́съ хвалы̀ є҆гѡ̀,"}, {"num": "з҃.", "text": "Поло́жшагѡ дꙋ́шꙋ мою̀ въ живо́тъ, и҆ не да́вшаго во смѧте́нїе но́гъ мои́хъ. Ꙗ҆́кѡ и҆скꙋси́лъ ны̀ є҆сѝ, бж҃е, разже́глъ ны̀ є҆сѝ, ꙗ҆́коже разжиза́етсѧ сребро̀. Вве́лъ ны̀ є҆сѝ въ сѣ́ть,"}, {"num": "и҃.", "text": "положи́лъ є҆сѝ скѡ́рби на хребтѣ̀ на́шемъ. Возве́лъ є҆сѝ человѣ́ки на"}, {"num": "ѳ҃.", "text": "главы̑ на́шѧ: проидо́хомъ сквозѣ̀ ѻ҆́гнь и҆ во́дꙋ, и҆ и҆зве́лъ є҆сѝ"}, {"num": "і҃.", "text": "ны̀ въ поко́й. Вни́дꙋ въ до́мъ тво́й со всесожже́нїемъ,"}, {"num": "а҃і.", "text": "возда́мъ тебѣ̀ мл҃твы моѧ̑, Ꙗ҆̀же и҆зреко́стѣ ᲂу҆стнѣ̀ моѝ, и҆ глаго́лаша ᲂу҆ста̀"}, {"num": "в҃і.", "text": "моѧ̑, въ ско́рби мое́й. Всесожжє́нїѧ тꙋ̑чна вознесꙋ̀ тебѣ̀ съ кади́ломъ, и҆ ѻ҆вны̀, вознесꙋ̀ тебѣ̀ волы̀ съ кѡзлы̑. Прїиди́те, ᲂу҆слы́шите, и҆ повѣ́мъ ва́мъ, всѝ боѧ́щїисѧ бг҃а, є҆ли̑ка сотворѝ дꙋшѝ мое́й."}, {"num": "г҃і.", "text": "Къ немꙋ̀"}, {"num": "д҃і.", "text": "ᲂу҆сты̑ мои́ми воззва́хъ, и҆ вознесо́хъ под̾ ѧ҆зы́комъ мои́мъ. Непра́вдꙋ а҆́ще ᲂу҆зрѣ́хъ въ се́рдцѣ мое́мъ, да не ᲂу҆слы́шитъ менѐ гдⷭ҇ь. Сегѡ̀ ра́ди ᲂу҆слы́ша мѧ̀ бг҃ъ, внѧ́тъ гла́сꙋ моле́нїѧ моегѡ̀. Бл҃гослове́нъ бг҃ъ, и҆́же не ѿста́ви"}, {"num": "є҃і.", "text": "мл҃́твꙋ мою̀ и҆"}, {"num": "ѕ҃і.", "text": "млⷭ҇ть свою̀ ѿ"}, {"num": "з҃і.", "text": "менѐ̀. а҃ Въ"}, {"num": "и҃і.", "text": "коне́цъ, въ пѣ́снехъ,"}, {"num": "ѳ҃і.", "text": "ѱало́мъ пѣ́сни дв҃дꙋ, ѯ҃ѕ."}]}, "66": {"number": 66, "cu_numeral": "ѯ҃ѕ", "title": "Ѱало́мъ ѯ҃ѕ (66)", "subtitle": "а҃ Въ коне́цъ, въ пѣ́снехъ, ѱало́мъ пѣ́сни дв҃дꙋ, ѯ҃ѕ.", "verses": [{"num": "а҃.", "text": "Бж҃е, ᲂу҆ще́дри ны̀ и҆ бл҃гослови́ ны, просвѣтѝ лицѐ твоѐ на ны̀, и҆ поми́лꙋй ны̀:"}, {"num": "в҃.", "text": "Позна́ти на землѝ пꙋ́ть тво́й, во всѣ́хъ ꙗ҆зы́цѣхъ сп҃се́нїе твоѐ."}, {"num": "г҃.", "text": "Да и҆сповѣ́дѧтсѧ тебѣ̀ лю́дїе, бж҃е, да и҆сповѣ́дѧтсѧ тебѣ̀ лю́дїе всѝ."}, {"num": "д҃.", "text": "Да возвеселѧ́тсѧ, и҆ да возра́дꙋютсѧ ꙗ҆зы́цы: ꙗ҆́кѡ сꙋ́диши лю́демъ правото́ю, и҆ ꙗ҆зы́ки на землѝ наста́виши."}, {"num": "є҃.", "text": "Да и҆сповѣ́дѧтсѧ тебѣ̀ лю́дїе, бж҃е, да и҆сповѣ́дѧтсѧ тебѣ̀ лю́дїе всѝ."}, {"num": "ѕ҃.", "text": "Землѧ̀ дадѐ пло́дъ сво́й: бл҃гослови́ ны, бж҃е, бж҃е на́шъ. Блгⷭ҇ви́ ны, бж҃е: и҆"}, {"num": "з҃.", "text": "да ᲂу҆боѧ́тсѧ є҆гѡ̀ всѝ концы̑ землѝ. Сла́ва: а҃ Въ коне́цъ, ѱало́мъ пѣ́сни дв҃дꙋ, ѯ҃з."}]}, "67": {"number": 67, "cu_numeral": "ѯ҃з", "title": "Ѱало́мъ ѯ҃з (67)", "subtitle": "а҃ Въ коне́цъ, ѱало́мъ пѣ́сни дв҃дꙋ, ѯ҃з.", "verses": [{"num": "а҃.", "text": "Да воскрⷭ҇нетъ бг҃ъ, и҆ расточа́тсѧ вразѝ є҆гѡ̀, и҆ да бѣжа́тъ ѿ лица̀ є҆гѡ̀ ненави́дѧщїи є҆го̀."}, {"num": "в҃.", "text": "Ꙗ҆́кѡ и҆зчеза́етъ ды́мъ, да и҆зче́знꙋтъ: ꙗ҆́кѡ та́етъ во́скъ ѿ лица̀ ѻ҆гнѧ̀, та́кѡ да поги́бнꙋтъ грѣ̑шницы ѿ лица̀ бж҃їѧ:"}, {"num": "г҃.", "text": "А҆ првⷣницы да возвеселѧ́тсѧ, да возра́дꙋютсѧ пред̾ бг҃омъ, да насладѧ́тсѧ въ весе́лїи."}, {"num": "д҃.", "text": "Воспо́йте бг҃ꙋ, по́йте и҆́мени є҆гѡ̀, пꙋтесотвори́те возше́дшемꙋ на за́пады: гдⷭ҇ь и҆́мѧ є҆мꙋ̀, и҆ ра́дꙋйтесѧ пред̾ ни́мъ."}, {"num": "є҃.", "text": "Да смѧтꙋ́тсѧ ѿ лица̀ є҆гѡ̀, ѻ҆ц҃а̀ си́рыхъ и҆ сꙋдїѝ вдови́цъ: бг҃ъ въ ѕ҃ з҃ и҃ ѳ҃ і҃ а҃і в҃і г҃і д҃і є҃і ѕ҃і з҃і и҃і ѳ҃і к҃ к҃а к҃в к҃г к҃д к҃є к҃ѕ к҃з к҃и к҃ѳ л҃ л҃а л҃в л҃г л҃д Да смѧтꙋ́тсѧ ѿ лица̀ є҆гѡ̀, ѻ҆ц҃а̀ си́рыхъ и҆ сꙋдїѝ вдови́цъ: бг҃ъ въ мѣ́стѣ ст҃ѣ́мъ свое́мъ."}, {"num": "ѕ҃.", "text": "Бг҃ъ вселѧ́етъ є҆диномы́слєнныѧ въ до́мъ, и҆зводѧ̀ ѡ҆кова̑нныѧ мꙋ́жествомъ, та́кожде преѡгорчева́ющыѧ живꙋ́щыѧ во гробѣ́хъ."}, {"num": "з҃.", "text": "Бж҃е, внегда̀ и҆сходи́ти тебѣ̀ пред̾ людьмѝ твои́ми, внегда̀ мимоходи́ти тебѣ̀ въ пꙋсты́ни,"}, {"num": "и҃.", "text": "Землѧ̀ потрѧсе́сѧ, и҆́бо нб҃са̀ ка́нꙋша ѿ лица̀ бг҃а сїна́ина, ѿ лица̀ бг҃а і҆и҃лева."}, {"num": "ѳ҃.", "text": "До́ждь во́ленъ ѿлꙋчи́ши, бж҃е, достоѧ́нїю твоемꙋ̀: и҆ и҆знемо́же, ты́ же соверши́лъ є҆сѝ є҆̀."}, {"num": "і҃.", "text": "Живѡ́тнаѧ твоѧ̑ живꙋ́тъ на не́й, ᲂу҆гото́валъ є҆сѝ бл҃гостїю твое́ю ни́щемꙋ, бж҃е."}, {"num": "а҃і.", "text": "Гдⷭ҇ь да́стъ глаго́лъ блг҃овѣствꙋ́ющымъ си́лою мно́гою."}, {"num": "в҃і.", "text": "Цр҃ь си́лъ возлю́бленнагѡ, красото́ю до́мꙋ раздѣли́ти коры̑сти."}, {"num": "г҃і.", "text": "А҆́ще поспитѐ посредѣ̀ предѣ̑лъ, крилѣ̑ голꙋби̑нѣ посре́брєнѣ, и҆ междора̑мїѧ є҆ѧ̀ въ блеща́нїи зла́та."}, {"num": "д҃і.", "text": "Внегда̀ ра́знствитъ нбⷭ҇ный цари̑ на не́й, ѡ҆снѣжа́тсѧ въ селмѡ́нѣ."}, {"num": "є҃і.", "text": "Гора̀ бж҃їѧ гора̀ тꙋ́чнаѧ, гора̀ ᲂу҆сыре́ннаѧ, гора̀ тꙋ́чнаѧ."}, {"num": "ѕ҃і.", "text": "Вскꙋ́ю непщꙋ́ете го́ры ᲂу҆сырє́нныѧ; гора̀, ю҆́же бл҃говолѝ бг҃ъ жи́ти въ не́й: и҆́бо гдⷭ҇ь всели́тсѧ до конца̀."}, {"num": "з҃і.", "text": "Колесни́ца бж҃їѧ тма́ми тє́мъ, ты́сѧща гобзꙋ́ющихъ: гдⷭ҇ь въ ни́хъ въ сїна́и во ст҃ѣ́мъ."}, {"num": "и҃і.", "text": "Возше́лъ є҆сѝ на высотꙋ̀, плѣни́лъ є҆сѝ плѣ́нъ: прїѧ́лъ є҆сѝ даѧ̑нїѧ въ человѣ́цѣхъ,"}, {"num": "ѳ҃і.", "text": "и҆́бо не покарѧ́ющыѧсѧ, є҆́же всели́тисѧ. Гдⷭ҇ь бг҃ъ бл҃гослове́нъ, бл҃гослове́нъ гдⷭ҇ь де́нь днѐ, поспѣши́тъ на́мъ бг҃ъ сп҃се́нїй на́шихъ."}, {"num": "к҃.", "text": "Бг҃ъ на́шъ бг҃ъ є҆́же сп҃са́ти: и҆ гдⷭ҇нѧ, гдⷭ҇нѧ и҆схѡ́дища смє́ртнаѧ."}, {"num": "к҃а.", "text": "Ѻ҆ба́че бг҃ъ сокрꙋши́тъ главы̑ врагѡ́въ свои́хъ, ве́рхъ вла̑съ преходѧ́щихъ въ прегрѣше́нїихъ свои́хъ."}, {"num": "к҃в.", "text": "Речѐ гдⷭ҇ь: ѿ васа́на ѡ҆бращꙋ̀, ѡ҆бращꙋ̀ во глꙋбина́хъ морски́хъ,"}, {"num": "к҃г.", "text": "Ꙗ҆́кѡ да ѡ҆мо́читсѧ нога̀ твоѧ̀ въ кро́ви, ѧ҆зы́къ пє́съ твои́хъ ѿ вра̑гъ ѿ негѡ̀."}, {"num": "к҃д.", "text": "Ви̑дѣна бы́ша шє́ствїѧ твоѧ̑, бж҃е, шє́ствїѧ бг҃а моегѡ̀ цр҃ѧ̀, и҆́же во ст҃ѣ́мъ."}, {"num": "к҃є.", "text": "Предвари́ша кнѧ̑зи бли́з̾ пою́щихъ, посредѣ̀ дѣ́въ тѷмпа́нницъ."}, {"num": "к҃ѕ.", "text": "Въ цр҃квахъ бл҃гослови́те бг҃а, гдⷭ҇а ѿ и҆стѡ́чникъ і҆и҃левыхъ."}, {"num": "к҃з.", "text": "Та́мѡ венїамі́нъ ю҆нѣ́йшїй во ᲂу҆́жасѣ, кнѧ̑зи і҆ꙋ́довы влады́ки и҆́хъ, кнѧ̑зи завꙋлѡ̑ни, кнѧ́зи нефѳалі̑мли."}, {"num": "к҃и.", "text": "Заповѣ́ждь, бж҃е, си́лою твое́ю, ᲂу҆крѣпѝ, бж҃е, сїѐ, є҆́же содѣ́лалъ є҆сѝ въ на́съ."}, {"num": "к҃ѳ.", "text": "Ѿ хра́ма твоегѡ̀ во і҆ерⷭ҇ли́мъ тебѣ̀ принесꙋ́тъ ца́рїе да́ры."}, {"num": "л҃.", "text": "Запретѝ ѕвѣрє́мъ трѡ́стнымъ: со́нмъ ю҆нє́цъ въ ю҆́ницахъ людски́хъ, є҆́же затвори́ти и҆скꙋшє́нныѧ сребро́мъ: расточѝ ꙗ҆зы́ки хотѧ́щыѧ бра́нємъ."}, {"num": "л҃а.", "text": "Прїи́дꙋтъ мл҃итвєнницы ѿ є҆гѵ́пта: є҆ѳїо́пїа предвари́тъ рꙋ́кꙋ свою̀ къ бг҃ꙋ."}, {"num": "л҃в.", "text": "Ца̑рства зємна̑ѧ по́йте бг҃ꙋ, воспо́йте гдⷭ҇еви,"}, {"num": "л҃г.", "text": "Возше́дшемꙋ на нб҃о нб҃сѐ на восто́ки: сѐ да́стъ гла́сꙋ своемꙋ̀ гла́съ си́лы."}, {"num": "л҃д.", "text": "Дади́те сла́вꙋ бг҃ови: на і҆и҃ли велелѣ́пота є҆гѡ̀, и҆ си́ла є҆гѡ̀ на л҃є л҃ѕ си́лы. Дади́те сла́вꙋ бг҃ови: на і҆и҃ли велелѣ́пота є҆гѡ̀, и҆ си́ла є҆гѡ̀ на ѻ҆́блацѣхъ."}, {"num": "л҃є.", "text": "Ди́венъ бг҃ъ во ст҃ы́хъ свои́хъ: бг҃ъ і҆и҃левъ, то́й да́стъ си́лꙋ и҆ держа́вꙋ лю́демъ свои̑мъ. бл҃гослове́нъ бг҃ъ. Сла́ва: а҃ Въ коне́цъ, ѡ҆ и҆змѣ́ншихсѧ, ѱало́мъ дв҃дꙋ, ѯ҃и."}]}, "68": {"number": 68, "cu_numeral": "ѯ҃и", "title": "Ѱало́мъ ѯ҃и (68)", "subtitle": "а҃ Въ коне́цъ, ѡ҆ и҆змѣ́ншихсѧ꙳, ѱало́мъ дв҃дꙋ, ѯ҃и.", "verses": [{"num": "а҃.", "text": "Сп҃си́ мѧ, бж҃е, ꙗ҆́кѡ внидо́ша во́ды до дꙋшѝ моеѧ̀,"}, {"num": "в҃.", "text": "Оу҆глѣбо́хъ въ тимѣ́нїи глꙋбины̀, и҆ нѣ́сть постоѧ́нїѧ: прїидо́хъ во глꙋбины̑ мѡрскі́ѧ, и҆ бꙋ́рѧ потопи́ мѧ."}, {"num": "г҃.", "text": "Оу҆трꙋди́хсѧ зовы́й, и҆змолчѐ горта́нь мо́й: и҆счезо́стѣ ѻ҆́чи моѝ, ѿ є҆́же ᲂу҆пова́ти мѝ на бг҃а моего̀."}, {"num": "д҃.", "text": "Оу҆мно́жишасѧ па́че вла̑съ главы̀ моеѧ̀ ненави́дѧщїи мѧ̀ тꙋ́не: ᲂу҆крѣпи́шасѧ вразѝ моѝ, и҆згонѧ́щїи мѧ̀ непра́веднѡ:"}, {"num": "є҃.", "text": "ꙗ҆̀же не восхища́хъ, тогда̀ воздаѧ́хъ. Бж҃е, ты̀ ᲂу҆вѣ́дѣлъ є҆сѝ безꙋ́мїе моѐ, и҆ прегрѣшє́нїѧ моѧ̑ ѿ тебѐ не ᲂу҆таи́шасѧ."}, {"num": "ѕ҃.", "text": "Да не постыдѧ́тсѧ ѡ҆ мнѣ̀ терпѧ́щїи тебѐ, гдⷭ҇и, гдⷭ҇и си́лъ, нижѐ да посра́мѧтсѧ ѡ҆ мнѣ̀ и҆́щꙋщїи тебѐ, бж҃е і҆и҃левъ."}, {"num": "з҃.", "text": "Ꙗ҆́кѡ тебѐ ра́ди претерпѣ́хъ поноше́нїе, покры̀ срамота̀ лицѐ моѐ."}, {"num": "и҃.", "text": "Чꙋ́ждь бы́хъ бра́тїи мое́й, и҆ стра́ненъ сыновѡ́мъ ма́тере моеѧ̀:"}, {"num": "ѳ҃.", "text": "Ꙗ҆́кѡ ре́вность до́мꙋ твоегѡ̀ снѣде́ мѧ, и҆ поношє́нїѧ поносѧ́щихъ тѝ нападо́ша на мѧ̀."}, {"num": "і҃.", "text": "И҆ покры́хъ посто́мъ дꙋ́шꙋ мою̀, и҆ бы́сть въ поноше́нїе мнѣ̀:"}, {"num": "а҃і.", "text": "И҆ положи́хъ ѡ҆дѣѧ́нїе моѐ вре́тище, и҆ бы́хъ и҆̀мъ въ при́тчꙋ."}, {"num": "в҃і.", "text": "Ѡ҆ мнѣ̀ глꙋмлѧ́хꙋсѧ сѣдѧ́щїи во вратѣ́хъ, и҆ ѡ҆ мнѣ̀ поѧ́хꙋ пїю́щїи вїно̀."}, {"num": "г҃і.", "text": "А҆́зъ же мл҃твою мое́ю къ тебѣ̀, бж҃е, вре́мѧ бл҃говоле́нїѧ, бж҃е: во мно́жествѣ млⷭ҇ти твоеѧ̀ ᲂу҆слы́ши мѧ̀, во и҆́стинѣ сп҃се́нїѧ твоегѡ̀."}, {"num": "д҃і.", "text": "Сп҃си́ мѧ ѿ бре́нїѧ, да не ᲂу҆глѣ́бнꙋ: да и҆зба́влюсѧ ѿ ненави́дѧщихъ мѧ̀ и҆ ѿ глꙋбо́кихъ вѡ́дъ."}, {"num": "є҃і.", "text": "Да не потопи́тъ менѐ бꙋ́рѧ водна́ѧ, нижѐ да пожре́тъ менѐ глꙋбина̀, нижѐ сведе́тъ ѡ҆ мнѣ̀ рове́нникъ ᲂу҆́стъ свои́хъ. Оу҆слы́ши мѧ̀, гдⷭ҇и, ꙗ҆́кѡ бл҃га млⷭ҇ть твоѧ̀: по мно́жествꙋ щедрѡ́тъ твои́хъ при́зри на мѧ̀. Не ѿвратѝ лица̀ твоегѡ̀ ѿ ѻ҆́трока твоегѡ̀: ꙗ҆́кѡ скорблю̀: ско́рѡ"}, {"num": "ѕ҃і.", "text": "ᲂу҆слы́ши мѧ̀. Вонмѝ дꙋшѝ мое́й, и҆ и҆зба́ви ю҆̀: вра̑гъ мои́хъ ра́ди и҆зба́ви мѧ̀. Ты́ бо вѣ́си поноше́нїе моѐ, и҆ стꙋ́дъ мо́й, и҆ срамотꙋ̀ мою̀: пред̾ тобо́ю всѝ ѡ҆скорблѧ́ющїи мѧ̀. Поноше́нїе ча́ѧше дꙋша̀ моѧ̀ и҆ стра́сть: и҆ жда́хъ соскорбѧ́щагѡ, и҆"}, {"num": "з҃і.", "text": "не бѣ̀, и҆ ᲂу҆тѣша́ющихъ, и҆ не ѡ҆брѣто́хъ. И҆ да́ша въ снѣ́дь"}, {"num": "и҃і.", "text": "мою̀ же́лчь, и҆ въ жа́ждꙋ мою̀ к҃в к҃г к҃д к҃є к҃ѕ к҃з"}, {"num": "ѳ҃і.", "text": "к҃и к҃ѳ л҃ л҃а л҃в л҃г л҃д л҃є л҃ѕ л҃з не ѡ҆брѣто́хъ."}, {"num": "к҃.", "text": "И҆ да́ша въ снѣ́дь мою̀"}, {"num": "к҃а.", "text": "же́лчь, и҆ въ жа́ждꙋ мою̀ напои́ша мѧ̀ ѻ҆́цта."}, {"num": "к҃в.", "text": "Да бꙋ́детъ трапе́за и҆́хъ пред̾ ни́ми въ сѣ́ть, и҆ въ воздаѧ́нїе и҆ въ собла́знъ."}, {"num": "к҃г.", "text": "Да помрача́тсѧ ѻ҆́чи и҆́хъ, є҆́же не ви́дѣти, и҆ хребе́тъ и҆́хъ вы́нꙋ слѧцы̀."}, {"num": "к҃д.", "text": "Проле́й на нѧ̀ гнѣ́въ тво́й, и҆ ꙗ҆́рость гнѣ́ва твоегѡ̀ да пости́гнетъ и҆̀хъ."}, {"num": "к҃є.", "text": "Да бꙋ́детъ дво́ръ и҆́хъ пꙋ́стъ, и҆ въ жили́щихъ и҆́хъ да не бꙋ́детъ живы́й."}, {"num": "к҃ѕ.", "text": "Занѐ, є҆го́же ты̀ порази́лъ є҆сѝ, ті́и погна́ша, и҆ къ болѣ́зни ꙗ҆́звъ мои́хъ приложи́ша."}, {"num": "к҃з.", "text": "Приложѝ беззако́нїе къ беззако́нїю и҆́хъ, и҆ да не вни́дꙋтъ въ пра́вдꙋ твою̀."}, {"num": "к҃и.", "text": "Да потребѧ́тсѧ ѿ кни́ги живы́хъ, и҆ съ првⷣными да не напи́шꙋтсѧ."}, {"num": "к҃ѳ.", "text": "Ни́щъ и҆ болѧ́й є҆́смь а҆́зъ: сп҃се́нїе твоѐ, бж҃е, да прїи́метъ мѧ̀."}, {"num": "л҃.", "text": "Восхвалю̀ и҆́мѧ бг҃а моегѡ̀ съ пѣ́снїю, возвели́чꙋ є҆го̀ во хвале́нїи:"}, {"num": "л҃а.", "text": "И҆ ᲂу҆го́дно бꙋ́детъ бг҃ꙋ па́че тельца̀ ю҆́на, ро́ги и҆зносѧ́ща и҆ па́знѡкти."}, {"num": "л҃в.", "text": "Да ᲂу҆́зрѧтъ ни́щїи и҆ возвеселѧ́тсѧ: взыщи́те бг҃а, и҆ жива̀ бꙋ́детъ дꙋша̀ ва́ша."}, {"num": "л҃г.", "text": "Ꙗ҆́кѡ ᲂу҆слы́ша ᲂу҆бѡ́гїѧ гдⷭ҇ь, и҆ ѡ҆кова̑нныѧ своѧ̑ не ᲂу҆ничижѝ."}, {"num": "л҃д.", "text": "Да восхва́лѧтъ є҆го̀ нб҃са̀ и҆ землѧ̀, мо́ре и҆ всѧ̑ живꙋ̑щаѧ въ не́мъ."}, {"num": "л҃є.", "text": "Ꙗ҆́кѡ бг҃ъ сп҃се́тъ сїѡ́на, и҆ сози́ждꙋтсѧ гра́ди і҆ꙋде́йстїи, и҆ вселѧ́тсѧ та́мѡ, и҆ наслѣ́дѧтъ и҆̀:"}, {"num": "л҃ѕ.", "text": "И҆ сѣ́мѧ рабѡ́въ твои́хъ ᲂу҆держи́тъ и҆̀, и҆ лю́бѧщїи и҆́мѧ твоѐ вселѧ́тсѧ въ не́мъ. а҃ Въ коне́цъ, дв҃дꙋ, въ воспомина́нїе, во є҆́же сп҃сти́ мѧ гдⷭ҇ꙋ, ѯ҃ѳ."}]}, "69": {"number": 69, "cu_numeral": "ѯ҃ѳ", "title": "Ѱало́мъ ѯ҃ѳ (69)", "subtitle": "а҃ Въ коне́цъ, дв҃дꙋ, въ воспомина́нїе, во є҆́же сп҃сти́ мѧ гдⷭ҇ꙋ, ѯ҃ѳ.", "verses": [{"num": "а҃.", "text": "Бж҃е, въ по́мощь мою̀ вонмѝ: гдⷭ҇и, помощи́ ми потщи́сѧ."}, {"num": "в҃.", "text": "Да постыдѧ́тсѧ и҆ посра́мѧтсѧ и҆́щꙋщїи дꙋ́шꙋ мою̀, да возвратѧ́тсѧ вспѧ́ть, и҆ постыдѧ́тсѧ хотѧ́щїи мѝ ѕла̑ѧ:"}, {"num": "г҃.", "text": "Да возвратѧ́тсѧ а҆́бїе стыдѧ́щесѧ, глаго́лющїи мѝ: бла́гоже, бла́гоже."}, {"num": "д҃.", "text": "Да возра́дꙋютсѧ и҆ возвеселѧ́тсѧ ѡ҆ тебѣ̀ всѝ и҆́щꙋщїи тебѐ, бж҃е, и҆ да глаго́лютъ вы́нꙋ, да возвели́читсѧ гдⷭ҇ь, лю́бѧщїи сп҃се́нїе твоѐ."}, {"num": "є҃.", "text": "А҆́зъ же ни́щъ є҆́смь и҆ ᲂу҆бо́гъ, бж҃е, помози́ ми: помо́щникъ мо́й, и҆ и҆зба́витель мо́й є҆сѝ ты̀, гдⷭ҇и, не закоснѝ. Сла́ва:"}]}, "70": {"number": 70, "cu_numeral": "ѻ҃", "title": "Ѱало́мъ ѻ҃ (70)", "subtitle": "не надпи́санъ ᲂу҆ є҆врє́й, ѻ҃.", "verses": [{"num": "а҃.", "text": "На тѧ̀, гдⷭ҇и, ᲂу҆пова́хъ, да не постыжꙋ́сѧ въ вѣ́къ."}, {"num": "в҃.", "text": "Пра́вдою твое́ю и҆зба́ви мѧ̀, и҆ и҆зми́ мѧ: приклонѝ ко мнѣ̀ ᲂу҆́хо твоѐ, и҆ сп҃си́ мѧ."}, {"num": "г҃.", "text": "Бꙋ́ди мѝ въ бг҃а защи́тителѧ, и҆ въ мѣ́сто крѣ́пко сп҃сти́ мѧ: ꙗ҆́кѡ ᲂу҆твержде́нїе моѐ, и҆ прибѣ́жище моѐ є҆сѝ ты̀."}, {"num": "д҃.", "text": "Бж҃е мо́й, и҆зба́ви мѧ̀ и҆з̾ рꙋкѝ грѣ́шнагѡ, и҆з̾ рꙋкѝ законопрестꙋ́пнагѡ и҆ ѡ҆би́дѧщагѡ:"}, {"num": "є҃.", "text": "Ꙗ҆́кѡ ты̀ є҆сѝ терпѣ́нїе моѐ, гдⷭ҇и, гдⷭ҇и, ᲂу҆пова́нїе моѐ ѿ ю҆́ности моеѧ̀."}, {"num": "ѕ҃.", "text": "Въ тебѣ̀ ᲂу҆тверди́хсѧ ѿ ᲂу҆тро́бы, ѿ чре́ва ма́тере моеѧ̀ ты̀ є҆сѝ мо́й покрови́тель, ѡ҆ тебѣ̀ пѣ́нїе моѐ вы́нꙋ."}, {"num": "з҃.", "text": "Ꙗ҆́кѡ чꙋ́до бы́хъ мнѡ́гимъ: и҆ ты̀ помо́щникъ мо́й крѣ́покъ."}, {"num": "и҃.", "text": "Да и҆спо́лнѧтсѧ ᲂу҆ста̀ моѧ̑ хвале́нїѧ, ꙗ҆́кѡ да воспою̀ сла́вꙋ твою̀, ве́сь де́нь великолѣ́пїе твоѐ."}, {"num": "ѳ҃.", "text": "Не ѿве́ржи менѐ во вре́мѧ ста́рости: внегда̀ ѡ҆скꙋдѣва́ти крѣ́пости мое́й, не ѡ҆ста́ви менѐ."}, {"num": "і҃.", "text": "Ꙗ҆́кѡ рѣ́ша вразѝ моѝ мнѣ̀, и҆ стргꙋ́щїи дꙋ́шꙋ мою̀ совѣща́ша вкꙋ́пѣ,"}, {"num": "а҃і.", "text": "Глаго́люще: бг҃ъ ѡ҆ста́вилъ є҆́сть є҆го̀, пожени́те и҆ и҆ми́те є҆го̀, ꙗ҆́кѡ нѣ́сть и҆збавлѧ́ѧй."}, {"num": "в҃і.", "text": "Бж҃е мо́й, не ᲂу҆дали́сѧ ѿ менѐ: бж҃е мо́й, въпо́мощь мою̀вонмѝ.Дапостыдѧ́тсѧи҆и҆зче́знꙋтъ ѡ҆клевета́ющїи дꙋ́шꙋ мою̀,"}, {"num": "г҃і.", "text": "да ѡ҆блекꙋ́тсѧ въ стꙋ́дъ и҆ сра́мъ и҆́щꙋщїи ѕла̑ѧ мнѣ̀."}, {"num": "д҃і.", "text": "А҆́зъ же всегда̀ воз̾ꙋпова́ю на тѧ̀, и҆ приложꙋ̀ на всѧ́кꙋ похвалꙋ̀ твою̀."}, {"num": "є҃і.", "text": "Оу҆ста̀ моѧ̑ возвѣстѧ́тъ пра́вдꙋ твою̀, ве́сь де́нь сп҃се́нїе твоѐ, ꙗ҆́кѡ не позна́хъ кни̑жнаѧ."}, {"num": "ѕ҃і.", "text": "Вни́дꙋ въ си́лѣ гдⷭ҇ни: гдⷭ҇и, помѧнꙋ̀ пра́вдꙋ тебѐ є҆ди́нагѡ."}, {"num": "з҃і.", "text": "Бж҃е мо́й, и҆̀мже наꙋчи́лъ мѧ̀ є҆сѝ ѿ ю҆́ности моеѧ̀, и҆ донн҃ѣ возвѣщꙋ̀ чꙋдеса̀ твоѧ̑."}, {"num": "и҃і.", "text": "И҆ да́же до ста́рости и҆ престарѣ́нїѧ, бж҃е мо́й не ѡ҆ста́ви менѐ̀, до́ндеже возвѣщꙋ̀ мы́шцꙋ твою̀ ро́дꙋ всемꙋ̀ грѧдꙋ́щемꙋ,"}, {"num": "ѳ҃і.", "text": "Си́лꙋ твою̀ и҆ пра́вдꙋ твою̀, бж҃е, да́же до вы́шнихъ, ꙗ҆̀же сотвори́лъ мѝ є҆сѝ вели̑чїѧ: бж҃е, кто̀ подо́бенъ тебѣ̀;"}, {"num": "к҃.", "text": "Е҆ли̑ки ꙗ҆ви́лъ мѝ є҆сѝ скѡ́рби мнѡ́ги и҆ ѕлы̀; и҆ ѡ҆бра́щьсѧ ѡ҆животвори́лъ мѧ̀ є҆сѝ и҆ ѿ бе́зднъ землѝ возве́лъ мѧ̀ є҆сѝ:"}, {"num": "к҃а.", "text": "Оу҆мно́жилъ є҆сѝ на мнѣ̀ вели́чествїе твоѐ, и҆ ѡ҆бра́щьсѧ ᲂу҆тѣ́шилъ мѧ̀ є҆сѝ, и҆ ѿ бе́зднъ землѝ па́ки возве́лъ мѧ̀ є҆сѝ."}, {"num": "к҃в.", "text": "И҆́бо а҆́зъ и҆сповѣ́мсѧ тебѣ̀ въ лю́дехъ, гдⷭ҇и, въ сосꙋ́дѣхъ ѱало́мскихъ и҆́стинꙋ твою̀, бж҃е, воспою̀ тебѣ̀ въ гꙋ́слехъ, ст҃ы́й і҆и҃левъ."}, {"num": "к҃г.", "text": "Возра́дꙋетѣсѧ ᲂу҆стнѣ̀ моѝ, є҆гда̀ воспою̀ тебѣ̀, и҆ дꙋша̀ моѧ̀, ю҆́же є҆сѝ и҆зба́вилъ:"}, {"num": "к҃д.", "text": "Е҆ще́ же и҆ ѧ҆зы́къ мо́й ве́сь де́нь поꙋчи́тсѧ пра́вдѣ твое́й, є҆гда̀ постыдѧ́тсѧ и҆ посра́мѧтсѧ и҆́щꙋщїй ѕла̑ѧ мнѣ̀. Ѡ҆ соломѡ́нѣ, ѱало́мъ дв҃дꙋ, ѻ҃а."}]}, "71": {"number": 71, "cu_numeral": "ѻ҃а", "title": "Ѱало́мъ ѻ҃а (71)", "subtitle": "Ѡ҆ соломѡ́нѣ, ѱало́мъ дв҃дꙋ, ѻ҃а.", "verses": [{"num": "а҃.", "text": "Бж҃е, сꙋ́дъ тво́й царе́ви да́ждь, и҆ пра́вдꙋ твою̀ сы́нꙋ царе́вꙋ:"}, {"num": "в҃.", "text": "Сꙋди́ти лю́демъ твои̑мъ въ пра́вдѣ, и҆ ни́щымъ твои̑мъ въ сꙋдѣ̀."}, {"num": "г҃.", "text": "Да воспрїи́мꙋтъ го́ры ми́ръ лю́демъ, и҆ хо́лми пра́вдꙋ."}, {"num": "д҃.", "text": "Сꙋ́дитъ ни́щымъ людски̑мъ, и҆ спасе́тъ сы́ны ᲂу҆бо́гихъ, и҆ смири́тъ клеветника̀."}, {"num": "є҃.", "text": "И҆ пребꙋ́детъ съ со́лнцемъ, и҆ пре́жде лꙋны̀ ро́да родѡ́въ."}, {"num": "ѕ҃.", "text": "Сни́детъ ꙗ҆́кѡ до́ждь на рꙋно̀, и҆ ꙗ҆́кѡ ка́плѧ ка́плющаѧ на зе́млю."}, {"num": "з҃.", "text": "Возсїѧ́етъ во дне́хъ є҆гѡ̀ пра́вда и҆ мно́жество ми́ра, до́ндеже ѿи́метсѧ лꙋна̀."}, {"num": "и҃.", "text": "И҆ ѡ҆блада́етъ ѿ мо́рѧ до мо́рѧ, и҆ ѿ рѣ́къ до конє́цъ вселе́нныѧ."}, {"num": "ѳ҃.", "text": "Пред̾ ни́мъ припадꙋ́тъ є҆ѳїо́плѧне, и҆ вразѝ є҆гѡ̀ пе́рсть поли́жꙋтъ."}, {"num": "і҃.", "text": "Ца́рїе ѳарсі́йстїи и҆ ѻ҆́строви да́ры принесꙋ́тъ, ца́рїе а҆ра́встїи и҆ сава̀ да́ры приведꙋ́тъ:"}, {"num": "а҃і.", "text": "И҆ покло́нѧтсѧ є҆мꙋ̀ всѝ ца́рїе зе́мстїи, всѝ ꙗ҆зы́цы порабо́таютъ є҆мꙋ̀."}, {"num": "в҃і.", "text": "Ꙗ҆́кѡ и҆зба́ви ни́ща"}, {"num": "г҃і.", "text": "ѿ си́льна, и҆ ᲂу҆бо́га, є҆мꙋ́же не бѣ̀ помо́щника. Пощади́тъ ни́ща и҆ ᲂу҆бо́га и҆ дꙋ́шы ᲂу҆бо́гихъ спасе́тъ:"}, {"num": "д҃і.", "text": "Ѿ ли́хвы и҆ ѿ непра́вды и҆зба́витъ дꙋ́шы и҆́хъ, и҆ че́стно и҆́мѧ є҆гѡ̀ пред̾ ни́ми."}, {"num": "є҃і.", "text": "И҆ жи́въ бꙋ́детъ и҆ да́стсѧ є҆мꙋ̀ ѿ зла́та а҆раві́йска, и҆ помо́лѧтсѧ ѡ҆ не́мъ вы́нꙋ. ве́сь де́нь благословѧ́тъ є҆го̀."}, {"num": "ѕ҃і.", "text": "Бꙋ́детъ ᲂу҆твержде́нїе на землѝ на версѣ́хъ го́ръ: превознесе́тсѧ па́че лїва́на пло́дъ є҆гѡ̀, и҆ процвѣтꙋ́тъ ѿ гра́да ꙗ҆́кѡ трава̀ земна́ѧ."}, {"num": "з҃і.", "text": "Бꙋ́детъ и҆́мѧ є҆гѡ̀ бл҃гослове́но во вѣ́ки, пре́жде со́лнца пребыва́етъ и҆́мѧ є҆гѡ̀: и҆ бл҃гословѧ́тсѧ въ не́мъ всѧ̑ кѡлѣ́на зємна́ѧ, всѝ"}, {"num": "и҃і.", "text": "ꙗ҆зы́цы ᲂу҆блажа́тъ є҆го̀. Бл҃гослове́нъ гдⷭ҇ь бг҃ъ і҆и҃левъ, творѧ́й чꙋдеса̀ є҆ди́нъ,"}, {"num": "ѳ҃і.", "text": "И҆ бл҃гослове́нно и҆́мѧ сла́вы є҆гѡ̀ во вѣ́къ и҆ въ вѣ́къ вѣ́ка: и҆ и҆спо́лнитсѧ сла́вы є҆гѡ̀ всѧ̀ землѧ̀. бꙋ́ди, бꙋ́ди. Сла́ва: Ѡ҆скꙋдѣ́ша пѣ̑сни дв҃да, сы́на і҆ессе́ова. Ѱало́мъ а҆са́фꙋ, ѻ҃в."}]}, "72": {"number": 72, "cu_numeral": "ѻ҃в", "title": "Ѱало́мъ ѻ҃в (72)", "subtitle": "Ѡ҆скꙋдѣ́ша пѣ̑сни дв҃да, сы́на і҆ессе́ова. Ѱало́мъ а҆са́фꙋ, ѻ҃в.", "verses": [{"num": "а҃.", "text": "Ко́ль бл҃гъ бг҃ъ і҆и҃левъ пра̑вымъ се́рдцемъ."}, {"num": "в҃.", "text": "Мои́ же вма́лѣ не подвижа́стѣсѧ но́зѣ, вма́лѣ не пролїѧ́шасѧ стѡпы̀ моѧ̑:"}, {"num": "г҃.", "text": "Ꙗ҆́кѡ возревнова́хъ на беззакѡ́нныѧ, ми́ръ грѣ́шникѡвъ зрѧ̀:"}, {"num": "д҃.", "text": "Ꙗ҆́кѡ нѣ́сть восклоне́нїѧ въ сме́рти и҆́хъ, и҆ ᲂу҆твержде́нїѧ въ ра́нѣ и҆́хъ:"}, {"num": "є҃.", "text": "Въ трꙋдѣ́хъ человѣ́ческихъ не сꙋ́ть, и҆ съ человѣ̑ки не прїи́мꙋтъ ра́нъ."}, {"num": "ѕ҃.", "text": "Сегѡ̀ ра́ди ᲂу҆держа̀ ѧ҆̀ горды́нѧ и҆́хъ до конца̀: ѡ҆дѣ́ѧшасѧ непра́вдою и҆ нече́стїемъ свои́мъ."}, {"num": "з҃.", "text": "И҆зы́детъ ꙗ҆́кѡ и҆з̾ тꙋ́ка непра́вда и҆́хъ: преидо́ша въ з҃ и҃ ѳ҃ і҃ а҃і в҃і г҃і д҃і є҃і ѕ҃і з҃і и҃і ѳ҃і к҃ к҃а к҃в к҃г к҃д к҃є к҃ѕ к҃з к҃и тїемъ свои́мъ. И҆зы́детъ ꙗ҆́кѡ и҆з̾ тꙋ́ка непра́вда и҆́хъ: преидо́ша въ любо́вь се́рдца."}, {"num": "и҃.", "text": "Помы́слиша и҆ глаго́лаша въ лꙋка́вствѣ, непра́вдꙋ въ высотꙋ̀ глаго́лаша:"}, {"num": "ѳ҃.", "text": "Положи́ша на нб҃сѝ ᲂу҆ста̀ своѧ̑, и҆ ѧ҆зы́къ и҆́хъ пре́йде по землѝ."}, {"num": "і҃.", "text": "Сегѡ̀ ра́ди ѡ҆братѧ́тсѧ лю́дїе моѝ сѣ́мѡ, и҆ дні́е и҆спо́лнени ѡ҆брѧ́щꙋтсѧ въ ни́хъ."}, {"num": "а҃і.", "text": "И҆ рѣ́ша: ка́кѡ ᲂу҆вѣ́дѣ бг҃ъ; и҆ а҆́ще є҆́сть ра́зꙋмъ въ вы́шнѣмъ;"}, {"num": "в҃і.", "text": "Сѐ сі́и грѣ̑шницы и҆ гобзꙋ́ющїи въ вѣ́къ, ᲂу҆держа́ша бога́тство."}, {"num": "г҃і.", "text": "И҆ рѣ́хъ: є҆да̀ всꙋ́е ѡ҆правди́хъ се́рдце моѐ, и҆ ᲂу҆мы́хъ въ непови́нныхъ рꙋ́цѣ моѝ:"}, {"num": "д҃і.", "text": "И҆ бы́хъ ꙗ҆́звенъ ве́сь де́нь, и҆ ѡ҆бличе́нїе моѐ на ᲂу҆́тренихъ."}, {"num": "є҃і.", "text": "А҆́ще глаго́лахъ, повѣ́мъ та́кѡ: сѐ ро́дꙋ сынѡ́въ твои́хъ, є҆мꙋ́же ѡ҆бѣща́хсѧ:"}, {"num": "ѕ҃і.", "text": "И҆ непщева́хъ разꙋмѣ́ти: сїѐ трꙋ́дъ є҆́сть предо мно́ю,"}, {"num": "з҃і.", "text": "До́ндеже вни́дꙋ во ст҃и́ло бж҃їе, и҆ разꙋмѣ́ю въ послѣ̑днѧѧ и҆́хъ."}, {"num": "и҃і.", "text": "Ѻ҆ба́че за льщє́нїѧ и҆́хъ, положи́лъ є҆сѝ и҆̀мъ ѕла̑ѧ, низложи́лъ є҆сѝ ѧ҆̀, внегда̀ разгордѣ́шасѧ."}, {"num": "ѳ҃і.", "text": "Ка́кѡ бы́ша въ запꙋстѣ́нїе: внеза́пꙋ и҆зчезо́ша, погибо́ша за беззако́нїе своѐ."}, {"num": "к҃.", "text": "Ꙗ҆́кѡ со́нїе востаю́щагѡ, гдⷭ҇и, во гра́дѣ твое́мъ ѡ҆́бразъ и҆́хъ ᲂу҆ничижи́ши."}, {"num": "к҃а.", "text": "Ꙗ҆́кѡ разжже́сѧ се́рдце моѐ, и҆ ᲂу҆трѡ́бы моѧ̑ и҆змѣни́шасѧ:"}, {"num": "к҃в.", "text": "И҆ а҆́зъ ᲂу҆ничиже́нъ, и҆ не разꙋмѣ́хъ, ско́тенъ бы́хъ ᲂу҆ тебє̀."}, {"num": "к҃г.", "text": "И҆ а҆́зъ вы́нꙋ съ тобо́ю: ᲂу҆держа́лъ є҆сѝ рꙋ́кꙋ деснꙋ́ю мою̀:"}, {"num": "к҃д.", "text": "И҆ совѣ́томъ твои́мъ наста́вилъ мѧ̀ є҆сѝ: и҆ со сла́вою прїѧ́лъ мѧ̀ є҆сѝ."}, {"num": "к҃є.", "text": "Что́ бо мѝ є҆́сть на нб҃сѝ; и҆ ѿ тебѐ что̀ восхотѣ́хъ на землѝ;"}, {"num": "к҃ѕ.", "text": "И҆зчезѐ се́рдце моѐ и҆ пло́ть моѧ̀, бж҃е се́рдца моегѡ̀, и҆ ча́сть моѧ̀, бж҃е, во вѣ́къ."}, {"num": "к҃з.", "text": "Ꙗ҆́кѡ сѐ ᲂу҆далѧ́ющїи себѐ ѿ тебѐ поги́бнꙋтъ: потреби́лъ є҆сѝ всѧ́каго любодѣ́ющаго ѿ тебѐ."}, {"num": "к҃и.", "text": "Мнѣ́ же прилѣплѧ́тисѧ бг҃ови бл҃го є҆́сть, полага́ти на гдⷭ҇а ᲂу҆пова́нїе моѐ, возвѣсти́ти мѝ всѧ̑ хвалы̑ твоѧ̑ во вратѣ́хъ дще́ре сїѡ́ни."}]}, "73": {"number": 73, "cu_numeral": "ѻ҃г", "title": "Ѱало́мъ ѻ҃г (73)", "subtitle": "Ра́зꙋма а҆са́фꙋ, ѻ҃г.", "verses": [{"num": "а҃.", "text": "Вскꙋ́ю, бж҃е, ѿри́нꙋлъ є҆сѝ до конца̀; разгнѣ́васѧ ꙗ҆́рость твоѧ̀ на ѻ҆́вцы па́жити твоеѧ̀;"}, {"num": "в҃.", "text": "Помѧнѝ со́нмъ тво́й, є҆го́же стѧжа́лъ є҆сѝ и҆спе́рва: и҆зба́вилъ є҆сѝ жезло́мъ достоѧ́нїѧ твоегѡ̀, гора̀ сїѡ́нъ сїѧ̀, въ не́йже всели́лсѧ є҆сѝ."}, {"num": "г҃.", "text": "Воздви́гни рꙋ́цѣ твоѝ на горды̑ни и҆́хъ въ коне́цъ, є҆ли̑ка лꙋка́внова вра́гъ во ст҃ѣ́мъ твое́мъ."}, {"num": "д҃.", "text": "И҆ восхвали́шасѧ ненави́дѧщїи тѧ̀ посредѣ̀ пра́здника твоегѡ̀: положи́ша зна́мєнїѧ своѧ̑, зна́мєнїѧ, и҆ не позна́ша,"}, {"num": "є҃.", "text": "Ꙗ҆́кѡ во и҆схо́дѣ превы́ше: ꙗ҆́кѡ въ дꙋбра́вѣ дре́вѧнѣ сѣки́рами разсѣко́ша"}, {"num": "ѕ҃.", "text": "Двє́ри є҆гѡ̀ вкꙋ́пѣ: сѣ́чивомъ ѕ҃ з҃ и҃ ѳ҃ і҃ а҃і в҃і г҃і д҃і є҃і ѕ҃і з҃і и҃і ѳ҃і к҃ к҃а к҃в к҃г дꙋбра́вѣ дре́вѧнѣ сѣки́рами разсѣко́ша Двє́ри є҆гѡ̀ вкꙋ́пѣ: сѣ́чивомъ и҆ ѻ҆ско́рдомъ разрꙋши́ша и҆̀."}, {"num": "з҃.", "text": "Возжго́ша ѻ҆гне́мъ ст҃и́ло твоѐ: на землѝ ѡ҆скверни́ша жили́ще и҆́мене твоегѡ̀."}, {"num": "и҃.", "text": "Рѣ́ша въ се́рдцѣ свое́мъ ю҆́жики и҆́хъ вкꙋ́пѣ: прїиди́те и҆ ѿста́вимъ всѧ̑ пра́здники бж҃їѧ ѿ землѝ."}, {"num": "ѳ҃.", "text": "Зна́мєнїѧ и҆́хъ не ви́дѣхомъ: нѣ́сть ктомꙋ̀ прⷪ҇ро́ка, и҆ на́съ не позна́етъ ктомꙋ̀."}, {"num": "і҃.", "text": "Доко́лѣ, бж҃е, поно́ситъ вра́гъ; раздражи́тъ проти́вный и҆́мѧ твоѐ до конца̀;"}, {"num": "а҃і.", "text": "Вскꙋ́ю ѿвраща́еши рꙋ́кꙋ твою̀ и҆ десни́цꙋ твою̀ ѿ среды̀ нѣ́дра твоегѡ̀ въ коне́цъ;"}, {"num": "в҃і.", "text": "Бг҃ъ же цр҃ь на́шъ пре́жде вѣ́ка содѣ́ла сп҃се́нїе посредѣ̀ землѝ."}, {"num": "г҃і.", "text": "Ты̀ ᲂу҆тверди́лъ є҆сѝ си́лою твое́ю мо́ре: ты̀ сте́рлъ є҆сѝ главы̑ ѕмїє́въ въ водѣ̀:"}, {"num": "д҃і.", "text": "Ты̀ сокрꙋши́лъ є҆сѝ главꙋ̀ ѕмі́евꙋ, да́лъ є҆сѝ того̀ бра́шно лю́демъ є҆ѳїѡ́пскимъ."}, {"num": "є҃і.", "text": "Ты̀ расто́рглъ є҆сѝ и҆сто́чники и҆ пото́ки: ты̀ и҆зсꙋши́лъ є҆сѝ рѣ́ки и҆ѳа̑мскїѧ."}, {"num": "ѕ҃і.", "text": "Тво́й є҆́сть де́нь, и҆ твоѧ̀ є҆́сть но́щь: ты̀ соверши́лъ є҆сѝ зарю̀ и҆ со́лнце."}, {"num": "з҃і.", "text": "Ты̀ сотвори́лъ є҆сѝ всѧ̑ предѣ́лы землѝ: жа́твꙋ и҆ ве́снꙋ ты̀ созда́лъ є҆сѝ ѧ҆̀."}, {"num": "и҃і.", "text": "Помѧнѝ сїѧ̑: вра́гъ поносѝ гдⷭ҇еви, и҆ лю́дїе безꙋ́мнїи раздражи́ша и҆́мѧ твоѐ."}, {"num": "ѳ҃і.", "text": "Не преда́ждь ѕвѣрє́мъ дꙋ́шꙋ и҆сповѣ́дающꙋюсѧ тебѣ̀: дꙋ́шъ ᲂу҆бо́гихъ твои́хъ не забꙋ́ди до конца̀."}, {"num": "к҃.", "text": "При́зри на завѣ́тъ тво́й: ꙗ҆́кѡ и҆спо́лнишасѧ помраче́ннїи землѝ домѡ́въ беззако́нїй."}, {"num": "к҃а.", "text": "Да не возврати́тсѧ смире́нный посра́мленъ: ни́щъ и҆ ᲂу҆бо́гъ восхвали́та и҆́мѧ твоѐ."}, {"num": "к҃в.", "text": "Воста́ни, бж҃е, сꙋдѝ прю̀ твою̀: помѧнѝ поноше́нїе твоѐ, є҆́же ѿ безꙋ́мнагѡ ве́сь де́нь."}, {"num": "к҃г.", "text": "Не забꙋ́ди гла́са мл҃твєнникъ твои́хъ: горды́нѧ ненави́дѧщихъ тѧ̀ взы́де вы́нꙋ. зна́менїй на́шихъ да восхо́дитъ вы́нꙋ къ тебѣ̀ Сла́ва: а҃ Въ коне́цъ, да не растли́ши, ѱало́мъ пѣ́сни а҆са́фꙋ, ѻ҃д."}]}, "74": {"number": 74, "cu_numeral": "ѻ҃д", "title": "Ѱало́мъ ѻ҃д (74)", "subtitle": "а҃ Въ коне́цъ, да не растли́ши, ѱало́мъ пѣ́сни а҆са́фꙋ, ѻ҃д.", "verses": [{"num": "а҃.", "text": "И҆сповѣ́мысѧ тебѣ̀, бж҃е, и҆сповѣ́мысѧ тебѣ̀ и҆ призове́мъ и҆́мѧ твоѐ: повѣ́мъ всѧ̑ чꙋдеса̀ твоѧ̑."}, {"num": "в҃.", "text": "Е҆гда̀ прїимꙋ̀ вре́мѧ, а҆́зъ правѡты̀ возсꙋждꙋ̀."}, {"num": "г҃.", "text": "Раста́ѧсѧ землѧ̀, и҆ всѝ живꙋ́щїи на не́й, а҆́зъ ᲂу҆тверди́хъ столпы̀ є҆ѧ̀."}, {"num": "д҃.", "text": "Рѣ́хъ беззако́ннꙋющымъ, не беззако́ннꙋйте: и҆ согрѣша́ющымъ, не возноси́те ро́га."}, {"num": "є҃.", "text": "Не воздвиза́йте на высотꙋ̀ ро́га ва́шегѡ, и҆ не глаго́лите на бг҃а непра́вдꙋ:"}, {"num": "ѕ҃.", "text": "Ꙗ҆́кѡ нижѐ ѿ и҆схѡ́дъ, нижѐ и҆ з҃ и҃ ѳ҃ і҃ а҃і шегѡ, и҆ не глаго́лите на бг҃а непра́вдꙋ: Ꙗ҆́кѡ нижѐ ѿ и҆схѡ́дъ, нижѐ и҆ за̑падъ, нижѐ ѿ пꙋсты́хъ го́ръ."}, {"num": "з҃.", "text": "Ꙗ҆́кѡ бг҃ъ сꙋдїѧ̀ є҆́сть: сего̀ смирѧ́етъ, и҆ сего̀ возно́ситъ."}, {"num": "и҃.", "text": "Ꙗ҆́кѡ ча́ша въ рꙋцѣ̀ гдⷭ҇ни, вїна̀ не растворе́на и҆спо́лнь растворе́нїѧ, и҆ ᲂу҆клонѝ ѿ сеѧ̀ въ сїю̀: ѻ҆ба́че дро́ждїе є҆гѡ̀ не и҆стощи́сѧ, и҆спїю́тъ всѝ грѣ́шнїи землѝ."}, {"num": "ѳ҃.", "text": "А҆́зъ же возра́дꙋюсѧ въ вѣ́къ, воспою̀ бг҃ꙋ і҆а́кѡвлю:"}, {"num": "і҃.", "text": "И҆ всѧ̑ ро́ги грѣ́шныхъ сломлю̀, и҆ вознесе́тсѧ ро́гъ првⷣнагѡ. а҃ Въ коне́цъ, въ пѣ́снехъ, ѱало́мъ а҆са́фꙋ, пѣ́снь ко а҆ссѷрі́анинꙋ, ѻ҃є."}]}, "75": {"number": 75, "cu_numeral": "ѻ҃є", "title": "Ѱало́мъ ѻ҃є (75)", "subtitle": "а҃ Въ коне́цъ, въ пѣ́снехъ, ѱало́мъ а҆са́фꙋ, пѣ́снь ко а҆ссѷрі́анинꙋ, ѻ҃є.", "verses": [{"num": "а҃.", "text": "Вѣ́домъ во і҆ꙋде́и бг҃ъ, во і҆и҃ли ве́лїе и҆́мѧ є҆гѡ̀."}, {"num": "в҃.", "text": "И҆ бы́сть въ ми́рѣ мѣ́сто є҆гѡ̀, и҆ жили́ще є҆гѡ̀ въ сїѡ́нѣ."}, {"num": "г҃.", "text": "Та́мѡ сокрꙋшѝ крѣ́пѡсти лꙋкѡ́въ, ѻ҆рꙋ́жїе и҆ ме́чь и҆ бра́нь."}, {"num": "д҃.", "text": "Просвѣща́еши ты̀ ди́вно ѿ го́ръ вѣ́чныхъ."}, {"num": "є҃.", "text": "Смѧто́шасѧ всѝ неразꙋ́мнїи се́рдцемъ: ᲂу҆снꙋ́ша сно́мъ свои́мъ, и҆ ничто́же ѡ҆брѣто́ша всѝ мꙋ́жїе бога́тства въ рꙋка́хъ свои́хъ."}, {"num": "ѕ҃.", "text": "Ѿ запреще́нїѧ твоегѡ̀, бж҃е і҆а́ковль, воздрема́ша всѣ́дшїи на ко́ни."}, {"num": "з҃.", "text": "Ты̀ стра́шенъ є҆сѝ, и҆ кто̀ противоста́нетъ тебѣ̀; ѿто́лѣ гнѣ́въ тво́й."}, {"num": "и҃.", "text": "Съ нб҃сѐ слы́шанъ сотвори́лъ є҆сѝ сꙋ́дъ, землѧ̀ ᲂу҆боѧ́сѧ и҆ ᲂу҆молча̀,"}, {"num": "ѳ҃.", "text": "Внегда̀ воста́ти на сꙋ́дъ бг҃ꙋ, сп҃стѝ всѧ̑ крѡ́ткїѧ землѝ."}, {"num": "і҃.", "text": "Ꙗ҆́кѡ помышле́нїе человѣ́ческое и҆сповѣ́стсѧ тебѣ̀, и҆ ѡ҆ста́нокъ помышле́нїѧ пра́зднꙋетъ тѝ."}, {"num": "а҃і.", "text": "Помоли́тесѧ и҆ воздади́те гдⷭ҇еви бг҃ꙋ на́шемꙋ: всѝ, и҆̀же ѡ҆́крестъ є҆гѡ̀, принесꙋ́тъ да́ры"}, {"num": "в҃і.", "text": "Стра́шномꙋ и҆ ѿе́млющемꙋ дꙋ́хи кнѧзе́й, стра́шномꙋ па́че царе́й земны́хъ. а҃ Въ коне́цъ, ѡ҆ і҆дїѳꙋ́мѣ, ѱало́мъ а҆са́фꙋ, ѻ҃ѕ."}]}, "76": {"number": 76, "cu_numeral": "ѻ҃ѕ", "title": "Ѱало́мъ ѻ҃ѕ (76)", "subtitle": "а҃ Въ коне́цъ, ѡ҆ і҆дїѳꙋ́мѣ, ѱало́мъ а҆са́фꙋ, ѻ҃ѕ.", "verses": [{"num": "а҃.", "text": "Гла́сомъ мои́мъ ко гдⷭ҇ꙋ воззва́хъ, гла́сомъ мои́мъ къ бг҃ꙋ, и҆ внѧ́тъ мѝ."}, {"num": "в҃.", "text": "Въ де́нь ско́рби моеѧ̀ бг҃а взыска́хъ рꙋка́ма мои́ма, но́щїю пред̾ ни́мъ, и҆ не прельще́нъ бы́хъ: ѿве́ржесѧ ᲂу҆тѣ́шитисѧ дꙋша̀ моѧ̀."}, {"num": "г҃.", "text": "Помѧнꙋ́хъ бг҃а и҆ возвесели́хсѧ, поглꙋмлѧ́хсѧ, и҆ малодꙋ́шствоваше дꙋ́хъ мо́й."}, {"num": "д҃.", "text": "Предвари́стѣ стражбы̑ ѻ҆́чи моѝ: смѧто́хсѧ и҆ не глаго́лахъ."}, {"num": "є҃.", "text": "Помы́слихъ дни̑ пє́рвыѧ, и҆ лѣ̑та вѣ̑чнаѧ помѧнꙋ́хъ, и҆ поꙋча́хсѧ:"}, {"num": "ѕ҃.", "text": "Но́щїю се́рдцемъ мои́мъ глꙋмлѧ́хсѧ и҆ тꙋжа́ше дꙋ́хъ мо́й:"}, {"num": "з҃.", "text": "Е҆да̀ во вѣ́ки ѿри́нетъ гдⷭ҇ь, и҆ не приложи́тъ бл҃говоли́ти па́ки;"}, {"num": "и҃.", "text": "И҆лѝ до конца̀ млⷭ҇ть свою̀ ѿсѣче́тъ, сконча̀ гл҃го́лъ ѿ ро́да въ ро́дъ;"}, {"num": "ѳ҃.", "text": "Е҆да̀ забꙋ́детъ ᲂу҆ще́дрити бг҃ъ; и҆лѝ ᲂу҆держи́тъ во гнѣ́вѣ свое́мъ щедрѡ́ты своѧ̑;"}, {"num": "і҃.", "text": "И҆ рѣ́хъ: ны́нѣ нача́хъ: сїѧ̀ и҆змѣ́на десни́цы вы́шнѧгѡ."}, {"num": "а҃і.", "text": "Помѧнꙋ́хъ дѣла̀ гдⷭ҇нѧ: ꙗ҆́кѡ помѧнꙋ̀ ѿ нача́ла чꙋдеса̀ твоѧ̑,"}, {"num": "в҃і.", "text": "И҆ поꙋчꙋ́сѧ во всѣ́хъ г҃і д҃і є҃і ѕ҃і з҃і и҃і ѳ҃і к҃ к҃а дѣла̀ гдⷭ҇нѧ: ꙗ҆́кѡ помѧнꙋ̀ ѿ нача́ла чꙋдеса̀ твоѧ̑, И҆"}, {"num": "г҃і.", "text": "поꙋчꙋ́сѧ во всѣ́хъ дѣ́лѣхъ твои́хъ, и҆ въ начина́нїихъ твои́хъ поглꙋмлю́сѧ. Бж҃е, во"}, {"num": "д҃і.", "text": "ст҃ѣ́мъ пꙋ́ть тво́й: кто̀ бг҃ъ ве́лїй ꙗ҆́кѡ бг҃ъ на́шъ; Ты̀ є҆сѝ бг҃ъ творѧ́й чꙋдеса̀: сказа́лъ є҆сѝ въ лю́дехъ си́лꙋ твою̀,"}, {"num": "є҃і.", "text": "И҆зба́вилъ є҆сѝ мы́шцею твое́ю лю́ди твоѧ̑, сы́ны і҆а̑кѡвли и҆ і҆ѡ́сифѡвы."}, {"num": "ѕ҃і.", "text": "Ви́дѣша тѧ̀ во́ды, бж҃е, ви́дѣша тѧ̀ во́ды, и҆ ᲂу҆боѧ́шасѧ: смѧто́шасѧ бє́здны,"}, {"num": "з҃і.", "text": "Мно́жество шꙋ́ма вѡ́дъ: гла́съ да́ша ѻ҆́блацы, и҆́бо стрѣ́лы твоѧ̑ прехо́дѧтъ."}, {"num": "и҃і.", "text": "Гла́съ гро́ма твоегѡ̀ въ колесѝ, ѡ҆свѣти́ша мѡ́лнїѧ твоѧ̑ вселе́ннꙋю: подви́жесѧ и҆ тре́петна бы́сть землѧ̀."}, {"num": "ѳ҃і.", "text": "Въ мо́ри пꙋтїѐ твоѝ, и҆ стєзѝ твоѧ̑ въ вода́хъ мно́гихъ, и҆ слѣды̀ твоѝ не позна́ютсѧ."}, {"num": "к҃.", "text": "Наста́вилъ є҆сѝ ꙗ҆́кѡ ѻ҆́вцы лю́ди твоѧ̑ рꙋко́ю мѡѷсе́овою и҆ а҆арѡ́нею. Сла́ва:"}]}, "77": {"number": 77, "cu_numeral": "ѻ҃з", "title": "Ѱало́мъ ѻ҃з (77)", "subtitle": "Ра́зꙋма а҆са́фꙋ, ѻ҃з.", "verses": [{"num": "а҃.", "text": "Внемли́те, лю́дїе моѝ, зако́нꙋ моемꙋ̀, приклони́те ᲂу҆́хо ва́ше во глаго́лы ᲂу҆́стъ мои́хъ."}, {"num": "в҃.", "text": "Ѿве́рзꙋ въ при́тчахъ ᲂу҆ста̀ моѧ̑, провѣща́ю гана̑нїѧ и҆спе́рва."}, {"num": "г҃.", "text": "Е҆ли̑ка слы́шахомъ и҆ позна́хомъ ѧ҆̀, и҆ ѻ҆тцы̀ на́ши повѣ́даша на́мъ:"}, {"num": "д҃.", "text": "Не ᲂу҆таи́шасѧ ѿ ча̑дъ и҆́хъ въ ро́дъ и҆́нъ, возвѣща́юще хвалы̑ гдⷭ҇ни, и҆ си̑лы є҆гѡ.̀ и҆ чꙋдеса̀ є҆гѡ̀, ꙗ҆̀же сотворѝ."}, {"num": "є҃.", "text": "И҆ воздви́же свидѣ́нїе во і҆а́кѡвѣ, и҆ зако́нъ положѝ во і҆и҃ли: є҆ли̑ка заповѣ́да ѻ҆тцє́мъ на́шымъ, сказа́ти ѧ҆̀ сыновѡ́мъ свои̑мъ;"}, {"num": "ѕ҃.", "text": "Ꙗ҆́кѡ да позна́етъ ро́дъ и҆́нъ, сы́нове родѧ́щїисѧ, и҆ воста́нꙋтъ и҆ повѣ́дѧтъ ѧ҆̀ сыновѡ́мъ свои̑мъ:"}, {"num": "з҃.", "text": "Да положа́тъ на бг҃а ᲂу҆пова́нїе своѐ, и҆ не забꙋ́дꙋтъ дѣ́лъ бж҃їихъ, и҆ за́пѡвѣди є҆гѡ̀ взы́щꙋтъ:"}, {"num": "и҃.", "text": "Да не бꙋ́дꙋтъ ꙗ҆́коже ѻ҆тцы̀ и҆́хъ, ро́дъ стропти́въ и҆ преѡгорчева́ѧй, ро́дъ и҆́же не и҆спра́ви се́рдца своегѡ,̀ и҆ не ᲂу҆вѣ́ри съ бг҃омъ дꙋ́ха своегѡ̀."}, {"num": "ѳ҃.", "text": "Сы́нове є҆фрє́мли налѧца́юще и҆ стрѣлѧ́юще лꙋ́ки, возврати́шасѧ въ де́нь бра́ни."}, {"num": "і҃.", "text": "Не сохрани́ша завѣ́та бж҃їѧ, и҆ въ зако́нѣ є҆гѡ̀ не восхотѣ́ша ходи́ти."}, {"num": "а҃і.", "text": "И҆ забы́ша бл҃годѣѧ̑нїѧ є҆гѡ̀, и҆ чꙋдеса̀ є҆гѡ̀, ꙗ҆̀же показа̀ и҆̀мъ:"}, {"num": "в҃і.", "text": "Пред̾ ѻ҆тцы̑ и҆́хъ, ꙗ҆̀же сотворѝ чꙋдеса̀ въ землѝ є҆гѵ́петстѣй, на по́ли танеѡ́сѣ."}, {"num": "г҃і.", "text": "Разве́рзе мо́ре, и҆ проведѐ и҆̀хъ: предста́ви во́ды ꙗ҆́кѡ мѣ́хъ."}, {"num": "д҃і.", "text": "И҆ наста́ви ѧ҆̀ ѡ҆́блакомъ во днѝ, и҆ всю̀ но́щь просвѣще́нїемъ ѻ҆гнѧ̀."}, {"num": "є҃і.", "text": "Разве́рзе ка́мень въ пꙋсты́ни, и҆ напоѝ ѧ҆̀ ꙗ҆́кѡ въ бе́зднѣ мно́зѣ:"}, {"num": "ѕ҃і.", "text": "И҆ и҆зведѐ во́дꙋ и҆з̾ ка́мене: и҆ низведѐ ꙗ҆́кѡ рѣ́ки во́ды."}, {"num": "з҃і.", "text": "И҆ приложи́ша є҆щѐ согрѣша́ти є҆мꙋ̀, преѡгорчи́ша вы́шнѧго въ безво́днѣй:"}, {"num": "и҃і.", "text": "И҆ и҆скꙋси́ша бг҃а въ сердца́хъ свои́хъ воспроси́ти бра̑шна дꙋша́мъ свои̑мъ."}, {"num": "ѳ҃і.", "text": "И҆ клевета́ша на бг҃а, и҆ рѣ́ша: є҆да̀ возмо́жетъ бг҃ъ ᲂу҆гото́вати трапе́зꙋ въ пꙋсты́ни;"}, {"num": "к҃.", "text": "Поне́же поразѝ ка́мень, и҆ потеко́ша во́ды, и҆ пото́цы наводни́шасѧ: є҆да̀ и҆ хлѣ́бъ мо́жетъ да́ти, и҆лѝ ᲂу҆гото́вати трапе́зꙋ лю́демъ свои̑мъ;"}, {"num": "к҃а.", "text": "Сегѡ̀ ра́ди слы́ша гдⷭ҇ь и҆ презрѣ̀, и҆ ѻ҆́гнь возгорѣ́сѧ во і҆а́кѡвѣ, и҆ гнѣ́въ взы́де на і҆и҃лѧ:"}, {"num": "к҃в.", "text": "Ꙗ҆́кѡ не вѣ́роваша бг҃ови, нижѐ ᲂу҆пова́ша на сп҃се́нїе є҆гѡ̀."}, {"num": "к҃г.", "text": "И҆ заповѣ́да ѻ҆блакѡ́мъ свы́ше, и҆ двє́ри нб҃сѐ ѿве́рзе:"}, {"num": "к҃д.", "text": "И҆ ѡ҆дождѝ и҆̀мъ ма́ннꙋ ꙗ҆́сти, и҆ хлѣ́бъ нбⷭ҇ный дадѐ и҆̀мъ."}, {"num": "к҃є.", "text": "Хлѣ́бъ а҆́гг҃лскїй ꙗ҆дѐ человѣ́къ: бра́шно посла̀ и҆̀мъ до сы́тости."}, {"num": "к҃ѕ.", "text": "Воздви́же ю҆́гъ съ нб҃сѐ, и҆ наведѐ си́лою свое́ю лі́ва:"}, {"num": "к҃з.", "text": "И҆ ѡ҆дождѝ на нѧ̀ ꙗ҆́кѡ пра́хъ плѡ́ти, и҆ ꙗ҆́кѡ песо́къ морскі́й пти̑цы перна̑ты."}, {"num": "к҃и.", "text": "И҆ нападо́ша посредѣ̀ ста́на и҆́хъ ѻ҆́крестъ жили́щъ и҆́хъ."}, {"num": "к҃ѳ.", "text": "И҆ ꙗ҆до́ша и҆ насы́тишасѧ ѕѣлѡ̀, и҆ жела́нїе и҆́хъ пренесѐ и҆̀мъ. Не лиши́ к҃ѳ л҃ л҃а л҃в л҃г л҃д л҃є л҃ѕ л҃з л҃и л҃ѳ м҃ м҃а м҃в м҃г м҃д м҃є м҃ѕ м҃з м҃и м҃ѳ н҃ н҃а н҃в н҃г н҃д н҃є н҃ѕ н҃з н҃и н҃ѳ ѯ҃ И҆ ꙗ҆до́ша и҆ насы́тишасѧ ѕѣлѡ̀, и҆ жела́нїе и҆́хъ пренесѐ и҆̀мъ."}, {"num": "л҃.", "text": "Не лиши́шасѧ ѿ жела́нїѧ своегѡ̀, є҆щѐ бра́шнꙋ сꙋ́щꙋ во ᲂу҆стѣ́хъ и҆́хъ,"}, {"num": "л҃а.", "text": "И҆ гнѣ́въ бж҃їй взы́де на нѧ̀, и҆ ᲂу҆бѝ мнѡ́жайшаѧ и҆́хъ, и҆ и҆збра̑ннымъ і҆и҃лєвымъ запѧ́тъ."}, {"num": "л҃в.", "text": "Во всѣ́хъ си́хъ согрѣши́ша є҆щѐ, и҆ не вѣ́роваша чꙋдесє́мъ є҆гѡ̀:"}, {"num": "л҃г.", "text": "И҆ и҆зчезо́ша въ сꙋетѣ̀ дні́е и҆́хъ, и҆ лѣ̑та и҆́хъ со тща́нїемъ."}, {"num": "л҃д.", "text": "Е҆гда̀ ᲂу҆бива́ше ѧ҆̀, тогда̀ взыска́хꙋ є҆го̀ и҆ ѡ҆браща́хꙋсѧ, ᲂу҆́треневахꙋ къ бг҃ꙋ:"}, {"num": "л҃є.", "text": "И҆ помѧнꙋ́ша, ꙗ҆́кѡ бг҃ъ помо́щникъ и҆̀мъ є҆́сть, и҆ бг҃ъ вы́шнїй и҆зба́витель и҆̀мъ є҆́сть."}, {"num": "л҃ѕ.", "text": "И҆ возлюби́ша є҆го̀ ᲂу҆сты̑ свои́ми, и҆ ѧ҆зы́комъ свои́мъ солга́ша є҆мꙋ̀:"}, {"num": "л҃з.", "text": "Се́рдце же и҆́хъ не бѣ̀ пра́во съ ни́мъ, нижѐ ᲂу҆вѣ́ришасѧ въ завѣ́тѣ є҆гѡ̀."}, {"num": "л҃и.", "text": "То́й же є҆́сть ще́дръ, и҆ ѡ҆чи́ститъ грѣхѝ и҆́хъ, и҆ не растли́тъ, и҆ ᲂу҆мно́житъ ѿврати́ти ꙗ҆́рость свою̀, и҆ не разжже́тъ всегѡ̀ гнѣ́ва своегѡ̀."}, {"num": "л҃ѳ.", "text": "И҆ помѧнꙋ̀, ꙗ҆́кѡ пло́ть сꙋ́ть: дꙋ́хъ ходѧ́й и҆ не"}, {"num": "м҃.", "text": "ѡ҆браща́ѧйсѧ, Колькра́ты преѡгорчи́ша є҆го̀ въ пꙋсты́ни, прогнѣ́ваша є҆го̀ въ землѝ безво́днѣй;"}, {"num": "м҃а.", "text": "И҆ ѡ҆брати́шасѧ, и҆ и҆скꙋси́ша бг҃а, и҆ ст҃а́го і҆и҃лева раздражи́ша."}, {"num": "м҃в.", "text": "И҆ не помѧнꙋ́ша рꙋкѝ є҆гѡ̀ въ де́нь, во́ньже и҆зба́ви ѧ҆̀ и҆з̾ рꙋкѝ ѡ҆скорблѧ́ющагѡ."}, {"num": "м҃г.", "text": "Ꙗ҆́коже положѝ во є҆гѵ́птѣ зна́мєнїѧ своѧ̑, и҆ чꙋдеса̀ своѧ̑ на по́ли танеѡ́сѣ."}, {"num": "м҃д.", "text": "И҆ преложѝ въ кро́вь рѣ́ки и҆́хъ и҆ и҆сто́чники и҆́хъ, ꙗ҆́кѡ да не пїю́тъ."}, {"num": "м҃є.", "text": "Посла̀ на нѧ̀ пє́сїѧ мꙋ̑хи, и҆ поѧдо́ша ѧ҆̀, и҆ жа̑бы, и҆ растлѝ ѧ҆̀."}, {"num": "м҃ѕ.", "text": "И҆ дадѐ ржѣ̀ плоды̀ и҆́хъ, и҆ трꙋды̀ и҆́хъ прꙋгѡ́мъ."}, {"num": "м҃з.", "text": "Оу҆бѝ гра́домъ вїногра́ды и҆́хъ, и҆ черни́чїе и҆́хъ сла́ною:"}, {"num": "м҃и.", "text": "И҆ предадѐ гра́дꙋ скоты̀ и҆́хъ, и҆ и҆мѣ́нїе и҆́хъ ѻ҆гню̀."}, {"num": "м҃ѳ.", "text": "Посла̀ на нѧ̀ гнѣ́въ ꙗ҆́рости своеѧ̀, ꙗ҆́рость и҆ гнѣ́въ и҆ ско́рбь, посла́нїе а҆́ггєлы лю́тыми."}, {"num": "н҃.", "text": "Пꙋтесотворѝ стезю̀ гнѣ́вꙋ своемꙋ̀: и҆ не пощадѣ̀ ѿ сме́рти дꙋ́шъ и҆́хъ, и҆ скоты̀ и҆́хъ въ сме́рти заключѝ:"}, {"num": "н҃а.", "text": "И҆ поразѝ всѧ́кое перворо́дное въ землѝ є҆гѵ́петстѣй, нача́токъ всѧ́кагѡ трꙋда̀ и҆́хъ въ селе́нїихъ ха́мовыхъ."}, {"num": "н҃в.", "text": "И҆ воздви́же ꙗ҆́кѡ ѻ҆́вцы лю́ди своѧ̑, и҆ возведѐ ѧ҆̀ ꙗ҆́кѡ ста́до въ пꙋсты́ни,"}, {"num": "н҃г.", "text": "И҆ наста́ви ѧ҆̀ на ᲂу҆пова́нїе,"}, {"num": "н҃д.", "text": "и҆ не ᲂу҆боѧ́шасѧ: и҆ врагѝ и҆́хъ покры̀ мо́ре: И҆ введѐ ѧ҆̀ въ го́рꙋ ст҃ы́ни своеѧ̀, го́рꙋ сїю̀, ю҆́же стѧжа̀ десни́ца є҆гѡ̀."}, {"num": "н҃є.", "text": "И҆ и҆згна̀ ѿ лица̀ и҆́хъ ꙗ҆зы́ки, и҆ по жре́бїю дадѐ и҆̀мъ [зе́млю] ᲂу҆́жемъ жребодаѧ́нїѧ, и҆ вселѝ въ селе́нїихъ и҆́хъ кѡлѣ́на і҆и҃лєва."}, {"num": "н҃ѕ.", "text": "И҆ и҆скꙋси́ша и҆ преѡгорчи́ша бг҃а вы́шнѧго, и҆ свидѣ́нїй є҆гѡ̀ не сохрани́ша:"}, {"num": "н҃з.", "text": "И҆ ѿврати́шасѧ, и҆ ѿверго́шасѧ, ꙗ҆́коже и҆ ѻ҆тцы̀ и҆́хъ: преврати́шасѧ въ лꙋ́къ развраще́нъ."}, {"num": "н҃и.", "text": "И҆ прогнѣ́ваша є҆го̀ въ"}, {"num": "н҃ѳ.", "text": "хо́лмѣхъ свои́хъ, и҆ во и҆стꙋка́нныхъ свои́хъ раздражи́ша є҆го̀. Слы́ша бг҃ъ и҆ презрѣ̀, и҆ ᲂу҆ничижѝ ѕѣлѡ̀ і҆и҃лѧ:"}, {"num": "ѯ҃.", "text": "И҆ ѿри́нꙋ ски́нїю силѡ́мскꙋю, селе́нїе є҆́же всели́сѧ въ человѣ́цѣхъ:"}, {"num": "ѯ҃а.", "text": "И҆ предадѐ въ плѣ́нъ крѣ́пость и҆́хъ, и҆ добро́тꙋ и҆́хъ въ ѯ҃а ѯ҃в ѯ҃г ѯ҃д ѯ҃є ѯ҃ѕ ѯ҃з ѯ҃и ѯ҃ѳ ѻ҃ ѻ҃а ѻ҃в человѣ́цѣхъ:"}, {"num": "ѯ҃в.", "text": "И҆ предадѐ въ плѣ́нъ"}, {"num": "ѯ҃г.", "text": "крѣ́пость и҆́хъ, и҆ добро́тꙋ и҆́хъ въ рꙋ́ки врагѡ́въ: И҆ затворѝ во ѻ҆рꙋ́жїи лю́ди своѧ̑, и҆ достоѧ́нїе своѐ презрѣ̀. Ю҆́ношы и҆́хъ поѧдѐ ѻ҆́гнь, и҆ дѣ̑вы и҆́хъ не ѡ҆сѣ́тѡваны бы́ша:"}, {"num": "ѯ҃д.", "text": "Сщ҃е́нницы и҆́хъ мече́мъ падо́ша, и҆ вдови́цы и҆́хъ не ѡ҆пла̑каны бꙋ́дꙋтъ:"}, {"num": "ѯ҃є.", "text": "И҆ воста̀ ꙗ҆́кѡ спѧ̀ гдⷭ҇ь, ꙗ҆́кѡ си́ленъ и҆ шꙋ́менъ ѿ вїна̀:"}, {"num": "ѯ҃ѕ.", "text": "И҆ поразѝ врагѝ своѧ̑ вспѧ́ть, поноше́нїе вѣ́чное дадѐ и҆̀мъ."}, {"num": "ѯ҃з.", "text": "И҆ ѿри́нꙋ селе́нїе і҆ѡ́сифово, и҆ колѣ́но є҆фре́мово не и҆збра̀:"}, {"num": "ѯ҃и.", "text": "И҆ и҆збра̀ колѣ́но і҆ꙋ́дово, го́рꙋ сїѡ́ню, ю҆́же возлюбѝ."}, {"num": "ѯ҃ѳ.", "text": "И҆ созда̀ ꙗ҆́кѡ є҆диноро́га ст҃и́лище своѐ: на землѝ ѡ҆снова̀ и҆̀ въ вѣ́къ."}, {"num": "ѻ҃.", "text": "И҆ и҆збра̀ дв҃да раба̀ своего̀, и҆ воспрїѧ́тъ є҆го̀"}, {"num": "ѻ҃а.", "text": "ѿ ста́дъ ѻ҆́вчихъ: Ѿ дои́лицъ поѧ́тъ є҆го̀, пастѝ і҆а́кѡва раба̀ своего̀, и҆ і҆и҃лѧ достоѧ́нїе своѐ:"}, {"num": "ѻ҃в.", "text": "И҆ ᲂу҆пасѐ ѧ҆̀ въ неѕло́бїи се́рдца своегѡ̀, и҆ въ ра́зꙋмѣхъ рꙋкꙋ̀ своє́ю наста́вилъ ѧ҆̀ є҆́сть. Сла́ва:"}]}, "78": {"number": 78, "cu_numeral": "ѻ҃и", "title": "Ѱало́мъ ѻ҃и (78)", "subtitle": "Ѱало́мъ а҆са́фꙋ, ѻ҃и.", "verses": [{"num": "а҃.", "text": "Бж҃е, прїидо́ша ꙗ҆зы́цы въ достоѧ́нїе твоѐ, ѡ҆скверни́ша хра́мъ ст҃ы́й тво́й,"}, {"num": "в҃.", "text": "Положи́ша і҆ерⷭ҇ли́мъ ꙗ҆́кѡ ѻ҆во́щное храни́лище: положи́ша трꙋ̑пїѧ ра̑бъ твои́хъ бра́шно пти́цамъ нбⷭ҇нымъ, плѡ́ти прпⷣбныхъ твои́хъ ѕвѣрє́мъ земны́мъ:"}, {"num": "г҃.", "text": "Пролїѧ́ша кро́вь и҆́хъ ꙗ҆́кѡ во́дꙋ ѻ҆́крестъ і҆ерⷭ҇ли́ма, и҆ не бѣ̀ погреба́ѧй."}, {"num": "д҃.", "text": "Бы́хомъ поноше́нїе сосѣ́дѡмъ на́шымъ, подражне́нїе и҆ порꙋга́нїе сꙋ́щымъ ѻ҆́крестъ на́съ."}, {"num": "є҃.", "text": "Доко́лѣ, гдⷭ҇и, прогнѣ́ваешисѧ до конца̀; разжже́тсѧ ꙗ҆́кѡ ѻ҆́гнь рве́нїе твоѐ;"}, {"num": "ѕ҃.", "text": "Проле́й гнѣ́въ тво́й на ꙗ҆зы́ки не зна́ющыѧ тебѐ̀, и҆ на ца̑рствїѧ, ꙗ҆̀же и҆́мене твоегѡ̀ не призва́ша:"}, {"num": "з҃.", "text": "Ꙗ҆́кѡ поѧдо́ша і҆а́кѡва, и҆ мѣ́сто є҆гѡ̀ ѡ҆пꙋстоши́ша."}, {"num": "и҃.", "text": "Не помѧнѝ на́шихъ беззако́нїй пе́рвыхъ: ско́рѡ да предварѧ́тъ ны̀ щедрѡ́ты твоѧ̑, гдⷭ҇и, ꙗ҆́кѡ ѡ҆бнища́хомъ ѕѣлѡ̀."}, {"num": "ѳ҃.", "text": "Помозѝ на́мъ, бж҃е, сп҃си́телю на́шъ, сла́вы ра́ди и҆́мене твоегѡ̀. гдⷭ҇и, и҆зба́ви ны̀, и҆ ѡ҆чи́сти грѣхѝ на́шѧ и҆́мене ра́ди твоегѡ:"}, {"num": "і҃.", "text": "Да не когда̀ рекꙋ́тъ ꙗ҆зы́цы: гдѣ̀ є҆́сть бг҃ъ и҆́хъ; и҆ да ᲂу҆вѣ́стсѧ во ꙗ҆зы́цѣхъ пред̾ ѻ҆чи́ма на́шима ѿмще́нїе кро́ве ра̑бъ твои́хъ пролиты́ѧ."}, {"num": "а҃і.", "text": "Да вни́детъ пред̾ тѧ̀ воздыха́нїе ѡ҆кова́нныхъ: по вели́чїю мы́шцы твоеѧ̀ снабдѝ сы́ны ᲂу҆мерщвле́нныхъ."}, {"num": "в҃і.", "text": "Возда́ждь сосѣ́дѡмъ на́шымъ седмери́цею въ нѣ́дро и҆́хъ поноше́нїе и҆́хъ, и҆́мже поноси́ша тѧ̀, гдⷭ҇и."}, {"num": "г҃і.", "text": "Мы́ же лю́дїе г҃і нѣ́дро и҆́хъ поноше́нїе и҆́хъ, и҆́мже поноси́ша тѧ̀, гдⷭ҇и. Мы́ же лю́дїе твоѝ, и҆ ѻ҆́вцы па́жити твоеѧ̀ и҆сповѣ́мысѧ тебѣ̀, бж҃е, во вѣ́къ, въ ро́дъ и҆ ро́дъ возвѣсти́мъ хвалꙋ̀ твою̀. а҃ Въ коне́цъ, ѡ҆ и҆змѣ́ншихсѧ, свидѣ́нїе а҆са́фꙋ, ѱало́мъ ѻ҃ѳ."}]}, "79": {"number": 79, "cu_numeral": "ѻ҃ѳ", "title": "Ѱало́мъ ѻ҃ѳ (79)", "subtitle": "а҃ Въ коне́цъ, ѡ҆ и҆змѣ́ншихсѧ, свидѣ́нїе а҆са́фꙋ, ѱало́мъ ѻ҃ѳ.", "verses": [{"num": "а҃.", "text": "Пасы́й і҆и҃лѧ вонмѝ, наставлѧ́ѧй ꙗ҆́кѡ ѻ҆вча̀ і҆ѡ́сифа, сѣдѧ́й на херꙋві́мѣхъ, ꙗ҆ви́сѧ,"}, {"num": "в҃.", "text": "Пред̾ є҆фре́момъ и҆ венїамі́номъ и҆ манассі́емъ: воздви́гни си́лꙋ твою̀, и҆ прїидѝ во є҆́же сп҃стѝ на́съ."}, {"num": "г҃.", "text": "Бж҃е, ѡ҆брати́ ны, и҆ просвѣтѝ лицѐ твоѐ, и҆ сп҃се́мсѧ."}, {"num": "д҃.", "text": "Гдⷭ҇и бж҃е си́лъ, доко́лѣ гнѣ́ваешисѧ на моли́твꙋ ра̑бъ твои́хъ."}, {"num": "є҃.", "text": "Напита́еши на́съ хлѣ́бомъ сле́знымъ, и҆ напои́ши на́съ слеза́ми въ мѣ́рꙋ."}, {"num": "ѕ҃.", "text": "Положи́лъ є҆сѝ на́съ въ прерѣка́нїе сосѣ́дѡмъ на́шымъ, и҆ вразѝ на́ши подражни́ша ны̀."}, {"num": "з҃.", "text": "Гдⷭ҇и бж҃е си́лъ, ѡ҆брати́ ны, и҆ просвѣтѝ лицѐ твоѐ, и҆ сп҃се́мсѧ."}, {"num": "и҃.", "text": "Вїногра́дъ и҆з̾ є҆гѵ́пта прене́слъ є҆сѝ: и҆згна́лъ є҆сѝ ꙗ҆зы́ки, и҆ насади́лъ є҆сѝ и҆̀:"}, {"num": "ѳ҃.", "text": "Пꙋтесотвори́лъ є҆сѝ пред̾ ни́мъ, и҆ насади́лъ є҆сѝ корє́нїѧ є҆гѡ̀, и҆ и҆спо́лни зе́млю."}, {"num": "і҃.", "text": "Покры̀ го́ры сѣ́нь є҆гѡ̀, и҆ вѣ̑твїѧ є҆гѡ̀ ке́дры бж҃їѧ:"}, {"num": "а҃і.", "text": "Прострѐ ро́зги є҆гѡ̀ до мо́рѧ и҆ да́же до рѣ́къ ѻ҆́трасли є҆гѡ̀."}, {"num": "в҃і.", "text": "Вскꙋ́ю низложи́лъ є҆сѝ ѡ҆пло́тъ є҆гѡ̀, и҆ ѡ҆б̾има́ютъ и҆̀ всѝ мимоходѧ́щїи пꙋте́мъ:"}, {"num": "г҃і.", "text": "Ѡ҆зоба̀ и҆̀ ве́прь ѿ дꙋбра́вы, и҆ ᲂу҆едине́нный ди́вїй поѧдѐ и҆̀."}, {"num": "д҃і.", "text": "Бж҃е си́лъ, ѡ҆брати́сѧ ᲂу҆̀бо, и҆ при́зри съ нб҃сѐ и҆ ви́ждь, и҆ посѣтѝ вїногра́дъ се́й:"}, {"num": "є҃і.", "text": "И҆ совершѝ и҆̀, є҆го́же насадѝ десни́ца твоѧ̀, и҆ на сы́на человѣ́ческаго, є҆го́же ᲂу҆крепи́лъ є҆сѝ себѣ̀."}, {"num": "ѕ҃і.", "text": "Пожже́нъ ѻ҆гне́мъ и҆ раско́панъ: ѿ запреще́нїѧ лица̀ твоегѡ̀ поги́бнꙋтъ."}, {"num": "з҃і.", "text": "Да бꙋ́детъ рꙋка̀ твоѧ̀ на мꙋ́жа десни́цы твоеѧ̀, и҆ на сы́на человѣ́ческаго, є҆го́же ᲂу҆крѣпи́лъ є҆сѝ себѣ̀."}, {"num": "и҃і.", "text": "И҆ не ѿстꙋ́пимъ ѿ тебѐ: ѡ҆живи́ши ны̀, и҆ и҆́мѧ твоѐ призове́мъ."}, {"num": "ѳ҃і.", "text": "Гдⷭ҇и бж҃е си́лъ, ѡ҆брати́ ны, и҆ просвѣтѝ лицѐ твоѐ, и҆ сп҃се́мсѧ. а҃ Въ коне́цъ, ѡ҆ точи́лѣхъ, ѱало́мъ а҆са́фꙋ, п҃."}]}, "80": {"number": 80, "cu_numeral": "п҃", "title": "Ѱало́мъ п҃ (80)", "subtitle": "а҃ Въ коне́цъ, ѡ҆ точи́лѣхъ, ѱало́мъ а҆са́фꙋ, п҃.", "verses": [{"num": "а҃.", "text": "Ра́дꙋйтесѧ бг҃ꙋ помо́щникꙋ на́шемꙋ, воскли́кните бг҃ꙋ і҆а́кѡвлю:"}, {"num": "в҃.", "text": "Прїими́те ѱало́мъ и҆ дади́те тѷмпа́нъ, ѱалти́рь красе́нъ съ гꙋ́сльми:"}, {"num": "г҃.", "text": "Вострꙋби́те въ новомѣсѧчїи трꙋбо́ю, во бл҃гознамени́тый де́нь пра́здника ва́шегѡ:"}, {"num": "д҃.", "text": "Ꙗ҆́кѡ повелѣ́нїе і҆и҃леви є҆́сть, и҆ сꙋдѷба̀ бг҃ꙋ і҆а́ковлю."}, {"num": "є҃.", "text": "Свидѣ́нїе во і҆ѡ́сифѣ положѝ є҆̀, внегда̀ и҆зы́ти"}, {"num": "ѕ҃.", "text": "є҆мꙋ̀ ѿ землѝ є҆гѵ́петскїѧ: ѧ҆зы́ка є҆гѡ́же не вѣ́дѧше, ᲂу҆слы́ша. Ѿѧ́тъ ѿ бре́мене з҃ и҃ ѳ҃ і҃ а҃і в҃і г҃і д҃і є҃і ѕ҃і з҃і є҆гѵ́петскїѧ: ѧ҆зы́ка є҆гѡ́же не вѣ́дѧше, ᲂу҆слы́ша. Ѿѧ́тъ ѿ бре́мене хребе́тъ є҆гѡ̀: рꙋ́цѣ є҆гѡ̀ въ кошѝ порабо́тастѣ."}, {"num": "з҃.", "text": "Въ ско́рби призва́лъ мѧ̀ є҆сѝ, и҆ и҆зба́вихъ тѧ̀: ᲂу҆слы́шахъ тѧ̀ въ та́йнѣ бꙋ́рнѣ:"}, {"num": "и҃.", "text": "и҆скꙋси́хъ тѧ̀ на водѣ̀ прерѣка́нїѧ: Слы́шите, лю́дїе моѝ, и҆ засвидѣ́тельствꙋю ва́мъ, і҆и҃лю, а҆́ще послꙋ́шаеши менѐ:"}, {"num": "ѳ҃.", "text": "Не бꙋ́детъ тебѣ̀ бо́гъ но́въ, нижѐ поклони́шисѧ бо́гꙋ чꙋжде́мꙋ."}, {"num": "і҃.", "text": "А҆́зъ бо є҆́смь гдⷭ҇ь бг҃ъ тво́й, и҆зведы́й тѧ̀ ѿ землѝ є҆гѵ́петскїѧ: разширѝ ᲂу҆ста̀ твоѧ̀, и҆ и҆спо́лню ѧ҆̀."}, {"num": "а҃і.", "text": "И҆ не послꙋ́шаша лю́дїе моѝ гла́са моегѡ̀, и҆ і҆и҃ль не внѧ́тъ мѝ:"}, {"num": "в҃і.", "text": "И҆ ѿпꙋсти́хъ ѧ҆̀ по начина́нїємъ серде́цъ и҆́хъ, по́йдꙋтъ въ начина́нїихъ свои́хъ. А҆́ще"}, {"num": "г҃і.", "text": "бы́ша лю́дїе моѝ послꙋ́шали менѐ, і҆и҃ль а҆́ще бы въ пꙋти̑ моѧ̑ ходи́лъ,"}, {"num": "д҃і.", "text": "Ни ѡ҆ чесо́мъ же ᲂу҆́бѡ врагѝ є҆гѡ̀ смири́лъ бы́хъ, и҆ на ѡ҆скорблѧ́ющыѧ и҆̀хъ возложи́лъ бы́хъ рꙋ́кꙋ мою̀."}, {"num": "є҃і.", "text": "Вразѝ гдⷭ҇ни солга́ша є҆мꙋ̀, и҆ бꙋ́детъ вре́мѧ и҆́хъ въ вѣ́къ."}, {"num": "ѕ҃і.", "text": "И҆ напита̀ и҆̀хъ ѿ тꙋ́ка пшени́чна, и҆ ѿ ка́мене ме́да насы́ти и҆̀хъ. Сла́ва:"}]}, "81": {"number": 81, "cu_numeral": "п҃а", "title": "Ѱало́мъ п҃а (81)", "subtitle": "Ѱало́мъ а҆са́фꙋ, п҃а.", "verses": [{"num": "а҃.", "text": "Бг҃ъ ста̀ въ со́нмѣ богѡ́въ, посредѣ́ же бо́ги разсꙋ́дитъ."}, {"num": "в҃.", "text": "Доко́лѣ сꙋ́дите непра́вдꙋ, и҆ ли́ца грѣ́шникѡвъ прїе́млете;"}, {"num": "г҃.", "text": "Сꙋди́те си́рꙋ"}, {"num": "д҃.", "text": "и҆ ᲂу҆бо́гꙋ, смире́на и҆ ни́ща ѡ҆правда́йте: И҆зми́те ни́ща и҆ ᲂу҆бо́га, и҆з̾ рꙋкѝ грѣ́шничи и҆зба́вите є҆го̀."}, {"num": "є҃.", "text": "Не позна́ша, нижѐ ᲂу҆разꙋмѣ́ша, во тьмѣ̀ хо́дѧтъ: да подви́жатсѧ всѧ̑ ѡ҆снова̑нїѧ землѝ."}, {"num": "ѕ҃.", "text": "А҆́зъ рѣ́хъ: бо́зи є҆стѐ, и҆ сы́нове вы́шнѧгѡ всѝ."}, {"num": "з҃.", "text": "Вы́ же ꙗ҆́кѡ человѣ́цы ᲂу҆мира́ете, и҆ ꙗ҆́кѡ є҆ди́нъ ѿ кнѧзе́й па́даете."}, {"num": "и҃.", "text": "Воскрⷭ҇нѝ бж҃е, сꙋдѝ землѝ, ꙗ҆́кѡ ты̀ наслѣ́диши во всѣ́хъ ꙗ҆зы́цѣхъ. а҃ Пѣ́снь ѱалма̀ а҆са́фꙋ, п҃в."}]}, "82": {"number": 82, "cu_numeral": "п҃в", "title": "Ѱало́мъ п҃в (82)", "subtitle": "а҃ Пѣ́снь ѱалма̀ а҆са́фꙋ, п҃в.", "verses": [{"num": "а҃.", "text": "Бж҃е, кто̀ ᲂу҆подо́битсѧ тебѣ̀; не премолчѝ, нижѐ ᲂу҆кротѝ, бж҃е:"}, {"num": "в҃.", "text": "Ꙗ҆́кѡ сѐ вразѝ твоѝ возшꙋмѣ́ша, и҆ ненави́дѧщїи тѧ̀ воздвиго́ша главꙋ̀."}, {"num": "г҃.", "text": "На лю́ди твоѧ̑ лꙋка́вноваша во́лею, и҆ совѣща́ша на ст҃ы̑ѧ твоѧ̑."}, {"num": "д҃.", "text": "Рѣ́ша: прїиди́те и҆ потреби́мъ ѧ҆̀ ѿ ꙗ҆зы̑къ, и҆ не помѧне́тсѧ и҆́мѧ і҆и҃лево ктомꙋ̀."}, {"num": "є҃.", "text": "Ꙗ҆́кѡ совѣща́ша є҆диномышле́нїемъ вкꙋ́пѣ, на тѧ̀ завѣ́тъ завѣща́ша:"}, {"num": "ѕ҃.", "text": "Селє́нїѧ і҆дꙋмє́йска и҆ і҆сма́илїте, мѡа́въ и҆ а҆га́рѧне,"}, {"num": "з҃.", "text": "Гева́лъ и҆ а҆ммѡ́нъ и҆ а҆мали́къ, и҆ноплемє́нницы съ живꙋ́щими въ тѵ́рѣ:"}, {"num": "и҃.", "text": "И҆́бо и҆ а҆ссꙋ́ръ прїи́де съ ни́ми, бы́ша въ застꙋпле́нїе ѳ҃ і҃ а҃і в҃і г҃і д҃і є҃і ѕ҃і з҃і и҃і ѳ҃і ми въ тѵ́рѣ: И҆́бо и҆ а҆ссꙋ́ръ прїи́де съ ни́ми, бы́ша въ застꙋпле́нїе сыновѡ́мъ лѡ́тѡвымъ."}, {"num": "ѳ҃.", "text": "Сотворѝ и҆̀мъ ꙗ҆́кѡ мадїа́мꙋ и҆ сїса́рѣ, ꙗ҆́кѡ і҆аві́мꙋ въ пото́цѣ кі́ссовѣ."}, {"num": "і҃.", "text": "Потреби́шасѧ во а҆ендѡ́рѣ, бы́ша ꙗ҆́кѡ гно́й земны́й."}, {"num": "а҃і.", "text": "Положѝ кнѧ́зи и҆́хъ ꙗ҆́кѡ ѡ҆ри́ва и҆ зи́ва, и҆ зеве́а и҆ салма́на, всѧ̑ кнѧ̑зи и҆́хъ,"}, {"num": "в҃і.", "text": "И҆̀же рѣ́ша: да наслѣ́димъ себѣ̀ ст҃и́лище бж҃їе."}, {"num": "г҃і.", "text": "Бж҃е мо́й, положѝ ѧ҆̀ ꙗ҆́кѡ ко́ло, ꙗ҆́кѡ тро́сть пред̾ лице́мъ вѣ́тра."}, {"num": "д҃і.", "text": "Ꙗ҆́кѡ ѻ҆́гнь попалѧ́ѧй дꙋбра̑вы, ꙗ҆́кѡ пла́мень пожига́ѧй го́ры:"}, {"num": "є҃і.", "text": "Та́кѡ пожене́ши ѧ҆̀ бꙋ́рею твое́ю, и҆ гнѣ́вомъ твои́мъ смѧте́ши ѧ҆̀."}, {"num": "ѕ҃і.", "text": "И҆спо́лни ли́ца и҆́хъ безче́стїѧ, и҆ взы́щꙋтъ и҆́мене твоегѡ̀, гдⷭ҇и."}, {"num": "з҃і.", "text": "Да постыдѧ́тсѧ и҆ смѧтꙋ́тсѧ въ вѣ́къ вѣ́ка, и҆ посра́мѧтсѧ и҆ поги́бнꙋтъ."}, {"num": "и҃і.", "text": "И҆ да позна́ютъ, ꙗ҆́кѡ и҆́мѧ тебѣ̀ гдⷭ҇ь, ты̀ є҆ди́нъ вы́шнїй по все́й землѝ. а҃ Въ коне́цъ, ѡ҆ точи́лѣхъ, сынѡ́мъ коре́ѡвымъ, ѱало́мъ п҃г."}]}, "83": {"number": 83, "cu_numeral": "п҃г", "title": "Ѱало́мъ п҃г (83)", "subtitle": "а҃ Въ коне́цъ, ѡ҆ точи́лѣхъ, сынѡ́мъ коре́ѡвымъ, ѱало́мъ п҃г.", "verses": [{"num": "а҃.", "text": "Ко́ль возлю́блєнна селє́нїѧ твоѧ̑, гдⷭ҇и си́лъ."}, {"num": "в҃.", "text": "Жела́етъ и҆ скончава́етсѧ дꙋша̀ моѧ̀ во дворы̀ гдⷭ҇ни: се́рдце моѐ и҆ пло́ть моѧ̀ возра́довастасѧ ѡ҆ бз҃ѣ жи́вѣ."}, {"num": "г҃.", "text": "И҆́бо пти́ца ѡ҆брѣ́те себѣ̀ хра́минꙋ, и҆ го́рлица гнѣздо̀ себѣ̀, и҆дѣ́же положи́тъ птенцы̀ своѧ̑: ѻ҆лтари̑ твоѧ̑, гдⷭ҇и си́лъ, цр҃ю̀ мо́й, и҆ бж҃е мо́й."}, {"num": "д҃.", "text": "Бл҃же́ни живꙋ́щїи въ домꙋ̀ твое́мъ: въ вѣ́ки вѣкѡ́въ восхва́лѧтъ тѧ̀."}, {"num": "є҃.", "text": "Бл҃же́нъ мꙋ́жъ, є҆мꙋ́же є҆́сть застꙋпле́нїе є҆гѡ̀ ᲂу҆ тебѐ: восхождє́нїѧ въ се́рдцѣ свое́мъ положѝ,"}, {"num": "ѕ҃.", "text": "Во ю҆до́ль плаче́внꙋю, въ мѣ́сто є҆́же положѝ: и҆́бо бл҃гослове́нїе да́стъ законополага́ѧй."}, {"num": "з҃.", "text": "По́йдꙋтъ ѿ си́лы въ си́лꙋ: ꙗ҆ви́тсѧ бг҃ъ богѡ́въ въ сїѡ́нѣ."}, {"num": "и҃.", "text": "Гдⷭ҇и бж҃е си́лъ, ᲂу҆слы́ши мл҃твꙋ мою̀, внꙋшѝ, бж҃е і҆а́кѡвль:"}, {"num": "ѳ҃.", "text": "Защи́тниче на́шъ, ви́ждь бж҃е, и҆ при́зри на лицѐ хрⷭ҇та̀ твоегѡ̀."}, {"num": "і҃.", "text": "Ꙗ҆́кѡ лꙋ́чше де́нь є҆ди́нъ во дво́рѣхъ твои́хъ па́че ты́сѧщъ: и҆зво́лихъ примета́тисѧ въ домꙋ̀ бг҃а моегѡ̀ па́че, не́же жи́ти мѝ въ селе́нїихъ грѣ́шничихъ."}, {"num": "а҃і.", "text": "Ꙗ҆́кѡ млⷭ҇ть и҆ и҆́стинꙋ лю́битъ гдⷭ҇ь, бг҃ъ блгⷣть и҆ сла́вꙋ да́стъ: гдⷭ҇ь не лиши́тъ бл҃ги́хъ ходѧ́щихъ неѕло́бїемъ."}, {"num": "в҃і.", "text": "Гдⷭ҇и бж҃е си́лъ, бл҃же́нъ человѣ́къ ᲂу҆пова́ѧй на тѧ̀. а҃ Въ коне́цъ, сынѡ́мъ коре́ѡвымъ, ѱало́мъ п҃д."}]}, "84": {"number": 84, "cu_numeral": "п҃д", "title": "Ѱало́мъ п҃д (84)", "subtitle": "а҃ Въ коне́цъ, сынѡ́мъ коре́ѡвымъ, ѱало́мъ п҃д.", "verses": [{"num": "а҃.", "text": "Бл҃говоли́лъ є҆сѝ, гдⷭ҇и, зе́млю твою̀, возврати́лъ є҆сѝ плѣ́нъ і҆а́кѡвль."}, {"num": "в҃.", "text": "Ѡ҆ста́вилъ є҆сѝ беззакѡ́нїѧ люде́й твои́хъ, покры́лъ є҆сѝ всѧ̑ грѣхѝ и҆́хъ."}, {"num": "г҃.", "text": "Оу҆кроти́лъ є҆сѝ ве́сь гнѣ́въ тво́й, возврати́лсѧ є҆сѝ ѿ гнѣ́ва ꙗ҆́рости твоеѧ̀."}, {"num": "д҃.", "text": "Возвратѝ на́съ, бж҃е сп҃се́нїй на́шихъ, и҆ ѿвратѝ ꙗ҆́рость твою̀ ѿ на́съ."}, {"num": "є҃.", "text": "Е҆да̀ во вѣ́ки прогнѣ́ваешисѧ на ны̀; и҆лѝ простре́ши гнѣ́въ тво́й ѿ ро́да въ ро́дъ;"}, {"num": "ѕ҃.", "text": "Бж҃е, ты̀ ѡ҆бра́щьсѧ ѡ҆живи́ши ны̀, и҆ лю́дїе твоѝ возвеселѧ́тсѧ ѡ҆ тебѣ̀."}, {"num": "з҃.", "text": "Ꙗ҆вѝ на́мъ, гдⷭ҇и, млⷭ҇ть твою̀, и҆ сп҃се́нїе твоѐ да́ждь на́мъ."}, {"num": "и҃.", "text": "Оу҆слы́шꙋ, что̀ рече́тъ ѡ҆ мнѣ̀ гдⷭ҇ь бг҃ъ: ꙗ҆́кѡ рече́тъ ми́ръ на лю́ди своѧ̑, и҆ на прпⷣбныѧ своѧ̑, и҆ на ѡ҆браща́ющыѧ сердца̀ къ немꙋ̀."}, {"num": "ѳ҃.", "text": "Ѻ҆ба́че бли́з̾ боѧ́щихсѧ є҆гѡ̀ сп҃се́нїе є҆гѡ̀, всели́ти сла́вꙋ въ зе́млю на́шꙋ."}, {"num": "і҃.", "text": "Млⷭ҇ть и҆ и҆́стина срѣто́стѣсѧ, пра́вда и҆ ми́ръ ѡ҆блобыза́стасѧ:"}, {"num": "а҃і.", "text": "И҆́стина ѿ землѝ возсїѧ̀, и҆ пра́вда съ нб҃сѐ прини́че."}, {"num": "в҃і.", "text": "И҆́бо гдⷭ҇ь да́стъ бл҃гость, и҆ землѧ̀ на́ша да́стъ пло́дъ сво́й."}, {"num": "г҃і.", "text": "Пра́вда пред̾ ни́мъ пред̾и́детъ, и҆ положи́тъ въ пꙋ́ть стѡпы̀ своѧ̑. Сла́ва:"}]}, "85": {"number": 85, "cu_numeral": "п҃є", "title": "Ѱало́мъ п҃є (85)", "subtitle": "Мл҃тва дв҃дꙋ, п҃є.", "verses": [{"num": "а҃.", "text": "Приклонѝ, гдⷭ҇и, ᲂу҆́хо твоѐ, и҆ ᲂу҆слы́ши мѧ̀: ꙗ҆́кѡ ни́щъ и҆ ᲂу҆бо́гъ є҆́смь а҆́зъ."}, {"num": "в҃.", "text": "Сохранѝ дꙋ́шꙋ мою̀, ꙗ҆́кѡ прпⷣбенъ є҆́смь: сп҃сѝ раба̀ твоего̀, бж҃е мо́й, ᲂу҆пова́ющаго на тѧ̀."}, {"num": "г҃.", "text": "Поми́лꙋй мѧ̀, гдⷭ҇и, ꙗ҆́кѡ къ тебѣ̀ воззовꙋ̀ ве́сь де́нь."}, {"num": "д҃.", "text": "Возвеселѝ дꙋ́шꙋ раба̀ твоегѡ̀:"}, {"num": "є҃.", "text": "ꙗ҆́кѡ къ тебѣ̀ взѧ́хъ дꙋ́шꙋ мою̀. Ꙗ҆́кѡ ты̀, гдⷭ҇и, бл҃гъ и҆ кро́токъ, и҆ многомлⷭ҇тивъ всѣ̑мъ призыва́ющымъ тѧ̀."}, {"num": "ѕ҃.", "text": "Внꙋшѝ, гдⷭ҇и, моли́твꙋ мою̀, вонмѝ гла́сꙋ моле́нїѧ моегѡ̀."}, {"num": "з҃.", "text": "Въ де́нь ско́рби моеѧ̀ воззва́хъ къ тебѣ̀, ꙗ҆́кѡ ᲂу҆слы́шалъ мѧ̀ є҆сѝ."}, {"num": "и҃.", "text": "Нѣ́сть подо́бенъ тебѣ̀ въ бозѣ́хъ, гдⷭ҇и, и҆ нѣ́сть по дѣлѡ́мъ твои̑мъ."}, {"num": "ѳ҃.", "text": "Всѝ ꙗ҆зы́цы, є҆ли́ки сотвори́лъ є҆сѝ, прїи́дꙋтъ и҆ покло́нѧтсѧ пред̾ тобо́ю, гдⷭ҇и, и҆ просла́вѧтъ и҆́мѧ твоѐ."}, {"num": "і҃.", "text": "Ꙗ҆́кѡ ве́лїй є҆сѝ ты̀, и҆ творѧ́й чꙋдеса̀, ты̀ є҆сѝ бг҃ъ є҆ди́нъ."}, {"num": "а҃і.", "text": "Наста́ви мѧ̀, гдⷭ҇и, на пꙋ́ть тво́й, и҆ пойдꙋ̀ во и҆́стинѣ твое́й: да возвесели́тсѧ се́рдце моѐ боѧ́тисѧ и҆́мене твоегѡ̀."}, {"num": "в҃і.", "text": "И҆сповѣ́мсѧ тебѣ̀, гдⷭ҇и бж҃е мо́й, всѣ́мъ се́рдцемъ мои́мъ и҆ просла́влю и҆́мѧ твоѐ въ вѣ́къ:"}, {"num": "г҃і.", "text": "Ꙗ҆́кѡ млⷭ҇ть твоѧ̀ ве́лїѧ на мнѣ̀, и҆ и҆зба́вилъ є҆сѝ дꙋ́шꙋ мою̀ ѿ а҆́да преиспо́днѣйшагѡ."}, {"num": "д҃і.", "text": "Бж҃е, законопрестꙋ̑пницы воста́ша на мѧ̀,"}, {"num": "є҃і.", "text": "и҆ со́нмъ держа́вныхъ взыска́ша дꙋ́шꙋ мою̀, и҆ не предложи́ша тебѐ пред̾ собо́ю. И҆ ты̀, гдⷭ҇и бж҃е мо́й, ще́дрый и҆ млⷭ҇тивый, долготерпѣли́вый и҆ многомлⷭ҇тивый, и҆ и҆́стинный,"}, {"num": "ѕ҃і.", "text": "При́зри на мѧ̀, и҆ поми́лꙋй мѧ̀: да́ждь держа́вꙋ твою̀ ѻ҆́трокꙋ твоемꙋ̀, и҆ сп҃сѝ сы́на рабы̀ твоеѧ̀."}, {"num": "з҃і.", "text": "Сотворѝ со мно́ю зна́менїе во бл҃го: и҆ да ви́дѧтъ ненави́дѧщїи мѧ̀, и҆ постыдѧ́тсѧ, ꙗ҆́кѡ ты̀, гдⷭ҇и, помо́глъ ми,̀ и҆ ᲂу҆тѣ́шилъ мѧ̀ є҆сѝ. а҃ Сынѡ́мъ коре́ѡвымъ, ѱало́мъ пѣ́сни, п҃ѕ."}]}, "86": {"number": 86, "cu_numeral": "п҃ѕ", "title": "Ѱало́мъ п҃ѕ (86)", "subtitle": "а҃ Сынѡ́мъ коре́ѡвымъ, ѱало́мъ пѣ́сни, п҃ѕ.", "verses": [{"num": "а҃.", "text": "Ѡ҆снова̑нїѧ є҆гѡ̀ на гора́хъ ст҃ы́хъ: лю́битъ гдⷭ҇ь врата̀ сїѡ̑нѧ, па́че всѣ́хъ селе́нїй і҆а́кѡвлихъ."}, {"num": "в҃.", "text": "Пресла̑внаѧ глаго́лашасѧ ѡ҆ тебѣ̀, гра́де бж҃їй."}, {"num": "г҃.", "text": "Помѧнꙋ̀ раа́въ и҆ вавѷлѡ́на вѣ́дꙋщымъ мѧ̀: и҆ сѐ и҆ноплемє́нницы, и҆ тѵ́ръ, и҆ лю́дїе є҆ѳїо́пстїи, сі́и бы́ша та́мѡ."}, {"num": "д҃.", "text": "Ма́ти сїѡ́нъ рече́тъ: человѣ́къ и҆ человѣ́къ роди́сѧ въ не́мъ, и҆ то́й ѡ҆снова̀ и҆̀ вы́шнїй."}, {"num": "є҃.", "text": "Гдⷭ҇ь повѣ́сть въ писа́нїи люде́й и҆ кнѧзе́й, си́хъ бы́вшихъ въ не́мъ:"}, {"num": "ѕ҃.", "text": "Ꙗ҆́кѡ веселѧ́щихсѧ всѣ́хъ жили́ще въ тебѣ̀. а҃ Пѣ́снь ѱалма̀ сынѡ́мъ коре́ѡвымъ, въ коне́цъ, ѡ҆ маеле́ѳѣ є҆́же ѿвѣща́ти, ра́зꙋма є҆ма́нꙋ і҆и҃лтѧнинꙋ, п҃з."}]}, "87": {"number": 87, "cu_numeral": "п҃з", "title": "Ѱало́мъ п҃з (87)", "subtitle": "ѡ҆ маеле́ѳѣ є҆́же ѿвѣща́ти, ра́зꙋма є҆ма́нꙋ і҆и҃лтѧнинꙋ, п҃з.", "verses": [{"num": "а҃.", "text": "Гдⷭ҇и бж҃е сп҃се́нїѧ моегѡ̀, во днѝ воззва́хъ, и҆ въ нощѝ пред̾ тобо́ю:"}, {"num": "в҃.", "text": "Да вни́детъ пред̾ тѧ̀ мл҃тва моѧ̀, приклонѝ ᲂу҆́хо твоѐ къ моле́нїю моемꙋ̀,"}, {"num": "г҃.", "text": "Ꙗ҆́кѡ и҆спо́лнисѧ ѕѡ́лъ дꙋша̀ моѧ̀, и҆ живо́тъ мо́й а҆́дꙋ прибли́жисѧ."}, {"num": "д҃.", "text": "Привмѣне́нъ бы́хъ съ низходѧ́щими въ ро́въ, бы́хъ ꙗ҆́кѡ человѣ́къ без̾ по́мощи,"}, {"num": "є҃.", "text": "Въ ме́ртвыхъ свобо́дь: ꙗ҆́кѡ ꙗ҆́звеннїи спѧ́щїи во гро́бѣ, и҆́хже не помѧнꙋ́лъ є҆сѝ ктомꙋ̀, и҆ ті́и ѿ рꙋкѝ твоеѧ̀ ѿринове́ни бы́ша."}, {"num": "ѕ҃.", "text": "Положи́ша мѧ̀ въ ро́вѣ преиспо́днѣмъ, въ те́мныхъ и҆ сѣ́ни сме́ртнѣй:"}, {"num": "з҃.", "text": "На мнѣ̀ ᲂу҆тверди́сѧ ꙗ҆́рость твоѧ̀, и҆ всѧ̑ вѡ́лны твоѧ̑ наве́лъ є҆сѝ на мѧ̀."}, {"num": "и҃.", "text": "Оу҆да́лилъ є҆сѝ зна́емыхъ мои́хъ ѿ менѐ: положи́ша мѧ̀ ме́рзость себѣ̀: пре́данъ бы́хъ и҆ не и҆схожда́хъ."}, {"num": "ѳ҃.", "text": "Ѻ҆́чи моѝ и҆знемого́стѣ ѿ нищеты̀: воззва́хъ къ тебѣ̀ гдⷭ҇и ве́сь де́нь, воздѣ́хъ къ тебѣ̀ рꙋ́цѣ моѝ."}, {"num": "і҃.", "text": "Е҆да̀ ме́ртвыми твори́ши чꙋдеса̀; и҆лѝ вра́чеве воскресѧ́тъ, и҆ и҆сповѣ́дѧтсѧ тебѣ̀;"}, {"num": "а҃і.", "text": "Е҆да̀ повѣ́сть кто̀ во гро́бѣ млⷭ҇ть твою̀, и҆ и҆́стинꙋ твою̀ въ поги́бели;"}, {"num": "в҃і.", "text": "Е҆да̀ позна̑на бꙋ́дꙋтъ во тмѣ̀ чꙋдеса̀ твоѧ̑, и҆ пра́вда твоѧ̑ въ землѝ забве́ннѣй;"}, {"num": "г҃і.", "text": "И҆ а҆́зъ къ тебѣ̀, гдⷭ҇и, воззва́хъ, и҆ ᲂу҆́трѡ мл҃тва моѧ̀ предвари́тъ тѧ̀."}, {"num": "д҃і.", "text": "Вскꙋ́ю, гдⷭ҇и, ѿрѣ́еши дꙋ́шꙋ мою̀; ѿвраща́еши лицѐ твоѐ ѿ менѐ;"}, {"num": "є҃і.", "text": "Ни́щъ є҆́смь а҆́зъ, и҆ въ трꙋдѣ́хъ ѿ ю҆́ности моеѧ̀: возне́съ же сѧ смири́хсѧ и҆ и҆знемого́хъ."}, {"num": "ѕ҃і.", "text": "На мнѣ̀ преидо́ша гнѣ́ви твоѝ, ᲂу҆страшє́нїѧ твоѧ̑ возмꙋти́ша мѧ̀: Ѡ҆быдо́ша мѧ̀ ꙗ҆́кѡ"}, {"num": "з҃і.", "text": "вода̀, ве́сь де́нь ѡ҆держа́ша мѧ̀ вкꙋ́пѣ."}, {"num": "и҃і.", "text": "Оу҆да́лилъ є҆сѝ ѿ менѐ дрꙋ́га и҆ и҆́скреннѧго и҆ зна́емыхъ мои́хъ ѿ страсте́й. Сла́ва: а҃ Ра́зꙋма є҆ѳа́ма і҆и҃лтѧнина, ѱсало́м п҃и."}]}, "88": {"number": 88, "cu_numeral": "п҃и", "title": "Ѱало́мъ п҃и (88)", "subtitle": "а҃ Ра́зꙋма є҆ѳа́ма і҆и҃лтѧнина, ѱсало́м п҃и.", "verses": [{"num": "а҃.", "text": "Млⷭ҇ти твоѧ̑, гдⷭ҇и, во вѣ́къ воспою̀, въ ро́дъ и҆ ро́дъ возвѣщꙋ̀ и҆́стинꙋ твою̀ ᲂу҆сты̑ мои́ми."}, {"num": "в҃.", "text": "Занѐ ре́клъ є҆сѝ: въ вѣ́къ млⷭ҇ть сози́ждетсѧ: на нб҃сѣ́хъ ᲂу҆гото́витсѧ и҆́стина твоѧ̀."}, {"num": "г҃.", "text": "Завѣща́хъ завѣ́тъ и҆збра̑ннымъ мои̑мъ, клѧ́хсѧ дв҃дꙋ рабꙋ̀ моемꙋ̀:"}, {"num": "д҃.", "text": "До вѣ́ка ᲂу҆гото́ваю сѣ́мѧ твоѐ, и҆ сози́ждꙋ въ ро́дъ и҆ ро́дъ прⷭ҇то́лъ тво́й."}, {"num": "є҃.", "text": "И҆сповѣ́дѧтъ нб҃са̀ чꙋдеса̀ твоѧ̑, гдⷭ҇и, и҆́бо и҆́стинꙋ твою̀ въ цр҃кви ст҃ы́хъ."}, {"num": "ѕ҃.", "text": "Ꙗ҆́кѡ кто̀ во ѻ҆́блацѣхъ ᲂу҆равни́тсѧ гдⷭ҇еви: ᲂу҆подо́битсѧ гдⷭ҇еви въ сынѣ́хъ бж҃їихъ;"}, {"num": "з҃.", "text": "Бг҃ъ прославлѧ́емь въ совѣ́тѣ ст҃ы́хъ, ве́лїй и҆ стра́шенъ є҆́сть над̾ всѣ́ми ѻ҆кре́стными є҆гѡ̀."}, {"num": "и҃.", "text": "Гдⷭ҇и бж҃е си́лъ, кто̀ подо́бенъ тебѣ̀; си́ленъ ѳ҃ і҃ а҃і в҃і г҃і д҃і є҃і ѕ҃і з҃і и҃і ѳ҃і к҃ к҃а к҃в к҃г к҃д к҃є к҃ѕ к҃з к҃и к҃ѳ л҃ л҃а л҃в л҃г л҃д л҃є л҃ѕ л҃з л҃и л҃ѳ м҃ всѣ́ми ѻ҆кре́стными є҆гѡ̀. Гдⷭ҇и бж҃е си́лъ, кто̀ подо́бенъ тебѣ̀; си́ленъ є҆сѝ гдⷭ҇и, и҆ и҆́стина твоѧ̀ ѻ҆́крестъ тебѐ."}, {"num": "ѳ҃.", "text": "Ты̀ влⷣчествꙋеши держа́вою морско́ю: возмꙋще́нїе же вѡ́лнъ є҆гѡ̀ ты̀ ᲂу҆кроча́еши."}, {"num": "і҃.", "text": "Ты̀ смири́лъ є҆сѝ ꙗ҆́кѡ ꙗ҆́звена го́рдаго: мы́шцею си́лы твоеѧ̀ расточи́лъ є҆сѝ врагѝ твоѧ̑."}, {"num": "а҃і.", "text": "Твоѧ̑ сꙋ́ть нб҃са̀, и҆ твоѧ̀ є҆́сть землѧ̀: вселе́ннꙋю и҆ и҆сполне́нїе є҆ѧ̀ ты̀ ѡ҆снова́лъ є҆сѝ."}, {"num": "в҃і.", "text": "Сѣ́веръ и҆ мо́ре ты̀ созда́лъ є҆сѝ: ѳавѡ́ръ и҆ є҆рмѡ́нъ ѡ҆ и҆́мени"}, {"num": "г҃і.", "text": "твое́мъ возра́дꙋетасѧ. Твоѧ̀ мы́шца съ си́лою: да ᲂу҆крѣпи́тсѧ рꙋка̀ твоѧ̀, и҆ вознесе́тсѧ десни́ца твоѧ̀."}, {"num": "д҃і.", "text": "Пра́вда и҆ сꙋдьба̀ ᲂу҆гото́ванїе прⷭ҇то́ла твоегѡ̀: млⷭ҇ть и҆ и҆́стина пред̾и́детѣ пред̾"}, {"num": "є҃і.", "text": "лице́мъ твои́мъ. Бл҃же́ни лю́дїе вѣ́дꙋщїи воскликнове́нїе: гдⷭ҇и, во свѣ́тѣ лица̀ твоегѡ̀ по́йдꙋтъ,"}, {"num": "ѕ҃і.", "text": "И҆ ѡ҆ и҆́мени твое́мъ возра́дꙋютсѧ ве́сь де́нь, и҆ пра́вдою твое́ю вознесꙋ́тсѧ."}, {"num": "з҃і.", "text": "Ꙗ҆́кѡ похвала̀ си́лы и҆́хъ ты̀ є҆сѝ, и҆ во бл҃говоле́нїи твое́мъ вознесе́тсѧ ро́гъ на́шъ:"}, {"num": "и҃і.", "text": "Ꙗ҆́кѡ гдⷭ҇не є҆́сть застꙋпле́нїе, и҆ ст҃а́гѡ і҆и҃лева цр҃ѧ̀ на́шегѡ."}, {"num": "ѳ҃і.", "text": "Тогда̀ глаго́лалъ є҆сѝ въ видѣ́нїи сыновѡ́мъ твои̑мъ, и҆ ре́клъ є҆сѝ: положи́хъ по́мощь на си́льнаго, вознесо́хъ и҆збра́ннаго ѿ людѐй мои́хъ:"}, {"num": "к҃.", "text": "Ѡ҆брѣто́хъ дв҃да раба̀ моего̀, є҆ле́емъ ст҃ы́мъ мои́мъ пома́захъ є҆го̀."}, {"num": "к҃а.", "text": "И҆́бо рꙋка̀ моѧ̀ застꙋ́питъ є҆го̀, и҆ мы́шца моѧ̀ ᲂу҆крѣпи́тъ є҆го̀:"}, {"num": "к҃в.", "text": "Ничто́же ᲂу҆спѣ́етъ вра́гъ на него̀, и҆ сы́нъ беззако́нїѧ не приложи́тъ ѡ҆ѕло́бити є҆го̀."}, {"num": "к҃г.", "text": "И҆ ссѣкꙋ̀ ѿ лица̀ є҆гѡ̀ врагѝ є҆гѡ̀, и҆ ненави́дѧщыѧ є҆го̀ побѣждꙋ̀."}, {"num": "к҃д.", "text": "И҆ и҆́стина моѧ̀ и҆ млⷭ҇ть моѧ̀ съ ни́мъ, и҆ ѡ҆ и҆́мени мое́мъ вознесе́тсѧ ро́гъ є҆гѡ̀:"}, {"num": "к҃є.", "text": "И҆ положꙋ̀ на мо́ри рꙋ́кꙋ є҆гѡ̀, и҆ на рѣка́хъ десни́цꙋ є҆гѡ̀."}, {"num": "к҃ѕ.", "text": "То́й призове́тъ мѧ̀: ѻ҆ц҃ъ мо́й є҆сѝ ты̀, бг҃ъ мо́й и҆ застꙋ́пникъ сп҃се́нїѧ моегѡ̀."}, {"num": "к҃з.", "text": "И҆ а҆́зъ пе́рвенца положꙋ̀ є҆го̀, высока̀ па́че царе́й земны́хъ."}, {"num": "к҃и.", "text": "Въ вѣ́къ сохраню̀ є҆мꙋ̀ млⷭ҇ть мою̀, и҆ завѣ́тъ мо́й вѣ́ренъ є҆мꙋ̀:"}, {"num": "к҃ѳ.", "text": "И҆ положꙋ̀ въ вѣ́къ вѣ́ка сѣ́мѧ є҆гѡ̀, и҆ прⷭ҇то́лъ є҆гѡ̀ ꙗ҆́кѡ дні́е не́ба."}, {"num": "л҃.", "text": "А҆́ще ѡ҆ста́вѧтъ сы́нове є҆гѡ̀ зако́нъ мо́й, и҆ въ сꙋдьба́хъ мои́хъ не по́йдꙋтъ:"}, {"num": "л҃а.", "text": "А҆́ще ѡ҆правда̑нїѧ моѧ̑ ѡ҆сквернѧ́тъ, и҆ за́повѣдей мои́хъ не сохранѧ́тъ:"}, {"num": "л҃в.", "text": "Посѣщꙋ̀ жезло́мъ беззакѡ́нїѧ и҆́хъ, и҆ ра́нами непра̑вды и҆́хъ,"}, {"num": "л҃г.", "text": "Млⷭ҇ть же мою̀ не разорю̀ ѿ ни́хъ, ни превреждꙋ̀ во и҆́стинѣ мое́й:"}, {"num": "л҃д.", "text": "Нижѐ ѡ҆скверню̀ завѣ́та моегѡ̀, и҆ и҆сходѧ́щихъ ѿ ᲂу҆́стъ мои́хъ не ѿве́ргꙋсѧ."}, {"num": "л҃є.", "text": "Е҆ди́ною клѧ́хсѧ ѡ҆ ст҃ѣ́мъ мое́мъ, а҆́ще дв҃дꙋ солжꙋ̀;"}, {"num": "л҃ѕ.", "text": "Сѣ́мѧ є҆гѡ̀ во вѣ́къ пребꙋ́детъ, и҆ престо́лъ є҆гѡ̀ ꙗ҆́кѡ со́лнце предо мно́ю,"}, {"num": "л҃з.", "text": "И҆ ꙗ҆́кѡ лꙋна̀ соверше́на въ вѣ́къ: и҆ свидѣ́тель на нб҃сѝ вѣ́ренъ."}, {"num": "л҃и.", "text": "Ты́ же ѿри́нꙋлъ є҆сѝ, и҆ ᲂу҆ничижи́лъ, негодова́лъ є҆сѝ пома́заннаго твоего̀:"}, {"num": "л҃ѳ.", "text": "Разори́лъ є҆сѝ завѣ́тъ раба̀ твоегѡ̀, ѡ҆скверни́лъ є҆сѝ на землѝ ст҃ы́ню є҆гѡ̀."}, {"num": "м҃.", "text": "Разори́лъ є҆сѝ всѧ̑ ѡ҆пло́ты є҆гѡ̀, положи́лъ є҆сѝ твє́р м҃а м҃в м҃г м҃д м҃є м҃ѕ м҃з м҃и м҃ѳ н҃ н҃а н҃в н҃г ст҃ы́ню є҆гѡ̀. Разори́лъ є҆сѝ всѧ̑ ѡ҆пло́ты є҆гѡ̀, положи́лъ є҆сѝ твє́рдаѧ є҆гѡ̀ стра́хъ."}, {"num": "м҃а.", "text": "Расхища́хꙋ є҆го̀ всѝ мимоходѧ́щїи пꙋте́мъ, бы́сть поноше́нїе сосѣ́дѡмъ свои̑мъ."}, {"num": "м҃в.", "text": "Возвы́силъ є҆сѝ десни́цꙋ стꙋжа́ющихъ є҆мꙋ̀, возвесели́лъ є҆сѝ всѧ̑ врагѝ є҆гѡ̀:"}, {"num": "м҃г.", "text": "Ѿврати́лъ є҆сѝ по́мощь меча̀ є҆гѡ̀, и҆ не застꙋпи́лъ є҆сѝ є҆го̀ во бра́ни."}, {"num": "м҃д.", "text": "Разори́лъ є҆сѝ ѿ ѡ҆чище́нїѧ є҆гѡ̀, престо́лъ є҆гѡ̀ на зе́млю пове́рглъ є҆сѝ:"}, {"num": "м҃є.", "text": "Оу҆ма́лилъ є҆сѝ дни̑ вре́мене є҆гѡ̀, ѡ҆блїѧ́лъ є҆сѝ є҆го̀ стꙋдо́мъ."}, {"num": "м҃ѕ.", "text": "Доко́лѣ, гдⷭ҇и, ѿвраща́ешисѧ въ коне́цъ; разжже́тсѧ ꙗ҆́кѡ ѻ҆́гнь гнѣ́въ тво́й;"}, {"num": "м҃з.", "text": "Помѧнѝ, кі́й мо́й соста́въ: є҆да́ бо всꙋ́е созда́лъ є҆сѝ всѧ̑ сы́ны человѣ́чєскїѧ;"}, {"num": "м҃и.", "text": "Кто̀ є҆́сть человѣ́къ, и҆́же поживе́тъ и҆ не ᲂу҆́зритъ сме́рти, и҆зба́витъ дꙋ́шꙋ свою̀ и҆з̾ рꙋкѝ а҆́довы;"}, {"num": "м҃ѳ.", "text": "Гдѣ̀ сꙋ́ть млⷭ҇ти твоѧ̑ дрє́внїѧ, гдⷭ҇и, и҆́миже клѧ́лсѧ є҆сѝ дв҃дꙋ во и҆́стинѣ твое́й:"}, {"num": "н҃.", "text": "Помѧнѝ, гдⷭ҇и, поноше́нїе ра̑бъ твои́хъ, є҆́же ᲂу҆держа́хъ въ нѣ́дрѣ мое́мъ мно́гихъ ꙗ҆зы̑къ:"}, {"num": "н҃а.", "text": "И҆́мже поноси́ша вразѝ твоѝ, гдⷭ҇и, и҆́мже поноси́ша и҆змѣне́нїю хрїста̀ твоегѡ̀."}, {"num": "н҃в.", "text": "Бл҃гослове́нъ гдⷭ҇ь во вѣ́къ: бꙋ́ди, бꙋ́ди. Сла́ва: а҃ Мл҃тва мѡѷсе́а человѣ́ка бж҃їѧ, п҃ѳ."}]}, "89": {"number": 89, "cu_numeral": "п҃ѳ", "title": "Ѱало́мъ п҃ѳ (89)", "subtitle": "а҃ Мл҃тва мѡѷсе́а человѣ́ка бж҃їѧ, п҃ѳ.", "verses": [{"num": "а҃.", "text": "Гдⷭ҇и, прибѣ́жище бы́лъ є҆сѝ на́мъ въ ро́дъ и҆ ро́дъ:"}, {"num": "в҃.", "text": "Пре́жде да́же гора́мъ не бы́ти и҆ созда́тисѧ землѝ и҆ вселе́ннѣй и҆ ѿ вѣ́ка и҆ до вѣ́ка ты̀ є҆сѝ."}, {"num": "г҃.", "text": "Не ѿвратѝ человѣ́ка во смире́нїе, и҆ ре́клъ є҆сѝ: ѡ҆брати́тесѧ сы́нове человѣ́честїи."}, {"num": "д҃.", "text": "Ꙗ҆́кѡ ты́сѧща лѣ́тъ пред̾ ѻ҆чи́ма твои́ма, гдⷭ҇и, ꙗ҆́кѡ де́нь вчера́шнїй, и҆́же мимои́де, и҆ стра́жа нощна́ѧ."}, {"num": "є҃.", "text": "Оу҆ничижє́нїѧ и҆́хъ лѣ̑та бꙋ́дꙋтъ: ᲂу҆́трѡ ꙗ҆́кѡ трава̀ мимои́детъ, ᲂу҆́трѡ процвѣте́тъ и҆ пре́йдетъ: на ве́черъ ѿпаде́тъ, ѡ҆жестѣ́етъ и҆ и҆́зсхнетъ."}, {"num": "ѕ҃.", "text": "Ꙗ҆́кѡ и҆зчезо́хомъ гнѣ́вомъ твои́мъ, и҆ ꙗ҆́ростїю твое́ю смꙋти́хомсѧ."}, {"num": "з҃.", "text": "Положи́лъ є҆сѝ беззакѡ́нїѧ на̑ша пред̾ тобо́ю: вѣ́къ на́шъ въ просвѣще́нїе лица̀ твоегѡ̀."}, {"num": "и҃.", "text": "Ꙗ҆́кѡ всѝ дні́е на́ши ѡ҆скꙋдѣ́ша, и҆ гнѣ́вомъ твои́мъ и҆зчезо́хомъ:"}, {"num": "ѳ҃.", "text": "Лѣ̑та на̑ша ꙗ҆́кѡ паꙋчи́на поꙋча́хꙋсѧ. дні́е лѣ́тъ на́шихъ въ ни́хже се́дмьдесѧтъ лѣ́тъ, а҆́ще же въ си́лахъ ѻ҆́смьдесѧтъ лѣ́тъ, и҆ мно́жае и҆́хъ трꙋ́дъ и҆ болѣ́знь: ꙗ҆́кѡ прїи́де кро́тость на ны̀, и҆ нака́жемсѧ."}, {"num": "і҃.", "text": "Кто̀ вѣ́сть держа́вꙋ гнѣ́ва твоегѡ̀; и҆ ѿ стра́ха твоегѡ̀ ꙗ҆́рость твою̀ и҆счестѝ;"}, {"num": "а҃і.", "text": "Десни́цꙋ твою̀ та́кѡ скажи́ ми, и҆ ѡ҆кова̑нныѧ се́рдцемъ въ мꙋ́дрости."}, {"num": "в҃і.", "text": "Ѡ҆брати́сѧ, гдⷭ҇и, доко́лѣ; и҆ ᲂу҆моле́нъ бꙋ́ди на рабы̑ твоѧ̑."}, {"num": "г҃і.", "text": "И҆спо́лнихомсѧ заꙋ́тра млⷭ҇ти твоеѧ̀, гдⷭ҇и, и҆ возра́довахомсѧ: и҆ возвесели́хомсѧ:"}, {"num": "д҃і.", "text": "Во всѧ̑ дни̑ є҃і ѕ҃і з҃і млⷭ҇ти твоеѧ̀, гдⷭ҇и, и҆ возра́довахомсѧ: и҆ возвесели́хомсѧ: Во всѧ̑ дни̑ на́шѧ возвесели́хомсѧ, за дни̑, въ нѧ́же смири́лъ ны̀ є҆сѝ, лѣ̑та въ нѧ́же ви́дѣхомъ ѕла̑ѧ."}, {"num": "є҃і.", "text": "И҆ при́зри на рабы̑ твоѧ̑, и҆ на дѣла̀ твоѧ̑, и҆ наста́ви сы́ны и҆́хъ."}, {"num": "ѕ҃і.", "text": "И҆ бꙋ́ди свѣ́тлость гдⷭ҇а бг҃а на́шегѡ на на́съ, и҆ дѣла̀ рꙋ́къ на́шихъ и҆спра́ви на на́съ, и҆ дѣ́ло рꙋ́къ на́шихъ и҆спра́ви."}]}, "90": {"number": 90, "cu_numeral": "ч҃", "title": "Ѱало́мъ ч҃ (90)", "subtitle": "Хвала̀ пѣ́сни дв҃довы, не надпи́санъ ᲂу҆ є҆врє́й, ч҃.", "verses": [{"num": "а҃.", "text": "Живы́й въ по́мощи вы́шнѧгѡ, въ кро́вѣ бг҃а нбⷭ҇нагѡ водвори́тсѧ."}, {"num": "в҃.", "text": "Рече́тъ гдⷭ҇еви: застꙋ́пникъ мо́й є҆сѝ и҆ прибѣ́жище моѐ, бг҃ъ мо́й, и҆ ᲂу҆пова́ю на него ̀."}, {"num": "г҃.", "text": "Ꙗ҆́кѡ то́й и҆зба́витъ т ѧ̀ ѿ сѣ́ти ло́вчи, и҆ ѿ словесѐ мѧте́жна:"}, {"num": "д҃.", "text": "Плещма̀ свои́ма ѡ҆сѣни́тъ тѧ̀, и҆ под̾ крилѣ̑ є҆гѡ̀ надѣ́ешисѧ: ѻ҆рꙋ́жїемъ ѡ҆бы́детъ тѧ̀ и҆́стина є҆гѡ̀."}, {"num": "є҃.", "text": "Не ᲂу҆бои́шисѧ ѿ стра́ха нощна́гѡ, ѿ стрѣлы̀ летѧ́щїѧ во днѝ,"}, {"num": "ѕ҃.", "text": "Ѿ ве́щи во тьмѣ̀ преходѧ́щїѧ, ѿ срѧ́ща и҆ бѣ́са полꙋ́деннагѡ."}, {"num": "з҃.", "text": "Паде́тъ ѿ"}, {"num": "и҃.", "text": "страны ̀ твоеѧ̀ ты́сѧща, и҆ тма̀ ѡ҆деснꙋ́ю тебѐ, къ тебѣ́ же не прибли́житсѧ: Ѻ҆ба́че ѻ҆чи́ма твои́ма смо́триши и ҆ воздаѧ́нїе грѣ́шникѡвъ ᲂу҆́зриши."}, {"num": "ѳ҃.", "text": "Ꙗ҆́кѡ ты̀, гдⷭ҇и, ᲂу҆пова́нїе моѐ: вы́шнѧго положи́лъ є҆сѝ прибѣ́жище твоѐ."}, {"num": "і҃.", "text": "Не прїи́детъ къ тебѣ̀ ѕло̀: и҆ ра́на не прибли́житсѧ тѣлесѝ твоемꙋ̀."}, {"num": "а҃і.", "text": "Ꙗ҆́кѡ а҆́гг҃лѡмъ свои̑мъ заповѣ́сть ѡ҆ тебѣ̀ сохрани́ти тѧ̀ во всѣ́хъ пꙋте́хъ твои́хъ."}, {"num": "в҃і.", "text": "На рꙋка́хъ во́змꙋтъ тѧ̀, да не когда̀ преткне́ши ѡ҆ ка́мень но́гꙋ твою̀:"}, {"num": "г҃і.", "text": "На а҆́спїда и҆ васїлі́ска настꙋ́пиши, и҆ попере́ши льва̀ и҆ ѕмі́ѧ."}, {"num": "д҃і.", "text": "Ꙗ҆́кѡ на мѧ̀ ᲂу҆пова̀, и҆ и҆зба́влю и҆̀: покры́ю и҆̀, ꙗ҆́кѡ позна̀ и҆́мѧ моѐ."}, {"num": "є҃і.", "text": "Воззове́тъ ко мнѣ̀, и҆ ᲂу҆слы́шꙋ є҆го̀: съ ни́мъ є҆́смь въ ско́рби , и҆змꙋ̀ є҆го̀, и҆ просла́влю є҆го̀:"}, {"num": "ѕ҃і.", "text": "Долгото́ю дне́й и҆спо́лню є҆гоⷱ҇̀ и҆ ꙗ҆влю̀ є҆мꙋ̀ сп҃се́нїе моѐ. Сла́ва:"}]}, "91": {"number": 91, "cu_numeral": "ч҃а", "title": "Ѱало́мъ ч҃а (91)", "subtitle": "а҃ Ѱало́мъ пѣ́сни въ де́нь сꙋббѡ́тный, ч҃а.", "verses": [{"num": "а҃.", "text": "Бл҃го є҆́сть и҆сповѣ́датисѧ гдⷭ҇еви, и҆ пѣ́ти и҆́мени твоемꙋ̀, вы́шнїй:"}, {"num": "в҃.", "text": "Возвѣща́ти заꙋ́тра млⷭ҇ть твою̀, и҆ и҆́стинꙋ твою̀ на всѧ́кꙋ но́щь,"}, {"num": "г҃.", "text": "Въ десѧтострꙋ́ннѣмъ ѱалти́ри съ пѣ́снїю въ гꙋ́слехъ."}, {"num": "д҃.", "text": "Ꙗ҆́кѡ возвесели́лъ мѧ̀ є҆сѝ, гдⷭ҇и, въ творе́нїи твое́мъ, и҆ въ дѣ́лѣхъ рꙋкꙋ̀ твоє́ю возра́дꙋюсѧ."}, {"num": "є҃.", "text": "Ꙗ҆́кѡ возвели́чишасѧ дѣла̀ твоѧ̑, гдⷭ҇и, ѕѣлѡ̀ ᲂу҆глꙋби́шасѧ помышлє́нїѧ твоѧ̑."}, {"num": "ѕ҃.", "text": "Мꙋ́жъ безꙋ́менъ не позна́етъ, и҆ неразꙋми́въ не разꙋмѣ́етъ си́хъ."}, {"num": "з҃.", "text": "Внегда̀ прозѧбо́ща грѣ̑шницы ꙗ҆́кѡ трава̀, и҆ пронико́ша всѝ дѣ́лающїи беззако́нїе, ꙗ҆́кѡ да потребѧ́тсѧ въ вѣ́къ вѣ́ка:"}, {"num": "и҃.", "text": "Ты́ же вы́шнїй во вѣ́къ гдⷭ҇и."}, {"num": "ѳ҃.", "text": "Ꙗ҆́кѡ сѐ вразѝ твоѝ, гдⷭ҇и, ꙗ҆́кѡ сѐ вразѝ твоѝ поги́бнꙋтъ, и҆ разы́дꙋтсѧ всѝ дѣ́лающїи беззако́нїе."}, {"num": "і҃.", "text": "И҆ вознесе́тсѧ ꙗ҆́кѡ є҆диноро́га ро́гъ мо́й, и҆ ста́рость моѧ̀ въ є҆ле́и масти́тѣ,"}, {"num": "а҃і.", "text": "И҆ воззрѣ̀ ѻ҆́ко моѐ на врагѝ моѧ̑, и҆ востаю́щыѧ на мѧ̀ лꙋка́внꙋющыѧ ᲂу҆слы́шитъ ᲂу҆́хо моѐ."}, {"num": "в҃і.", "text": "Првⷣникъ ꙗ҆́кѡ фі́нїѯъ процвѣте́тъ, ꙗ҆́кѡ ке́дръ, и҆́же въ лїва́нѣ, ᲂу҆мно́житсѧ."}, {"num": "г҃і.", "text": "Насажде́ни въ домꙋ̀ гдⷭ҇ни, во дво́рѣхъ бг҃а на́шегѡ процвѣтꙋ́тъ;"}, {"num": "д҃і.", "text": "Е҆щѐ ᲂу҆мно́жатсѧ въ ста́рости масти́тѣ, и҆ бл҃гопрїе́млюще бꙋ́дꙋтъ."}, {"num": "є҃і.", "text": "Да возвѣстѧ́тъ, ꙗ҆́кѡ пра́въ гдⷭ҇ь бг҃ъ на́шъ, и҆ нѣ́сть непра́вды въ не́мъ. Въ де́нь предсꙋббѡ́тный, внегда̀ насели́сѧ землѧ̀, хвала̀ пѣ́сни дв҃дꙋ, ч҃в."}]}, "92": {"number": 92, "cu_numeral": "ч҃в", "title": "Ѱало́мъ ч҃в (92)", "subtitle": "Въ де́нь предсꙋббѡ́тный, внегда̀ насели́сѧ землѧ̀, хвала̀ пѣ́сни дв҃дꙋ, ч҃в.", "verses": [{"num": "а҃.", "text": "Гдⷭ҇ь воцр҃и́сѧ, въ лѣ́потꙋ ѡ҆блече́сѧ, ѡ҆блече́сѧ гдⷭ҇ь въ си́лꙋ, и҆ препоѧ́сасѧ: и҆́бо ᲂу҆твердѝ вселе́ннꙋю, ꙗ҆́же не подви́житсѧ."}, {"num": "в҃.", "text": "Гото́въ прⷭ҇то́лъ тво́й ѿто́лѣ: ѿ вѣ́ка ты̀ є҆сѝ."}, {"num": "г҃.", "text": "Воздвиго́ша рѣ́ки, гдⷭ҇и, воздвиго́ша рѣ́ки гла́сы своѧ̑:"}, {"num": "д҃.", "text": "Во́змꙋтъ рѣ́ки сотрє́нїѧ своѧ̑, ѿ гласѡ́въ во́дъ мно́гихъ."}, {"num": "є҃.", "text": "ди̑вны высѡты̀ мѡрскі̑ѧ: ди́венъ въ высо́кихъ гдⷭ҇ь."}, {"num": "ѕ҃.", "text": "Свидѣ̑нїѧ твоѧ̑ ᲂу҆вѣ́ришасѧ ѕѣлѡ̀. до́мꙋ твоемꙋ̀ подоба́етъ ст҃ы́нѧ, гдⷭ҇и, въ долготꙋ̀ дні́й."}]}, "93": {"number": 93, "cu_numeral": "ч҃г", "title": "Ѱало́мъ ч҃г (93)", "subtitle": "Ѱало́мъ дв҃дꙋ, въ четве́ртый сꙋббѡ́ты, ч҃г.", "verses": [{"num": "а҃.", "text": "Бг҃ъ ѿмще́нїй гдⷭ҇ь, бг҃ъ ѿмще́нїй не ѡ҆бинꙋ́лсѧ є҆́сть."}, {"num": "в҃.", "text": "Вознеси́сѧ, сꙋдѧ́й землѝ, возда́ждь воздаѧ́нїе гѡ́рдымъ."}, {"num": "г҃.", "text": "Доко́лѣ грѣ̑шницы, гдⷭ҇и, доко́лѣ грѣ̑шницы восхва́лѧтсѧ;"}, {"num": "д҃.", "text": "Провѣща́ютъ и҆ возглаго́лютъ непра́вдꙋ, возглаго́лютъ всѝ дѣ́лающїи беззако́нїе;"}, {"num": "є҃.", "text": "Лю́ди твоѧ̑, гдⷭ҇и, смири́ша, и҆ достоѧ́нїе твоѐ ѡ҆ѕло́биша."}, {"num": "ѕ҃.", "text": "Вдови́цꙋ и҆ си́ра ᲂу҆мори́ша, и҆ ѕ҃ з҃ и҃ ѳ҃ і҃ а҃і в҃і г҃і д҃і є҃і ѕ҃і з҃і и҃і ѳ҃і к҃ к҃а к҃в к҃г смири́ша, и҆ достоѧ́нїе твоѐ ѡ҆ѕло́биша. Вдови́цꙋ и҆ си́ра ᲂу҆мори́ша, и҆ прише́лца ᲂу҆би́ша."}, {"num": "з҃.", "text": "И҆ рѣ́ша: не ᲂу҆́зритъ гдⷭ҇ь, нижѐ ᲂу҆разꙋмѣ́етъ бг҃ъ і҆а́кѡвль."}, {"num": "и҃.", "text": "Разꙋмѣ́йте же безꙋ́мнїи въ лю́дехъ, и҆ бꙋ́їи нѣ́когда ᲂу҆мꙋдри́тесѧ:"}, {"num": "ѳ҃.", "text": "Насажде́й ᲂу҆́хо, не слы́шитъ ли; и҆лѝ созда́вый ѻ҆́ко, не сматрѧ́етъ ли;"}, {"num": "і҃.", "text": "Наказꙋ́ѧй ꙗ҆зы́ки, не ѡ҆бличи́тъ ли, ᲂу҆ча́й человѣ́ка ра́зꙋмꙋ;"}, {"num": "а҃і.", "text": "Гдⷭ҇ь вѣ́сть"}, {"num": "в҃і.", "text": "помышлє́нїѧ человѣ́чєскаѧ, ꙗ҆́кѡ сꙋ́ть сꙋ́єтна. Бл҃же́нъ человѣ́къ, є҆го́же а҆́ще нака́жеши,"}, {"num": "г҃і.", "text": "гдⷭ҇и, и҆ ѿ зако́на твоегѡ̀ наꙋчи́ши є҆го̀: Оу҆кроти́ти є҆го̀ ѿ дне́й лю́тыхъ, до́ндеже и҆зры́етсѧ грѣ́шномꙋ ꙗ҆́ма."}, {"num": "д҃і.", "text": "Ꙗ҆́кѡ не ѿри́нетъ гдⷭ҇ь люде́й свои́хъ, и҆ достоѧ́нїѧ своегѡ̀ не ѡ҆ста́витъ:"}, {"num": "є҃і.", "text": "До́ндеже пра́вда ѡ҆брати́тсѧ на сꙋ́дъ, и҆ держа́щїисѧ є҆ѧ̀ всѝ пра́вїи срⷣцемъ."}, {"num": "ѕ҃і.", "text": "Кто̀ воста́нетъ мѝ на лꙋка́внꙋющыѧ; и҆лѝ кто̀ спредста́нетъ мѝ на дѣ́лающыѧ беззако́нїе;"}, {"num": "з҃і.", "text": "А҆́ще не гдⷭ҇ь помо́глъ бы мѝ, вма́лѣ всели́ласѧ бы во а҆́дъ дꙋша̀ моѧ̀."}, {"num": "и҃і.", "text": "А҆́ще глаго́лахъ: подви́жесѧ нога̀ моѧ̀, млⷭ҇ть твоѧ̀, гдⷭ҇и, помога́ше мѝ:"}, {"num": "ѳ҃і.", "text": "По мно́жествꙋ болѣ́зней мои́хъ въ се́рдцѣ мое́мъ, ᲂу҆тѣшє́нїѧ твоѧ̑ возвесели́ша дꙋ́шꙋ мою̀."}, {"num": "к҃.", "text": "Да не пребꙋ́детъ тебѣ̀ престо́лъ беззако́нїѧ, созида́ѧй трꙋ́дъ на повелѣ́нїе."}, {"num": "к҃а.", "text": "Оу҆ловѧ́тъ на дꙋ́шꙋ првⷣничꙋ,"}, {"num": "к҃в.", "text": "и҆ кро́вь непови́ннꙋю ѡ҆сꙋ́дѧтъ. И҆ бы́сть мнѣ̀ гдⷭ҇ь въ прибѣ́жище, и҆ бг҃ъ мо́й въ по́мощь ᲂу҆пова́нїѧ моегѡ̀."}, {"num": "к҃г.", "text": "И҆ возда́стъ и҆̀мъ гдⷭ҇ь беззако́нїе и҆́хъ, и҆ по лꙋка́вствїю и҆́хъ погꙋби́тъ ѧ҆̀ гдⷭ҇ь бг҃ъ. Сла́ва:"}]}, "94": {"number": 94, "cu_numeral": "ч҃д", "title": "Ѱало́мъ ч҃д (94)", "subtitle": "Хвала̀ пѣ́сни дв҃дꙋ, не надпи́санъ ᲂу҆ є҆врє́й, ч҃д.", "verses": [{"num": "а҃.", "text": "Прїиди́те возра́дꙋемсѧ гдⷭ҇еви, воскли́кнемъ бг҃ꙋ сп҃си́телю на́шемꙋ:"}, {"num": "в҃.", "text": "Предвари́мъ лицѐ є҆гѡ̀ во и҆сповѣ́данїи, и҆ во ѱалмѣ́хъ воскли́кнемъ є҆мꙋ̀:"}, {"num": "г҃.", "text": "Ꙗ҆́кѡ бг҃ъ ве́лїй гдⷭ҇ь, и҆ цр҃ь ве́лїй по все́й землѝ."}, {"num": "д҃.", "text": "Ꙗ҆́кѡ въ рꙋцѣ̀ є҆гѡ̀ всѝ концы̑ землѝ, и҆ высѡты̀ го́ръ тогѡ̀ сꙋ́ть."}, {"num": "є҃.", "text": "Ꙗ҆́кѡ тогѡ̀ є҆́сть мо́ре, и҆ то́й сотворѝ є҆̀, и҆ сꙋ́шꙋ рꙋ́цѣ є҆гѡ̀ созда́стѣ."}, {"num": "ѕ҃.", "text": "Прїиди́те поклони́мсѧ и҆ припаде́мъ є҆мꙋ̀, и҆ воспла́чемсѧ пред̾ гдⷭ҇емъ сотво́ршимъ на́съ:"}, {"num": "з҃.", "text": "Ꙗ҆́кѡ то́й є҆́сть бг҃ъ на́шъ: и҆ мы̀ лю́дїе па́жити є҆гѡ,̀ и҆ ѻ҆́вцы рꙋкѝ є҆гѡ̀. дне́сь а҆́ще гла́съ є҆гѡ̀ ᲂу҆слы́шите,"}, {"num": "и҃.", "text": "Не ѡ҆жесточи́те серде́цъ ва́шихъ, ꙗ҆́кѡ"}, {"num": "ѳ҃.", "text": "въ прогнѣ́ванїи, по днѝ и҆скꙋше́нїѧ въ пꙋсты́ни: Во́ньже и҆скꙋси́ша мѧ̀ ѻ҆тцы̀ ва́ши, и҆скꙋси́ша мѧ̀, и҆ ви́дѣша дѣла̀ моѧ̑."}, {"num": "і҃.", "text": "Четы́редесѧть лѣ́тъ негодова́хъ ро́да тогѡ̀, и҆ рѣ́хъ: і҃ а҃і дѣла̀ моѧ̑. Четы́редесѧть лѣ́тъ негодова́хъ ро́да тогѡ̀, и҆ рѣ́хъ: при́снѡ заблꙋжда́ютъ се́рдцемъ, ті́и же не позна́ша пꙋте́й мои́хъ:"}, {"num": "а҃і.", "text": "Ꙗ҆́кѡ клѧ́хсѧ во гнѣ́вѣ мое́мъ, а҆́ще вни́дꙋтъ въ поко́й мо́й."}]}, "95": {"number": 95, "cu_numeral": "ч҃є", "title": "Ѱало́мъ ч҃є (95)", "subtitle": "не надпи́санъ ᲂу҆ є҆врє́й, ч҃є.", "verses": [{"num": "а҃.", "text": "Воспо́йте гдⷭ҇еви пѣ́снь но́вꙋ,"}, {"num": "в҃.", "text": "воспо́йте гдⷭ҇еви всѧ̀ землѧ̀: Воспо́йте гдⷭ҇еви, бл҃гослови́те и҆́мѧ є҆гѡ̀: бл҃говѣсти́те де́нь ѿ днѐ сп҃се́нїе є҆гѡ̀:"}, {"num": "г҃.", "text": "Возвѣсти́те во ꙗ҆зы́цѣхъ сла́вꙋ є҆гѡ̀, во всѣ́хъ лю́дехъ чꙋдеса̀ є҆гѡ̀."}, {"num": "д҃.", "text": "Ꙗ҆́кѡ ве́лїй гдⷭ҇ь и҆ хва́ленъ ѕѣлѡ̀, стра́шенъ є҆́сть над̾ всѣ́ми бѡ́ги."}, {"num": "є҃.", "text": "Ꙗ҆́кѡ всѝ бо́зи ꙗ҆зы̑къ бѣ́сове: гдⷭ҇ь же небеса̀ сотворѝ."}, {"num": "ѕ҃.", "text": "И҆сповѣ́данїе и҆ красота̀ пред̾ ни́мъ, ст҃ы́нѧ и҆ великолѣ́пїе во ст҃и́лѣ є҆гѡ̀."}, {"num": "з҃.", "text": "Принеси́те гдⷭ҇еви, ѻ҆те́чєствїѧ ꙗ҆зы̑къ,"}, {"num": "и҃.", "text": "принеси́те гдⷭ҇еви сла́вꙋ и҆ че́сть. Принеси́те гдⷭ҇еви сла́вꙋ и҆́мени є҆гѡ̀: возми́те жє́ртвы, и҆ входи́те во дворы̀ є҆гѡ̀:"}, {"num": "ѳ҃.", "text": "Поклони́тесѧ гдⷭ҇еви во дворѣ̀ ст҃ѣ́мъ є҆гѡ̀: да подви́житсѧ ѿ лица̀ є҆гѡ̀ всѧ̀ землѧ̀."}, {"num": "і҃.", "text": "Рцы́те во ꙗ҆зы́цѣхъ, ꙗ҆́кѡ гдⷭ҇ь воцр҃и́сѧ: и҆́бо и҆спра́ви вселе́ннꙋю, ꙗ҆́же не подви́житсѧ: сꙋ́дитъ лю́демъ пра́востїю."}, {"num": "а҃і.", "text": "Да возвеселѧ́тсѧ нб҃са̀, и҆ ра́дꙋетсѧ землѧ̀: да подви́житсѧ мо́ре, и҆ и҆сполне́нїе є҆гѡ̀:"}, {"num": "в҃і.", "text": "Возра́дꙋютсѧ полѧ̀, и҆ всѧ̑ ꙗ҆̀же на ни́хъ: тогда̀ возра́дꙋютсѧ всѧ̑ древа̀ дꙋбра̑внаѧ"}, {"num": "г҃і.", "text": "Ѿ лица̀ гдⷭ҇нѧ, ꙗ҆́кѡ грѧде́тъ, ꙗ҆́кѡ грѧде́тъ сꙋди́ти землѝ: сꙋди́ти вселе́ннѣй въ пра́вдꙋ, и҆ лю́демъ и҆́стиною свое́ю."}]}, "96": {"number": 96, "cu_numeral": "ч҃ѕ", "title": "Ѱало́мъ ч҃ѕ (96)", "subtitle": "не надпи́санъ ᲂу҆ є҆врє́й, ч҃ѕ.", "verses": [{"num": "а҃.", "text": "Гдⷭ҇ь воцр҃и́сѧ, да ра́дꙋетсѧ землѧ̀, да веселѧ́тсѧ ѻ҆́строви мно́зи."}, {"num": "в҃.", "text": "Ѻ҆́блакъ и҆ мра́къ ѻ҆́крестъ є҆гѡ̀: пра́вда и҆ сꙋдьба̀ и҆справле́нїе прⷭ҇то́ла є҆гѡ̀."}, {"num": "г҃.", "text": "Ѻ҆́гнь пред̾ ни́мъ пред̾и́детъ, и҆ попали́тъ ѻ҆́крестъ врагѝ є҆гѡ̀."}, {"num": "д҃.", "text": "Ѡ҆свѣти́ша мѡ́лнїѧ є҆гѡ̀ вселе́ннꙋю, ви́дѣ, и҆ подви́жесѧ землѧ̀."}, {"num": "є҃.", "text": "Го́ры ꙗ҆́кѡ во́скъ раста́ѧша ѿ лица̀ гдⷭ҇нѧ, ѿ лица̀ гдⷭ҇а всеѧ̀ землѝ."}, {"num": "ѕ҃.", "text": "Возвѣсти́ша нб҃са̀ пра́вдꙋ є҆гѡ̀: и҆ ви́дѣша всѝ лю́дїе сла́вꙋ є҆гѡ̀."}, {"num": "з҃.", "text": "Да постыдѧ́тсѧ всѝ кла́нѧющїисѧ и҆стꙋка̑ннымъ, хва́лѧщїисѧ ѡ҆ і҆́дѡлѣхъ свои́хъ: поклони́тесѧ є҆мꙋ̀ всѝ а҆́гг҃ли є҆гѡ̀."}, {"num": "и҃.", "text": "Слы́ша и҆ возвесели́сѧ сїѡ́нъ, и҆ возра́довашасѧ дщє́ри і҆ꙋдє́йскїѧ, сꙋде́бъ ра́ди твои́хъ гдⷭ҇и:"}, {"num": "ѳ҃.", "text": "Ꙗ҆́кѡ ты̀ гдⷭ҇ь вы́шнїй над̾ все́ю земле́ю, ѕѣлѡ̀ превозне́слсѧ є҆сѝ ѳ҃ і҃ а҃і в҃і гдⷭ҇и: Ꙗ҆́кѡ ты̀ гдⷭ҇ь вы́шнїй над̾ все́ю земле́ю, ѕѣлѡ̀ превозне́слсѧ є҆сѝ над̾ всѣ́ми бѡ́ги."}, {"num": "і҃.", "text": "Лю́бѧщїи гдⷭ҇а, ненави́дите ѕла̑ѧ: храни́тъ гдⷭ҇ь дꙋ́шы прпⷣбныхъ свои́хъ, и҆з̾ рꙋкѝ грѣ́шничи и҆зба́витъ ѧ҆̀."}, {"num": "а҃і.", "text": "Свѣ́тъ возсїѧ̀ првⷣникꙋ, и҆ пра̑вымъ срⷣцемъ весе́лїе."}, {"num": "в҃і.", "text": "Весели́тесѧ првⷣнїи, ѡ҆ гдⷭ҇ѣ, и҆ и҆сповѣ́дайте па́мѧть ст҃ы́ни є҆гѡ̀. Сла́ва:"}]}, "97": {"number": 97, "cu_numeral": "ч҃з", "title": "Ѱало́мъ ч҃з (97)", "subtitle": "Ѱало́мъ дв҃дꙋ, ч҃з.", "verses": [{"num": "а҃.", "text": "Воспо́йте гдⷭ҇еви пѣ́снь но́вꙋ, ꙗ҆́кѡ ди̑вна сотворѝ гдⷭ҇ь: сп҃сѐ є҆го̀ десни́ца є҆гѡ̀, и҆ мы́шца ст҃а́ѧ є҆гѡ̀."}, {"num": "в҃.", "text": "Сказа̀ гдⷭ҇ь сп҃се́нїе своѐ, пред̾ ꙗ҆зы̑ки ѿкры̀ пра́вдꙋ свою̀."}, {"num": "г҃.", "text": "Помѧнꙋ̀ млⷭ҇ть свою̀ і҆а́кѡвꙋ, и҆ и҆́стинꙋ свою̀ до́мꙋ і҆и҃левꙋ: ви́дѣша всѝ концы̑ землѝ сп҃се́нїе бг҃а на́шегѡ."}, {"num": "д҃.", "text": "Воскли́кните бг҃ови, всѧ̀ землѧ̀, воспо́йте, и҆ ра́дꙋйтесѧ, и҆ по́йте."}, {"num": "є҃.", "text": "По́йте гдⷭ҇еви въ гꙋ́слехъ, въ гꙋ́слехъ и҆ гла́сѣ ѱало́мстѣ,"}, {"num": "ѕ҃.", "text": "Въ трꙋба́хъ ко́ваныхъ, и҆ гла́сомъ трꙋбы̀ ро́жаны: вострꙋби́те пред̾ цр҃е́мъ гдⷭ҇емъ."}, {"num": "з҃.", "text": "Да подви́житсѧ мо́ре и҆ и҆сполне́нїе є҆гѡ̀, вселе́ннаѧ и҆ всѝ живꙋ́щїи"}, {"num": "и҃.", "text": "на не́й. Рѣ́кивоспле́щꙋтърꙋко́ю вкꙋ́пѣ, го́рывозра́дꙋютсѧ"}, {"num": "ѳ҃.", "text": "Ѿ лица̀ гдⷭ҇нѧ, ꙗ҆́кѡ грѧде́тъ, ꙗ҆́кѡ и҆́детъ сꙋди́ти землѝ: сꙋди́ти вселе́ннѣй въ пра́вдꙋ, и҆ лю́демъ пра́востїю."}]}, "98": {"number": 98, "cu_numeral": "ч҃и", "title": "Ѱало́мъ ч҃и (98)", "subtitle": "Ѱало́мъ дв҃дꙋ, ч҃и.", "verses": [{"num": "а҃.", "text": "Гдⷭ҇ь воцр҃и́сѧ, да гнѣ́ваютсѧ лю́дїе: сѣдѧ́й на херꙋві́мѣхъ, да подви́житсѧ землѧ̀."}, {"num": "в҃.", "text": "Гдⷭ҇ь въ сїѡ́нѣ вели́къ, и҆ высо́къ є҆́сть над̾ всѣ́ми людьмѝ."}, {"num": "г҃.", "text": "Да и҆сповѣ́дѧтсѧ и҆́мени твоемꙋ̀ вели́комꙋ, ꙗ҆́кѡ стра́шно и҆ ст҃о є҆́сть."}, {"num": "д҃.", "text": "И҆ че́сть царе́ва сꙋ́дъ лю́битъ: ты̀ ᲂу҆гото́валъ є҆сѝ правоты̑, сꙋ́дъ и҆ пра́вдꙋ во і҆а́кѡвѣ ты̀ сотвори́лъ є҆сѝ."}, {"num": "є҃.", "text": "Возноси́те гдⷭ҇а бг҃а на́шего, и҆ покланѧ́йтесѧ подно́жїю нѡ́гꙋ є҆гѡ̀, ꙗ҆́кѡ ст҃о є҆́сть."}, {"num": "ѕ҃.", "text": "Мѡѷсе́й и҆ а҆арѡ́нъ во і҆ере́ехъ є҆гѡ̀, и҆ самꙋи́лъ въ призыва́ющихъ и҆́мѧ є҆гѡ̀, призыва́хꙋ гдⷭ҇а, и҆ то́й послꙋ́шаше и҆̀хъ."}, {"num": "з҃.", "text": "Въ столпѣ̀ ѡ҆́блачнѣ глаго́лаше къ ни̑мъ: ꙗ҆́кѡ хранѧ́хꙋ свидѣ̑нїѧ є҆гѡ̀ и҆ повелѣ̑нїѧ є҆гѡ̀, ꙗ҆̀же дадѐ и҆̀мъ."}, {"num": "и҃.", "text": "Гдⷭ҇и бж҃е на́шъ, ты̀ послꙋ́шалъ є҆сѝ и҆̀хъ: бж҃е, ты̀ млⷭ҇тивъ быва́лъ є҆сѝ и҆̀мъ, и҆ мща́ѧ на всѧ̑ начина̑нїѧ и҆́хъ."}, {"num": "ѳ҃.", "text": "Возноси́те гдⷭ҇а бг҃а на́шего, и҆ покланѧ́йтесѧ въ горѣ̀ ст҃ѣ́й є҆гѡ̀: ꙗ҆́кѡ ст҃ъ гдⷭ҇ь бг҃ъ на́шъ."}]}, "99": {"number": 99, "cu_numeral": "ч҃ѳ", "title": "Ѱало́мъ ч҃ѳ (99)", "subtitle": "Ѱало́мъ дв҃дꙋ, во и҆сповѣ́данїе, ч҃ѳ.", "verses": [{"num": "а҃.", "text": "Воскли́кните бг҃ови всѧ̀ землѧ̀:"}, {"num": "в҃.", "text": "Рабо́тайте гдⷭ҇еви въ весе́лїи, вни́дите пред̾ ни́мъ въ ра́дости."}, {"num": "г҃.", "text": "Оу҆вѣ́дите, ꙗ҆́кѡ гдⷭ҇ь то́й є҆́сть бг҃ъ на́шъ: то́й сотворѝ на́съ, а҆ не мы̀: мы́ же лю́дїе є҆гѡ̀ и҆ ѻ҆́вцы па́жити є҆гѡ̀."}, {"num": "д҃.", "text": "Вни́дите во врата̀ є҆гѡ̀ во и҆сповѣ́данїи, во дворы̀ є҆гѡ̀ въ пѣ́нїихъ: и҆сповѣ́дайтесѧ є҆мꙋ̀, хвали́те и҆́мѧ є҆гѡ̀."}, {"num": "є҃.", "text": "Ꙗ҆́кѡ бл҃гъ гдⷭ҇ь, въ вѣ́къ млⷭ҇ть є҆гѡ̀, и҆ да́же до ро́да и҆ ро́да и҆́стина є҆гѡ̀."}]}, "100": {"number": 100, "cu_numeral": "р҃", "title": "Ѱало́мъ р҃ (100)", "subtitle": "Ѱало́мъ дв҃дꙋ, р҃.", "verses": [{"num": "а҃.", "text": "Млⷭ҇ть и҆ сꙋ́дъ воспою̀ тебѣ̀ гдⷭ҇и:"}, {"num": "в҃.", "text": "Пою̀ и҆ разꙋмѣ́ю въ пꙋтѝ непоро́чнѣ: когда̀ прїи́деши ко мнѣ̀; прехожда́хъ въ неѕло́бїи се́рдца моегѡ̀ посредѣ̀ до́мꙋ моегѡ̀."}, {"num": "г҃.", "text": "Не предлага́хъ пред̾ ѻ҆чи́ма мои́ма ве́щь законопрестꙋ́пнꙋю, творѧ́щыѧ престꙋпле́нїе возненави́дѣхъ."}, {"num": "д҃.", "text": "Не прильпѐ мнѣ̀ се́рдце стропти́во: ᲂу҆клонѧ́ющагосѧ ѿ менѐ лꙋка́ваго не позна́хъ."}, {"num": "є҃.", "text": "Ѡ҆клевета́ющаго та́й и҆́скреннѧго своего̀, сего̀ и҆згонѧ́хъ: го́рдымъ ѻ҆́комъ и҆ несы́тымъ се́рдцемъ съ си́мъ не ꙗ҆дѧ́хъ."}, {"num": "ѕ҃.", "text": "Ѻ҆́чи моѝ на вѣ̑рныѧ землѝ, посажда́ти ѧ҆̀ со мно́ю: ходѧ́й по пꙋтѝ непоро́чнꙋ, се́й мѝ слꙋжа́ше."}, {"num": "з҃.", "text": "Не живѧ́ше посредѣ̀ до́мꙋ моегѡ̀ творѧ́й горды́ню: глаго́лѧй непра́вєднаѧ, не и҆справлѧ́ше пред̾ ѻ҆чи́ма"}, {"num": "и҃.", "text": "мои́ма. Воꙋ́трїѧ и҆збива́хъ всѧ̑ грѣ̑шныѧ землѝ, є҆́же потреби́ти ѿ гра́да гдⷭ҇нѧ всѧ̑ дѣ́лающыѧ беззако́нїе. Сла́ва:"}]}, "101": {"number": 101, "cu_numeral": "р҃а", "title": "Ѱало́мъ р҃а (101)", "subtitle": "и҆ пред̾ гдⷭ҇емъ пролїе́тъ моле́нїе своѐ, р҃а.", "verses": [{"num": "а҃.", "text": "Гдⷭ҇и, ᲂу҆слы́ши мл҃твꙋ мою̀, и҆ во́пль мо́й къ тебѣ̀ да прїи́детъ."}, {"num": "в҃.", "text": "Не ѿвратѝ лица̀ твоегѡ̀ ѿ менѐ: во́ньже а҆́ще де́нь скорблю̀, приклонѝ ко мнѣ̀ ᲂу҆́хо твоѐ: во́ньже а҆́ще де́нь призовꙋ́ тѧ, ско́рѡ ᲂу҆слы́ши мѧ̀."}, {"num": "г҃.", "text": "Ꙗ҆́кѡ и҆зчезо́ша ꙗ҆́кѡ ды́мъ дні́е моѝ, и҆"}, {"num": "д҃.", "text": "кѡ́сти моѧ̑ ꙗ҆́кѡ сꙋши́ло сосхо́шасѧ. Оу҆ѧ́звленъ бы́хъ ꙗ҆́кѡ трава̀, и҆ и҆́зсше се́рдце моѐ, ꙗ҆́кѡ забы́хъ снѣ́сти хлѣ́бъ мо́й."}, {"num": "є҃.", "text": "Ѿ гла́са воздыха́нїѧ моегѡ̀ прильпѐ ко́сть моѧ̀ пло́ти мое́й."}, {"num": "ѕ҃.", "text": "Оу҆подо́бихсѧ неѧ́сыти пꙋсты́ннѣй, бы́хъ ꙗ҆́кѡ нощны́й вра́нъ на ны́рищи."}, {"num": "з҃.", "text": "Бдѣ́хъ, и҆ бы́хъ ꙗ҆́кѡ пти́ца ѡ҆со́бѧщаѧсѧ на здѣ̀."}, {"num": "и҃.", "text": "Ве́сь де́нь поноша́хꙋ мѝ вразѝ моѝ, и҆ хва́лѧщїи мѧ̀ мно́ю кленѧ́хꙋсѧ."}, {"num": "ѳ҃.", "text": "Занѐ пе́пелъ ꙗ҆́кѡ хлѣ́бъ ꙗ҆дѧ́хъ, и҆ питїѐ моѐ съ пла́чемъ растворѧ́хъ,"}, {"num": "і҃.", "text": "Ѿ лица̀ гнѣ́ва твоегѡ̀ и҆ ꙗ҆́рости твоеѧ̀: ꙗ҆́кѡ возне́съ низве́рглъ мѧ̀ є҆сѝ."}, {"num": "а҃і.", "text": "Дні́е моѝ ꙗ҆́кѡ сѣ́нь ᲂу҆клони́шасѧ, и҆ а҆́зъ ꙗ҆́кѡ сѣ́нѡ и҆зсхо́хъ."}, {"num": "в҃і.", "text": "Ты́ же, гдⷭ҇и, во вѣ́къ пребыва́еши, и҆ па́мѧть твоѧ̀ въ ро́дъ и҆ ро́дъ."}, {"num": "г҃і.", "text": "Ты̀ воскр҃съ ᲂу҆ще́дриши сїѡ́на: ꙗ҆́кѡ вре́мѧ ᲂу҆ще́дрити є҆го̀, ꙗ҆́кѡ прїи́де вре́мѧ."}, {"num": "д҃і.", "text": "Ꙗ҆́кѡ бл҃говоли́ша рабѝ твоѝ ка́менїе є҆гѡ̀, и҆ пе́рсть є҆гѡ̀ ᲂу҆ще́дрѧтъ."}, {"num": "є҃і.", "text": "И҆ ᲂу҆боѧ́тсѧ ꙗ҆зы́цы и҆́мене гдⷭ҇нѧ, и҆ всѝ ца́рїе зе́мстїи сла́вы твоеѧ̀:"}, {"num": "ѕ҃і.", "text": "Ꙗ҆́кѡ сози́ждетъ гдⷭ҇ь сїѡ́на, и҆ ꙗ҆ви́тсѧ во сла́вѣ свое́й."}, {"num": "з҃і.", "text": "Призрѣ̀ на мл҃твꙋ смире́нныхъ, и҆ не ᲂу҆ничижѝ моле́нїѧ и҆́хъ."}, {"num": "и҃і.", "text": "Да напи́шетсѧ сїѐ въ ро́дъ и҆́нъ, и҆ лю́дїе зи́ждемїи восхва́лѧтъ гдⷭ҇а:"}, {"num": "ѳ҃і.", "text": "Ꙗ҆́кѡ прини́че съ высоты̀ ст҃ы́ѧ своеѧ̀, гдⷭ҇ь съ нб҃сѐ на зе́млю призрѣ̀,"}, {"num": "к҃.", "text": "Оу҆слы́шати воздыха́нїе ѡ҆кова́нныхъ, разрѣши́ти сы́ны ᲂу҆мерщвле́нныхъ:"}, {"num": "к҃а.", "text": "Возвѣсти́ти въ сїѡ́нѣ и҆́мѧ гдⷭ҇не, и҆ хвалꙋ̀ є҆гѡ̀ во і҆ерⷭ҇ли́мѣ:"}, {"num": "к҃в.", "text": "Внегда̀ собра́тисѧ лю́демъ вкꙋ́пѣ, и҆ царє́мъ, є҆́же рабо́тати гдⷭ҇еви. Ѿвѣща̀"}, {"num": "к҃г.", "text": "є҆мꙋ̀ на пꙋтѝ крѣ́пости є҆гѡ̀: ᲂу҆мале́нїе дне́й мои́хъ возвѣсти́ ми:"}, {"num": "к҃д.", "text": "Не возведѝ менѐ во преполове́нїе дне́й мои́хъ: въ ро́дѣ родѡ́въ лѣ̑та твоѧ̑."}, {"num": "к҃є.", "text": "Въ нача́лѣхъ ты̀, гдⷭ҇и, зе́млю ѡ҆снова́лъ є҆сѝ, и҆ дѣла̀ рꙋкꙋ̀ твоє́ю сꙋ́ть нб҃са̀."}, {"num": "к҃ѕ.", "text": "Та̑ поги́бнꙋтъ,"}, {"num": "к҃з.", "text": "ты́ же пребыва́еши: и҆ всѧ̑ ꙗ҆́кѡ ри́за ѡ҆бетша́ютъ, и҆ ꙗ҆́кѡ ѻ҆де́ждꙋ свїе́ши ѧ҆̀ и҆и҆змѣнѧ́тсѧ. Ты́же то́йжде є҆сѝ, и҆лѣ̑татвоѧ̑не ѡ҆скꙋдѣ́ютъ."}, {"num": "к҃и.", "text": "Сы́нове ра̑бъ твои́хъ вселѧ́тсѧ, и҆ сѣ́мѧ и҆́хъ во вѣ́къ и҆спра́витсѧ."}]}, "102": {"number": 102, "cu_numeral": "р҃в", "title": "Ѱало́мъ р҃в (102)", "subtitle": "Ѱало́мъ дв҃дꙋ, р҃в.", "verses": [{"num": "а҃.", "text": "Бл҃гословѝ дꙋшѐ моѧ̀ гдⷭ҇а, и҆ всѧ̑ внꙋ́трєннѧѧ моѧ̑ и҆́мѧ ст҃о́е є҆гѡ̀:"}, {"num": "в҃.", "text": "Бл҃гословѝ дꙋшѐ моѧ̀ гдⷭ҇а, и҆ не забыва́й всѣ́хъ воздаѧ́нїй є҆гѡ̀:"}, {"num": "г҃.", "text": "Ѡ҆чища́ющаго всѧ̑ беззакѡ́нїѧ твоѧ̑, и҆сцѣлѧ́ющаго всѧ̑ недꙋ́ги твоѧ̑,"}, {"num": "д҃.", "text": "И҆҆збавлѧ́ющаго ѿ и҆стлѣ́нїѧ живо́тъ тво́й, вѣнча́ющаго тѧ̀ млⷭ҇тїю и҆ щедро́тами,"}, {"num": "є҃.", "text": "И҆сполнѧ́ющаго во бл҃ги́хъ жела́нїе"}, {"num": "ѕ҃.", "text": "твоѐ: ѡ҆бнови́тсѧ ꙗ҆́кѡ ѻ҆́рлѧ ю҆́ность твоѧ̀. Творѧ́й млⷭ҇тыни гдⷭ҇ь, и҆ сꙋдьбꙋ̀ всѣ̑мъ ѡ҆би̑димымъ,"}, {"num": "з҃.", "text": "Сказа̀ пꙋти̑ своѧ̑ мѡѷсе́ови, сыновѡ́мъ і҆и҃лєвымъ хотѣ̑нїѧ своѧ̑."}, {"num": "и҃.", "text": "Ще́дръ и҆ млⷭ҇тивъ гдⷭ҇ь, долготерпѣли́въ и҆ многомлⷭ҇тивъ."}, {"num": "ѳ҃.", "text": "Не до конца̀ прогнѣ́ваетсѧ, нижѐ во вѣ́къ враждꙋ́етъ:"}, {"num": "і҃.", "text": "Не по беззако́нїємъ на́шымъ сотвори́лъ є҆́сть на́мъ, нижѐ по грѣхѡ́мъ на́шымъ возда́лъ є҆́сть на́мъ."}, {"num": "а҃і.", "text": "Ꙗ҆́кѡ по высотѣ̀ нбⷭ҇нѣй ѿ землѝ, ᲂу҆тверди́лъ є҆́сть гдⷭ҇ь млⷭ҇ть свою̀ на боѧ́щихсѧ є҆гѡ̀:"}, {"num": "в҃і.", "text": "Е҆ли́кѡ ѿстоѧ́тъ восто́цы ѿ за̑падъ, ᲂу҆да́лилъ є҆́сть ѿ на́съ беззакѡ́нїѧ на̑ша."}, {"num": "г҃і.", "text": "Ꙗ҆́коже ще́дритъ ѻ҆те́цъ сы́ны, ᲂу҆ще́дри гдⷭ҇ь боѧ́щихсѧ є҆гѡ̀."}, {"num": "д҃і.", "text": "Ꙗ҆́кѡ то́й позна̀ созда́нїе на́ше, помѧнꙋ̀, ꙗ҆́кѡ пе́рсть є҆смы̀."}, {"num": "є҃і.", "text": "Человѣ́къ, ꙗ҆́кѡ трава̀ дні́е є҆гѡ̀, ꙗ҆́кѡ цвѣ́тъ се́льный, та́кѡ ѡ҆цвѣте́тъ:"}, {"num": "ѕ҃і.", "text": "Ꙗ҆́кѡ дꙋ́хъ про́йде въ не́мъ, и҆ не бꙋ́детъ, и҆ не позна́етъ ктомꙋ̀ мѣ́ста своегѡ̀."}, {"num": "з҃і.", "text": "Млⷭ҇ть же гдⷭ҇нѧ ѿ вѣ́ка и҆ до вѣ́ка на боѧ́щихсѧ є҆гѡ̀:"}, {"num": "и҃і.", "text": "И҆ пра́вда"}, {"num": "ѳ҃і.", "text": "є҆гѡ̀ на сынѣ́хъ сынѡ́въ хранѧ́щихъ завѣ́тъ є҆гѡ̀ и҆ по́мнѧщихъ за́пѡвѣди є҆гѡ̀ твори́ти ѧ҆̀. Гдⷭ҇ь на нб҃сѝ ᲂу҆гото́ва прⷭ҇то́лъ сво́й, и҆ црⷭ҇тво є҆гѡ̀ всѣ́ми ѡ҆блада́етъ."}, {"num": "к҃.", "text": "Бл҃гослови́те гдⷭ҇а всѝ а҆́гг҃ли є҆гѡ̀, си́льнїи крѣ́постїю, творѧ́щїи сло́во є҆гѡ̀, ᲂу҆слы́шати гла́съ слове́съ"}, {"num": "к҃а.", "text": "є҆гѡ̀. Бл҃гослови́те гдⷭ҇а всѧ̑ си̑лы є҆гѡ̀, слꙋги̑ є҆гѡ̀ творѧ́щїи во́лю є҆гѡ̀. Бл҃гослови́те гдⷭ҇а"}, {"num": "к҃в.", "text": "всѧ̑ дѣла̀ є҆гѡ̀, на всѧ́комъ мѣ́стѣ влⷣчества є҆гѡ̀: бл҃гословѝ, дꙋшѐ моѧ̀, гдⷭ҇а. Сла́ва:"}]}, "103": {"number": 103, "cu_numeral": "р҃г", "title": "Ѱало́мъ р҃г (103)", "subtitle": "Ѱало́мъ дв҃дꙋ, ѡ҆ мїрстѣ́мъ бытїѝ, р҃г.", "verses": [{"num": "а҃.", "text": "Бл҃гословѝ, дꙋшѐ моѧ̀, гдⷭ҇а. гдⷭ҇и бж҃е мо́й, возвели́чилсѧ є҆сѝ ѕѣлѡ̀: во и҆сповѣ́данїе и҆ въ велелѣ́потꙋ ѡ҆бле́клсѧ є҆сѝ:"}, {"num": "в҃.", "text": "Ѡ҆дѣѧ́йсѧ свѣ́томъ ꙗ҆́кѡ ри́зою, простира́ѧй не́бо ꙗ҆́кѡ ко́жꙋ:"}, {"num": "г҃.", "text": "Покрыва́ѧй вода́ми превы́спрєннѧѧ своѧ̑, полага́ѧй ѻ҆́блаки на восхожде́нїе своѐ, ходѧ́й на крилꙋ̑ вѣ́трєню:"}, {"num": "д҃.", "text": "Творѧ́й а҆́гг҃лы своѧ̑ дꙋ́хи, и҆ слꙋги̑ своѧ̑ пла́мень ѻ҆́гненный:"}, {"num": "є҃.", "text": "Ѡ҆снова́ѧй зе́млю на тве́рди є҆ѧ̀: не преклони́тсѧ въ вѣ́къ є҃ ѕ҃ з҃ и҃ ѳ҃ і҃ а҃і в҃і г҃і д҃і є҃і ѕ҃і з҃і и҃і ѳ҃і к҃ к҃а к҃в к҃г к҃д к҃є к҃ѕ к҃з к҃и к҃ѳ л҃ л҃а л҃в л҃г л҃д л҃є ѻ҆́гненный: Ѡ҆снова́ѧй зе́млю на тве́рди є҆ѧ̀: не преклони́тсѧ въ вѣ́къ вѣ́ка."}, {"num": "ѕ҃.", "text": "Бе́здна ꙗ҆́кѡ ри́за ѡ҆дѣѧ́нїе є҆ѧ̀, на гора́хъ ста́нꙋтъ во́ды:"}, {"num": "з҃.", "text": "Ѿ запреще́нїѧ твоегѡ̀ побѣ́гнꙋтъ, ѿ гла́са гро́ма твоегѡ̀ ᲂу҆боѧ́тсѧ."}, {"num": "и҃.", "text": "Восхо́дѧтъ го́ры, и҆ низхо́дѧтъ полѧ̀, въ мѣ́сто є҆́же ѡ҆снова́лъ є҆сѝ и҆̀мъ."}, {"num": "ѳ҃.", "text": "Предѣ́лъ положи́лъ є҆сѝ, є҆гѡ́же не пре́йдꙋтъ, нижѐ ѡ҆братѧ́тсѧ покры́ти зе́млю."}, {"num": "і҃.", "text": "Посыла́ѧй и҆сто́чники въ де́брехъ, посредѣ̀ го́ръ про́йдꙋтъ во́ды."}, {"num": "а҃і.", "text": "Напаѧ́ютъ всѧ̑ ѕвѣ̑ри сє́лныѧ, ждꙋ́тъ ѻ҆на́гри въ жа́ждꙋ свою̀."}, {"num": "в҃і.", "text": "На ты́хъ пти̑цы нбⷭ҇ныѧ привита́ютъ: ѿ среды̀ ка́менїѧ дадѧ́тъ гла́съ."}, {"num": "г҃і.", "text": "Напаѧ́ѧй го́ры ѿ превы́спреннихъ свои́хъ: ѿ плода̀ дѣ́лъ твои́хъ насы́титсѧ землѧ̀."}, {"num": "д҃і.", "text": "Прозѧба́ѧй травꙋ̀ скотѡ́мъ, и҆ ѕла́къ на слꙋ́жбꙋ человѣ́кѡмъ, и҆звестѝ хлѣ́бъ ѿ землѝ:"}, {"num": "є҃і.", "text": "И҆ вїно̀ весели́тъ се́рдце человѣ́ка, ᲂу҆ма́стити лицѐ є҆ле́емъ: и҆ хлѣ́бъ се́рдце человѣ́ка ᲂу҆крѣпи́тъ."}, {"num": "ѕ҃і.", "text": "Насы́тѧтсѧ древа̀ пѡльска́ѧ, ке́дри лїва́нстїи, и҆̀хже є҆сѝ насади́лъ."}, {"num": "з҃і.", "text": "Та́мѡ пти̑цы вогнѣздѧ́тсѧ, є҆рѡді́ево жили́ще предводи́тельствꙋетъ и҆́ми."}, {"num": "и҃і.", "text": "Го́ры высѡ́кїѧ є҆ле́нємъ, ка́мень прибѣ́жище за́ѧцємъ."}, {"num": "ѳ҃і.", "text": "Сотвори́лъ є҆́сть лꙋнꙋ̀ во времена̀: со́лнце позна̀ за́падъ сво́й."}, {"num": "к҃.", "text": "Положи́лъ є҆сѝ тьмꙋ̀, и҆ бы́сть но́щь, въ не́йже про́йдꙋтъ всѝ ѕвѣ́рїе дꙋбра́внїи,"}, {"num": "к҃а.", "text": "Скѵ́мни рыка́ющїи восхи́тити, и҆ взыска́ти ѿ бг҃а пи́щꙋ себѣ̀."}, {"num": "к҃в.", "text": "Возсїѧ̀ со́лнце, и҆ собра́шасѧ, и҆ въ ло́жахъ свои́хъ лѧ́гꙋтъ."}, {"num": "к҃г.", "text": "И҆зы́детъ человѣ́къ на дѣ́ло своѐ и҆ на дѣ́ланїе своѐ до ве́чера."}, {"num": "к҃д.", "text": "Ꙗ҆́кѡ возвели́чишасѧ дѣла̀ твоѧ̑, гдⷭ҇и: всѧ̑ премⷣростїю сотвори́лъ є҆сѝ: и҆спо́лнисѧ землѧ̀ тва́ри твоеѧ̀."}, {"num": "к҃є.", "text": "Сїѐ мо́ре вели́кое и҆ простра́нное: та́мѡ га́ди, и҆́хже нѣ́сть числа̀, живѡ́тнаѧ ма̑лаѧ съ вели́кими:"}, {"num": "к҃ѕ.", "text": "Та́мѡ корабли̑ препла́ваютъ, ѕмі́й се́й, є҆го́же созда́лъ є҆сѝ рꙋга́тисѧ є҆мꙋ̀."}, {"num": "к҃з.", "text": "Всѧ̑ къ тебѣ̀ ча́ютъ, да́ти пи́щꙋ и҆̀мъ во бл҃го вре́мѧ."}, {"num": "к҃и.", "text": "Да́вшꙋ тебѣ̀ и҆̀мъ, соберꙋ́тъ: ѿве́рзшꙋ тебѣ̀ рꙋ́кꙋ, всѧ́чєскаѧ и҆спо́лнѧтсѧ бл҃гости:"}, {"num": "к҃ѳ.", "text": "Ѿвра́щшꙋ же тебѣ̀ лицѐ, возмѧтꙋ́тсѧ: ѿи́меши дꙋ́хъ и҆́хъ, и҆ и҆зче́знꙋтъ и҆ въ пе́рсть свою̀ возвратѧ́тсѧ:"}, {"num": "л҃.", "text": "По́слеши дх҃а твоего̀, и҆ сози́ждꙋтсѧ, и҆ ѡ҆бнови́ши лицѐ землѝ."}, {"num": "л҃а.", "text": "Бꙋ́ди сла́ва гдⷭ҇нѧ во вѣ́ки: возвесели́тсѧ гдⷭ҇ьѡ҆ дѣ́лѣхъсвои́хъ:Призира́ѧй назе́млюи҆творѧ́й ю҆̀ трѧсти́сѧ:"}, {"num": "л҃в.", "text": "прикаса́ѧйсѧ гора́мъ, и҆ дымѧ́тсѧ."}, {"num": "л҃г.", "text": "Воспою̀ гдⷭ҇еви въживотѣ̀мое́мъ, пою̀ бг҃ꙋ моемꙋ̀, до́ндеже є҆́смь:Да ᲂу҆слади́тсѧ є҆мꙋ̀бесѣ́да моѧ̀, а҆́зъ же возвеселю́сѧ ѡ҆ гдⷭ҇ѣ."}, {"num": "л҃д.", "text": "Да и҆зче́знꙋтъ грѣ̑шницы ѿ землѝ, и҆ беззакѡ́нницы, ꙗ҆́коже не"}, {"num": "л҃є.", "text": "бы́ти и҆̀мъ. благословѝ, дꙋшѐ моѧ̀, гдⷭ҇а. Сла́ва: А҆ллилꙋ́їа, р҃д."}]}, "104": {"number": 104, "cu_numeral": "р҃д", "title": "Ѱало́мъ р҃д (104)", "subtitle": "А҆ллилꙋ́їа, р҃д.", "verses": [{"num": "а҃.", "text": "И҆сповѣ́дайтесѧ гдⷭ҇еви, и҆ призыва́йте и҆́мѧ є҆гѡ̀: возвѣсти́те во ꙗ҆зы́цѣхъ дѣла̀ є҆гѡ̀."}, {"num": "в҃.", "text": "Воспо́йте є҆мꙋ̀ и҆ по́йте є҆мꙋ̀: повѣ́дите всѧ̑ чꙋдеса̀ є҆гѡ̀."}, {"num": "г҃.", "text": "Хвали́тесѧ ѡ҆ и҆́мени ст҃ѣ́мъ є҆гѡ̀: да возвесели́тсѧ се́рдце и҆́щꙋщихъ гдⷭ҇а:"}, {"num": "д҃.", "text": "Взыщи́те гдⷭ҇а, и҆ ᲂу҆тверди́тесѧ, взыщи́те лица̀ є҆гѡ̀ вы́нꙋ."}, {"num": "є҃.", "text": "Помѧни́те чꙋдеса̀ є҆гѡ̀, ꙗ҆̀же сотворѝ, чꙋдеса̀ є҆гѡ̀, и҆ сꙋдьбы̑ ᲂу҆́стъ є҆гѡ̀."}, {"num": "ѕ҃.", "text": "Сѣ́мѧ а҆враа́мле рабѝ є҆гѡ̀, сы́нове і҆а̑кѡвли и҆збра́ннїи є҆гѡ̀. То́й гдⷭ҇ь"}, {"num": "з҃.", "text": "бг҃ъ на́шъ: по все́й землѝ сꙋдьбы̑ є҆гѡ̀."}, {"num": "и҃.", "text": "Помѧнꙋ̀ въ вѣ́къ завѣ́тъ сво́й, сло́во, є҆́же заповѣ́да въ ты́сѧщы родѡ́въ:"}, {"num": "ѳ҃.", "text": "Е҆́же завѣща̀ а҆враа́мꙋ, и҆ клѧ́твꙋ свою̀ і҆саа́кꙋ:"}, {"num": "і҃.", "text": "И҆ поста́ви ю҆̀ і҆а́кѡвꙋ въ повелѣ́нїе, и҆ і҆и҃лю въ завѣ́тъ вѣ́ченъ,"}, {"num": "а҃і.", "text": "Глаго́лѧ: тебѣ̀ да́мъ зе́млю ханаа́ню, ᲂу҆́же достоѧ́нїѧ ва́шегѡ:"}, {"num": "в҃і.", "text": "Внегда̀ бы́ти и҆̀мъ ма̑лымъ число́мъ, малѣ́йшымъ и҆ прише́льцємъ въ не́й,"}, {"num": "г҃і.", "text": "И҆ преидо́ша ѿ ꙗ҆зы́ка въ ꙗ҆зы́къ, и҆ ѿ ца́рствїѧ въ лю́ди и҆́ны:"}, {"num": "д҃і.", "text": "Не ѡ҆ста́ви человѣ́ка ѡ҆би́дѣти и҆̀хъ, и҆ ѡ҆бличѝ ѡ҆ ни́хъ цари̑:"}, {"num": "є҃і.", "text": "Не прикаса́йтесѧ пома̑заннымъ мои̑мъ, и҆ во прⷪ҇ро́цѣхъ мои́хъ не лꙋка́внꙋйте."}, {"num": "ѕ҃і.", "text": "И҆ призва̀ гла́дъ на зе́млю: всѧ́ко ᲂу҆твержде́нїе хлѣ́бное сотры̀."}, {"num": "з҃і.", "text": "Посла̀ пред̾ ни́ми человѣ́ка: въ раба̀ про́данъ бы́сть і҆ѡ́сифъ."}, {"num": "и҃і.", "text": "Смири́ша во ѡ҆ко́вахъ но́ѕѣ є҆гѡ̀, желѣ́зо про́йде дꙋша̀ є҆гѡ̀:"}, {"num": "ѳ҃і.", "text": "До́ндеже прїи́де сло́во є҆гѡ̀, сло́во гдⷭ҇не разжжѐ є҆го̀."}, {"num": "к҃.", "text": "Посла̀ ца́рь и҆ разрѣшѝ є҆го̀: кнѧ́зь люде́й, и҆ ѡ҆ста́ви є҆го̀."}, {"num": "к҃а.", "text": "Поста́ви є҆го̀ господи́на до́мꙋ своемꙋ̀, и҆ кнѧ́зѧ всемꙋ̀ стѧжа́нїю своемꙋ̀,"}, {"num": "к҃в.", "text": "Наказа́ти кнѧ̑зи є҆гѡ̀ ꙗ҆́кѡ себѐ, и҆ ста́рцы є҆гѡ̀ ᲂу҆мꙋдри́ти."}, {"num": "к҃г.", "text": "И҆ вни́де і҆и҃ль во є҆гѵ́петъ, и҆ і҆а́кѡвъ прише́льствова въ зе́млю ха́мовꙋ."}, {"num": "к҃д.", "text": "И҆ возрастѝ лю́ди своѧ̑ ѕѣлѡ̀, и҆ ᲂу҆крѣпѝ ѧ҆̀ па́че врагѡ́въ и҆́хъ."}, {"num": "к҃є.", "text": "Превратѝ се́рдце и҆́хъ возненави́дѣти лю́ди є҆гѡ̀, ле́сть сотвори́ти въ рабѣ́хъ є҆гѡ̀:"}, {"num": "к҃ѕ.", "text": "Посла̀ мѡѷсе́а раба̀ своего̀, а҆арѡ́на, є҆го́же и҆збра̀ себѣ̀."}, {"num": "к҃з.", "text": "Положѝ въ ни́хъ словеса̀ зна́менїй свои́хъ, и҆ чꙋде́съ свои́хъ въ землѝ ха́мовѣ."}, {"num": "к҃и.", "text": "Посла̀ тьмꙋ̀ и҆ помрачѝ, ꙗ҆́кѡ преѡгорчи́ша словеса̀ є҆гѡ̀."}, {"num": "к҃ѳ.", "text": "Преложѝ во́ды и҆́хъ въ кро́вь, и҆ и҆зморѝ ры̑бы и҆́хъ."}, {"num": "л҃.", "text": "Воскипѣ̀ землѧ̀ и҆́хъ жа́бами, въ сокро́вищницахъ царе́й и҆́хъ."}, {"num": "л҃а.", "text": "Речѐ, и҆ прїидо́ша пє́сїѧ мꙋ̑хи, и҆ скні̑пы во всѧ̑ предѣ́лы и҆́хъ."}, {"num": "л҃в.", "text": "Положѝ дожди̑ и҆́хъ гра́ды, ѻ҆́гнь попалѧ́ющь въ землѝ и҆́хъ."}, {"num": "л҃г.", "text": "И҆ поразѝ вїногра́ды и҆́хъ и҆ смѡ́квы и҆́хъ, и҆ сотры̀ всѧ́кое дре́во предѣ̑лъ и҆́хъ."}, {"num": "л҃д.", "text": "Речѐ, и҆ прїидо́ша прꙋ́зи"}, {"num": "л҃є.", "text": "и҆ гꙋ́сєницы, и҆̀мже не бѣ̀ числа̀: И҆ снѣдо́ша всѧ́кꙋ травꙋ̀ въ землѝ л҃є л҃ѕ л҃з л҃и л҃ѳ м҃ м҃а м҃в м҃г м҃д м҃є гꙋ́сєницы, и҆̀мже не бѣ̀ числа̀: И҆ снѣдо́ша всѧ́кꙋ травꙋ̀ въ землѝ и҆́хъ, и҆ поѧдо́ша всѧ́къ пло́дъ землѝ и҆́хъ."}, {"num": "л҃ѕ.", "text": "И҆ поразѝ всѧ́каго пе́рвенца въ землѝ и҆́хъ, нача́токъ всѧ́кагѡ трꙋда̀ и҆́хъ:"}, {"num": "л҃з.", "text": "И҆ и҆зведѐ ѧ҆̀ съ сребро́мъ и҆ зла́томъ, и҆ не бѣ̀ въ колѣ́нѣхъ и҆́хъ болѧ́й."}, {"num": "л҃и.", "text": "Возвесели́сѧ є҆гѵ́петъ во и҆схожде́нїи и҆́хъ: ꙗ҆́кѡ нападѐ стра́хъ и҆́хъ на нѧ̀."}, {"num": "л҃ѳ.", "text": "Распрострѐ ѻ҆́блакъ въ покро́въ и҆̀мъ, и҆ ѻ҆́гнь, є҆́же просвѣти́ти и҆̀мъ но́щїю."}, {"num": "м҃.", "text": "Проси́ша, и҆ прїидо́ша кра́стєли, и҆ хлѣ́ба нбⷭ҇нагѡ насы́ти ѧ҆̀:"}, {"num": "м҃а.", "text": "Разве́рзе ка́мень, и҆ потеко́ша во́ды, потеко́ша въ безво́дныхъ рѣ́ки:"}, {"num": "м҃в.", "text": "Ꙗ҆́кѡ помѧнꙋ̀ сло́во ст҃о́е своѐ, є҆́же ко а҆враа́мꙋ рабꙋ̀ своемꙋ̀:"}, {"num": "м҃г.", "text": "И҆ и҆зведѐ лю́ди своѧ̑ въ ра́дости, и҆ и҆збра̑нныѧ своѧ̑ въ весе́лїи."}, {"num": "м҃д.", "text": "И҆ дадѐ и҆̀мъ страны̑ ꙗ҆зы̑къ, и҆ трꙋды̀ люде́й наслѣ́доваша:"}, {"num": "м҃є.", "text": "Ꙗ҆́кѡ да сохранѧ́тъ ѡ҆правда̑нїѧ є҆гѡ̀ и҆ зако́на є҆гѡ̀ взы́щꙋтъ. Сла́ва:"}]}, "105": {"number": 105, "cu_numeral": "р҃є", "title": "Ѱало́мъ р҃є (105)", "subtitle": "А҆ллилꙋ́їа, р҃є.", "verses": [{"num": "а҃.", "text": "И҆сповѣ́дайтесѧ гдⷭ҇еви, ꙗ҆́кѡ бл҃гъ, ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀."}, {"num": "в҃.", "text": "Кто̀ возглаго́летъ си̑лы гдⷭ҇ни, слы̑шаны сотвори́тъ всѧ̑ хвалы̑ є҆гѡ̀;"}, {"num": "г҃.", "text": "Бл҃же́ни хранѧ́щїи сꙋ́дъ и҆ творѧ́щїи пра́вдꙋ во всѧ́кое вре́мѧ."}, {"num": "д҃.", "text": "Помѧнѝ на́съ гдⷭ҇и во бл҃говоле́нїи люде́й твои́хъ, посѣтѝ на́съ сп҃се́нїемъ твои́мъ:"}, {"num": "є҃.", "text": "Ви́дѣти во бл҃гости и҆збра̑нныѧ твоѧ̑, возвесели́тисѧ въ весе́лїи ꙗ҆зы́ка твоегѡ̀, хвали́тисѧ съ достоѧ́нїемъ твои́мъ."}, {"num": "ѕ҃.", "text": "Согрѣши́хомъ со ѻ҆тцы̑ на́шими, беззако́нновахомъ, непра́вдовахомъ:"}, {"num": "з҃.", "text": "Ѻ҆тцы̀ на́ши во є҆гѵ́птѣ не разꙋмѣ́ша чꙋде́съ твои́хъ, не помѧнꙋ́ша мно́жества млⷭ҇ти твоеѧ̀: и҆ преѡгорчи́ша восходѧ́ще въ чермно́е мо́ре."}, {"num": "и҃.", "text": "И҆ сп҃сѐ и҆̀хъ и҆́мене своегѡ̀ ра́ди, сказа́ти си́лꙋ свою̀."}, {"num": "ѳ҃.", "text": "И҆ запретѝ чермно́мꙋ мо́рю"}, {"num": "і҃.", "text": "и҆ и҆зсѧ́че, и҆ наста́ви ѧ҆̀ въ бе́зднѣ ꙗ҆́кѡ въ пꙋсты́ни. И҆ сп҃сѐ ѧ҆̀ и҆з̾ рꙋкѝ ненави́дѧщихъ, и҆ и҆зба́ви ѧ҆̀ и҆з̾ рꙋкѝ врагѡ́въ."}, {"num": "а҃і.", "text": "Покры̀ вода̀ стꙋжа́ющыѧ и҆̀мъ: ни є҆ди́нъ ѿ ни́хъ и҆збы́сть."}, {"num": "в҃і.", "text": "И҆ вѣ́роваша словесѝ є҆гѡ̀, и҆ воспѣ́ша хвалꙋ̀ є҆гѡ̀."}, {"num": "г҃і.", "text": "Оу҆скори́ша, забы́ша дѣла̀ є҆гѡ̀, не стерпѣ́ша совѣ́та є҆гѡ̀:"}, {"num": "д҃і.", "text": "И҆ похотѣ́ша жела́нїю въ пꙋсты́ни, и҆ и҆скꙋси́ша бг҃а въ безво́днѣй."}, {"num": "є҃і.", "text": "И҆ дадѐ и҆̀мъ проше́нїе и҆́хъ, посла̀ сы́тость въ дꙋ́шы и҆́хъ."}, {"num": "ѕ҃і.", "text": "И҆ прогнѣ́ваша мѡѷсе́а въ станꙋ̀, а҆арѡ́на ст҃а́го гдⷭ҇нѧ."}, {"num": "з҃і.", "text": "Ѿве́рзесѧ землѧ̀ и҆ пожрѐ даѳа́на, и҆ покры̀ на со́нмищи а҆вїрѡ́на:"}, {"num": "и҃і.", "text": "И҆ разжже́сѧ ѻ҆́гнь въ со́нмѣ и҆́хъ, пла́мень попалѝ грѣ́шники."}, {"num": "ѳ҃і.", "text": "И҆ сотвори́ша тельца̀ въ хѡри́вѣ, и҆ поклони́шасѧ и҆стꙋка́нномꙋ:"}, {"num": "к҃.", "text": "И҆ и҆змѣни́ша сла́вꙋ є҆гѡ̀ въ подо́бїе тельца̀ ꙗ҆дꙋ́щагѡ травꙋ̀."}, {"num": "к҃а.", "text": "И҆ забы́ша бг҃а сп҃са́ющаго и҆̀хъ, сотво́ршаго вє́лїѧ во є҆гѵ́птѣ,"}, {"num": "к҃в.", "text": "Чꙋдеса̀ въ землѝ ха́мовѣ, стра̑шнаѧ въ мо́ри чермнѣ́мъ."}, {"num": "к҃г.", "text": "И҆ речѐ потреби́ти и҆̀хъ, а҆́ще не бы̀ мѡѷсе́й и҆збра́нный є҆гѡ̀ ста́лъ въ сокрꙋше́нїи пред̾ ни́мъ, возврати́ти ꙗ҆́рость є҆гѡ̀, да не погꙋби́тъ и҆̀хъ."}, {"num": "к҃д.", "text": "И҆ ᲂу҆ничижи́ша зе́млю жела́ннꙋю, не ꙗ҆́ша вѣ́ры словесѝ є҆гѡ̀:"}, {"num": "к҃є.", "text": "И҆ поропта́ша въ селе́нїихъ свои́хъ, не ᲂу҆слы́шаша гла́са гдⷭ҇нѧ."}, {"num": "к҃ѕ.", "text": "И҆ воздви́же рꙋ́кꙋ свою̀ на нѧ̀, низложи́ти ѧ҆̀ въ пꙋсты́ни,"}, {"num": "к҃з.", "text": "И҆ низложи́ти сѣ́мѧ и҆́хъ во ꙗ҆зы́цѣхъ, и҆ расточи́ти ѧ҆̀ въ страны̑."}, {"num": "к҃и.", "text": "И҆ причасти́шасѧ веельфегѡ́рꙋ, и҆ снѣдо́ша жє́ртвы ме́ртвыхъ:"}, {"num": "к҃ѳ.", "text": "И҆ раздражи́ша є҆го̀ въ начина́нїихъ свои́хъ, и҆ ᲂу҆мно́жисѧ въ ни́хъ паде́нїе."}, {"num": "л҃.", "text": "И҆ ста̀ фїнее́съ"}, {"num": "л҃а.", "text": "и҆ ᲂу҆млⷭ҇тиви, и҆ преста̀ сѣ́чь: И҆ вмѣни́сѧ є҆мꙋ̀ въ пра́вдꙋ, въ ро́дъ и҆ ро́дъ до вѣ́ка."}, {"num": "л҃в.", "text": "И҆ прогнѣ́ваша є҆го̀ на водѣ̀ прерѣка́нїѧ, и҆ ѡ҆ѕло́бленъ бы́сть мѡѷсе́й и҆́хъ ра́ди:"}, {"num": "л҃г.", "text": "Ꙗ҆́кѡ преѡгорчи́ша дꙋ́хъ є҆гѡ̀, и҆ ра́знствова ᲂу҆стна́ма л҃г л҃д л҃є л҃ѕ л҃з л҃и л҃ѳ м҃ м҃а м҃в м҃г м҃д м҃є м҃ѕ м҃з м҃и и҆́хъ ра́ди: Ꙗ҆́кѡ преѡгорчи́ша дꙋ́хъ є҆гѡ̀, и҆ ра́знствова ᲂу҆стна́ма свои́ма."}, {"num": "л҃д.", "text": "Не потреби́ша ꙗ҆зы́ки, ꙗ҆̀же речѐ гдⷭ҇ь и҆̀мъ."}, {"num": "л҃є.", "text": "И҆ смѣси́шасѧ во ꙗ҆зы́цѣхъ, и҆ навыко́ша дѣлѡ́мъ и҆́хъ:"}, {"num": "л҃ѕ.", "text": "И҆ порабо́таша и҆стꙋка̑ннымъ и҆́хъ, и҆ бы́сть и҆̀мъ въ собла́знъ."}, {"num": "л҃з.", "text": "И҆ пожро́ша сы́ны своѧ̑ и҆ дщє́ри своѧ̑ бѣсовѡ́мъ."}, {"num": "л҃и.", "text": "И҆ пролїѧ́ша кро́вь непови́ннꙋю, кро́вь сынѡ́въ свои́хъ и҆ дще́рей, ꙗ҆̀же пожро́ша и҆стꙋка̑ннымъ ханаа̑нскимъ. и҆ ᲂу҆бїе́на бы́сть землѧ̀ и҆́хъ кровьмѝ,"}, {"num": "л҃ѳ.", "text": "И҆ ѡ҆скверни́сѧ въ дѣ́лѣхъ и҆́хъ, и҆ соблꙋди́ша въ начина́нїихъ свои́хъ."}, {"num": "м҃.", "text": "И҆ разгнѣ́васѧ ꙗ҆́ростїю гдⷭ҇ь на лю́ди своѧ̑, и҆ ѡ҆мерзѝ достоѧ́нїе своѐ:"}, {"num": "м҃а.", "text": "И҆ предадѐ ѧ҆̀ въ рꙋ́ки врагѡ́въ и҆ ѡ҆блада́ша и҆́ми ненави́дѧщїи и҆̀хъ."}, {"num": "м҃в.", "text": "И҆ стꙋжи́ша и҆̀мъ вразѝ и҆́хъ, и҆ смири́шасѧ под̾ рꙋка́ми и҆́хъ."}, {"num": "м҃г.", "text": "Мно́жицею и҆зба́ви ѧ҆̀: ті́и же преѡгорчи́ша є҆го̀ совѣ́томъ свои́мъ, и҆ смири́шасѧ въ беззако́нїихъ свои́хъ."}, {"num": "м҃д.", "text": "И҆ ви́дѣ гдⷭ҇ь, внегда̀ скорбѣ́ти и҆̀мъ, внегда̀ ᲂу҆слы́шаше моле́нїе и҆́хъ:"}, {"num": "м҃є.", "text": "И҆ помѧнꙋ̀ завѣ́тъ сво́й и҆ раска́ѧсѧ по мно́жествꙋ млⷭ҇ти своеѧ̀:"}, {"num": "м҃ѕ.", "text": "И҆ дадѐ ѧ҆̀ въ щедрѡ́ты пред̾ всѣ́ми плѣни́вшими ѧ҆̀. Сп҃си́ ны гдⷭ҇и бж҃е на́шъ, и҆"}, {"num": "м҃з.", "text": "собери́ ны ѿ ꙗ҆зы̑къ, и҆сповѣ́датисѧ и҆́мени твоемꙋ̀ ст҃о́мꙋ, хвали́тисѧ во хвалѣ̀ твое́й. Бл҃гослове́нъ гдⷭ҇ь бг҃ъ"}, {"num": "м҃и.", "text": "і҆и҃левъ ѿ вѣ́ка и҆ до вѣ́ка. и҆ рекꙋ́тъ всѝ лю́дїе: бꙋ́ди, бꙋ́ди. Сла́ва: А҆ллилꙋ́їа, р҃ѕ."}]}, "106": {"number": 106, "cu_numeral": "р҃ѕ", "title": "Ѱало́мъ р҃ѕ (106)", "subtitle": "А҆ллилꙋ́їа, р҃ѕ.", "verses": [{"num": "а҃.", "text": "И҆сповѣ́дайтесѧ гдⷭ҇еви, ꙗ҆́кѡ бл҃гъ, ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀."}, {"num": "в҃.", "text": "Да рекꙋ́тъ и҆зба́вленнїи гдⷭ҇емъ, и҆̀хже и҆зба́ви и҆з̾ рꙋкѝ врага̀,"}, {"num": "г҃.", "text": "И҆ ѿ стра́нъ собра̀ и҆́хъ, ѿ востѡ́къ, и҆ за̑падъ, и҆ сѣ́вера, и҆ мо́рѧ:"}, {"num": "д҃.", "text": "Заблꙋди́ша въ пꙋсты́ни безво́днѣй, пꙋтѝ гра́да ѡ҆би́тельнагѡ не ѡ҆брѣто́ша:"}, {"num": "є҃.", "text": "А҆́лчꙋще и҆ жа́ждꙋще, дꙋша̀ и҆́хъ въ ни́хъ и҆зчезѐ."}, {"num": "ѕ҃.", "text": "И҆ воззва́ша ко гдⷭ҇ꙋ, внегда̀ скорбѣ́ти и҆̀мъ, и҆ ѿ нꙋ́ждъ и҆́хъ и҆зба́ви ѧ҆̀:"}, {"num": "з҃.", "text": "И҆ наста́ви ѧ҆̀ на пꙋ́ть пра́въ, вни́ти во гра́дъ ѡ҆би́тельный."}, {"num": "и҃.", "text": "Да и҆сповѣ́дѧтсѧ гдⷭ҇еви млⷭ҇ти є҆гѡ̀, и҆ чꙋдеса̀ є҆гѡ̀ сыновѡ́мъ человѣ́чєскимъ."}, {"num": "ѳ҃.", "text": "Ꙗ҆́кѡ насы́тилъ є҆́сть дꙋ́шꙋ тщꙋ̀, и҆ дꙋ́шꙋ а҆́лчꙋщꙋ и҆спо́лни бла̑гъ: Сѣдѧ́щыѧ во тьмѣ̀ и҆ сѣ́ни сме́ртнѣй, ѡ҆кова̑нныѧ нището́ю и҆ желѣ́зомъ, Ꙗ҆́кѡ преѡгорчи́ша словеса̀ бж҃їѧ, и҆ совѣ́тъ вы́шнѧгѡ раздражи́ша. И҆"}, {"num": "і҃.", "text": "смири́сѧ въ трꙋдѣ́хъ се́рдце и҆́хъ, и҆ и҆знемого́ша, и҆ не в҃і г҃і"}, {"num": "а҃і.", "text": "д҃і є҃і ѕ҃і з҃і и҃і ѳ҃і к҃ к҃а к҃в к҃г к҃д к҃є к҃ѕ к҃з к҃и к҃ѳ л҃ л҃а л҃в л҃г л҃д л҃є л҃ѕ л҃з л҃и л҃ѳ м҃ м҃а м҃в м҃г раздражи́ша."}, {"num": "в҃і.", "text": "И҆ смири́сѧ въ трꙋдѣ́хъ се́рдце и҆́хъ, и҆ и҆знемого́ша, и҆ не бѣ̀ помога́ѧй."}, {"num": "г҃і.", "text": "И҆ воззва́ша ко гдⷭ҇ꙋ, внегда̀ скорбѣ́ти и҆̀мъ и҆ ѿ нꙋ́ждъ и҆́хъ сп҃сѐ ѧ҆̀:"}, {"num": "д҃і.", "text": "И҆ и҆зведѐ ѧ҆̀ и҆з̾ тьмы̀, и҆ сѣ́ни сме́ртныѧ, и҆ ᲂу҆́зы и҆́хъ растерза̀."}, {"num": "є҃і.", "text": "Да и҆сповѣ́дѧтсѧ гдⷭ҇еви млⷭ҇ти є҆гѡ̀, и҆ чꙋдеса̀ є҆гѡ̀ сыновѡ́мъ человѣ́чєскимъ:"}, {"num": "ѕ҃і.", "text": "Ꙗ҆́кѡ сокрꙋшѝ врата̀ мѣ̑днаѧ, и҆ верєѝ желѣ̑зныѧ сломѝ."}, {"num": "з҃і.", "text": "Воспрїѧ́тъ ѧ҆̀ ѿ пꙋтѝ беззако́нїѧ и҆́хъ: беззако́нїй бо ра́ди свои́хъ смири́шасѧ."}, {"num": "и҃і.", "text": "Всѧ́кагѡ бра́шна возгнꙋша́сѧ дꙋша̀ и҆́хъ, и҆ прибли́жишасѧ до вра́тъ сме́ртныхъ:"}, {"num": "ѳ҃і.", "text": "И҆ воззва́ша ко гдⷭ҇ꙋ, внегда̀ скорбѣ́ти и҆̀мъ, и҆ ѿ нꙋ́ждъ и҆́хъ сп҃сѐ ѧ҆̀:"}, {"num": "к҃.", "text": "Посла̀ сло́во своѐ, и҆ и҆зцѣлѝ ѧ҆̀, и҆ и҆зба́ви ѧ҆̀ ѿ растлѣ́нїй и҆́хъ."}, {"num": "к҃а.", "text": "Да и҆сповѣ́дѧтсѧ гдⷭ҇еви млⷭ҇ти є҆гѡ̀, и҆ чꙋдеса̀ є҆гѡ̀ сыновѡ́мъ человѣ́чєскимъ:"}, {"num": "к҃в.", "text": "И҆ да пожрꙋ́тъ є҆мꙋ̀ же́ртвꙋ хвалы̀, и҆ да возвѣстѧ́тъ дѣла̀ є҆гѡ̀ въ ра́дости."}, {"num": "к҃г.", "text": "Сходѧ́щїи въ мо́ре въ корабле́хъ, творѧ́щїи дѣ̑ланїѧ въ вода́хъ мно́гихъ,"}, {"num": "к҃д.", "text": "Ті́и ви́дѣша дѣла̀ гдⷭ҇нѧ, и҆ чꙋдеса̀ є҆гѡ̀ во глꙋбинѣ̀,"}, {"num": "к҃є.", "text": "Речѐ, и҆ ста̀ дꙋ́хъ бꙋ́ренъ, и҆ вознесо́шасѧ во́лны є҆гѡ̀:"}, {"num": "к҃ѕ.", "text": "Восхо́дѧтъ до нб҃съ, и҆ низхо́дѧтъ до бе́зднъ: дꙋша̀ и҆́хъ въ ѕлы́хъ та́ѧше:"}, {"num": "к҃з.", "text": "Смѧто́шасѧ, подвиго́шасѧ ꙗ҆́кѡ пїѧ́ный, и҆ всѧ̀ мꙋ́дрость и҆́хъ поглощена̀ бы́сть."}, {"num": "к҃и.", "text": "И҆ воззва́ша ко гдⷭ҇ꙋ, внегда̀ скорбѣ́ти и҆̀мъ, и҆ ѿ нꙋ́ждъ и҆́хъ и҆зведѐ ѧ҆̀:"}, {"num": "к҃ѳ.", "text": "И҆ повелѣ̀ бꙋ́ри, и҆ ста̀ въ тишинꙋ̀, и҆ ᲂу҆молко́ша во́лны є҆гѡ̀."}, {"num": "л҃.", "text": "И҆ возвесели́шасѧ, ꙗ҆́кѡ ᲂу҆молко́ша, и҆ наста́ви ѧ҆̀ въ приста́нище хотѣ́нїѧ своегѡ̀."}, {"num": "л҃а.", "text": "Да и҆сповѣ́дѧтсѧ гдⷭ҇еви млⷭ҇ти є҆гѡ̀, и҆ чꙋдеса̀ є҆гѡ̀ сыновѡ́мъ человѣ́чєскимъ:"}, {"num": "л҃в.", "text": "Да вознесꙋ́тъ є҆го̀ въ цр҃кви людстѣ́й, и҆ на сѣда́лищи ста́рєцъ восхва́лѧтъ є҆го̀."}, {"num": "л҃г.", "text": "Положи́лъ є҆́сть рѣ́ки въ пꙋсты́ню, и҆ и҆схѡ́диша вѡдна́ѧ въ жа́ждꙋ,"}, {"num": "л҃д.", "text": "Зе́млю плодоно́снꙋю въ сла́ность, ѿ ѕло́бы живꙋ́щихъ на не́й."}, {"num": "л҃є.", "text": "Положи́лъ є҆́сть пꙋсты́ню во є҆зе́ра вѡдна́ѧ и҆ зе́млю безво́днꙋю во и҆схѡ́дища вѡдна́ѧ."}, {"num": "л҃ѕ.", "text": "И҆ населѝ та́мѡ а҆́лчꙋщыѧ, и҆ соста́виша гра́ды ѡ҆би́тєльны:"}, {"num": "л҃з.", "text": "И҆ насѣ́ѧша се́ла,"}, {"num": "л҃и.", "text": "и҆ насади́ша вїногра́ды, и҆ сотвори́ша пло́дъ жи́тенъ. И҆ бл҃гословѝ ѧ҆̀, и҆ ᲂу҆мно́жишасѧ ѕѣлѡ̀: и҆ скоты̀ и҆́хъ не ᲂу҆ма́ли."}, {"num": "л҃ѳ.", "text": "И҆ ᲂу҆ма́лишасѧ и҆ ѡ҆ѕло́бишасѧ ѿ ско́рби ѕѡ́лъ и҆ болѣ́зни:"}, {"num": "м҃.", "text": "И҆злїѧ́сѧ ᲂу҆ничиже́нїе на кнѧ̑зи и҆́хъ, и҆ ѡ҆блазнѝ ѧ҆̀ по непрохо́днѣй, а҆ не по пꙋтѝ."}, {"num": "м҃а.", "text": "И҆ помо́же ᲂу҆бо́гꙋ ѿ нищеты̀, и҆ положѝ ꙗ҆́кѡ ѻ҆́вцы ѻ҆те́чєствїѧ."}, {"num": "м҃в.", "text": "Оу҆́зрѧтъ пра́вїи и҆ возвеселѧ́тсѧ: и҆ всѧ́кое беззако́нїе загради́тъ ᲂу҆ста̀ своѧ̑."}, {"num": "м҃г.", "text": "Кто̀ премꙋ́дръ и҆ сохрани́тъ сїѧ̑: и҆ ᲂу҆разꙋмѣ́ютъ млⷭ҇ти гдⷭ҇ни. Сла́ва: а҃ Пѣ́снь, ѱало́мъ дв҃дꙋ, р҃з."}]}, "107": {"number": 107, "cu_numeral": "р҃з", "title": "Ѱало́мъ р҃з (107)", "subtitle": "а҃ Пѣ́снь, ѱало́мъ дв҃дꙋ, р҃з.", "verses": [{"num": "а҃.", "text": "Гото́во се́рдце моѐ, бж҃е, гото́во се́рдце моѐ: воспою̀ и҆ пою̀ во сла́вѣ мое́й."}, {"num": "в҃.", "text": "Воста́ни сла́ва моѧ̀, воста́ни, ѱалти́рю и҆ гꙋ́сли: воста́нꙋ ра́нѡ."}, {"num": "г҃.", "text": "И҆сповѣ́мсѧ тебѣ̀ въ лю́дехъ, гдⷭ҇и, пою̀ тебѣ̀ во ꙗ҆зы́цѣхъ."}, {"num": "д҃.", "text": "Ꙗ҆́кѡ ве́лїѧ верхꙋ̀ нб҃съ млⷭ҇ть твоѧ̀, и҆ до ѻ҆́блакъ и҆́стина твоѧ̀."}, {"num": "є҃.", "text": "Вознеси́сѧ на нб҃са̀, бж҃е, и҆ по все́й землѝ сла́ва твоѧ̀."}, {"num": "ѕ҃.", "text": "Ꙗ҆́кѡ да и҆зба́вѧтсѧ возлю́бленнїи твоѝ: сп҃сѝ десни́цею твое́ю, и҆ ᲂу҆слы́ши мѧ̀."}, {"num": "з҃.", "text": "Бг҃ъ возглаго́ла во ст҃ѣ́мъ свое́мъ: вознесꙋ́сѧ и҆ раздѣлю̀ сїкі́мꙋ, и҆ ᲂу҆до́ль селе́нїй размѣ́рю."}, {"num": "и҃.", "text": "Мо́й є҆́сть галаа́дъ, и҆ мо́й є҆́сть манассі́й, и҆ є҆фре́мъ застꙋпле́нїе главы̀ моеѧ̀: і҆ꙋ́да ца́рь мо́й."}, {"num": "ѳ҃.", "text": "Мѡа́въ коно́бъ ᲂу҆пова́нїѧ моегѡ̀: на і҆дꙋме́ю наложꙋ̀ сапо́гъ мо́й: мнѣ̀ и҆ноплемє́нницы покори́шасѧ."}, {"num": "і҃.", "text": "Кто̀ введе́тъ мѧ̀ во гра́дъ ѡ҆гражде́нїѧ; и҆лѝ кто̀ наста́витъ мѧ̀ до і҆дꙋме́и:"}, {"num": "а҃і.", "text": "Не ты́ ли, бж҃е, ѿри́нꙋвый на́съ, и҆ не и҆зы́деши, бж҃е, въ си́лахъ на́шихъ;"}, {"num": "в҃і.", "text": "Да́ждь на́мъ по́мощь ѿ ско́рби: и҆ сꙋ́етно спасе́нїе человѣ́ческо."}, {"num": "г҃і.", "text": "Ѡ҆ бз҃ѣ сотвори́мъ си́лꙋ, и҆ то́й ᲂу҆ничижи́тъ врагѝ на́шѧ."}]}, "108": {"number": 108, "cu_numeral": "р҃и", "title": "Ѱало́мъ р҃и (108)", "subtitle": "Въ коне́цъ, ѱало́мъ дв҃дꙋ, р҃и.", "verses": [{"num": "а҃.", "text": "Бж҃е, хвалы̀ моеѧ̀ не премолчѝ:"}, {"num": "в҃.", "text": "Ꙗ҆́кѡ ᲂу҆ста̀ грѣ̑шнича и҆ ᲂу҆ста̀ льсти́вагѡ на мѧ̀ ѿверзо́шасѧ, глаго́лаша на мѧ̀ ѧ҆зы́комъ льсти́вымъ,"}, {"num": "г҃.", "text": "И҆ словесы̀ ненави́стными ѡ҆быдо́ша мѧ̀ и҆ бра́шасѧ со мно́ю тꙋ́не. Вмѣ́стѡ є҆́же люби́ти"}, {"num": "д҃.", "text": "мѧ̀ ѡ҆болга́хꙋ мѧ̀, а҆́зъ же молѧ́хсѧ:"}, {"num": "є҃.", "text": "И҆ положи́ша на мѧ̀ ѕла̑ѧ за бл҃га̑ѧ, и҆ не́нависть за возлюбле́нїе моѐ."}, {"num": "ѕ҃.", "text": "Поста́ви на него̀ грѣ́шника, и҆ дїа́волъ да ста́нетъ ѡ҆деснꙋ́ю є҆гѡ̀:"}, {"num": "з҃.", "text": "Внегда̀ сꙋди́тисѧ є҆мꙋ̀, да и҆зы́детъ ѡ҆сꙋжде́нъ, и҆ моли́тва є҆гѡ̀ да бꙋ́детъ въ грѣ́хъ."}, {"num": "и҃.", "text": "Да бꙋ́дꙋтъ дні́е є҆гѡ̀ ма́ли, и҆ є҆пі́скопство є҆гѡ̀ да прїи́метъ и҆́нъ:"}, {"num": "ѳ҃.", "text": "Да бꙋ́дꙋтъ сы́нове є҆гѡ̀ си́ри, и҆ жена̀ є҆гѡ̀ вдова̀:"}, {"num": "і҃.", "text": "Дви́жꙋщесѧ да преселѧ́тсѧ сы́нове є҆гѡ̀ и҆ воспро́сѧтъ,"}, {"num": "а҃і.", "text": "да и҆згна́ни бꙋ́дꙋтъ и҆з̾ домѡ́въ свои́хъ. Да взы́щетъ заимода́вецъ всѧ̑, є҆ли̑ка сꙋ́ть є҆гѡ̀: и҆ да восхи́тѧтъ чꙋжді́и трꙋды̀ є҆гѡ̀."}, {"num": "в҃і.", "text": "Да не бꙋ́детъ є҆мꙋ̀ застꙋ́пника, нижѐ да бꙋ́детъ ᲂу҆щедрѧ́ѧй сироты̀ є҆гѡ̀:"}, {"num": "г҃і.", "text": "Да бꙋ́дꙋтъ ча̑да є҆гѡ̀ въ погꙋбле́нїе, въ ро́дѣ є҆ди́нѣмъ да потреби́тсѧ и҆́мѧ є҆гѡ̀."}, {"num": "д҃і.", "text": "Да воспомѧне́тсѧ беззако́нїе ѻ҆тє́цъ є҆гѡ̀ пред̾ гдⷭ҇емъ, и҆ грѣ́хъ ма́тере є҆гѡ̀ да не ѡ҆чи́ститсѧ:"}, {"num": "є҃і.", "text": "Да бꙋ́дꙋтъ пред̾ гдⷭ҇емъ вы́нꙋ, и҆ да потреби́тсѧ ѿ землѝ па́мѧть и҆́хъ:"}, {"num": "ѕ҃і.", "text": "Зане́же не помѧнꙋ̀ сотвори́ти ѕ҃і з҃і и҃і ѳ҃і к҃ к҃а к҃в к҃г к҃д к҃є к҃ѕ к҃з к҃и к҃ѳ л҃ л҃а потреби́тсѧ ѿ землѝ па́мѧть и҆́хъ: Зане́же не помѧнꙋ̀ сотвори́ти млⷭ҇ть, и҆ погна̀ человѣ́ка ни́ща и҆ ᲂу҆бо́га, и҆ ᲂу҆миле́на се́рдцемъ ᲂу҆мертви́ти."}, {"num": "з҃і.", "text": "И҆ возлюбѝ клѧ́твꙋ, и҆ прїи́детъ є҆мꙋ̀: и҆ не восхотѣ̀ бл҃гослове́нїѧ, и҆ ᲂу҆дали́тсѧ ѿ негѡ̀."}, {"num": "и҃і.", "text": "И҆ ѡ҆блече́сѧ въ клѧ́твꙋ ꙗ҆́кѡ въ ри́зꙋ, и҆ вни́де ꙗ҆́кѡ вода̀ во ᲂу҆тро́бꙋ є҆гѡ̀ и҆ ꙗ҆́кѡ є҆ле́й въ кѡ́сти є҆гѡ̀:"}, {"num": "ѳ҃і.", "text": "Да бꙋ́детъ є҆мꙋ̀ ꙗ҆́кѡ ри́за, въ ню́же ѡ҆блачи́тсѧ, и҆ ꙗ҆́кѡ по́ѧсъ, и҆́мже вы́нꙋ ѡ҆поѧсꙋ́етсѧ."}, {"num": "к҃.", "text": "Сїѐ дѣ́ло ѡ҆болга́ющихъ мѧ̀ ᲂу҆ гдⷭ҇а,"}, {"num": "к҃а.", "text": "и҆ глаго́лющихъ лꙋка̑ваѧ на дꙋ́шꙋ мою̀. И҆ ты̀ гдⷭ҇и, гдⷭ҇и, сотворѝ со мно́ю и҆́мене ра́ди твоегѡ̀, ꙗ҆́кѡ бл҃га млⷭ҇ть твоѧ̀:"}, {"num": "к҃в.", "text": "И҆зба́ви мѧ̀, ꙗ҆́кѡ ни́щъ и҆ ᲂу҆бо́гъ є҆́смь а҆́зъ, и҆ се́рдце моѐ смѧте́сѧ внꙋ́трь менѐ."}, {"num": "к҃г.", "text": "Ꙗ҆́кѡ сѣ́нь, внегда̀ ᲂу҆клони́тисѧ є҆́й, ѿѧ́хсѧ: стрѧсо́хсѧ ꙗ҆́кѡ прꙋ́зи."}, {"num": "к҃д.", "text": "Кѡлѣ́на моѧ̑ и҆знемо́госта ѿ поста̀, и҆ пло́ть моѧ̀ и҆змѣни́сѧ є҆ле́а ра́ди."}, {"num": "к҃є.", "text": "И҆ а҆́зъ бы́хъ поноше́нїе и҆̀мъ: ви́дѣша мѧ̀, покива́ша глава́ми свои́ми."}, {"num": "к҃ѕ.", "text": "Помози́ ми, гдⷭ҇и бж҃е мо́й, и҆ сп҃си́ мѧ по млⷭ҇ти твое́й:"}, {"num": "к҃з.", "text": "И҆ да разꙋмѣ́ютъ, ꙗ҆́кѡ рꙋка̀ твоѧ̀ сїѧ̀, и҆ ты̀ гдⷭ҇и сотвори́лъ є҆сѝ ю҆̀."}, {"num": "к҃и.", "text": "Прокленꙋ́тъ ті́и, и҆ ты̀ бл҃гослови́ши: востаю́щїи на мѧ̀ да постыдѧ́тсѧ, ра́бъ же тво́й возвесели́тсѧ."}, {"num": "к҃ѳ.", "text": "Да ѡ҆блекꙋ́тсѧ ѡ҆болга́ющїи мѧ̀ въ срамотꙋ̀, и҆ ѡ҆де́ждꙋтсѧ ꙗ҆́кѡ ѻ҆де́ждою стꙋдо́мъ свои́мъ."}, {"num": "л҃.", "text": "И҆сповѣ́мсѧ гдⷭ҇еви ѕѣлѡ̀ ᲂу҆сты̑ мои́ми, и҆ посредѣ̀ мно́гихъ восхвалю̀ є҆го̀:"}, {"num": "л҃а.", "text": "Ꙗ҆́кѡ предста̀ ѡ҆деснꙋ́ю ᲂу҆бо́гагѡ, є҆́же сп҃стѝ ѿ гонѧ́щихъ дꙋ́шꙋ мою̀. Сла́ва:"}]}, "109": {"number": 109, "cu_numeral": "р҃ѳ", "title": "Ѱало́мъ р҃ѳ (109)", "subtitle": "Ѱало́мъ дв҃дꙋ, р҃ѳ.", "verses": [{"num": "а҃.", "text": "Речѐ гдⷭ҇ь гдⷭ҇еви моемꙋ̀: сѣдѝ ѡ҆деснꙋ́ю менѐ, до́ндеже положꙋ̀ врагѝ твоѧ̑ подно́жїе но́гъ твои́хъ."}, {"num": "в҃.", "text": "Же́злъ си́лы по́слетъ тѝ гдⷭ҇ь ѿ сїѡ́на, и҆ гдⷭ҇ствꙋй посредѣ̀ врагѡ́въ твои́хъ."}, {"num": "г҃.", "text": "Съ тобо́ю нача́ло въ де́нь си́лы твоеѧ̀, во свѣ́тлостехъ ст҃ы́хъ твои́хъ: и҆з̾ чре́ва пре́жде денни́цы роди́хъ тѧ̀."}, {"num": "д҃.", "text": "Клѧ́тсѧ гдⷭ҇ь, и҆ не раска́етсѧ: ты̀ і҆ере́й во вѣ́къ по чи́нꙋ мелхїседе́ковꙋ."}, {"num": "є҃.", "text": "Гдⷭ҇ь ѡ҆деснꙋ́ю тебѐ сокрꙋши́лъ є҆́сть въ де́нь гнѣ́ва своегѡ̀ цари̑:"}, {"num": "ѕ҃.", "text": "Сꙋ́дитъ во ꙗ҆зы́цѣхъ, и҆спо́лнитъ падє́нїѧ, сокрꙋши́тъ главы̑ на землѝ мно́гихъ."}, {"num": "з҃.", "text": "Ѿ пото́ка на пꙋтѝ пїе́тъ: сегѡ̀ ра́ди вознесе́тъ главꙋ̀. А҆ллилꙋ́їа, р҃і."}]}, "110": {"number": 110, "cu_numeral": "р҃і", "title": "Ѱало́мъ р҃і (110)", "subtitle": "А҆ллилꙋ́їа, р҃і.", "verses": [{"num": "а҃.", "text": "И҆сповѣ́мсѧ тебѣ̀, гдⷭ҇и, всѣ́мъ се́рдцемъ мои́мъ, въ совѣ́тѣ пра́выхъ и҆ со́нмѣ."}, {"num": "в҃.", "text": "Вє́лїѧ дѣла̀ гдⷭ҇нѧ, и҆зы̑скана во всѣ́хъ во́лѧхъ є҆гѡ̀:"}, {"num": "г҃.", "text": "И҆сповѣ́данїе и҆ великолѣ́пїе дѣ́ло є҆гѡ̀: и҆ пра́вда є҆гѡ̀ пребыва́етъ въ вѣ́къ вѣ́ка."}, {"num": "д҃.", "text": "Па́мѧть сотвори́лъ є҆́сть чꙋде́съ свои́хъ: млⷭ҇тивъ и҆ ще́дръ гдⷭ҇ь."}, {"num": "є҃.", "text": "Пи́щꙋ дадѐ боѧ́щымсѧ є҆гѡ̀: помѧне́тъ въ"}, {"num": "ѕ҃.", "text": "вѣ́къ завѣ́тъ сво́й. Крѣ́пость дѣ́лъ свои́хъ возвѣстѝ лю́демъ свои̑мъ, да́ти и҆̀мъ достоѧ́нїе ꙗ҆зы̑къ."}, {"num": "з҃.", "text": "Дѣла̀ рꙋ́къ є҆гѡ̀ и҆́стина и҆ сꙋ́дъ: вѣ̑рны всѧ̑ за́пѡвѣди є҆гѡ̀, Оу҆твержє́ны въ вѣ́къ вѣ́ка,"}, {"num": "и҃.", "text": "сотворє́ны во и҆́стинѣ и҆ правотѣ̀."}, {"num": "ѳ҃.", "text": "И҆збавле́нїе посла̀ лю́демъ свои̑мъ, заповѣ́да въ вѣ́къ завѣ́тъ сво́й: ст҃о и҆ стра́шно и҆́мѧ є҆гѡ̀."}, {"num": "і҃.", "text": "Нача́ло премꙋ́дрости стра́хъ гдⷭ҇ень, ра́зꙋмъ же бл҃гъ всѣ̑мъ творѧ́щымъ и҆̀: хвала̀ є҆гѡ̀ пребыва́етъ въ вѣ́къ вѣ́ка. А҆ллилꙋ́їа, ѱало́мъ, ра҃і."}]}, "111": {"number": 111, "cu_numeral": "ра҃і", "title": "Ѱало́мъ ра҃і (111)", "subtitle": "А҆ллилꙋ́їа, ѱало́мъ, ра҃і.", "verses": [{"num": "а҃.", "text": "Бл҃же́нъ мꙋ́жъ боѧ́йсѧ гдⷭ҇а, въ за́повѣдехъ є҆гѡ̀ восхо́щетъ ѕѣлѡ̀."}, {"num": "в҃.", "text": "Си́льно на землѝ бꙋ́детъ сѣ́мѧ є҆гѡ̀, ро́дъ пра́выхъ бл҃гослови́тсѧ:"}, {"num": "г҃.", "text": "Сла́ва и҆ бога́тство въ домꙋ̀ є҆гѡ̀, и҆ пра́вда є҆гѡ̀ пребыва́етъ въ вѣ́къ вѣ́ка."}, {"num": "д҃.", "text": "Возсїѧ̀ во тьмѣ̀ свѣ́тъ пра̑вымъ: млⷭ҇тивъ и҆ ще́дръ и҆ првⷣнъ."}, {"num": "є҃.", "text": "Бл҃гъ мꙋ́жъ ще́дрѧ и҆ даѧ̀: ᲂу҆стро́итъ словеса̀ своѧ̑ на сꙋдѣ̀, ꙗ҆́кѡ въ вѣ́къ не подви́житсѧ."}, {"num": "ѕ҃.", "text": "Въ па́мѧть вѣ́чнꙋю бꙋ́детъ првⷣникъ."}, {"num": "з҃.", "text": "Ѿ слꙋ́ха ѕла̀ не ᲂу҆бои́тсѧ."}, {"num": "и҃.", "text": "Гото́во се́рдце є҆гѡ̀ ᲂу҆пова́ти на гдⷭ҇а: ᲂу҆тверди́сѧ се́рдце є҆гѡ̀, не ᲂу҆бои́тсѧ, до́ндеже воззри́тъ на врагѝ своѧ̑. Расточѝ ѳ҃ і҃ се́рдце є҆гѡ̀, не ᲂу҆бои́тсѧ, до́ндеже воззри́тъ на врагѝ своѧ̑."}, {"num": "ѳ҃.", "text": "Расточѝ дадѐ ᲂу҆бѡ́гимъ: пра́вда є҆гѡ̀ пребыва́етъ во вѣ́къ вѣ́ка: ро́гъ є҆гѡ̀ вознесе́тсѧ въ сла́вѣ."}, {"num": "і҃.", "text": "Грѣ́шникъ ᲂу҆́зритъ и҆ прогнѣ́ваетсѧ, зꙋбы̀ свои́ми поскреже́щетъ и҆ раста́етъ: жела́нїе грѣ́шника поги́бнетъ. Сла́ва: А҆ллилꙋ́їа, рв҃і."}]}, "112": {"number": 112, "cu_numeral": "рв҃і", "title": "Ѱало́мъ рв҃і (112)", "subtitle": "А҆ллилꙋ́їа, рв҃і.", "verses": [{"num": "а҃.", "text": "Хвали́те ѻ҆́троцы гдⷭ҇а, хвали́те и҆́мѧ гдⷭ҇не."}, {"num": "в҃.", "text": "Бꙋ́ди и҆́мѧ гдⷭ҇не бл҃гослове́но ѿ ны́нѣ и҆ до вѣ́ка."}, {"num": "г҃.", "text": "Ѿ востѡ́къ со́лнца до за̑падъ хва́льно и҆́мѧ гдⷭ҇не."}, {"num": "д҃.", "text": "Высо́къ над̾ всѣ́ми ꙗ҆зы̑ки гдⷭ҇ь: над̾ нб҃сы̀ сла́ва є҆гѡ̀."}, {"num": "є҃.", "text": "Кто̀ ꙗ҆́кѡ гдⷭ҇ь бг҃ъ на́шъ; на высо́кихъ живы́й,"}, {"num": "ѕ҃.", "text": "И҆ на смирє́нныѧ призира́ѧй на нб҃сѝ и҆ на землѝ:"}, {"num": "з҃.", "text": "Воздвиза́ѧй ѿ землѝ ни́ща, и҆ ѿ гно́ища возвыша́ѧй ᲂу҆бо́га:"}, {"num": "и҃.", "text": "Посади́ти є҆го̀ съ кнѧ̑зи, съ кнѧ̑зи люде́й свои́хъ:"}, {"num": "ѳ҃.", "text": "Вселѧ́ѧ непло́довь въ до́мъ, ма́терь ѡ҆ ча́дѣхъ веселѧ́щꙋсѧ. А҆ллилꙋ́їа, рг҃і."}]}, "113": {"number": 113, "cu_numeral": "рг҃і", "title": "Ѱало́мъ рг҃і (113)", "subtitle": "А҆ллилꙋ́їа, рг҃і.", "verses": [{"num": "а҃.", "text": "Во и҆схо́дѣ і҆и҃левѣ ѿ є҆гѵ́пта, до́мꙋ і҆а́кѡвлѧ и҆з̾ люде́й ва̑рваръ,"}, {"num": "в҃.", "text": "Бы́сть і҆ꙋде́а ст҃ы́нѧ є҆гѡ̀, і҆и҃ль ѻ҆́бласть є҆гѡ̀."}, {"num": "г҃.", "text": "Мо́ре ви́де и҆ побѣжѐ, і҆ѻрда́нъ возврати́сѧ вспѧ́ть:"}, {"num": "д҃.", "text": "Го́ры взыгра́шасѧ ꙗ҆́кѡ ѻ҆внѝ, и҆ хо́лми ꙗ҆́кѡ а҆́гнцы ѻ҆́вчїи."}, {"num": "є҃.", "text": "Что́ ти є҆́сть мо́ре, ꙗ҆́кѡ побѣ́гло є҆сѝ; и҆ тебѣ̀ і҆ѻрда́не, ꙗ҆́кѡ возврати́лсѧ є҆сѝ вспѧ́ть;"}, {"num": "ѕ҃.", "text": "Го́ры, ꙗ҆́кѡ взыгра́стесѧ ꙗ҆́кѡ ѻ҆внѝ и҆ хо́лми ꙗ҆́кѡ а҆́гнцы ѻ҆́вчїи,"}, {"num": "з҃.", "text": "Ѿ лица̀ гдⷭ҇нѧ подви́жесѧ землѧ̀, ѿ лица̀ бг҃а і҆а́кѡвлѧ:"}, {"num": "и҃.", "text": "Ѡ҆бра́щшагѡ ка́мень во є҆зе́ра водна́ѧ, и҆ несѣко́мый во и҆сто́чникивѡдны́ѧ."}, {"num": "ѳ҃.", "text": "Не на́мъ, гдⷭ҇и, нена́мъ, но и҆́мени твоемꙋ̀ да́ждь сла́вꙋ ѡ҆ млⷭ҇ти твое́й и҆ и҆́стинѣ твое́й:"}, {"num": "і҃.", "text": "Да не когда̀ рекꙋ́тъ ꙗ҆зы́цы: гдѣ̀ є҆́сть бг҃ъ и҆́хъ,"}, {"num": "а҃і.", "text": "Бг҃ъ же на́шъ на нб҃сѝ и҆ на землѝ, всѧ̑ є҆ли̑ка восхотѣ̀ сотворѝ."}, {"num": "в҃і.", "text": "І҆́дѡли ꙗ҆зы̑къ сребро̀ и҆ зла́то, дѣла̀ рꙋ́къ человѣ́ческихъ:"}, {"num": "г҃і.", "text": "Оу҆ста̀ и҆́мꙋтъ, и҆ не возглаго́лютъ:"}, {"num": "д҃і.", "text": "ѻ҆́чи и҆́мꙋтъ, и҆ не ᲂу҆́зрѧтъ: Оу҆́шы и҆́мꙋтъ и҆ не ᲂу҆слы́шатъ: нѡ́здри и҆́мꙋтъ, и҆ не ѡ҆бонѧ́ютъ:"}, {"num": "є҃і.", "text": "Рꙋ́цѣ и҆́мꙋтъ, и҆ не ѡ҆сѧ́жꙋтъ: но́зѣ и҆́мꙋтъ, и҆ не по́йдꙋтъ: не возгласѧ́тъ горта́немъ свои́мъ."}, {"num": "ѕ҃і.", "text": "Подо́бни и҆̀мъ да бꙋ́дꙋтъ творѧ́щїи ѧ҆̀, и҆ всѝ надѣ́ющїисѧ на нѧ̀."}, {"num": "з҃і.", "text": "До́мъ і҆и҃левъ ᲂу҆пова̀ на гдⷭ҇а: помо́щникъ и҆ защи́титель и҆̀мъ є҆́сть."}, {"num": "и҃і.", "text": "До́мъ а҆арѡ́нь ᲂу҆пова̀ на гдⷭ҇а: помо́щникъ и҆ защи́титель и҆̀мъ є҆́сть."}, {"num": "ѳ҃і.", "text": "Боѧ́щїисѧ гдⷭ҇а ᲂу҆пова́ша на"}, {"num": "к҃.", "text": "гдⷭ҇а, помо́щникъ и҆ защи́титель и҆̀мъ є҆́сть. Гдⷭ҇ь помѧнꙋ́въ ны̀ бл҃го к҃ к҃а к҃в"}, {"num": "к҃а.", "text": "к҃г к҃д к҃є к҃ѕ гдⷭ҇а, помо́щникъ и҆ защи́титель и҆̀мъ є҆́сть. Гдⷭ҇ь помѧнꙋ́въ ны̀ бл҃гослови́лъ є҆́сть на́съ: бл҃гослови́лъ є҆́сть до́мъ і҆и҃левъ, бл҃гослови́лъ є҆́сть до́мъ а҆арѡ́нь: Бл҃гослови́лъ є҆́сть боѧ́щыѧсѧ гдⷭ҇а, ма̑лыѧ съ вели́кими."}, {"num": "к҃в.", "text": "Да приложи́тъ гдⷭ҇ь на вы̀, на вы̀ и҆ на сы́ны ва́шѧ: Бл҃гослове́ни вы̀ гдⷭ҇еви, сотво́ршемꙋ нб҃о и҆ зе́млю. Нб҃о нб҃сѐ гдⷭ҇еви, зе́млю же дадѐ сыновѡ́мъ человѣ́чєскимъ. Не ме́ртвїи восхва́лѧтъ тѧ̀ гдⷭ҇и, нижѐ всѝ низходѧ́щїи во а҆́дъ: Но мы̀ живі́и"}, {"num": "к҃г.", "text": "благослови́мъ гдⷭ҇а,"}, {"num": "к҃д.", "text": "ѿ ны́нѣ"}, {"num": "к҃є.", "text": "и҆ до"}, {"num": "к҃ѕ.", "text": "вѣ́ка. А҆ллилꙋ́їа, рд҃і."}]}, "114": {"number": 114, "cu_numeral": "рд҃і", "title": "Ѱало́мъ рд҃і (114)", "subtitle": "А҆ллилꙋ́їа, рд҃і.", "verses": [{"num": "а҃.", "text": "Возлюби́хъ, ꙗ҆́кѡ ᲂу҆слы́шитъ гдⷭ҇ь гла́съ моле́нїѧ моегѡ̀,"}, {"num": "в҃.", "text": "Ꙗ҆́кѡ приклонѝ ᲂу҆́хо своѐ мнѣ̀: и҆ во дни̑ моѧ̑ призовꙋ̀."}, {"num": "г҃.", "text": "Ѡ҆б̾ѧ́ша мѧ̀ болѣ̑зни смє́ртныѧ, бѣды̑ а҆́дѡвы ѡ҆брѣто́ша мѧ̀, ско́рбь и҆ болѣ́знь ѡ҆брѣто́х: и҆ и҆́мѧ гдⷭ҇не призва́хъ:"}, {"num": "д҃.", "text": "Ѽ гдⷭ҇и, и҆зба́ви дꙋ́шꙋ мою̀. млⷭ҇тивъ гдⷭ҇ь и҆ првⷣнъ, и҆ бг҃ъ на́шъ ми́лꙋетъ."}, {"num": "є҃.", "text": "Хранѧ́й младе́нцы гдⷭ҇ь: смири́хсѧ, и҆ сп҃се́ мѧ."}, {"num": "ѕ҃.", "text": "Ѡ҆брати́сѧ, дꙋшѐ моѧ̀ въ поко́й тво́й, ꙗ҆́кѡ гдⷭ҇ь бл҃годѣ́йствова тѧ̀:"}, {"num": "з҃.", "text": "Ꙗ҆́кѡ и҆з̾ѧ́тъ дꙋ́шꙋ мою̀ ѿ сме́рти, ѻ҆́чи моѝ ѿ сле́зъ, и҆ но́зѣ моѝ ѿ поползнове́нїѧ."}, {"num": "и҃.", "text": "Бл҃гоꙋгождꙋ̀ пред̾ гдⷭ҇емъ во странѣ̀ живы́хъ. Сла́ва: А҆ллилꙋ́їа, рє҃і."}]}, "115": {"number": 115, "cu_numeral": "рє҃і", "title": "Ѱало́мъ рє҃і (115)", "subtitle": "А҆ллилꙋ́їа, рє҃і.", "verses": [{"num": "а҃.", "text": "Вѣ́ровахъ, тѣ́мже возглаго́лахъ:"}, {"num": "в҃.", "text": "а҆́зъ же смири́хсѧ ѕѣлѡ̀.А҆́зъ же рѣ́хъ во и҆зстꙋпле́нїи мое́мъ: всѧ́къ человѣ́къ ло́жъ."}, {"num": "г҃.", "text": "Что̀ возда́мъ гдⷭ҇еви ѡ҆ всѣ́хъ, ꙗ҆̀же воздаде́ ми;"}, {"num": "д҃.", "text": "Ча́шꙋ сп҃се́нїѧ прїимꙋ̀, и҆ и҆́мѧ гдⷭ҇не призовꙋ̀: Мл҃твы моѧ̑"}, {"num": "є҃.", "text": "гдⷭ҇еви возда́мъ пред̾ всѣ́ми людьмѝ є҆гѡ̀."}, {"num": "ѕ҃.", "text": "Чтⷭ҇на̀ пред̾ гдⷭ҇емъ сме́рть прпⷣбныхъ є҆гѡ̀."}, {"num": "з҃.", "text": "Ѽ гдⷭ҇и, а҆́зъ ра́бъ тво́й, а҆́зъ ра́бъ тво́й и҆ сы́нъ рабы́ни твоеѧ̀: растерза́лъ є҆сѝ ᲂу҆́зы моѧ̑."}, {"num": "и҃.", "text": "Тебѣ̀ пожрꙋ̀ же́ртвꙋ хвалы̀, и҆ во и҆́мѧ гдⷭ҇не"}, {"num": "ѳ҃.", "text": "призовꙋ̀: Мл҃твы моѧ̑ гдⷭ҇еви возда́мъ пред̾ всѣ́ми людьмѝ є҆гѡ̀,"}, {"num": "і҃.", "text": "Во дво́рѣхъ до́мꙋ гдⷭ҇нѧ, посредѣ̀ тебѐ і҆ерⷭ҇ли́ме. А҆ллилꙋ́їа, рѕ҃і."}]}, "116": {"number": 116, "cu_numeral": "рѕ҃і", "title": "Ѱало́мъ рѕ҃і (116)", "subtitle": "А҆ллилꙋ́їа, рѕ҃і.", "verses": [{"num": "а҃.", "text": "а҃ в҃ Хвали́те гдⷭ҇а всѝ ꙗ҆зы́цы, похвали́те є҆го̀, всѝ лю́дїе:"}, {"num": "в҃.", "text": "Ꙗ҆́кѡ ᲂу҆тверди́сѧ млⷭ҇ть є҆гѡ̀ на на́съ, и҆ и҆́стина гдⷭ҇нѧ пребыва́етъ во вѣ́къ. А҆ллилꙋ́їа, рз҃і."}]}, "117": {"number": 117, "cu_numeral": "рз҃і", "title": "Ѱало́мъ рз҃і (117)", "subtitle": "А҆ллилꙋ́їа, рз҃і.", "verses": [{"num": "а҃.", "text": "И҆сповѣ́дайтесѧ гдⷭ҇еви, ꙗ҆́кѡ бл҃гъ, ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀."}, {"num": "в҃.", "text": "Да рече́тъ ᲂу҆́бѡ до́мъ і҆и҃левъ: ꙗ҆́кѡ бл҃гъ, ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀."}, {"num": "г҃.", "text": "Да рече́тъ ᲂу҆́бѡ до́мъ а҆арѡ́нь: ꙗ҆́кѡ бл҃гъ, ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀."}, {"num": "д҃.", "text": "Да рекꙋ́тъᲂу҆́бѡвсѝбоѧ́щїисѧ гдⷭ҇а:ꙗ҆́кѡбл҃гъ, ꙗ҆́кѡвъвѣ́къ млⷭ҇ть є҆гѡ̀."}, {"num": "є҃.", "text": "Ѿ ско́рби призва́хъ гдⷭ҇а, и҆ ᲂу҆слы́ша мѧ̀ въ простра́нство."}, {"num": "ѕ҃.", "text": "Гдⷭ҇ь мнѣ̀ помо́щникъ, и҆ не ᲂу҆бою́сѧ, что̀ сотвори́тъ мнѣ̀ человѣ́къ;"}, {"num": "з҃.", "text": "Гдⷭ҇ь мнѣ̀ помо́щникъ, и҆ а҆́зъ воззрю̀ на врагѝ моѧ̑."}, {"num": "и҃.", "text": "Бл҃го є҆́сть надѣ́ѧтисѧ на гдⷭ҇а, не́жели надѣ́ѧтисѧ на человѣ́ка:"}, {"num": "ѳ҃.", "text": "Бл҃го є҆́сть ᲂу҆пова́ти на гдⷭ҇а, не́жели ᲂу҆пова́ти на кнѧ̑зи."}, {"num": "і҃.", "text": "Всѝ ꙗ҆зы́цы ѡ҆быдо́ша мѧ̀, и҆ и҆́менемъ гдⷭ҇нимъ противлѧ́хсѧ и҆̀мъ: Ѡ҆быше́дше"}, {"num": "а҃і.", "text": "ѡ҆быдо́ша мѧ̀, и҆ и҆́менемъ гдⷭ҇нимъ противлѧ́хсѧ и҆̀мъ:"}, {"num": "в҃і.", "text": "Ѡ҆быдо́ша мѧ̀ ꙗ҆́кѡ пче́лы со́тъ, и҆ разгорѣ́шасѧ ꙗ҆́кѡ ѻ҆́гнь въ те́рнїи: и҆ и҆́менемъ гдⷭ҇нимъ противлѧ́хсѧ и҆̀мъ."}, {"num": "г҃і.", "text": "Ѿринове́нъ преврати́хсѧ па́сти, и҆ гдⷭ҇ь прїѧ́тъ мѧ̀."}, {"num": "д҃і.", "text": "Крѣ́пость моѧ̀ и҆ пѣ́нїе моѐ гдⷭ҇ь, и҆ бы́сть мѝ во сп҃се́нїе."}, {"num": "є҃і.", "text": "Гла́съ ра́дости и҆ сп҃се́нїѧ въ селе́нїихъ првⷣныхъ: десни́ца гдⷭ҇нѧ сотворѝ си́лꙋ."}, {"num": "ѕ҃і.", "text": "Десни́ца гдⷭ҇нѧ вознесе́ мѧ, десни́ца гдⷭ҇нѧ сотворѝ си́лꙋ."}, {"num": "з҃і.", "text": "Не ᲂу҆мрꙋ̀, но жи́въ бꙋ́дꙋ, и҆ повѣ́мъ дѣла̀ гдⷭ҇нѧ."}, {"num": "и҃і.", "text": "Наказꙋ́ѧ наказа́ мѧ гдⷭ҇ь, сме́рти же не предаде́ мѧ."}, {"num": "ѳ҃і.", "text": "Ѿве́рзите мнѣ̀ врата̀ пра́вды: вше́дъ въ нѧ̀ и҆сповѣ́мсѧ гдⷭ҇еви."}, {"num": "к҃.", "text": "Сїѧ̑ врата̀ гдⷭ҇нѧ: првⷣнїи вни́дꙋтъ въ нѧ̀."}, {"num": "к҃а.", "text": "И҆сповѣ́мсѧ тебѣ̀, ꙗ҆́кѡ ᲂу҆слы́шалъ мѧ̀ є҆сѝ и҆ бы́лъ є҆сѝ мнѣ̀ во сп҃се́нїе."}, {"num": "к҃в.", "text": "Ка́мень, є҆го́же небрего́ша зи́ждꙋщїи, се́й бы́сть во главꙋ̀ ᲂу҆́гла:"}, {"num": "к҃г.", "text": "Ѿ гдⷭ҇а бы́сть се́й и҆ є҆́сть ди́венъ во ѻ҆чесѣ́хъ на́шихъ."}, {"num": "к҃д.", "text": "Се́й де́нь, є҆го́же сотворѝ гдⷭ҇ь, возра́дꙋемсѧ и҆ возвесели́мсѧ во́нь. Ѽ гдⷭ҇и, сп҃си́"}, {"num": "к҃є.", "text": "же: ѽ гдⷭ҇и, поспѣши́ же."}, {"num": "к҃ѕ.", "text": "Бл҃гослове́нъ грѧды́й во и҆́мѧ гдⷭ҇не: бл҃гослови́хомъ вы̀ и҆з̾ до́мꙋ гдⷭ҇нѧ."}, {"num": "к҃з.", "text": "Бг҃ъ гдⷭ҇ь, и҆ ꙗ҆ви́сѧ на́мъ: соста́вите пра́здникъ во ᲂу҆чаща́ющихъ до рѡ́гъ ѻ҆лтаре́выхъ. Бг҃ъ мо́й є҆сѝ ты̀,"}, {"num": "к҃и.", "text": "и҆ и҆сповѣ́мсѧ тебѣ̀: бг҃ъ мо́й є҆сѝ ты̀, и҆ вознесꙋ́ тѧ:"}, {"num": "к҃ѳ.", "text": "и҆сповѣ́мсѧ тебѣ̀, ꙗ҆́кѡ ᲂу҆слы́шалъ мѧ̀ є҆сѝ, и҆ бы́лъ є҆сѝ мнѣ̀ во сп҃се́нїе. И҆сповѣ́дайтесѧ гдⷭ҇еви, ꙗ҆́кѡ бл҃гъ, ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀. Сла́ва:"}]}, "118": {"number": 118, "cu_numeral": "ри҃і", "title": "Ѱало́мъ ри҃і (118)", "subtitle": "А҆ллилꙋ́їа, ри҃і.", "verses": [{"num": "а҃.", "text": "Бл҃же́ни непоро́чнїи въ пꙋ́ть, ходѧ́щїи въ зако́нѣ гдⷭ҇ни."}, {"num": "в҃.", "text": "Бл҃же́ни и҆спыта́ющїи свидѣ̑нїѧ є҆гѡ̀, всѣ́мъ сердце́мъ взы́щꙋтъ є҆го̀."}, {"num": "г҃.", "text": "Не дѣ́лающїи бо беззако́нїѧ въ пꙋте́хъ є҆гѡ̀ ходи́ша."}, {"num": "д҃.", "text": "Ты̀ заповѣ́далъ є҆сѝ за́пѡвѣди твоѧ̑ сохрани́ти"}, {"num": "є҃.", "text": "ѕѣлѡ̀. Дабы̀ и҆спра́вилисѧ пꙋтїѐ моѝ, сохрани́ти ѡ҆правда̑нїѧ твоѧ̑."}, {"num": "ѕ҃.", "text": "Тогда̀ не постыжꙋ́сѧ, внегда̀ призрѣ́ти мѝ на всѧ̑ за́пѡвѣди твоѧ̑."}, {"num": "з҃.", "text": "И҆сповѣ́мсѧ тебѣ̀ въ пра́вости се́рдца, внегда̀ наꙋчи́ти ми сѧ сꙋдьба́мъ пра́вды твоеѧ̀."}, {"num": "и҃.", "text": "Ѡ҆правда̑нїѧ твоѧ̑ сохраню̀: не ѡ҆ста́ви менѐ до ѕѣла̀."}, {"num": "ѳ҃.", "text": "Въ чесо́мъ и҆спра́витъ ю҆нѣ́йшїй пꙋ́ть сво́й; внегда̀ сохрани́ти словеса̀ твоѧ̑."}, {"num": "і҃.", "text": "Всѣ́мъ се́рдцемъ мои́мъ взыска́хъ тебѐ: не ѿри́ни менѐ ѿ за́повѣдїй твои́хъ."}, {"num": "а҃і.", "text": "Въ се́рдцѣ мое́мъ скры́хъ словеса̀ твоѧ̑, ꙗ҆́кѡ да не согрѣшꙋ̀ тебѣ̀."}, {"num": "в҃і.", "text": "Бл҃гослове́нъ є҆сѝ гдⷭ҇и: наꙋчи́ мѧ ѡ҆правда́нїємъ твои̑мъ."}, {"num": "г҃і.", "text": "Оу҆стна́ма мои́ма возвѣсти́хъ всѧ̑ сꙋдьбы̑ ᲂу҆́стъ твои́хъ."}, {"num": "д҃і.", "text": "На пꙋтѝ свидѣ́нїй твои́хъ наслади́хсѧ, ꙗ҆́кѡ ѡ҆ всѧ́комъ бога́тствѣ."}, {"num": "є҃і.", "text": "Въ за́повѣдехъ твои́хъ поглꙋмлю́сѧ, и҆ ᲂу҆разꙋмѣ́ю пꙋти̑ твоѧ̑."}, {"num": "ѕ҃і.", "text": "Во ѡ҆правда́нїихъ твои́хъ поꙋчꙋ́сѧ: не забꙋ́дꙋ слове́съ твои́хъ."}, {"num": "з҃і.", "text": "Возда́ждь рабꙋ̀ твоемꙋ̀: живи́ мѧ, и҆ сохраню̀ словеса̀ твоѧ̑."}, {"num": "и҃і.", "text": "Ѿкры́й ѻ҆́чи моѝ, и҆ ᲂу҆разꙋмѣ́ю чꙋдеса̀ ѿ зако́на твоегѡ̀."}, {"num": "ѳ҃і.", "text": "Пришле́цъ а҆́зъ є҆́смь на землѝ: не скры́й ѿ менѐ за́пѡвѣди твоѧ̑."}, {"num": "к҃.", "text": "Возлюбѝ дꙋша̀ моѧ̀ возжела́ти сꙋдьбы̑ твоѧ̑ на всѧ́кое вре́мѧ."}, {"num": "к҃а.", "text": "Запрети́лъ є҆сѝ гѡ́рдымъ: про́клѧти ᲂу҆клонѧ́ющїисѧ ѿ за́повѣдїй твои́хъ."}, {"num": "к҃в.", "text": "Ѿимѝ ѿ менѐ поно́съ и҆ ᲂу҆ничиже́нїе, ꙗ҆́кѡ свидѣ́нїй твои́хъ взыска́хъ."}, {"num": "к҃г.", "text": "И҆́бо сѣдо́ша кнѧ̑зи, и҆ на мѧ̀ клевета́хꙋ, ра́бъ же тво́й глꙋмлѧ́шесѧ во ѡ҆правда́нїихъ твои́хъ:"}, {"num": "к҃д.", "text": "И҆́бо свидѣ̑нїѧ твоѧ̑ поꙋче́нїе моѐ є҆́сть и҆ совѣ́ти моѝ ѡ҆правда̑нїѧ твоѧ̑."}, {"num": "к҃є.", "text": "Прильпѐ землѝ дꙋша̀ моѧ̀: живи́ мѧ по словесѝ твоемꙋ̀."}, {"num": "к҃ѕ.", "text": "Пꙋти̑ моѧ̑ возвѣсти́хъ, и҆ ᲂу҆слы́шалъ мѧ̀ є҆сѝ: наꙋчи́ мѧ ѡ҆правда́нїємъ твои̑мъ."}, {"num": "к҃з.", "text": "Пꙋ́ть ѡ҆правда́нїй твои́хъ вразꙋми́ ми, и҆ поглꙋмлю́сѧ въ чꙋдесѣ́хъ твои́хъ."}, {"num": "к҃и.", "text": "Воздрема̀ дꙋша̀ моѧ̀ ѿ ᲂу҆ны́нїѧ: ᲂу҆тверди́ мѧ въ словесѣ́хъ твои́хъ."}, {"num": "к҃ѳ.", "text": "Пꙋ́ть непра́вды ѿста́ви ѿ менѐ, и҆ зако́номъ твои́мъ поми́лꙋй мѧ̀."}, {"num": "л҃.", "text": "Пꙋ́ть и҆́стины и҆зво́лихъ, и҆ сꙋдьбы̑ твоѧ̑ не забы́хъ."}, {"num": "л҃а.", "text": "Прилѣпи́хсѧ свидѣ́нїємъ твои̑мъ гдⷭ҇и, не посрамѝ менѐ."}, {"num": "л҃в.", "text": "Пꙋ́ть за́повѣдїй твои́хъ теко́хъ, є҆гда̀ разшири́лъ є҆сѝ се́рдце моѐ."}, {"num": "л҃г.", "text": "Законоположѝ мнѣ̀ гдⷭ҇и пꙋ́ть ѡ҆правда́нїй твои́хъ, и҆ взыщꙋ̀ и҆̀ вы́нꙋ:"}, {"num": "л҃д.", "text": "Вразꙋми́ мѧ, и҆ и҆спыта́ю зако́нъ тво́й, и҆ сохраню и҆̀ всѣ́мъ се́рдцемъ мои́мъ."}, {"num": "л҃є.", "text": "Наста́ви мѧ̀ на стезю̀ за́повѣдїй л҃є л҃ѕ л҃з л҃и л҃ѳ м҃ м҃а м҃в м҃г м҃д м҃є м҃ѕ м҃з м҃и м҃ѳ н҃ н҃а н҃в н҃г н҃д н҃є н҃ѕ н҃з н҃и н҃ѳ ѯ҃ ѯ҃а ѯ҃в ѯ҃г ѯ҃д ѯ҃є ѯ҃ѕ ѯ҃з ѯ҃и ѯ҃ѳ сохраню̀ и҆̀ всѣ́мъ се́рдцемъ мои́мъ. Наста́ви мѧ̀ на стезю̀ за́повѣдїй твои́хъ, ꙗ҆́кѡ тꙋ́ю восхотѣ́хъ."}, {"num": "л҃ѕ.", "text": "Приклонѝ се́рдце моѐ во свидѣ̑нїѧ твоѧ̑, а҆ не въ лихои́мство."}, {"num": "л҃з.", "text": "Ѿвратѝ ѻ҆́чи моѝ є҆́же не ви́дѣти сꙋеты̀: въ пꙋтѝ твое́мъ живи́ мѧ."}, {"num": "л҃и.", "text": "Поста́ви рабꙋ̀ твоемꙋ̀ сло́во твоѐ въ стра́хъ тво́й."}, {"num": "л҃ѳ.", "text": "Ѿимѝ поноше́нїе моѐ, є҆́же непщева́хъ: ꙗ҆́кѡ сꙋдьбы̑ твоѧ̑ бл҃ги."}, {"num": "м҃.", "text": "Сѐ возжела́хъ за́пѡвѣди твоѧ̑: въ пра́вдѣ твое́й живи́ мѧ."}, {"num": "м҃а.", "text": "И҆ да прїи́детъ на мѧ̀ млⷭ҇ть твоѧ̀ гдⷭ҇и, сп҃се́нїе твоѐ по словесѝ твоемꙋ̀:"}, {"num": "м҃в.", "text": "И҆ ѿвѣща́ю поноша́ющымъ мѝ сло́во, ꙗ҆́кѡ ᲂу҆пова́хъ на словеса̀ твоѧ̑."}, {"num": "м҃г.", "text": "И҆ не ѿимѝ ѿ ᲂу҆́стъ мои́хъ словесѐ и҆́стинна до ѕѣла̀, ꙗ҆́кѡ на сꙋдьбы̑ твоѧ̑ ᲂу҆пова́хъ:"}, {"num": "м҃д.", "text": "И҆ сохраню̀ зако́нъ тво́й вы́нꙋ, въ вѣ́къ и҆ въ вѣ́къ вѣ́ка."}, {"num": "м҃є.", "text": "И҆ хожда́хъ въ широтѣ̀, ꙗ҆́кѡ за́пѡвѣди твоѧ̑ взыска́хъ:"}, {"num": "м҃ѕ.", "text": "И҆ глаго́лахъ ѡ҆ свидѣ́нїихъ твои́хъ пред̾ цари̑, и҆ не стыдѧ́хсѧ."}, {"num": "м҃з.", "text": "И҆ поꙋча́хсѧ въ за́повѣдехъ твои́хъ, ꙗ҆̀же возлюби́хъ ѕѣлѡ̀:"}, {"num": "м҃и.", "text": "И҆ воздвиго́хъ рꙋ́цѣ моѝ къ за́повѣдемъ твои̑мъ, ꙗ҆̀же возлюби́хъ, и҆ глꙋмлѧ́хсѧ во ѡ҆правда́нїихъ твои́хъ."}, {"num": "м҃ѳ.", "text": "Помѧнѝ словеса̀ твоѧ̑ рабꙋ̀ твоемꙋ̀, и҆́хже ᲂу҆пова́нїе да́лъ мѝ є҆сѝ."}, {"num": "н҃.", "text": "То́ мѧ ᲂу҆тѣ́ши во смире́нїи мое́мъ, ꙗ҆́кѡ сло́во твоѐ живи́ мѧ."}, {"num": "н҃а.", "text": "Го́рдїи законопрестꙋпова́хꙋ до ѕѣла̀: ѿ зако́на же твоегѡ̀ не ᲂу҆клони́хсѧ."}, {"num": "н҃в.", "text": "Помѧнꙋ́хъ сꙋдьбы̑ твоѧ̑ ѿ вѣ́ка гдⷭ҇и, и҆ ᲂу҆тѣ́шихсѧ."}, {"num": "н҃г.", "text": "Печа́ль прїѧ́тъ мѧ̀ ѿ грѣ̑шникъ ѡ҆ставлѧ́ющихъ зако́нъ тво́й. Пѣ̑та бѧ́хꙋ мнѣ̀"}, {"num": "н҃д.", "text": "ѡ҆правда̑нїѧ твоѧ̑, на мѣ́стѣ прише́льствїѧ моегѡ̀."}, {"num": "н҃є.", "text": "Помѧнꙋ́хъ въ нощѝ и҆́мѧ твоѐ гдⷭ҇и, и҆ сохрани́хъ зако́нъ тво́й. Се́й"}, {"num": "н҃ѕ.", "text": "бы́сть мнѣ̀, ꙗ҆́кѡ ѡ҆правда́нїй твои́хъ взыска́хъ."}, {"num": "н҃з.", "text": "Ча́сть моѧ̀ є҆сѝ гдⷭ҇и: рѣ́хъ сохрани́ти зако́нъ тво́й."}, {"num": "н҃и.", "text": "Помоли́хсѧ лицꙋ̀ твоемꙋ̀ всѣ́мъ се́рдцемъ мои́мъ: поми́лꙋй мѧ̀ по словесѝ твоемꙋ̀."}, {"num": "н҃ѳ.", "text": "Помы́слихъ пꙋти̑ твоѧ̑, и҆ возврати́хъ но́зѣ моѝ во свидѣ̑нїѧ твоѧ̑."}, {"num": "ѯ҃.", "text": "Оу҆гото́вихсѧ и҆ не смꙋти́хсѧ, сохрани́ти за́пѡвѣди твоѧ̑. Оу҆́жѧ грѣ̑шникъ ѡ҆бѧза́шасѧ мнѣ̀,"}, {"num": "ѯ҃а.", "text": "и҆ зако́на твоегѡ̀ не забы́хъ."}, {"num": "ѯ҃в.", "text": "Полꙋ́нощи воста́хъ и҆сповѣ́датисѧ тебѣ̀ ѡ҆ сꙋдьба́хъ пра́вды твоеѧ̀."}, {"num": "ѯ҃г.", "text": "Прича́стникъ а҆́зъ є҆́смь всѣ̑мъ боѧ́щымсѧ тебѐ и҆ хранѧ́щымъ"}, {"num": "ѯ҃д.", "text": "за́пѡвѣди твоѧ̑. Млⷭ҇ти твоеѧ̀ гдⷭ҇и и҆спо́лнь землѧ̀: ѡ҆правда́нїємъ твои̑мъ наꙋчи́ мѧ."}, {"num": "ѯ҃є.", "text": "Бл҃гость сотвори́лъ є҆сѝ съ рабо́мъ твои́мъ, гдⷭ҇и, по словесѝ твоемꙋ̀:"}, {"num": "ѯ҃ѕ.", "text": "Бл҃гости и҆ наказа́нїю и҆ ра́зꙋмꙋ наꙋчи́ мѧ, ꙗ҆́кѡ за́повѣдемъ твои̑мъ вѣ́ровахъ."}, {"num": "ѯ҃з.", "text": "Пре́жде да́же не смири́ти ми сѧ, а҆́зъ прегрѣши́хъ: сегѡ̀ ра́ди сло́во"}, {"num": "ѯ҃и.", "text": "твоѐ сохрани́хъ. Бл҃гъ є҆сѝ ты̀ гдⷭ҇и, и҆ бл҃гостїю твое́ю наꙋчи́ мѧ ѡ҆правда́нїємъ твои̑мъ."}, {"num": "ѯ҃ѳ.", "text": "Оу҆мно́жисѧ на мѧ̀ непра́вда го́рдыхъ, а҆́зъ же всѣ́мъ се́рдцемъ мои́мъ и҆спыта́ю за́пѡвѣди твоѧ̑."}, {"num": "ѻ҃.", "text": "Оу҆сыри́сѧ ꙗ҆́кѡ млеко̀ се́рдце и҆́хъ: ѻ҃ ѻ҃а ѻ҃в мои́мъ и҆спыта́ю за́пѡвѣди"}, {"num": "ѻ҃а.", "text": "твоѧ̑. Оу҆сыри́сѧ ꙗ҆́кѡ млеко̀ се́рдце и҆́хъ: а҆́зъ же зако́нꙋ твоемꙋ̀ поꙋчи́хсѧ. Бл҃го мнѣ̀, ꙗ҆́кѡ смири́лъ мѧ̀ є҆сѝ, ꙗ҆́кѡ да наꙋчꙋ́сѧ ѡ҆правда́нїємъ твои̑мъ."}, {"num": "ѻ҃в.", "text": "Бл҃гъ мнѣ̀ зако́нъ ᲂу҆́стъ твои́хъ па́че ты́сѧщъ зла́та и҆ сребра̀. Сла́ва: ѻ҃҃г ѻ҃҃д ѻ҃҃є ѻ҃҃ѕ ѻ҃҃з ѻ҃҃и ѻ҃҃ѳ п҃ п҃҃а п҃҃в п҃҃г п҃҃д п҃҃є п҃҃ѕ п҃҃з п҃҃и п҃҃ѳ ч҃ ч҃҃а ч҃҃в ч҃҃г"}, {"num": "ѻ҃г.", "text": "Рꙋ́це твоѝ сотвори́стѣ мѧ̀ и҆ созда́стѣ мѧ̀: вразꙋми́ мѧ, и҆ наꙋчꙋ́сѧ за́повѣдемъ твои̑мъ."}, {"num": "ѻ҃д.", "text": "Боѧ́щїисѧ тебє̀ ᲂу҆́зрѧтъ мѧ̀ и҆ возвеселѧ́тсѧ, ꙗ҆́кѡ на словеса̀ твоѧ̑ ᲂу҆пова́хъ."}, {"num": "ѻ҃є.", "text": "Разꙋмѣ́хъ гдⷭ҇и, ꙗ҆́кѡ пра́вда сꙋдьбы̑ твоѧ̑, и҆ вои́стиннꙋ смири́лъ мѧ̀ є҆сѝ."}, {"num": "ѻ҃ѕ.", "text": "Бꙋ́ди же млⷭ҇ть твоѧ̀, да ᲂу҆тѣ́шитъ мѧ̀, по словесѝ твоемꙋ̀ рабꙋ̀ твоемꙋ̀."}, {"num": "ѻ҃з.", "text": "Да прїи́дꙋтъ мнѣ̀ щедрѡ́ты твоѧ̑, и҆ жи́въ бꙋ́дꙋ, ꙗ҆́кѡ зако́нъ тво́й поꙋче́нїе моѐ є҆́сть."}, {"num": "ѻ҃и.", "text": "Да постыдѧ́тсѧ го́рдїи, ꙗ҆́кѡ непра́веднѡ беззако́нноваша на мѧ̀: а҆́зъ же поглꙋмлю́сѧ въ за́повѣдехъ твои́хъ."}, {"num": "ѻ҃ѳ.", "text": "Да ѡ҆братѧ́тъ мѧ̀ боѧ́щїисѧ тебѐ, и҆ вѣ́дѧщїи свидѣ̑нїѧ твоѧ̑."}, {"num": "п҃.", "text": "Бꙋ́ди се́рдце моѐ непоро́чно во ѡ҆правда́нїихъ твои́хъ, ꙗ҆́кѡ да не постыжꙋ́сѧ."}, {"num": "п҃а.", "text": "И҆зчеза́етъ во сп҃се́нїе твоѐ дꙋша̀ моѧ̀, на словеса̀ твоѧ̑ ᲂу҆пова́хъ. И҆зчезо́ша"}, {"num": "п҃в.", "text": "ѻ҆́чи моѝ въ сло́во твоѐ, глаго́люще: когда̀ ᲂу҆тѣ́шиши мѧ̀;"}, {"num": "п҃г.", "text": "Занѐ бы́хъ ꙗ҆́кѡ мѣ́хъ на сла́нѣ: ѡ҆правда́нїй твои́хъ не забы́хъ."}, {"num": "п҃д.", "text": "Коли́кѡ є҆́сть дні́й раба̀ твоегѡ̀; когда̀ сотвори́ши мѝ ѿ гонѧ́щихъ мѧ̀ сꙋ́дъ;"}, {"num": "п҃є.", "text": "Повѣ́даша мнѣ̀ законопрестꙋ̑пницы глꙋмлє́нїѧ, но не ꙗ҆́кѡ зако́нъ тво́й гдⷭ҇и."}, {"num": "п҃ѕ.", "text": "Всѧ̑ за́пѡвѣди твоѧ̑ и҆́стина: непра́веднѡ погна́ша мѧ̀, помози́ ми."}, {"num": "п҃з.", "text": "Вма́лѣ не сконча́ша менѐ на землѝ: а҆́зъ же не ѡ҆ста́вихъ за́повѣдей твои́хъ."}, {"num": "п҃и.", "text": "По млⷭ҇ти твое́й живи́ мѧ, и҆ сохраню̀ свидѣ̑нїѧ ᲂу҆́стъ твои́хъ."}, {"num": "п҃ѳ.", "text": "Во вѣ́къ гдⷭ҇и сло́во твоѐ пребыва́етъ на нб҃сѝ."}, {"num": "ч҃.", "text": "Въ ро́дъ и҆ ро́дъ и҆́стина твоѧ̀: ѡ҆снова́лъ є҆сѝ зе́млю, и҆ пребыва́етъ."}, {"num": "ч҃а.", "text": "Оу҆чине́нїемъ твои́мъ пребыва́етъ де́нь:"}, {"num": "ч҃в.", "text": "ꙗ҆́кѡ всѧ́чєскаѧ рабѡ́тна тебѣ̀. Ꙗ҆́кѡ а҆́ще бы не зако́нъ тво́й поꙋче́нїе моѐ бы́лъ, тогда̀ ᲂу҆́бѡ поги́блъ бы́хъ во смире́нїи мое́мъ:"}, {"num": "ч҃г.", "text": "Во вѣ́къ не забꙋ́дꙋ ѡ҆правда́нїй твои́хъ, ꙗ҆́кѡ въ ни́хъ ѡ҆живи́лъ мѧ̀ є҆сѝ. [Среда̀:] ч҃҃д ч҃҃є ч҃҃ѕ ч҃҃з ч҃҃и ч҃҃ѳ р҃ р҃а р҃в р҃г р҃д р҃є р҃ѕ р҃з р҃и р҃ѳ р҃і ра҃і рв҃і рг҃і рд҃і рє҃і рѕ҃і рз҃і ри҃і рѳ҃і р҃к рк҃а рк҃в рк҃г рк҃д рк҃є рк҃ѕ"}, {"num": "ч҃д.", "text": "Тво́й є҆́смь а҆́зъ, сп҃си́ мѧ: ꙗ҆́кѡ ѡ҆правда́нїй твои́хъ взыска́хъ."}, {"num": "ч҃є.", "text": "Менѐ жда́ша грѣ̑шницы погꙋби́ти мѧ̀: свидѣ̑нїѧ твоѧ̑ разꙋмѣ́хъ."}, {"num": "ч҃ѕ.", "text": "Всѧ́кїѧ кончи́ны ви́дѣхъ коне́цъ: широка̀ за́повѣдь твоѧ̀ ѕѣлѡ̀."}, {"num": "ч҃з.", "text": "Ко́ль возлюби́хъ зако́нъ тво́й гдⷭ҇и, ве́сь де́нь поꙋче́нїе моѐ є҆́сть."}, {"num": "ч҃и.", "text": "Па́че вра̑гъ мои́хъ ᲂу҆мꙋдри́лъ мѧ̀ є҆сѝ за́повѣдїю твое́ю, ꙗ҆́кѡ въ вѣ́къ моѧ̀ є҆́сть."}, {"num": "ч҃ѳ.", "text": "Па́че всѣ́хъ ᲂу҆ча́щихъ мѧ̀ разꙋмѣ́хъ, ꙗ҆́кѡ свидѣ̑нїѧ твоѧ̑ поꙋче́нїе моѐ є҆́сть."}, {"num": "р҃.", "text": "Па́че ста́рєцъ разꙋмѣ́хъ, ꙗ҆́кѡ за́пѡвѣди твоѧ̑ взыска́хъ."}, {"num": "р҃а.", "text": "Ѿ всѧ́кагѡ пꙋтѝ лꙋка́ва возбрани́хъ нога́мъ мои̑мъ, ꙗ҆́кѡ да сохраню̀ словеса̀ твоѧ̑:"}, {"num": "р҃в.", "text": "Ѿ сꙋде́бъ твои́хъ не ᲂу҆клони́хсѧ, ꙗ҆́кѡ ты̀ законоположи́лъ мѝ є҆сѝ."}, {"num": "р҃г.", "text": "Ко́ль сладка̑ горта́ни моемꙋ̀ словеса̀ твоѧ̑, па́че ме́да ᲂу҆стѡ́мъ мои̑мъ."}, {"num": "р҃д.", "text": "Ѿ за́повѣдей твои́хъ разꙋмѣ́хъ: сегѡ̀ ра́ди возненави́дѣхъ всѧ́къ пꙋ́ть непра́вды."}, {"num": "р҃є.", "text": "Свѣти́льникъ нога́ма мои́ма зако́нъ тво́й, и҆ свѣ́тъ стезѧ́мъ мои̑мъ."}, {"num": "р҃ѕ.", "text": "Клѧ́хсѧ и҆ поста́вихъ сохрани́ти сꙋдьбы̑ пра́вды твоеѧ̀."}, {"num": "р҃з.", "text": "Смири́хсѧ до ѕѣла̀: гдⷭ҇и, живи́ мѧ по словесѝ твоемꙋ̀."}, {"num": "р҃и.", "text": "Вѡ́льнаѧ ᲂу҆́стъ мои́хъ бл҃говоли́ же гдⷭ҇и, и҆ сꙋдьба́мъ твои̑мъ наꙋчи́ мѧ."}, {"num": "р҃ѳ.", "text": "Дꙋша̀ моѧ̀ въ рꙋкꙋ̀ твоє́ю вы́нꙋ, и҆ зако́на твоегѡ̀ не забы́хъ."}, {"num": "р҃і.", "text": "Положи́ша грѣ̑шницы сѣ́ть мнѣ̀: и҆ ѿ за́повѣдей твои́хъ не заблꙋди́хъ."}, {"num": "ра҃і.", "text": "Наслѣ́довахъ свидѣ̑нїѧ твоѧ̑ во вѣ́къ, ꙗ҆́кѡ ра́дованїе се́рдца моегѡ̀ сꙋ́ть:"}, {"num": "рв҃і.", "text": "Приклони́хъ се́рдце моѐ сотвори́ти ѡ҆правда̑нїѧ твоѧ̑ въ вѣ́къ за воздаѧ́нїе."}, {"num": "рг҃і.", "text": "Законопрестꙋ̑пныѧ возненави́дѣхъ, зако́нъ же тво́й возлюби́хъ."}, {"num": "рд҃і.", "text": "Помо́щникъ мо́й и҆ застꙋ́пникъ мо́й є҆сѝ ты̀: на словеса̀ твоѧ̑ ᲂу҆пова́хъ."}, {"num": "рє҃і.", "text": "Оу҆клони́тесѧ ѿ менѐ лꙋка́внꙋющїи, и҆ и҆спыта́ю за́пѡвѣди бг҃а моегѡ̀."}, {"num": "рѕ҃і.", "text": "Застꙋпи́ мѧ по словесѝ твоемꙋ̀, и҆ жи́въ бꙋ́дꙋ: и҆ не посрамѝ менѐ ѿ ча́ѧнїѧ моегѡ̀:"}, {"num": "рз҃і.", "text": "Помози́ ми, и҆ сп҃сꙋ́сѧ, и҆ поꙋчꙋ́сѧ во ѡ҆правда́нїихъ твои́хъ вы́нꙋ. Оу҆ничижи́лъ"}, {"num": "ри҃і.", "text": "є҆сѝ всѧ̑ ѿстꙋпа́ющыѧ ѿ ѡ҆правда́нїй твои́хъ: ꙗ҆́кѡ непра́ведно помышле́нїе и҆́хъ."}, {"num": "рѳ҃і.", "text": "Престꙋпа́ющыѧ непщева́хъ всѧ̑ грѣ̑шныѧ землѝ: сегѡ̀ ра́ди возлюби́хъ свидѣ̑нїѧ твоѧ̑."}, {"num": "р҃к.", "text": "Пригвоздѝ стра́хꙋ твоемꙋ̀ плѡ́ти моѧ̑: ѿ сꙋде́бъ бо твои́хъ ᲂу҆боѧ́хсѧ."}, {"num": "рк҃а.", "text": "Сотвори́хъ сꙋ́дъ и҆ пра́вдꙋ: не преда́ждь менѐ ѡ҆би́дѧщымъ мѧ̀."}, {"num": "рк҃в.", "text": "Воспрїимѝ раба̀ твоего̀ во бл҃го, да не ѡ҆клевета́ютъ менѐ го́рдїи, Ѻ҆́чи"}, {"num": "рк҃г.", "text": "моѝ и҆зчезо́стѣ во сп҃се́нїе твоѐ, и҆ въ сло́во пра́вды твоеѧ̀:"}, {"num": "рк҃д.", "text": "Сотворѝ съ рабо́мъ твои́мъ по млⷭ҇ти твое́й, и҆ ѡ҆правда́нїємъ твои̑мъ наꙋчи́ мѧ."}, {"num": "рк҃є.", "text": "Ра́бъ тво́й є҆́смь а҆́зъ: вразꙋми́ мѧ, и҆ ᲂу҆вѣ́мъ свидѣ̑нїѧ твоѧ̑."}, {"num": "рк҃ѕ.", "text": "Вре́мѧ сотвори́ти гдⷭ҇еви: разори́ша зако́нъ тво́й."}, {"num": "рк҃з.", "text": "Сегѡ̀ ра́ди возлюби́хъ за́пѡвѣди твоѧ̑ па́че зла́та и҆ топа́зїа. Сегѡ̀ рк҃з рк҃и рк҃ѳ р҃л рл҃а Сегѡ̀ ра́ди возлюби́хъ за́пѡвѣди твоѧ̑ па́че зла́та и҆ топа́зїа."}, {"num": "рк҃и.", "text": "Сегѡ̀ ра́ди ко всѣ̑мъ за́повѣдемъ твои̑мъ направлѧ́хсѧ, всѧ́къ пꙋ́ть непра́вды возненави́дѣхъ."}, {"num": "рк҃ѳ.", "text": "Ди̑вна свидѣ̑нїѧ твоѧ̑: сегѡ̀ ра́ди и҆спыта̀ ѧ҆̀ дꙋша̀ моѧ̀."}, {"num": "р҃л.", "text": "Ꙗ҆вле́нїе слове́съ твои́хъ просвѣща́етъ и҆ вразꙋмлѧ́етъ младе́нцы."}, {"num": "рл҃а.", "text": "Оу҆ста̀ моѧ̑ ѿверзо́хъ и҆ привлеко́хъ дꙋ́хъ, ꙗ҆́кѡ за́повѣдїй твои́хъ жела́хъ. Сла́ва: рл҃в рл҃г рл҃д рл҃є рл҃ѕ рл҃з рл҃и рл҃ѳ р҃м рм҃а рм҃в рм҃г рм҃д рм҃є рм҃ѕ рм҃з рм҃и рм҃ѳ р҃н рн҃а рн҃в рн҃г рн҃д рн҃є рн҃ѕ рн҃з"}, {"num": "рл҃в.", "text": "При́зри на мѧ̀ и҆ поми́лꙋй мѧ̀, по сꙋдꙋ̀ лю́бѧщихъ и҆́мѧ твоѐ."}, {"num": "рл҃г.", "text": "Стѡпы̀ моѧ̑ напра́ви по словесѝ твоемꙋ̀, и҆ да не ѡ҆блада́етъ мно́ю всѧ́кое беззако́нїе:"}, {"num": "рл҃д.", "text": "И҆зба́ви мѧ̀ ѿ клеветы̀ человѣ́ческїѧ, и҆ сохраню̀ за́пѡвѣди твоѧ̑."}, {"num": "рл҃є.", "text": "Лицѐ твоѐ просвѣтѝ на раба̀ твоего̀, и҆ наꙋчи́ мѧ ѡ҆правда́нїємъ твои̑мъ."}, {"num": "рл҃ѕ.", "text": "И҆схѡ́дища водна̑ѧ и҆зведо́стѣ ѻ҆́чи моѝ, поне́же не сохрани́хъ зако́на твоегѡ̀. Првⷣнъ є҆сѝ гдⷭ҇и, и҆"}, {"num": "рл҃з.", "text": "пра́ви сꙋдѝ твоѝ:"}, {"num": "рл҃и.", "text": "Заповѣ́далъ є҆сѝ пра́вдꙋ свидѣ̑нїѧ твоѧ̑, и҆"}, {"num": "рл҃ѳ.", "text": "и҆́стинꙋ ѕѣлѡ̀. И҆ста́ѧла мѧ̀ є҆́сть ре́вность твоѧ̀: ꙗ҆́кѡ забы́ша словеса̀ твоѧ̑ вразѝ моѝ."}, {"num": "р҃м.", "text": "Разжже́но сло́во твоѐ ѕѣлѡ̀, и҆ ра́бъ тво́й возлюбѝ є҆̀."}, {"num": "рм҃а.", "text": "Ю҆нѣ́йшїй а҆́зъ є҆́смь и҆ ᲂу҆ничиже́нъ: ѡ҆правда́нїй твои́хъ не забы́хъ."}, {"num": "рм҃в.", "text": "Пра́вда твоѧ̀ пра́вда во вѣ́къ, и҆ зако́нъ тво́й и҆́стина."}, {"num": "рм҃г.", "text": "Скѡ́рби и҆ нꙋ́жди ѡ҆брѣто́ша мѧ̀: за́пѡвѣди твоѧ̑ поꙋче́нїе моѐ."}, {"num": "рм҃д.", "text": "Пра́вда свидѣ̑нїѧ твоѧ̑ въ вѣ́къ: вразꙋми́ мѧ, и҆ жи́въ бꙋ́дꙋ."}, {"num": "рм҃є.", "text": "Воззва́хъ всѣ́мъ се́рдцемъ мои́мъ: ᲂу҆слы́ши мѧ̀ гдⷭ҇и: ѡ҆правда̑нїѧ твоѧ̑ взыщꙋ̀."}, {"num": "рм҃ѕ.", "text": "Воззва́хъ тѝ: сп҃си́ мѧ, и҆ сохраню̀ свидѣ̑нїѧ твоѧ̑."}, {"num": "рм҃з.", "text": "Предвари́хъ въ безго́дїи, и҆ воззва́хъ, на словеса̀ твоѧ̑ ᲂу҆пова́хъ."}, {"num": "рм҃и.", "text": "Предвари́стѣ ѻ҆́чи моѝ ко ᲂу҆́трꙋ, поꙋчи́тисѧ словесє́мъ твои̑мъ."}, {"num": "рм҃ѳ.", "text": "Гла́съ мо́й ᲂу҆слы́ши, гдⷭ҇и, по млⷭ҇ти твое́й, по сꙋдбѣ̀ твое́й живи́ мѧ."}, {"num": "р҃н.", "text": "Прибли́жишасѧ гонѧ́щїи мѧ̀ беззако́нїемъ: ѿ зако́на же твоегѡ̀ ᲂу҆дали́шасѧ."}, {"num": "рн҃а.", "text": "Бли́з̾ є҆сѝ ты̀, гдⷭ҇и, и҆ всѝ пꙋтїѐ твоѝ и҆́стина."}, {"num": "рн҃в.", "text": "И҆спе́рва позна́хъ ѿ свидѣ́нїй твои́хъ, ꙗ҆́кѡ въ вѣ́къ ѡ҆снова́лъ ѧ҆̀ є҆сѝ."}, {"num": "рн҃г.", "text": "Ви́ждь смире́нїе моѐ, и҆ и҆зми́ мѧ: ꙗ҆́кѡ зако́на твоегѡ̀ не забы́хъ."}, {"num": "рн҃д.", "text": "Сꙋдѝ сꙋ́дъ мо́й, и҆ и҆зба́ви мѧ̀: словесѐ ра́ди твоегѡ̀ живи́ мѧ."}, {"num": "рн҃є.", "text": "Дале́че ѿ грѣ̑шникъ сп҃се́нїе, ꙗ҆́кѡ ѡ҆правда́нїй твои́хъ не взыска́ша."}, {"num": "рн҃ѕ.", "text": "Щедрѡ́ты твоѧ̑ мнѡ́ги, гдⷭ҇и, по сꙋдьбѣ̀ твое́й живи́ мѧ."}, {"num": "рн҃з.", "text": "Мно́зи и҆згонѧ́щїи мѧ̀ и҆ стꙋжа́ющїи мѝ: ѿ свидѣ́нїй твои́хъ не ᲂу҆клони́хсѧ. Ви́дѣхъ"}, {"num": "рн҃и.", "text": "не разꙋмѣва́ющыѧ и҆ и҆ста́ѧхъ: ꙗ҆́кѡ слове́съ рн҃и рн҃ѳ р҃ѯ рѯ҃а рѯ҃в рѯ҃г рѯ҃д рѯ҃є рѯ҃ѕ рѯ҃з рѯ҃и рѯ҃ѳ р҃ѻ рѻ҃а рѻ҃в рѻ҃г рѻ҃д рѻ҃є рѻ҃ѕ ᲂу҆клони́хсѧ. Ви́дѣхъ не разꙋмѣва́ющыѧ и҆ и҆ста́ѧхъ: ꙗ҆́кѡ слове́съ твои́хъ не сохрани́ша."}, {"num": "рн҃ѳ.", "text": "Ви́ждь, ꙗ҆́кѡ за́пѡвѣди твоѧ̑ возлюби́хъ: гдⷭ҇и, по млⷭ҇ти твое́й живи́ мѧ."}, {"num": "р҃ѯ.", "text": "Нача́ло слове́съ твои́хъ и҆́стина, и҆ во вѣ́къ всѧ̑ сꙋдьбы̑ пра́вды твоеѧ̀."}, {"num": "рѯ҃а.", "text": "Кнѧ̑зи погна́ша мѧ̀ тꙋ́не: и҆ ѿ слове́съ твои́хъ ᲂу҆боѧ́сѧ се́рдце моѐ."}, {"num": "рѯ҃в.", "text": "Возра́дꙋюсѧ а҆́зъ ѡ҆ словесѣ́хъ твои́хъ, ꙗ҆́кѡ ѡ҆брѣта́ѧй коры́сть мно́гꙋ."}, {"num": "рѯ҃г.", "text": "Непра́вдꙋ возненави́дѣхъ и҆ ѡ҆мерзи́хъ, зако́нъ же тво́й возлюби́хъ."}, {"num": "рѯ҃д.", "text": "Седмери́цею дне́мъ хвали́хъ тѧ̀ ѡ҆ сꙋдьба́хъ пра́вды твоеѧ̀."}, {"num": "рѯ҃є.", "text": "Ми́ръ мно́гъ"}, {"num": "рѯ҃ѕ.", "text": "лю́бѧщымъ зако́нъ тво́й, и҆ нѣ́сть и҆̀мъ собла́зна. Ча́ѧхъ сп҃се́нїѧ твоегѡ̀, гдⷭ҇и, и҆ за́пѡвѣди твоѧ̑ возлюби́хъ."}, {"num": "рѯ҃з.", "text": "Сохранѝ дꙋша̀ моѧ̀ свидѣ̑нїѧ твоѧ̑, и҆ возлюбѝ ѧ҆̀ ѕѣлѡ̀."}, {"num": "рѯ҃и.", "text": "Сохрани́хъ за́пѡвѣди твоѧ̑ и҆ свидѣ̑нїѧ твоѧ̑, ꙗ҆́кѡ всѝ пꙋтїѐ моѝ пред̾ тобо́ю, гдⷭ҇и."}, {"num": "рѯ҃ѳ.", "text": "Да прибли́житсѧ моле́нїе моѐ пред̾ тѧ̀: гдⷭ҇и, по словесѝ твоемꙋ̀ вразꙋми́ мѧ."}, {"num": "р҃ѻ.", "text": "Да вни́детъ проше́нїе моѐ пред̾ тѧ̀: гдⷭ҇и, по словесѝ твоемꙋ̀ и҆зба́ви мѧ̀."}, {"num": "рѻ҃а.", "text": "Ѿры́гнꙋтъ ᲂу҆стнѣ̀ моѝ пѣ́нїе, є҆гда̀ наꙋчи́ши мѧ̀ ѡ҆правда́нїємъ твои̑мъ."}, {"num": "рѻ҃в.", "text": "Провѣща́етъ ѧ҆зы́къ мо́й словеса̀ твоѧ̑, ꙗ҆́кѡ всѧ̑ за́пѡвѣди твоѧ̑ пра́вда."}, {"num": "рѻ҃г.", "text": "Да бꙋ́детъ рꙋка̀ твоѧ̀ є҆́же сп҃сти́ мѧ, ꙗ҆́кѡ за́пѡвѣди твоѧ̑ и҆зво́лихъ."}, {"num": "рѻ҃д.", "text": "Возжела́хъ сп҃се́нїе твоѐ, гдⷭ҇и, и҆ зако́нъ тво́й поꙋче́нїе моѐ є҆́сть."}, {"num": "рѻ҃є.", "text": "Жива̀ бꙋ́детъ дꙋша̀ моѧ̀, и҆ восхва́литъ тѧ̀: и҆ сꙋдьбы̑ твоѧ̑ помо́гꙋтъ мнѣ̀."}, {"num": "рѻ҃ѕ.", "text": "Заблꙋди́хъ ꙗ҆́кѡ ѻ҆вча̀ поги́бшее: взыщѝ раба̀ твоего̀: ꙗ҆́кѡ за́повѣдей твои́хъ не забы́хъ. Сла́ва:"}]}, "119": {"number": 119, "cu_numeral": "рѳ҃і", "title": "Ѱало́мъ рѳ҃і (119)", "subtitle": "Пѣ́снь степе́ней, рѳ҃і.", "verses": [{"num": "а҃.", "text": "Ко гдⷭ҇ꙋ, внегда̀ скорбѣ́ти мѝ, воззва́хъ, и҆ ᲂу҆слы́ша мѧ̀."}, {"num": "в҃.", "text": "Гдⷭ҇и, и҆зба́ви дꙋ́шꙋ мою̀ ѿ ᲂу҆сте́нъ непра́ведныхъ, и҆ ѿ ѧ҆зы́ка льсти́ва."}, {"num": "г҃.", "text": "Что̀ да́стсѧ тебѣ̀, и҆лѝ что̀ приложи́тсѧ тебѣ̀ къ ѧ҆зы́кꙋ льсти́вꙋ;"}, {"num": "д҃.", "text": "Стрѣ́лы си́льнагѡ и҆з̾ѡщрє́ны, со ᲂу҆́гльми пꙋсты́нными."}, {"num": "є҃.", "text": "Оу҆вы̀ мнѣ̀, ꙗ҆́кѡ прише́льствїе моѐ продолжи́сѧ, всели́хсѧ съ селє́нїи кида́рскими:"}, {"num": "ѕ҃.", "text": "Мно́гѡ прише́льствова дꙋша̀ моѧ̀. съ ненави́дѧщими ми́ра бѣ́хъ ми́ренъ:"}, {"num": "з҃.", "text": "Е҆гда̀ глаго́лахъ и҆̀мъ, борѧ́хꙋ мѧ̀ тꙋ́не."}]}, "120": {"number": 120, "cu_numeral": "р҃к", "title": "Ѱало́мъ р҃к (120)", "subtitle": "Пѣ́снь степе́ней, р҃к.", "verses": [{"num": "а҃.", "text": "Возведо́хъ ѻ҆́чи моѝ въ го́ры, ѿню́дꙋже прїи́детъ по́мощь моѧ̀."}, {"num": "в҃.", "text": "По́мощь моѧ̀ ѿ гдⷭ҇а, сотво́ршагѡ нб҃о и҆ зе́млю."}, {"num": "г҃.", "text": "Не да́ждь во смѧте́нїе ногѝ твоеѧ̀, нижѐ воздре́млетъ хранѧ́й тѧ̀:"}, {"num": "д҃.", "text": "Сѐ не воздре́млетъ, нижѐ ᲂу҆́снетъ хранѧ́й і҆и҃лѧ."}, {"num": "є҃.", "text": "Гдⷭ҇ь сохрани́тъ тѧ̀, гдⷭ҇ь покро́въ тво́й на рꙋ́кꙋ деснꙋ́ю твою̀."}, {"num": "ѕ҃.", "text": "Во днѝ со́лнце не ѡ҆жже́тъ тебѐ, нижѐ лꙋна̀ но́щїю."}, {"num": "з҃.", "text": "Гдⷭ҇ь сохрани́тъ тѧ̀ ѿ всѧ́кагѡ ѕла̀, сохрани́тъ дꙋ́шꙋ твою̀ гдⷭ҇ь:"}, {"num": "и҃.", "text": "Гдⷭ҇ь сохрани́тъ вхожде́нїе твоѐ, и҆ и҆схожде́нїе твоѐ, ѿ ны́нѣ и҆ до вѣ́ка."}]}, "121": {"number": 121, "cu_numeral": "рк҃а", "title": "Ѱало́мъ рк҃а (121)", "subtitle": "Пѣ́снь степе́ней, рк҃а.", "verses": [{"num": "а҃.", "text": "Возвесели́хсѧ ѡ҆ ре́кшихъ мнѣ̀: въ до́мъ гдⷭ҇ень по́йдемъ."}, {"num": "в҃.", "text": "Стоѧ́ще бѧ́хꙋ но́ги на́шѧ во дво́рѣхъ твои́хъ, і҆ерⷭ҇ли́ме."}, {"num": "г҃.", "text": "І҆ерⷭ҇ли́мъ зи́ждемый ꙗ҆́кѡ гра́дъ, є҆мꙋ́же прича́стїе є҆гѡ̀ вкꙋ́пѣ."}, {"num": "д҃.", "text": "Та́мѡ бо взыдо́ша кѡлѣ́на, кѡлѣ́на гдⷭ҇нѧ, свидѣ́нїе і҆и҃лево, и҆сповѣ́датисѧ и҆́мени гдⷭ҇ню."}, {"num": "є҃.", "text": "Ꙗ҆́кѡ та́мѡ сѣдо́ша престо́ли на сꙋ́дъ, престо́ли въ домꙋ̀ дв҃довѣ."}, {"num": "ѕ҃.", "text": "Вопроси́те же ꙗ҆̀же ѡ҆ ми́рѣ і҆ерⷭ҇ли́ма: и҆ ѻ҆би́лїе лю́бѧщымъ тѧ̀."}, {"num": "з҃.", "text": "Бꙋ́ди же ми́ръ въ си́лѣ твое́й, и҆ ѻ҆би́лїе въ столпостѣна́хъ твои́хъ."}, {"num": "и҃.", "text": "Ра́ди бра́тїй мои́хъ и҆ бли́жнихъ мои́хъ глаго́лахъ ᲂу҆́бѡ ми́ръ ѡ҆ тебѣ̀."}, {"num": "ѳ҃.", "text": "До́мꙋ ра́ди гдⷭ҇а бг҃а на́шегѡ взыска́хъ бл҃га̑ѧ тебѣ̀."}]}, "122": {"number": 122, "cu_numeral": "рк҃в", "title": "Ѱало́мъ рк҃в (122)", "subtitle": "Пѣ́снь степе́ней, рк҃в.", "verses": [{"num": "а҃.", "text": "Къ тебѣ̀ возведо́хъ ѻ҆́чи моѝ, живꙋ́щемꙋ на нб҃сѝ."}, {"num": "в҃.", "text": "Сѐ ꙗ҆́кѡ ѻ҆́чи ра̑бъ въ рꙋкꙋ̀ госпо́дїй свои́хъ, ꙗ҆́кѡ ѻ҆́чи рабы́ни въ рꙋкꙋ̀ госпожѝ своеѧ̀: та́кѡ ѻ҆́чи на́ши ко гдⷭ҇ꙋ бг҃ꙋ на́шемꙋ, до́ндеже ᲂу҆ще́дритъ ны̀."}, {"num": "г҃.", "text": "Поми́лꙋй на́съ гдⷭ҇и, поми́лꙋй на́съ, ꙗ҆́кѡ помно́гꙋ и҆спо́лнихомсѧ ᲂу҆ничиже́нїѧ:"}, {"num": "д҃.", "text": "Наипа́че напо́лнисѧ дꙋша̀ на́ша поноше́нїѧ гобзꙋ́ющихъ и҆ ᲂу҆ничиже́нїѧ го́рдыхъ."}]}, "123": {"number": 123, "cu_numeral": "рк҃г", "title": "Ѱало́мъ рк҃г (123)", "subtitle": "Пѣ́снь степе́ней, рк҃г.", "verses": [{"num": "а҃.", "text": "Ꙗ҆́кѡ а҆́ще не гдⷭ҇ь бы бы́лъ въ на́съ, да рече́тъ ᲂу҆́бѡ і҆и҃ль:"}, {"num": "в҃.", "text": "Ꙗ҆́кѡ а҆́ще не гдⷭ҇ь бы бы́лъ въ на́съ, внегда̀ воста́ти человѣ́кѡмъ на ны̀, ᲂу҆̀бо живы́хъ поже́рли бы́ша на́съ:"}, {"num": "г҃.", "text": "Внегда̀ прогнѣ́ватисѧ ꙗ҆́рости и҆́хъ на ны̀, ᲂу҆̀бо вода̀ потопи́ла бы на́съ."}, {"num": "д҃.", "text": "Пото́къ пре́йде дꙋша̀ на́ша:"}, {"num": "є҃.", "text": "Оу҆́бо пре́йде дꙋша̀ на́ша во́дꙋ непостоѧ́ннꙋю."}, {"num": "ѕ҃.", "text": "Бл҃гослове́нъ гдⷭ҇ь, и҆́же не дадѐ на́съ въ лови́твꙋ зꙋбѡ́мъ и҆́хъ."}, {"num": "з҃.", "text": "Дꙋша̀ на́ша ꙗ҆́кѡ пти́ца и҆зба́висѧ ѿ сѣ́ти ловѧ́щихъ: сѣ́ть сокрꙋши́сѧ, и҆ мы̀ и҆зба́влени бы́хомъ."}, {"num": "и҃.", "text": "По́мощь на́ша во и҆́мѧ гдⷭ҇а, сотво́ршагѡ не́бо и҆ зе́млю. Сла́ва:"}]}, "124": {"number": 124, "cu_numeral": "рк҃д", "title": "Ѱало́мъ рк҃д (124)", "subtitle": "Пѣ́снь степе́ней, рк҃д.", "verses": [{"num": "а҃.", "text": "Надѣ́ющїисѧ на гдⷭ҇а ꙗ҆́кѡ"}, {"num": "в҃.", "text": "гора̀ сїѡ́нъ: не подви́житсѧ въ вѣ́къ живы́й во і҆ерⷭ҇ли́мѣ. Го́ры ѻ҆́крестъ є҆гѡ̀, и҆ гдⷭ҇ь ѻ҆́крестъ люде́й свои́хъ, ѿ ны́нѣ и҆ до вѣ́ка."}, {"num": "г҃.", "text": "Ꙗ҆́кѡ не ѡ҆ста́витъ гдⷭ҇ь жезла̀ грѣ́шныхъ на жре́бїй првⷣныхъ, ꙗ҆́кѡ да не"}, {"num": "д҃.", "text": "про́стрꙋтъ првⷣнїи въ беззакѡ́нїѧ рꙋ́къ свои́хъ. Оу҆бл҃жѝ гдⷭ҇и бл҃гі̑ѧ, и҆ пра̑выѧ се́рдцемъ."}, {"num": "є҃.", "text": "Оу҆клонѧ́ющыѧсѧ же въ развращє́нїѧ ѿведе́тъ гдⷭ҇ь съ дѣ́лающими беззако́нїе: ми́ръ на і҆и҃лѧ."}]}, "125": {"number": 125, "cu_numeral": "рк҃є", "title": "Ѱало́мъ рк҃є (125)", "subtitle": "Пѣ́снь степе́ней, рк҃є.", "verses": [{"num": "а҃.", "text": "Внегда̀ возврати́ти гдⷭ҇ꙋ плѣ́нъ сїѡ́нь, бы́хомъ ꙗ҆́кѡ ᲂу҆тѣ́шени."}, {"num": "в҃.", "text": "Тогда̀ и҆спо́лнишасѧ ра́дости ᲂу҆ста̀ на̑ша, и҆ ѧ҆зы́къ на́шъ весе́лїѧ, тогда̀ рекꙋ́тъво ꙗ҆зы́цѣхъ:возвели́чилъє҆́стьгдⷭ҇ьсотвори́тисъ ни́ми."}, {"num": "г҃.", "text": "Возвели́чилъ є҆́сть гдⷭ҇ь сотвори́ти съ на́ми: бы́хомъ веселѧ́щесѧ."}, {"num": "д҃.", "text": "Возвратѝ гдⷭ҇и плѣне́нїе на́ше, ꙗ҆́кѡ пото́ки ю҆́гомъ."}, {"num": "є҃.", "text": "Сѣ́ющїи слеза́ми ра́достїю по́жнꙋтъ."}, {"num": "ѕ҃.", "text": "Ходѧ́щїи хожда́хꙋ и҆ пла́кахꙋсѧ, мета́юще сѣ́мена своѧ̑: грѧдꙋ́ще же прїи́дꙋтъ ра́достїю, взе́млюще рꙋкоѧ̑ти своѧ̑."}]}, "126": {"number": 126, "cu_numeral": "рк҃ѕ", "title": "Ѱало́мъ рк҃ѕ (126)", "subtitle": "Пѣ́снь степе́ней, рк҃ѕ.", "verses": [{"num": "а҃.", "text": "А҆́ще не гдⷭ҇ь сози́ждетъ до́мъ, всꙋ́е трꙋди́шасѧ зи́ждꙋщїи: а҆́ще не гдⷭ҇ь сохрани́тъ гра́дъ, всꙋ́е бдѣ̀ стрегі́й."}, {"num": "в҃.", "text": "Всꙋ́е ва́мъ є҆́сть ᲂу҆́треневати: воста́нете по сѣдѣ́нїи ꙗ҆дꙋ́щїи хлѣ́бъ болѣ́зни, є҆гда̀ да́стъ возлю́блєннымъ свои̑мъ со́нъ."}, {"num": "г҃.", "text": "Сѐ достоѧ́нїе гдⷭ҇не сы́нове, мзда̀ плода̀ чре́внѧгѡ."}, {"num": "д҃.", "text": "Ꙗ҆́кѡ стрѣ́лы въ рꙋцѣ̀ си́льнагѡ, та́кѡ сы́нове ѿтрѧсе́нныхъ."}, {"num": "є҃.", "text": "Бл҃же́нъ, и҆́же и҆спо́лнитъ жела́нїе своѐ ѿ ни́хъ: не постыдѧ́тсѧ, є҆гда̀ глаго́лютъ врагѡ́мъ свои̑мъ во вратѣ́хъ."}]}, "127": {"number": 127, "cu_numeral": "рк҃з", "title": "Ѱало́мъ рк҃з (127)", "subtitle": "Пѣ́снь степе́ней, рк҃з.", "verses": [{"num": "а҃.", "text": "Бл҃же́ни всѝ боѧ́щїисѧ гдⷭ҇а, ходѧ́щїи въ пꙋте́хъ є҆гѡ̀:"}, {"num": "в҃.", "text": "Трꙋды̀ плодѡ́въ твои́хъ снѣ́си: бл҃же́нъ є҆сѝ, и҆ добро̀ тебѣ̀ бꙋ́детъ."}, {"num": "г҃.", "text": "Жена̀ твоѧ̀ ꙗ҆́кѡ лоза̀ плодови́та въ страна́хъ до́мꙋ твоегѡ̀:"}, {"num": "д҃.", "text": "Сы́нове твоѝ ꙗ҆́кѡ новосаждє́нїѧ ма̑сличнаѧ ѻ҆́крестъ трапе́зы твоеѧ̀."}, {"num": "є҃.", "text": "Сѐ та́кѡ бл҃гослови́тсѧ человѣ́къ боѧ́йсѧ гдⷭ҇а. Бл҃гослови́тъ тѧ̀ гдⷭ҇ь"}, {"num": "ѕ҃.", "text": "ѿ сїѡ́на,"}, {"num": "з҃.", "text": "и҆ ᲂу҆́зриши бл҃га̑ѧ і҆ерⷭ҇ли́ма всѧ̑ дни̑ живота̀ твоегѡ̀, И҆ ᲂу҆́зриши сы́ны сынѡ́въ твои́хъ: ми́ръ на і҆и҃лѧ."}]}, "128": {"number": 128, "cu_numeral": "рк҃и", "title": "Ѱало́мъ рк҃и (128)", "subtitle": "Пѣ́снь степе́ней, рк҃и.", "verses": [{"num": "а҃.", "text": "Мно́жицею бра́шасѧ со мно́ю ѿ ю҆́ности моеѧ̀, да рече́тъ ᲂу҆́бѡ і҆и҃ль:"}, {"num": "в҃.", "text": "Мно́жицею бра́шасѧ со мно́ю ѿ ю҆́ности моеѧ̀, и҆́бо не премого́ша мѧ̀."}, {"num": "г҃.", "text": "На хребтѣ̀ мое́мъ дѣ́лаша грѣ̑шницы, продолжи́ша беззако́нїе своѐ."}, {"num": "д҃.", "text": "Гдⷭ҇ь пра́веденъ ссѣчѐ вы̑ѧ грѣ́шникѡвъ."}, {"num": "є҃.", "text": "Да постыдѧ́тсѧ и҆ возвратѧ́тсѧ вспѧ́ть всѝ ненави́дѧщїи сїѡ́на:"}, {"num": "ѕ҃.", "text": "Да бꙋ́дꙋтъ ꙗ҆́кѡ трава̀ на здѣ́хъ, ꙗ҆́же пре́жде восторже́нїѧ и҆́зсше:"}, {"num": "з҃.", "text": "Е҆́юже не и҆спо́лни рꙋкѝ своеѧ̀ жнѧ́й, и҆ нѣ́дра своегѡ̀ рꙋкоѧ̑ти собира́ѧй:"}, {"num": "и҃.", "text": "И҆ не рѣ́ша мимоходѧ́щїи: бл҃гослове́нїе гдⷭ҇не на вы̀, бл҃гослови́хомъ вы̀ во и҆́мѧ гдⷭ҇не. Сла́ва:"}]}, "129": {"number": 129, "cu_numeral": "рк҃ѳ", "title": "Ѱало́мъ рк҃ѳ (129)", "subtitle": "Пѣ́снь степе́ней, рк҃ѳ.", "verses": [{"num": "а҃.", "text": "И҆з̾ глꙋбины̀ воззва́хъ къ тебѣ̀ гдⷭ҇и: гдⷭ҇и, ᲂу҆слы́ши гла́съ мо́й."}, {"num": "в҃.", "text": "Да бꙋ́дꙋтъ ᲂу҆́ши твоѝ вне́млющѣ гла́сꙋ моле́нїѧ моегѡ̀."}, {"num": "г҃.", "text": "А҆́ще беззакѡ́нїѧ на́зриши гдⷭ҇и, гдⷭ҇и, кто̀ постои́тъ; ꙗ҆́кѡ ᲂу҆ тебѐ ѡ҆чище́нїе є҆́сть."}, {"num": "д҃.", "text": "И҆́мене ра́ди твоегѡ̀ потерпѣ́хъ тѧ̀ гдⷭ҇и, потерпѣ̀ дꙋша̀ моѧ̀ въ сло́во твоѐ: ᲂу҆пова̀ дꙋша̀ моѧ̀ на гдⷭ҇а."}, {"num": "є҃.", "text": "Ѿ стра́жи ᲂу҆́треннїѧ до но́щи, ѿ стра́жи ᲂу҆́треннїѧ да ᲂу҆пова́етъ і҆и҃ль на гдⷭ҇а:"}, {"num": "ѕ҃.", "text": "Ꙗ҆́кѡ ᲂу҆ гдⷭ҇а млⷭ҇ть, и҆ мно́гое ᲂу҆ негѡ̀ и҆збавле́нїе: и҆ то́й и҆зба́витъ і҆и҃лѧ ѿ всѣ́хъ беззако́нїй є҆гѡ̀."}]}, "130": {"number": 130, "cu_numeral": "р҃л", "title": "Ѱало́мъ р҃л (130)", "subtitle": "Пѣ́снь степе́ней, р҃л.", "verses": [{"num": "а҃.", "text": "Гдⷭ҇и, не вознесе́сѧ се́рдце моѐ, нижѐ вознесо́стѣсѧ ѻ҆́чи моѝ: нижѐ ходи́хъ въ вели́кихъ, нижѐ въ ди́вныхъ па́че менѐ."}, {"num": "в҃.", "text": "А҆́ще не смиреномꙋ́дрствовахъ, но вознесо́хъ дꙋ́шꙋ мою̀, ꙗ҆́кѡ ѿдое́ное на ма́терь свою̀, та́кѡ возда́си на дꙋ́шꙋ мою̀."}, {"num": "г҃.", "text": "Да ᲂу҆пова́етъ і҆и҃ль на гдⷭ҇а, ѿ ны́нѣ и҆ до вѣ́ка."}]}, "131": {"number": 131, "cu_numeral": "рл҃а", "title": "Ѱало́мъ рл҃а (131)", "subtitle": "Пѣ́снь степе́ней, рл҃а.", "verses": [{"num": "а҃.", "text": "Помѧнѝ, гдⷭ҇и, дв҃да, и҆ всю̀ кро́тость є҆гѡ̀:"}, {"num": "в҃.", "text": "Ꙗ҆́кѡ клѧ́тсѧ гдⷭ҇еви, ѡ҆бѣща́сѧ бг҃ꙋ і҆а́кѡвлю:"}, {"num": "г҃.", "text": "А҆́ще вни́дꙋ въ селе́нїе до́мꙋ моегѡ̀, и҆лѝ взы́дꙋ на ѻ҆́дръ посте́ли моеѧ̀:"}, {"num": "д҃.", "text": "А҆́ще да́мъ со́нъ ѻ҆чи́ма мои́ма, и҆ вѣ́ждома мои́ма дрема́нїе, и҆ поко́й скранїа́ма мои́ма:"}, {"num": "є҃.", "text": "До́ндеже ѡ҆брѧ́щꙋ мѣ́сто гдⷭ҇еви, селе́нїе бг҃ꙋ і҆а́кѡвлю."}, {"num": "ѕ҃.", "text": "Сѐ слы́шахомъ ѧ҆̀ во є҆ѵфра́ѳѣ, ѡ҆брѣто́хомъ ѧ҆̀ въ полѧ́хъ дꙋбра́вы:"}, {"num": "з҃.", "text": "Вни́демъ въ селє́нїѧ є҆гѡ̀, поклони́мсѧ на мѣ́сто, и҆дѣ́же стоѧ́стѣ но́зѣ є҆гѡ̀."}, {"num": "и҃.", "text": "Воскрⷭ҇нѝ, гдⷭ҇и, въ поко́й тво́й, ты̀ и҆ кївѡ́тъ ст҃ы́ни твоеѧ̀."}, {"num": "ѳ҃.", "text": "Сщ҃е́нницы твоѝ ѡ҆блекꙋ́тсѧ пра́вдою, и҆ прпⷣбнїи твоѝ возра́дꙋютсѧ."}, {"num": "і҃.", "text": "Дв҃да ра́ди раба̀ твоегѡ̀, не ѿвратѝ лицѐ пома́заннагѡ твоегѡ̀. Клѧ́тсѧ гдⷭ҇ь дв҃дꙋ"}, {"num": "а҃і.", "text": "и҆́стиною, и҆ не ѿве́ржетсѧ є҆ѧ̀: ѿ плода̀ чре́ва твоегѡ̀ посаждꙋ̀ на престо́лѣ твое́мъ."}, {"num": "в҃і.", "text": "А҆́ще сохранѧ́тъ сы́нове твоѝ завѣ́тъ мо́й, и҆ свидѣ̑нїѧ моѧ̑ сїѧ̑, и҆̀мже наꙋчꙋ̀ ѧ҆̀, и҆ сы́нове и҆́хъ до вѣ́ка сѧ́дꙋтъ на престо́лѣ твое́мъ."}, {"num": "г҃і.", "text": "Ꙗ҆́кѡ и҆збра̀ гдⷭ҇ь сїѡ́на, и҆зво́ли и҆̀ въ жили́ще себѣ̀."}, {"num": "д҃і.", "text": "Се́й поко́й мо́й во вѣ́къ вѣ́ка, здѣ̀ вселю́сѧ, ꙗ҆́кѡ и҆зво́лихъ и ҆̀."}, {"num": "є҃і.", "text": "Лови́твꙋ є҆гѡ̀бл҃гословлѧ́ѧй бл҃гословлю̀, ни́щыѧ є҆гѡ̀насы́щꙋ хлѣ̑бы:"}, {"num": "ѕ҃і.", "text": "Сщ҃е́нники є҆гѡ̀ ѡ҆блекꙋ̀ во сп҃се́нїе, и҆ прпⷣбнїи є҆гѡ̀ ра́достїю возра́ ѕ҃і з҃і и҃і Сщ҃е́нники є҆гѡ̀ ѡ҆блекꙋ̀ во сп҃се́нїе, и҆ прпⷣбнїи є҆гѡ̀ ра́достїю возра́дꙋютсѧ."}, {"num": "з҃і.", "text": "Та́мѡ возращꙋ̀ ро́гъ дв҃дови, ᲂу҆гото́вахъ свѣти́лникъ пома́занномꙋ моемꙋ̀."}, {"num": "и҃і.", "text": "Врагѝ є҆гѡ̀ ѡ҆блекꙋ̀ стꙋдо́мъ, на не́мъ же процвѣте́тъ ст҃ы́нѧ моѧ̀."}]}, "132": {"number": 132, "cu_numeral": "рл҃в", "title": "Ѱало́мъ рл҃в (132)", "subtitle": "Пѣ́снь степе́ней, рл҃в.", "verses": [{"num": "а҃.", "text": "Сѐ что̀ добро̀, и҆лѝ что̀ красно̀, но є҆́же жи́ти бра́тїи вкꙋ́пѣ;"}, {"num": "в҃.", "text": "Ꙗ҆́кѡ мѵ́ро на главѣ̀, сходѧ́щее на брадꙋ̀, брадꙋ̀ а҆арѡ́ню, сходѧ́щее на ѡ҆ме́ты ѡ҆де́жды є҆гѡ̀:"}, {"num": "г҃.", "text": "Ꙗ҆́кѡ роса̀ а҆ермѡ́нскаѧ сходѧ́щаѧ на го́ры сїѡ̑нскїѧ: ꙗ҆́кѡ та́мѡ заповѣ́да гдⷭ҇ь бл҃гослове́нїе и҆ живо́тъ до вѣ́ка."}]}, "133": {"number": 133, "cu_numeral": "рл҃г", "title": "Ѱало́мъ рл҃г (133)", "subtitle": "Пѣ́снь степе́ней, рл҃г.", "verses": [{"num": "а҃.", "text": "Сѐ ны́нѣ бл҃гослови́те гдⷭ҇а, всѝ рабѝ гдⷭ҇ни, стоѧ́щїи въ хра́мѣ гдⷭ҇ни, во дво́рѣхъ до́мꙋ бг҃а на́шегѡ."}, {"num": "в҃.", "text": "Въ но́щехъ воздѣжи́те рꙋ́ки ва́шѧ во ст҃а̑ѧ, и҆ бл҃гослови́те гдⷭ҇а."}, {"num": "г҃.", "text": "Бл҃гослови́тъ тѧ̀ гдⷭ҇ь ѿ сїѡ́на, сотвори́вый не́бо и҆ зе́млю. Сла́ва:"}]}, "134": {"number": 134, "cu_numeral": "рл҃д", "title": "Ѱало́мъ рл҃д (134)", "subtitle": "А҆ллилꙋ́їа, рл҃д.", "verses": [{"num": "а҃.", "text": "Хвали́те и҆́мѧ гдⷭ҇не, хвали́те рабѝ гдⷭ҇а,"}, {"num": "в҃.", "text": "Стоѧ́щїи во хра́мѣ гдⷭ҇ни, во дво́рѣхъ до́мꙋ бг҃а на́шегѡ."}, {"num": "г҃.", "text": "Хвали́те гдⷭ҇а, ꙗ҆́кѡ бла́гъ гдⷭ҇ь: по́йте и҆́мени є҆гѡ̀, ꙗ҆́кѡ добро̀."}, {"num": "д҃.", "text": "Ꙗ҆́кѡ і҆а́кѡва и҆збра̀ себѣ̀ гдⷭ҇ь, і҆и҃лѧ въ достоѧ́нїе себѣ̀."}, {"num": "є҃.", "text": "Ꙗ҆́кѡ а҆́зъ позна́хъ, ꙗ҆́кѡ ве́лїй гдⷭ҇ь, и҆ гдⷭ҇ь на́шъ над̾ всѣ́ми бѡ́ги:"}, {"num": "ѕ҃.", "text": "Всѧ̑ є҆ли̑ка восхотѣ̀ гдⷭ҇ь, сотворѝ на нб҃сѝ и҆ на землѝ, въ морѧ́хъ и҆ во всѣ́хъ бе́зднахъ."}, {"num": "з҃.", "text": "Возводѧ̀ ѻ҆́блаки ѿ послѣ́днихъ землѝ, мѡ́лнїи въ до́ждь сотворѝ: и҆зводѧ́й вѣ́тры ѿ сокро́вищъ свои́хъ."}, {"num": "и҃.", "text": "И҆́же поразѝ пе́рвенцы є҆гѵ́пєтскїѧ, ѿ человѣ́ка до скота̀:"}, {"num": "ѳ҃.", "text": "Посла̀ зна́мєнїѧ и҆ чꙋдеса̀ посредѣ̀ тебѐ, є҆гѵ́пте, на фараѡ́на и҆ на всѧ̑ рабы̑ є҆гѡ̀."}, {"num": "і҃.", "text": "И҆́же поразѝ ꙗ҆зы́ки мнѡ́ги, и҆ и҆збѝ цари̑ крѣ̑пки:"}, {"num": "а҃і.", "text": "Сиѡ́на царѧ̀ а҆морре́йска, и҆ ѡ҆́га царѧ̀ васа́нска, и҆ всѧ̑ ца̑рствїѧ ханаа̑нска:"}, {"num": "в҃і.", "text": "И҆ дадѐ зе́млю и҆́хъ достоѧ́нїе, достоѧ́нїе і҆и҃лю лю́демъ свои̑мъ."}, {"num": "г҃і.", "text": "Гдⷭ҇и, и҆́мѧ твоѐ въ вѣ́къ, и҆ па́мѧть твоѧ̀ въ ро́дъ и҆ ро́дъ:"}, {"num": "д҃і.", "text": "Ꙗ҆́кѡ сꙋди́ти и҆́мать гдⷭ҇ь лю́демъ свои̑мъ, и҆ ѡ҆ рабѣ́хъ свои́хъ ᲂу҆мо́литсѧ."}, {"num": "є҃і.", "text": "І҆́дѡли ꙗ҆зы̑къ сребро̀ и҆ зла́то, дѣла̀ рꙋ́къ человѣ́ческихъ:"}, {"num": "ѕ҃і.", "text": "Оу҆ста̀ и҆́мꙋтъ и҆ не возглаго́лютъ:"}, {"num": "з҃і.", "text": "ѻ҆́чи и҆́мꙋтъ и҆ не ᲂу҆́зрѧтъ: Оу҆́ши и҆́мꙋтъ и҆ не ᲂу҆слы́шатъ: ниже́ бо є҆́сть дꙋ́хъ во ᲂу҆стѣ́хъ и҆́хъ."}, {"num": "и҃і.", "text": "Подо́бни и҆̀мъ да бꙋ́дꙋтъ творѧ́щїи ѧ҆̀, и҆ всѝ надѣ́ющїисѧ на нѧ̀."}, {"num": "ѳ҃і.", "text": "До́ме і҆и҃левъ, бл҃гослови́те гдⷭ҇а: до́ме а҆арѡ́нь, бл҃гослови́те гдⷭ҇а:"}, {"num": "к҃.", "text": "до́ме леѵі́инъ, бл҃гослови́те гдⷭ҇а: Боѧ́щїисѧ гдⷭ҇а, бл҃гослови́те гдⷭ҇а."}, {"num": "к҃а.", "text": "Бл҃гослове́нъ гдⷭ҇ь ѿ сїѡ́на, живы́й во і҆ерⷭ҇ли́мѣ. А҆ллилꙋ́їа, рл҃є."}]}, "135": {"number": 135, "cu_numeral": "рл҃є", "title": "Ѱало́мъ рл҃є (135)", "subtitle": "А҆ллилꙋ́їа, рл҃є.", "verses": [{"num": "а҃.", "text": "И҆сповѣ́дайтесѧ гдⷭ҇еви, ꙗ҆́кѡ бл҃гъ: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀."}, {"num": "в҃.", "text": "И҆сповѣ́дайтесѧ бг҃ꙋ богѡ́въ: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀."}, {"num": "г҃.", "text": "И҆сповѣ́дайтесѧ гдⷭ҇еви господе́й: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀."}, {"num": "д҃.", "text": "Сотво́ршемꙋ чꙋдеса̀ вє́лїѧ є҆ди́номꙋ: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀."}, {"num": "є҃.", "text": "Сотво́ршемꙋ нб҃са̀ ра́зꙋмомъ: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀."}, {"num": "ѕ҃.", "text": "Оу҆тверди́вшемꙋ зе́млю на вода́хъ: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀."}, {"num": "з҃.", "text": "Сотво́ршемꙋ свѣти̑ла вє́лїѧ є҆ди́номꙋ: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀:"}, {"num": "и҃.", "text": "Со́лнце во ѡ҆́бласть днѐ: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀:"}, {"num": "ѳ҃.", "text": "Лꙋнꙋ̀ и҆ ѕвѣ́зды во ѡ҆́бласть но́щи: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ:."}, {"num": "і҃.", "text": "Порази́вшемꙋ є҆гѵ́пта съ пе́рвєнцы є҆гѡ̀: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀:"}, {"num": "а҃і.", "text": "И҆ и҆зве́дшемꙋ і҆и҃лѧ ѿ среды̀ и҆́хъ: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀:"}, {"num": "в҃і.", "text": "Рꙋко́ю крѣ́пкою и҆ мы́шцею высо́кою: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀. г҃і д҃і є҃і ѕ҃і з҃і и҃і ѳ҃і к҃ к҃а к҃в к҃г к҃д к҃є к҃ѕ крѣ́пкою и҆ мы́шцею высо́кою: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀."}, {"num": "г҃і.", "text": "Раздѣ́льшемꙋ чермно́е мо́ре въ раздѣлє́нїѧ: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀."}, {"num": "д҃і.", "text": "И҆ прове́дшемꙋ і҆и҃лѧ посредѣ̀ є҆гѡ̀: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀:"}, {"num": "є҃і.", "text": "И҆ и҆стрѧ́сшемꙋ фараѡ́на, и҆ си́лꙋ є҆гѡ̀ въ мо́ре чермно́е: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀."}, {"num": "ѕ҃і.", "text": "Прове́дшемꙋ лю́ди своѧ̑ въ пꙋсты́ни: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀."}, {"num": "з҃і.", "text": "Порази́вшемꙋ цари̑ вє́лїѧ: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀."}, {"num": "и҃і.", "text": "И҆ ᲂу҆би́вшемꙋ цари̑ крѣ̑пкїѧ: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀:"}, {"num": "ѳ҃і.", "text": "Сиѡ́на царѧ̀ а҆морре́йска: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀."}, {"num": "к҃.", "text": "И҆ ѡ҆́га царѧ̀ васа́нска: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀."}, {"num": "к҃а.", "text": "И҆ да́вшемꙋ зе́млю и҆́хъ достоѧ́нїе: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀:"}, {"num": "к҃в.", "text": "Достоѧ́нїе і҆и҃лю рабꙋ̀ своемꙋ̀: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀."}, {"num": "к҃г.", "text": "Ꙗ҆́кѡ во смире́нїи на́шемъ помѧнꙋ́ ны гдⷭ҇ь: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀."}, {"num": "к҃д.", "text": "И҆ и҆зба́вилъ ны̀ є҆́сть ѿ врагѡ́въ на́шихъ: ꙗ҆́кѡ въ вѣ́къ"}, {"num": "к҃є.", "text": "млⷭ҇ть є҆гѡ̀. Даѧ́й пи́щꙋ всѧ́кой пло́ти: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀."}, {"num": "к҃ѕ.", "text": "И҆сповѣ́дайтесѧ бг҃ꙋ нбⷭ҇номꙋ: ꙗ҆́кѡ въ вѣ́къ млⷭ҇ть є҆гѡ̀. Дв҃дꙋ і҆еремі́емъ, рл҃ѕ."}]}, "136": {"number": 136, "cu_numeral": "рл҃ѕ", "title": "Ѱало́мъ рл҃ѕ (136)", "subtitle": "Дв҃дꙋ і҆еремі́емъ, рл҃ѕ.", "verses": [{"num": "а҃.", "text": "На рѣка́хъ вавѷлѡ́нскихъ, та́мѡ сѣдо́хомъ и҆ пла́кахомъ, внегда̀ помѧнꙋ́ти на́мъ сїѡ́на:"}, {"num": "в҃.", "text": "На ве́рбїихъ посредѣ̀ є҆гѡ̀ ѡ҆бѣ́сихомъ ѻ҆рга́ны на́шѧ."}, {"num": "г҃.", "text": "Ꙗ҆́кѡ та́мѡ вопроси́ша ны̀ плѣ́ншїи на́съ ѡ҆ словесѣ́хъ пѣ́сней, и҆ ве́дшїи на́съ ѡ҆ пѣ́нїи: воспо́йте на́мъ ѿ пѣ́сней сїѡ́нскихъ."}, {"num": "д҃.", "text": "Ка́кѡ воспое́мъ пѣ́снь гдⷭ҇ню на землѝ чꙋжде́й;"}, {"num": "є҃.", "text": "А҆́ще забꙋ́дꙋ тебѐ і҆ерⷭ҇ли́ме, забве́на бꙋ́ди десни́ца моѧ̀."}, {"num": "ѕ҃.", "text": "Прильпнѝ ѧ҆зы́къ мо́й горта́ни моемꙋ̀, а҆́ще не"}, {"num": "з҃.", "text": "помѧнꙋ̀ тебѐ, а҆́ще не предложꙋ̀ і҆ерⷭ҇ли́ма ꙗ҆́кѡ въ нача́лѣ весе́лїѧ моегѡ̀. Помѧнѝ гдⷭ҇и сы́ны є҆дѡ̑мскїѧ въ де́нь і҆ерⷭ҇ли́мль, глаго́лющыѧ: и҆стоща́йте, и҆стоща́йте до ѡ҆снова́нїй є҆гѡ̀."}, {"num": "и҃.", "text": "Дщѝ вавѷлѡ́нѧ ѡ҆каѧ́ннаѧ, бл҃же́нъ, и҆́же возда́стъ тебѣ̀ воздаѧ́нїе твоѐ, є҆́же воздала̀ є҆сѝ на́мъ:"}, {"num": "ѳ҃.", "text": "Бл҃же́нъ, и҆́же и҆́метъ и҆ разбїе́тъ младе́нцы твоѧ̑ ѡ҆ ка́мень. Сла́ва:"}]}, "137": {"number": 137, "cu_numeral": "рл҃з", "title": "Ѱало́мъ рл҃з (137)", "subtitle": "Ѱало́мъ дв҃дꙋ, а҆гге́а и҆ заха́рїи, рл҃з.", "verses": [{"num": "а҃.", "text": "И҆сповѣ́мсѧ тебѣ̀ гдⷭ҇и всѣ́мъ се́рдцемъ мои́мъ, и҆ пред̾ а҆́гг҃лы воспою̀ тебѣ̀, ꙗ҆́кѡ ᲂу҆слы́шалъ є҆сѝ всѧ̑ глаго́лы ᲂу҆́стъ мои́хъ:"}, {"num": "в҃.", "text": "Поклоню́сѧ ко хра́мꙋ ст҃о́мꙋ твоемꙋ̀, и҆ и҆сповѣ́мсѧ и҆́мени твоемꙋ̀ ѡ҆ млⷭ҇ти твое́й и҆ и҆́стинѣ твое́й: ꙗ҆́кѡ возвели́чилъ є҆сѝ над̾ всѣ́мъ и҆́мѧ твоѐ ст҃о́е. г҃ д҃ є҃ ѕ҃ з҃ и҃ и҆́стинѣ твое́й: ꙗ҆́кѡ возвели́чилъ є҆сѝ над̾ всѣ́мъ и҆́мѧ твоѐ ст҃о́е. Во́ньже а҆́ще де́нь призовꙋ́ тѧ, ско́рѡ ᲂу҆слы́ши мѧ̀: ᲂу҆мно́жиши мѧ̀"}, {"num": "г҃.", "text": "въ дꙋшѝ мое́й си́лою твое́ю."}, {"num": "д҃.", "text": "Да и҆сповѣ́дѧтсѧ тебѣ̀ гдⷭ҇и всѝ ца́рїе зе́мстїи, ꙗ҆́кѡ ᲂу҆слы́шаша всѧ̑ гл҃го́лы ᲂу҆́стъ твои́хъ: И҆"}, {"num": "є҃.", "text": "да воспою́тъ въ пꙋте́хъ гдⷭ҇нихъ,"}, {"num": "ѕ҃.", "text": "ꙗ҆́кѡ ве́лїѧ сла́ва гдⷭ҇нѧ: Ꙗ҆́кѡ высо́къ гдⷭ҇ь и҆ смирє́нныѧ призира́етъ, и҆ высѡ́каѧ и҆здале́ча вѣ́сть."}, {"num": "з҃.", "text": "А҆́ще пойдꙋ̀ посредѣ̀ ско́рби, живи́ши мѧ̀: на гнѣ́въ вра̑гъ мои́хъ просте́рлъ є҆сѝ рꙋ́кꙋ твою̀, и҆ сп҃се́ мѧ десни́ца твоѧ̀."}, {"num": "и҃.", "text": "Гдⷭ҇ь возда́стъ за мѧ̀: гдⷭ҇и млⷭ҇ть твоѧ̀ во вѣ́къ, дѣ́лъ рꙋкꙋ̀ твоє́ю не пре́зри."}]}, "138": {"number": 138, "cu_numeral": "рл҃и", "title": "Ѱало́мъ рл҃и (138)", "subtitle": "Въ коне́цъ дв҃дꙋ, ѱало́мъ заха́рїинъ, въ разсѣ́ѧнїи, рл҃и.", "verses": [{"num": "а҃.", "text": "Гдⷭ҇и, и҆скꙋси́лъ мѧ̀ є҆сѝ, и҆ позна́лъ мѧ̀ є҆сѝ: ты̀ позна́лъ є҆сѝ сѣда́нїе моѐ и҆ воста́нїе моѐ."}, {"num": "в҃.", "text": "Ты̀ разꙋмѣ́лъ є҆сѝ помышлє́нїѧ моѧ̑ и҆здале́ча:"}, {"num": "г҃.", "text": "Стезю̀ мою̀ и҆ ᲂу҆́же моѐ ты̀ є҆сѝ и҆зслѣ́довалъ, и҆ всѧ̑ пꙋти̑ моѧ̑ прови́дѣлъ є҆сѝ."}, {"num": "д҃.", "text": "Ꙗ҆́кѡ нѣ́сть льстѝ въ ѧ҆зы́цѣ мое́мъ: сѐ гдⷭ҇и ты̀ позна́лъ є҆сѝ"}, {"num": "є҃.", "text": "Всѧ̑ послѣ̑днѧѧ и҆ дрє́внѧѧ: ты̀ созда́лъ є҆сѝ мѧ̀, и҆ положи́лъ є҆сѝ на мнѣ̀ рꙋ́кꙋ твою̀."}, {"num": "ѕ҃.", "text": "Оу҆диви́сѧ ра́зꙋмъ тво́й ѿ менѐ, ᲂу҆тверди́сѧ, не возмогꙋ̀ къ немꙋ̀."}, {"num": "з҃.", "text": "Ка́мѡ пойдꙋ̀ ѿ дх҃а твоегѡ̀, и҆ ѿ лица̀ твоегѡ̀ ка́мѡ бѣжꙋ̀;"}, {"num": "и҃.", "text": "А҆́ще взы́дꙋ на нб҃о, ты̀ та́мѡ є҆сѝ: а҆́ще сни́дꙋ во а҆́дъ, та́мѡ є҆сѝ."}, {"num": "ѳ҃.", "text": "А҆́ще возмꙋ̀ крилѣ̑ моѝ ра́нѡ, и҆ вселю́сѧ въ послѣ́днихъ мо́рѧ:"}, {"num": "і҃.", "text": "И҆ та́мѡ бо рꙋка̀ твоѧ̀ наста́витъ мѧ̀, и҆ ᲂу҆держи́тъ мѧ̀ десни́ца твоѧ̀."}, {"num": "а҃і.", "text": "И҆ рѣ́хъ: є҆да̀ тьма̀ попере́тъ мѧ̀, и҆ но́щь просвѣще́нїе въ сла́дости мое́й."}, {"num": "в҃і.", "text": "Ꙗ҆́кѡ тьма̀ не помрачи́тсѧ ѿ тебѐ, и҆ но́щь ꙗ҆́кѡ де́нь просвѣти́тсѧ: ꙗ҆́кѡ тьма̀ є҆ѧ̀, та́кѡ и҆ свѣ́тъ є҆ѧ̀."}, {"num": "г҃і.", "text": "Ꙗ҆́кѡ ты̀ созда́лъ є҆сѝ ᲂу҆трѡ́бы моѧ̑, воспрїѧ́лъ мѧ̀ є҆сѝ и҆з̾ чре́ва ма́тере моеѧ̀."}, {"num": "д҃і.", "text": "И҆сповѣ́мсѧ тебѣ̀, ꙗ҆́кѡ стра́шнѡ ᲂу҆диви́лсѧ є҆сѝ: чꙋ̑дна дѣла̀ твоѧ̑, и҆ дꙋша̀ моѧ̀ зна́етъ ѕѣлѡ̀."}, {"num": "є҃і.", "text": "Не ᲂу҆таи́сѧ ко́сть моѧ̀ ѿ тебѐ, ю҆́же сотвори́лъ є҆сѝ въ та́йнѣ, и҆ соста́въ мо́й въ преиспо́днихъ землѝ."}, {"num": "ѕ҃і.", "text": "Несодѣ́ланное моѐ ви́дѣстѣ ѻ҆́чи твоѝ, и҆ въ кни́зѣ твое́й всѝ напи́шꙋтсѧ: во дне́хъ сози́ждꙋтсѧ, и҆ никто́же въ ни́хъ."}, {"num": "з҃і.", "text": "Мнѣ́ же ѕѣлѡ̀ че́стни бы́ша дрꙋ́зи твоѝ, бж҃е, ѕѣлѡ̀ ᲂу҆тверди́шасѧ влⷣчєствїѧ и҆́хъ."}, {"num": "и҃і.", "text": "И҆зочтꙋ̀ и҆̀хъ, и҆ па́че песка̀ ᲂу҆мно́жатсѧ: воста́хъ, и҆ є҆щѐ є҆́смь съ тобо́ю."}, {"num": "ѳ҃і.", "text": "А҆́ще и҆збїе́ши грѣ́шники бж҃е: мꙋ́жїе крове́й ᲂу҆клони́тесѧ ѿ менѐ."}, {"num": "к҃.", "text": "Ꙗ҆́кѡ ревни́ви є҆стѐ въ помышле́нїихъ, прїи́мꙋтъ въ сꙋетꙋ̀ гра́ды твоѧ̑."}, {"num": "к҃а.", "text": "Не ненави́дѧщыѧ ли тѧ̀ гдⷭ҇и возненави́дѣхъ, и҆ ѡ҆ вразѣ́хъ твои́хъ и҆ста́ѧхъ;"}, {"num": "к҃в.", "text": "Соверше́нною не́навистїю возненави́дѣхъ ѧ҆̀: во врагѝ бы́ша мѝ."}, {"num": "к҃г.", "text": "И҆скꙋси́ мѧ бж҃е, и҆ ᲂу҆вѣ́ждь се́рдце моѐ: к҃г к҃д ѧ҆̀: во врагѝ бы́ша мѝ. И҆скꙋси́ мѧ бж҃е, и҆ ᲂу҆вѣ́ждь се́рдце моѐ: и҆стѧжи́ мѧ, и҆ разꙋмѣ́й стєзѝ моѧ̑:"}, {"num": "к҃д.", "text": "И҆ ви́ждь, а҆́ще пꙋ́ть беззако́нїѧ во мнѣ̀, и҆ наста́ви мѧ̀ на пꙋ́ть вѣ́ченъ."}]}, "139": {"number": 139, "cu_numeral": "рл҃ѳ", "title": "Ѱало́мъ рл҃ѳ (139)", "subtitle": "Въ коне́цъ, ѱало́мъ дв҃дꙋ, рл҃ѳ.", "verses": [{"num": "а҃.", "text": "И҆зми́ мѧ, гдⷭ҇и, ѿ человѣ́ка лꙋка́ва, ѿ мꙋ́жа непра́ведна и҆зба́ви мѧ̀:"}, {"num": "в҃.", "text": "И҆̀же помы́слиша непра́вдꙋ въ се́рдцѣ, ве́сь де́нь ѡ҆полча́хꙋ бра̑ни:"}, {"num": "г҃.", "text": "И҆з̾ѡстри́ша ѧ҆зы́къ сво́й ꙗ҆́кѡ ѕмїи́нъ: ꙗ҆́дъ а҆́спїдовъ под̾ ᲂу҆стна́ми и҆́хъ."}, {"num": "д҃.", "text": "Сохрани́ мѧ гдⷭ҇и и҆з̾ рꙋкѝ грѣ́шничи, ѿ человѣ̑къ непра́ведныхъ и҆зми́ мѧ: и҆̀же помы́слиша запѧ́ти стѡпы̀ моѧ̑."}, {"num": "є҃.", "text": "Скры́ша го́рдїи сѣ́ть мнѣ̀, и҆ ᲂу҆́жы препѧ́ша сѣ́ть нога́ма мои́ма:"}, {"num": "ѕ҃.", "text": "При стезѝ собла́зны положи́ша мѝ. Рѣ́хъ гдⷭ҇еви: бг҃ъ мо́й є҆сѝ ты̀,"}, {"num": "з҃.", "text": "внꙋшѝ гдⷭ҇и гла́съ моле́нїѧ моегѡ̀."}, {"num": "и҃.", "text": "Гдⷭ҇и, гдⷭ҇и, си́ло сп҃се́нїѧ моегѡ̀, ѡ҆сѣни́лъ є҆сѝ над̾ главо́ю мое́ю въ де́нь бра́ни."}, {"num": "ѳ҃.", "text": "Не преда́ждь менѐ гдⷭ҇и ѿ жела́нїѧ моегѡ̀ грѣ́шникꙋ: помы́слиша на мѧ̀, не ѡ҆ста́ви менѐ, да не когда̀ вознесꙋ́тсѧ."}, {"num": "і҃.", "text": "Глава̀ ѡ҆крꙋже́нїѧ и҆́хъ, трꙋ́дъ ᲂу҆сте́нъ и҆́хъ покры́етъ ѧ҆̀."}, {"num": "а҃і.", "text": "Падꙋ́тъ на ни́хъ ᲂу҆́глїѧ ѻ҆́гнєннаѧ, низложи́ши ѧ҆̀ во страсте́хъ: и҆ не постоѧ́тъ."}, {"num": "в҃і.", "text": "Мꙋ́жъ ѧ҆зы́ченъ не и҆спра́витсѧ на землѝ: мꙋ́жа непра́ведна ѕла̑ѧ ᲂу҆ловѧ́тъ во и҆стлѣ́нїе."}, {"num": "г҃і.", "text": "Позна́хъ, ꙗ҆́кѡ сотвори́тъ гдⷭ҇ь сꙋ́дъ ни́щымъ, и҆ ме́сть ᲂу҆бѡ́гимъ."}, {"num": "д҃і.", "text": "Ѻ҆ба́че првⷣнїи и҆сповѣ́дѧтсѧ и҆́мени твоемꙋ̀, и҆ вселѧ́тсѧ пра́вїи съ лице́мъ твои́мъ. Сла́ва:"}]}, "140": {"number": 140, "cu_numeral": "р҃м", "title": "Ѱало́мъ р҃м (140)", "subtitle": "Ѱало́мъ дв҃дꙋ, р҃м.", "verses": [{"num": "а҃.", "text": "Гдⷭ҇и воззва́хъ къ тебѣ̀, ᲂу҆слы́ши мѧ̀: вонмѝ гла́сꙋ моле́нїѧ моегѡ̀, внегда̀ воззва́ти мѝ къ тебѣ̀."}, {"num": "в҃.", "text": "Да и҆спра́витсѧ мл҃тва моѧ̀ ꙗ҆́кѡ кади́ло пред̾ тобо́ю, воздѣѧ́нїе рꙋкꙋ̀ моє́ю, же́ртва вече́рнѧѧ."}, {"num": "г҃.", "text": "Положѝ гдⷭ҇и хране́нїе ᲂу҆стѡ́мъ мои̑мъ, и҆ две́рь ѡ҆гражде́нїѧ ѡ҆ ᲂу҆стна́хъ мои́хъ."}, {"num": "д҃.", "text": "Не ᲂу҆клонѝ се́рдце моѐ въ словеса̀ лꙋка́вствїѧ, непщева́ти вины̀ ѡ҆ грѣсѣ́хъ съ челѡвѣ̑ки дѣ́лающими беззако́нїе и҆ не сочтꙋ́сѧ со и҆збра́нными и҆́хъ."}, {"num": "є҃.", "text": "Нака́жетъ мѧ̀ првⷣникъ млⷭ҇тїю и҆ ѡ҆бличи́тъ мѧ̀, є҆ле́й же грѣ́шнагѡ да не нама́ститъ главы̀ моеѧ̀: ꙗ҆́кѡ є҆щѐ и҆ мл҃тва моѧ̀ во бл҃говоле́нїихъ и҆́хъ."}, {"num": "ѕ҃.", "text": "Пожє́рты бы́ша при ѕ҃ з҃ и҃ ѳ҃ і҃ є҆щѐ и҆ мл҃тва моѧ̀ во бл҃говоле́нїихъ и҆́хъ. Пожє́рты бы́ша при ка́мени сꙋдїи̑ и҆́хъ: ᲂу҆слы́шатсѧ глаго́ли моѝ, ꙗ҆́кѡ возмого́ша."}, {"num": "з҃.", "text": "Ꙗ҆́кѡ то́лща землѝ просѣ́десѧ на землѝ, расточи́шасѧ кѡ́сти и҆́хъ при а҆́дѣ."}, {"num": "и҃.", "text": "Ꙗ҆́кѡ къ тебѣ̀ гдⷭ҇и гдⷭ҇и ѻ҆́чи моѝ, на тѧ̀ ᲂу҆пова́хъ, не ѿимѝ дꙋ́шꙋ мою̀."}, {"num": "ѳ҃.", "text": "Сохрани́ мѧ ѿ сѣ́ти, ю҆́же соста́виша мѝ и҆ ѿ собла̑знъ дѣ́лающихъ беззако́нїе."}, {"num": "і҃.", "text": "Падꙋ́тъ во мре́жꙋ свою̀ грѣ̑шницы: є҆ди́нъ є҆́смъ а҆́зъ, до́ндеже прейдꙋ̀. а҃ Ра́зꙋма дв҃дꙋ, внегда̀ бы́ти є҆мꙋ̀ въ верте́пѣ молѧ́щемꙋсѧ, рм҃а."}]}, "141": {"number": 141, "cu_numeral": "рм҃а", "title": "Ѱало́мъ рм҃а (141)", "subtitle": "а҃ Ра́зꙋма дв҃дꙋ, внегда̀ бы́ти є҆мꙋ̀ въ верте́пѣ молѧ́щемꙋсѧ, рм҃а.", "verses": [{"num": "а҃.", "text": "Гла́сомъ мои́мъ ко гдⷭ҇ꙋ воззва́хъ, гла́сомъ мои́мъ ко гдⷭ҇ꙋ помоли́хсѧ."}, {"num": "в҃.", "text": "Пролїю̀ пред̾ ни́мъ моле́нїе моѐ, печа́ль мою̀ пред̾ ни́мъ возвѣщꙋ̀."}, {"num": "г҃.", "text": "Внегда̀ и҆зчеза́ти ѿ менє̀ дꙋ́хꙋ моемꙋ̀, и҆ ты̀ позна́лъ є҆сѝ стєзѝ моѧ̑: на пꙋтѝ се́мъ, по немꙋ́же хожда́хъ, скры́ша сѣ́ть мнѣ̀."}, {"num": "д҃.", "text": "Сматрѧ́хъ ѡ҆деснꙋ́ю и҆ возглѧ́дахъ, и҆ не бѣ̀ зна́ѧй менѐ: поги́бе бѣ́гство ѿ менѐ, и҆ нѣ́сть взыска́ѧй дꙋ́шꙋ мою̀:"}, {"num": "є҃.", "text": "Воззва́хъ къ тебѣ̀ гдⷭ҇и, рѣ́хъ: ты̀ є҆сѝ ᲂу҆пова́нїе моѐ, ча́сть моѧ̀ є҆сѝ на землѝ живы́хъ."}, {"num": "ѕ҃.", "text": "Вонмѝ моле́нїю моемꙋ̀, ꙗ҆́кѡ смири́хсѧ ѕѣлѡ̀: и҆зба́ви мѧ̀ ѿ гонѧ́щихъ мѧ̀, ꙗ҆́кѡ ᲂу҆крепи́шасѧ па́че менѐ."}, {"num": "з҃.", "text": "И҆зведѝ и҆з̾ темни́цы дꙋ́шꙋ мою̀ и҆сповѣ́датисѧ и҆́мени твоемꙋ̀: менѐ ждꙋ́тъ првⷣницы, до́ндеже возда́си мнѣ̀. Ѱ ало́мъ дв҃дꙋ, є҆гда̀ гонѧ́ше є҆го̀ а҆вессалѡ́мъ сы́нъ є҆гѡ̀, рм҃в."}]}, "142": {"number": 142, "cu_numeral": "рм҃в", "title": "Ѱало́мъ рм҃в (142)", "subtitle": "Ѱ ало́мъ дв҃дꙋ, є҆гда̀ гонѧ́ше є҆го̀ а҆вессалѡ́мъ сы́нъ є҆гѡ̀, рм҃в.", "verses": [{"num": "а҃.", "text": "Гдⷭ҇и, ᲂу҆слы́ши моли́твꙋ мою̀, внꙋшѝ моле́нїе моѐ во и҆́стинѣ твое́й, ᲂу҆слы́ши мѧ̀ въ пра́вдѣ твое́й:"}, {"num": "в҃.", "text": "И҆ не вни́ди въ сꙋ́дъ съ рабо́мъ твои́мъ, ꙗ҆́кѡ не ѡ҆правди́тсѧ пред̾ тобо́ю всѧ́къ живы́й."}, {"num": "г҃.", "text": "Ꙗ҆́кѡ погна̀ вра́гъ дꙋ́шꙋ мою̀: смири́лъ є҆́сть въ зе́млю живо́тъ мо́й: посади́лъ мѧ̀ є҆́сть въ те́мныхъ, ꙗ҆́кѡ мє́ртвыѧ вѣ́ка."}, {"num": "д҃.", "text": "И҆ ᲂу҆ны̀ во мнѣ̀ дꙋ́хъ мо́й, во мнѣ̀ смѧте́сѧ се́рдце моѐ."}, {"num": "є҃.", "text": "Помѧнꙋ́хъ дни̑ дрє́внїѧ, поꙋчи́хсѧ во всѣ́хъ дѣ́лѣхъ твои́хъ, въ творе́нїихъ рꙋкꙋ̀ твоє́ю поꙋча́хсѧ."}, {"num": "ѕ҃.", "text": "Воздѣ́хъ къ тебѣ̀ рꙋ́цѣ моѝ: дꙋша̀ моѧ̀ ꙗ҆́кѡ землѧ̀ безво́днаѧ тебѣ̀."}, {"num": "з҃.", "text": "Ско́рѡ ᲂу҆слы́ши мѧ̀ гдⷭ҇и, и҆зчезѐ дꙋ́хъ мо́й: не ѿвратѝ лица̀ твоегѡ̀ ѿ менѐ, и҆ ᲂу҆подо́блюсѧ низходѧ́щымъ въ ро́въ."}, {"num": "и҃.", "text": "Слы́шанꙋ сотворѝ мнѣ̀ заꙋ́тра млⷭ҇ть твою̀, ꙗ҆́кѡ на тѧ̀ ᲂу҆пова́хъ: скажѝ мнѣ̀ гдⷭ҇и пꙋ́ть, во́ньже пойдꙋ̀, ꙗ҆́кѡ къ тебѣ̀ взѧ́хъ дꙋ́шꙋ мою̀. И҆зми́ ѳ҃ і҃ а҃і в҃і гдⷭ҇и пꙋ́ть, во́ньже пойдꙋ̀, ꙗ҆́кѡ къ тебѣ̀ взѧ́хъ дꙋ́шꙋ мою̀."}, {"num": "ѳ҃.", "text": "И҆зми́ мѧ ѿ вра̑гъ мои́хъ гдⷭ҇и, къ тебѣ̀ прибѣго́хъ."}, {"num": "і҃.", "text": "Наꙋчи́ мѧ твори́ти во́лю твою̀, ꙗ҆́кѡ ты̀ є҆сѝ бг҃ъ мо́й: дх҃ъ тво́й бл҃гі́й наста́витъ мѧ̀ на зе́млю пра́вꙋ."}, {"num": "а҃і.", "text": "И҆́мене твоегѡ̀ ра́ди, гдⷭ҇и, живи́ши мѧ̀ пра́вдою твое́ю: и҆зведе́ши ѿ печа́ли дꙋ́шꙋ мою̀:"}, {"num": "в҃і.", "text": "И҆ млⷭ҇тїю твое́ю потреби́ши врагѝ моѧ̑, и҆ погꙋби́ши всѧ̑ стꙋжа́ющыѧ дꙋшѝ мое́й: ꙗ҆́кѡ а҆́зъ ра́бъ тво́й є҆́смь. Сла́ва:"}]}, "143": {"number": 143, "cu_numeral": "рм҃г", "title": "Ѱало́мъ рм҃г (143)", "subtitle": "Ѱало́мъ дв҃дꙋ, къ голїа́ѳꙋ, рм҃г.", "verses": [{"num": "а҃.", "text": "Бл҃гослове́нъ гдⷭ҇ь бг҃ъ мо́й, наꙋча́ѧй рꙋ́цѣ моѝ на ѡ҆полче́нїе, пе́рсты моѧ̑ на бра́нь."}, {"num": "в҃.", "text": "Млⷭ҇ть моѧ̀ и҆ прибѣ́жище моѐ, застꙋ́пникъ мо́й и҆ и҆зба́витель мо́й, защи́титель мо́й, и҆ на него̀ ᲂу҆пова́хъ: повинꙋ́ѧй лю́ди моѧ̑ под̾ мѧ̀."}, {"num": "г҃.", "text": "Гдⷭ҇и, что̀ є҆́сть человѣ́къ, ꙗ҆́кѡ позна́лсѧ є҆сѝ є҆мꙋ̀; и҆лѝ сы́нъ человѣ́чь, ꙗ҆́кѡ вмѣнѧ́еши є҆гѡ̀;"}, {"num": "д҃.", "text": "Человѣ́къ сꙋетѣ̀ ᲂу҆подо́бисѧ: дні́е є҆гѡ̀ ꙗ҆́кѡ сѣ́нь прехо́дѧтъ. Гдⷭ҇и, преклонѝ нб҃са̀, и҆"}, {"num": "є҃.", "text": "сни́ди: косни́сѧ гора́мъ, и҆ воздымѧ́тсѧ:"}, {"num": "ѕ҃.", "text": "Блеснѝ мо́лнїю, и҆ разжене́ши ѧ҆̀: послѝ стрѣ́лы твоѧ̑, и҆ смѧте́ши ѧ҆̀."}, {"num": "з҃.", "text": "Послѝ рꙋ́кꙋ твою̀ съ высоты̀, и҆зми́ мѧ и҆ и҆зба́ви мѧ̀ ѿ во́дъ мно́гихъ, и҆з̾ рꙋкѝ сынѡ́въ чꙋжди́хъ,"}, {"num": "и҃.", "text": "И҆́хже ᲂу҆ста̀ глаго́лаша сꙋетꙋ̀, и҆ десни́ца и҆́хъ десни́ца непра́вды."}, {"num": "ѳ҃.", "text": "Бж҃е, пѣ́снь но́вꙋ воспою̀ тебѣ̀, во ѱалти́ри десѧтострꙋ́ннѣмъ пою̀ тебѣ̀:"}, {"num": "і҃.", "text": "Даю́щемꙋ сп҃се́нїе царє́мъ, и҆збавлѧ́ющемꙋ дв҃да раба̀ своего̀ ѿ меча̀ лю́та."}, {"num": "а҃і.", "text": "И҆зба́ви мѧ̀ и҆ и҆зми́ мѧ и҆з̾ рꙋкѝ сынѡ́въ чꙋжди́хъ, и҆́хже ᲂу҆ста̀ глаго́лаша сꙋетꙋ̀, и҆ десни́ца и҆́хъ десни́ца непра́вды:"}, {"num": "в҃і.", "text": "И҆́хже сы́нове и҆́хъ ꙗ҆́кѡ новосаждє́нїѧ водрꙋжє́наѧ въ ю҆́ности свое́й, дщє́ри и҆́хъ ᲂу҆до́брєны, преꙋкра́шєны ꙗ҆́кѡ подо́бїе хра́ма:"}, {"num": "г҃і.", "text": "Храни̑лища и҆́хъ и҆спо́лнєна, ѿрыга̑ющаѧ ѿ сегѡ̀ въ сїѐ: ѻ҆́вцы и҆́хъ многоплѡ́дны, мно́жащыѧсѧ во и҆схо́дищихъ свои́хъ: воло́ве и҆́хъ то́лсти."}, {"num": "д҃і.", "text": "Нѣ́сть паде́нїѧ ѡ҆пло́тꙋ, нижѐ прохо́да, нижѐ во́плѧ въ сто́гнахъ и҆́хъ."}, {"num": "є҃і.", "text": "Оу҆бл҃жи́ша лю́ди, и҆̀мже сїѧ̑ сꙋ́ть: бл҃же́ни лю́дїе, и҆̀мже гдⷭ҇ь бг҃ъ и҆́хъ."}]}, "144": {"number": 144, "cu_numeral": "рм҃д", "title": "Ѱало́мъ рм҃д (144)", "subtitle": "Хвала̀ дв҃дꙋ, рм҃д.", "verses": [{"num": "а҃.", "text": "Вознесꙋ́ тѧ бж҃е мо́й цр҃ю̀ мо́й, и҆ бл҃гословлю̀ и҆́мѧ твоѐ въ вѣ́къ и҆ въ вѣ́къ вѣ́ка:"}, {"num": "в҃.", "text": "На всѧ́къ де́нь бл҃гословлю́ тѧ, и҆ восхвалю̀ и҆́мѧ твоѐ въ вѣ́къ и҆ въ вѣ́къ вѣ́ка."}, {"num": "г҃.", "text": "Ве́лїй гдⷭ҇ь и҆ хва́ленъ ѕѣлѡ̀, и҆ вели́чїю є҆гѡ̀ нѣ́сть конца̀."}, {"num": "д҃.", "text": "Ро́дъ и҆ ро́дъ восхва́лѧтъ дѣла̀ твоѧ̑, и҆ си́лꙋ твою̀ возвѣстѧ́тъ:"}, {"num": "є҃.", "text": "Великолѣ́пїе сла́вы ст҃ы́ни твоеѧ̀ возглаго́лютъ, и҆ чꙋдеса̀ твоѧ̑ повѣ́дѧтъ:"}, {"num": "ѕ҃.", "text": "И҆ си́лꙋ стра́шныхъ твои́хъ рекꙋ́тъ, и҆ вели́чїе твоѐ повѣ́дѧтъ:"}, {"num": "з҃.", "text": "Па́мѧть мно́жества бл҃гости твоеѧ̀"}, {"num": "и҃.", "text": "ѿры́гнꙋтъ, и҆ пра́вдою твое́ю возра́дꙋютсѧ. Ще́дръ и҆ млⷭ҇тивъ гдⷭ҇ь, долготерпѣли́въ и҆ многомлⷭ҇тивъ. Бл҃гъ"}, {"num": "ѳ҃.", "text": "гдⷭ҇ь всѧ́чєскимъ, и҆ щедрѡ́ты є҆гѡ̀ на всѣ́хъ дѣ́лѣхъ є҆гѡ̀."}, {"num": "і҃.", "text": "Да и҆сповѣ́дѧтсѧ тебѣ̀ гдⷭ҇и всѧ̑ дѣла̀ твоѧ̑, и҆ прпⷣбнїи твоѝ да бл҃гословѧ́тъ тѧ̀:"}, {"num": "а҃і.", "text": "Сла́вꙋ црⷭ҇твїѧ твоегѡ̀ рекꙋ́тъ, и҆ си́лꙋ а҃і в҃і г҃і д҃і є҃і ѕ҃і з҃і и҃і ѳ҃і к҃ к҃а твоѝ да бл҃гословѧ́тъ тѧ̀: Сла́вꙋ црⷭ҇твїѧ твоегѡ̀ рекꙋ́тъ, и҆ си́лꙋ твою̀ возглаго́лютъ:"}, {"num": "в҃і.", "text": "Сказа́ти сыновѡ́мъ человѣ́чєскимъ"}, {"num": "г҃і.", "text": "си́лꙋ твою̀, и҆ сла́вꙋ великолѣ́пїѧ црⷭ҇твїѧ твоегѡ̀. Црⷭ҇тво твоѐ црⷭ҇тво всѣ́хъ вѣкѡ́въ, и҆ влⷣчество"}, {"num": "д҃і.", "text": "твоѐ во всѧ́комъ ро́дѣ и҆ ро́дѣ. вѣ́ренъ гдⷭ҇ь во всѣ́хъ словесѣ́хъ свои́хъ, и҆ прпⷣбенъ во всѣ́хъ дѣ́лѣхъ свои́хъ. Оу҆твержда́етъ гдⷭ҇ь всѧ̑ низпа́дающыѧ, и҆ возставлѧ́етъ всѧ̑ низве́ржєнныѧ."}, {"num": "є҃і.", "text": "Ѻ҆́чи всѣ́хъ на тѧ̀ ᲂу҆пова́ютъ, и҆ ты̀ дае́ши и҆̀мъ пи́щꙋ во бл҃говре́менїи:"}, {"num": "ѕ҃і.", "text": "Ѿверза́еши ты̀ рꙋ́кꙋ твою̀, и҆ и҆сполнѧ́еши всѧ́кое живо́тно бл҃говоле́нїѧ."}, {"num": "з҃і.", "text": "Првⷣнъ гдⷭ҇ь во всѣ́хъ пꙋте́хъ свои́хъ, и҆ прпⷣбенъ во всѣ́хъ дѣ́лѣхъ свои́хъ."}, {"num": "и҃і.", "text": "Бли́з̾ гдⷭ҇ь всѣ̑мъ призыва́ющымъ є҆го̀, всѣ̑мъ призыва́ющымъ є҆го̀ во и҆́стинѣ."}, {"num": "ѳ҃і.", "text": "Во́лю боѧ́щихсѧ є҆гѡ̀ сотвори́тъ и҆ моли́твꙋ и҆́хъ ᲂу҆слы́шитъ, и҆ сп҃се́тъ ѧ҆̀."}, {"num": "к҃.", "text": "Храни́тъ гдⷭ҇ь всѧ̑ лю́бѧщыѧ є҆го̀, и҆ всѧ̑ грѣ́шники потреби́тъ."}, {"num": "к҃а.", "text": "Хвалꙋ̀ гдⷭ҇ню возглаго́лютъ ᲂу҆ста̀ моѧ̑: и҆ да бл҃гослови́тъ всѧ́ка пло́ть и҆́мѧ ст҃о́е є҆гѡ̀ въ вѣ́къ и҆ въ вѣ́къ вѣ́ка. Сла́ва: А҆ллилꙋ́їа, а҆гге́а и҆ заха́рїи, рм҃є."}]}, "145": {"number": 145, "cu_numeral": "рм҃є", "title": "Ѱало́мъ рм҃є (145)", "subtitle": "А҆ллилꙋ́їа, а҆гге́а и҆ заха́рїи, рм҃є.", "verses": [{"num": "а҃.", "text": "Хвалѝ дꙋшѐ моѧ̀ гдⷭ҇а:"}, {"num": "в҃.", "text": "Восхвалю̀ гдⷭ҇а въ животѣ̀ мое́мъ, пою̀ бг҃ꙋ моемꙋ̀, до́ндеже є҆́смь."}, {"num": "г҃.", "text": "Не надѣ́йтесѧ на кнѧ̑зи, на сы́ны человѣ́чєскїѧ, въ ни́хже нѣ́сть сп҃се́нїѧ."}, {"num": "д҃.", "text": "И҆зы́детъ дꙋ́хъ є҆гѡ̀, и҆ возврати́тсѧ въ зе́млю свою̀: въ то́й де́нь"}, {"num": "є҃.", "text": "поги́бнꙋтъ всѧ̑ помышлє́нїѧ є҆гѡ̀. Бл҃же́нъ, є҆мꙋ́же бг҃ъ і҆а́кѡвль помо́щникъ є҆гѡ̀, ᲂу҆пова́нїе є҆гѡ̀ на гдⷭ҇а бг҃а своего̀:"}, {"num": "ѕ҃.", "text": "Сотво́ршаго нб҃о и҆ зе́млю, мо́ре, и҆ всѧ̑, ꙗ҆̀же въ ни́хъ: хранѧ́щаго и҆́стинꙋ въ вѣ́къ:"}, {"num": "з҃.", "text": "Творѧ́щаго сꙋ́дъ ѡ҆би̑димымъ: даю́щаго пи́щꙋ а҆́лчꙋщымъ. гдⷭ҇ь рѣши́тъ ѡ҆кова̑нныѧ:"}, {"num": "и҃.", "text": "Гдⷭ҇ь ᲂу҆мꙋдрѧ́етъ слѣпцы̀: гдⷭ҇ь возво́дитъ низве́ржєнныѧ: гдⷭ҇ь лю́битъ првⷣники."}, {"num": "ѳ҃.", "text": "Гдⷭ҇ь храни́тъ прише́льцы, си́ра и҆ вдовꙋ̀ прїи́метъ, и҆ пꙋ́ть грѣ́шныхъ погꙋби́тъ."}, {"num": "і҃.", "text": "Воцр҃и́тсѧ гдⷭ҇ь во вѣ́къ, бг҃ъ тво́й сїѡ́не въ ро́дъ и҆ ро́дъ. А҆ллилꙋ́їа, рм҃ѕ."}]}, "146": {"number": 146, "cu_numeral": "рм҃ѕ", "title": "Ѱало́мъ рм҃ѕ (146)", "subtitle": "А҆ллилꙋ́їа, рм҃ѕ.", "verses": [{"num": "а҃.", "text": "Хвали́те гдⷭ҇а, ꙗ҆́кѡ бл҃гъ ѱало́мъ: бг҃ови на́шемꙋ да ᲂу҆слади́тсѧ хвале́нїе."}, {"num": "в҃.", "text": "Зи́ждай і҆ерⷭ҇ли́ма гдⷭ҇ь: разсѣ̑ѧнїѧ і҆и҃лєва собере́тъ."}, {"num": "г҃.", "text": "И҆зцѣлѧ́ѧй сокрꙋшє́нныѧ се́рдцемъ, и҆ ѡ҆бѧзꙋ́ѧй сокрꙋшє́нїѧ и҆́хъ."}, {"num": "д҃.", "text": "И҆зчита́ѧй мно́жество ѕвѣ́здъ, и҆ всѣ̑мъ и҆̀мъ и҆мена̀ нарица́ѧй."}, {"num": "є҃.", "text": "Ве́лїй гдⷭ҇ь на́шъ, и҆ є҃ ѕ҃ з҃ и҃ ѳ҃ і҃ а҃і жество ѕвѣ́здъ, и҆ всѣ̑мъ и҆̀мъ и҆мена̀ нарица́ѧй. Ве́лїй гдⷭ҇ь на́шъ, и҆ ве́лїѧ крѣ́пость є҆гѡ̀, и҆ ра́зꙋма є҆гѡ̀ нѣ́сть числа̀."}, {"num": "ѕ҃.", "text": "Прїе́млѧй крѡ́ткїѧ гдⷭ҇ь, смирѧ́ѧй же грѣ́шники до землѝ."}, {"num": "з҃.", "text": "Начни́те гдⷭ҇еви во и҆сповѣ́данїи, по́йте бг҃ови на́шемꙋ въ гꙋ́слехъ: Ѡ҆дѣва́ющемꙋ нб҃о"}, {"num": "и҃.", "text": "ѻ҆́блаки, ᲂу҆готовлѧ́ющемꙋ землѝ до́ждь: прозѧба́ющемꙋ на гора́хъ травꙋ̀, и҆ ѕла́къ на слꙋ́жбꙋ человѣ́кѡмъ:"}, {"num": "ѳ҃.", "text": "Даю́щемꙋ скотѡ́мъ пи́щꙋ и҆́хъ, и҆ птенцє́мъ вра́нѡвымъ призыва́ющымъ є҆го̀."}, {"num": "і҃.", "text": "Не въ си́лѣ ко́нстѣй"}, {"num": "а҃і.", "text": "восхо́щетъ, нижѐ въ лы́стѣхъ мꙋ́жескихъ бл҃говоли́тъ: Бл҃говоли́тъ гдⷭ҇ь въ боѧ́щихсѧ є҆гѡ̀ и҆ во ᲂу҆пова́ющихъ на млⷭ҇ть є҆гѡ̀. А҆ллилꙋ́їа, а҆гге́а и҆ заха́рїи, рм҃з."}]}, "147": {"number": 147, "cu_numeral": "рм҃з", "title": "Ѱало́мъ рм҃з (147)", "subtitle": "А҆ллилꙋ́їа, а҆гге́а и҆ заха́рїи, рм҃з.", "verses": [{"num": "а҃.", "text": "Похвалѝ і҆ерⷭ҇ли́ме гдⷭ҇а, хвалѝ бг҃а твоего̀ сїѡ́не:"}, {"num": "в҃.", "text": "Ꙗ҆́кѡ ᲂу҆крѣпѝ верєѝ вра́тъ твои́хъ, бл҃гословѝ сы́ны твоѧ̑ въ тебѣ̀."}, {"num": "г҃.", "text": "Полага́ѧй предѣ́лы твоѧ̑ ми́ръ, и҆ тꙋ́ка пшени́чна насыща́ѧй тѧ̀."}, {"num": "д҃.", "text": "Посыла́ѧй сло́во своѐ землѝ, до ско́рости тече́тъ сло́во є҆гѡ̀:"}, {"num": "є҃.", "text": "Даю́щагѡ снѣ́гъ сво́й ꙗ҆́кѡ во́лнꙋ, мглꙋ̀ ꙗ҆́кѡ пе́пелъ посыпа́ющагѡ:"}, {"num": "ѕ҃.", "text": "Мета́ющагѡ го́лоть сво́й ꙗ҆́кѡ хлѣ́бы: проти́вꙋ лица̀ мра́за є҆гѡ̀ кто̀ постои́тъ;"}, {"num": "з҃.", "text": "По́слетъ сло́во своѐ, и҆ и҆ста́етъ ѧ҆̀: дхне́тъ дꙋ́хъ є҆гѡ̀, и҆ потекꙋ́тъ во́ды."}, {"num": "и҃.", "text": "Возвѣща́ѧй сло́во своѐ і҆а́кѡвꙋ, ѡ҆правда̑нїѧ и҆ сꙋдьбы̑ своѧ̑ і҆и҃леви."}, {"num": "ѳ҃.", "text": "Не сотворѝ та́кѡ всѧ́комꙋ ꙗ҆зы́кꙋ, и҆ сꙋдьбы̑ своѧ̑ не ꙗ҆вѝ и҆̀мъ. Сла́ва: А҆ллилꙋ́їа, а҆гге́а и҆ заха́рїи, рм҃и."}]}, "148": {"number": 148, "cu_numeral": "рм҃и", "title": "Ѱало́мъ рм҃и (148)", "subtitle": "А҆ллилꙋ́їа, а҆гге́а и҆ заха́рїи, рм҃и.", "verses": [{"num": "а҃.", "text": "Хвали́те гдⷭ҇а съ нб҃съ, хвали́те є҆го̀ въ вы́шнихъ."}, {"num": "в҃.", "text": "Хвали́те є҆го̀ всѝ а҆́гг҃ли є҆гѡ̀, хвали́те є҆го̀ всѧ̑ си̑лы є҆гѡ̀."}, {"num": "г҃.", "text": "Хвали́те є҆го̀ со́лнце и҆ лꙋна̀,"}, {"num": "д҃.", "text": "хвали́те є҆го̀ всѧ̑ ѕвѣ́зды и҆ свѣ́тъ: Хвали́те є҆го̀ нб҃са̀ нб҃съ, и҆ вода̀, ꙗ҆́же превы́ше нб҃съ."}, {"num": "є҃.", "text": "Да восхва́лѧтъ и҆́мѧ гдⷭ҇не: ꙗ҆́кѡ то́й речѐ, и҆ бы́ша: то́й повелѣ̀, и҆ созда́шасѧ."}, {"num": "ѕ҃.", "text": "Поста́ви ѧ҆̀ въ вѣ́къ и҆ въ вѣ́къ вѣ́ка: повелѣ́нїе положѝ, и҆ не мимои́детъ."}, {"num": "з҃.", "text": "Хвали́те гдⷭ҇а ѿ землѝ, ѕмі́еве и҆ всѧ̑ бє́здны:"}, {"num": "и҃.", "text": "Ѻ҆́гнь, гра́дъ, снѣ́гъ, го́лоть, дꙋ́хъ бꙋ́ренъ, творѧ̑щаѧ сло́во є҆гѡ̀:"}, {"num": "ѳ҃.", "text": "Го́ры и҆ всѝ хо́лми, древа̀"}, {"num": "і҃.", "text": "плодонѡ́сна и҆ всѝ ке́дри: Ѕвѣ́рїе и҆ всѝ ско́ти, га́ди и҆ пти̑цы перна̑ты:"}, {"num": "а҃і.", "text": "Ца́рїе зе́мстїи и҆ всѝ лю́дїе,"}, {"num": "в҃і.", "text": "кнѧ̑зи и҆ всѝ сꙋдїи̑ зе́мстїи: Ю҆́нѡши и҆ дѣ̑вы, ста́рцы съ ю҆́нотами."}, {"num": "г҃і.", "text": "Да восхва́лѧтъ и҆́мѧ гдⷭ҇не: ꙗ҆́кѡ вознесе́сѧ и҆́мѧ тогѡ̀ є҆ди́нагѡ, и҆сповѣ́данїе є҆гѡ̀ на землѝ и҆ на нб҃сѝ."}, {"num": "д҃і.", "text": "И҆ вознесе́тъ ро́гъ д҃і є҆ди́нагѡ, и҆сповѣ́данїе є҆гѡ̀ на землѝ и҆ на нб҃сѝ. И҆ вознесе́тъ ро́гъ люде́й свои́хъ. пѣ́снь всѣ̑мъ прпⷣбнымъ є҆гѡ̀, сыновѡ́мъ і҆и҃лєвымъ, лю́демъ приближа́ющымсѧ є҆мꙋ̀. А҆ллилꙋ́їа, рм҃ѳ."}]}, "149": {"number": 149, "cu_numeral": "рм҃ѳ", "title": "Ѱало́мъ рм҃ѳ (149)", "subtitle": "А҆ллилꙋ́їа, рм҃ѳ.", "verses": [{"num": "а҃.", "text": "Воспо́йте гдⷭ҇еви пѣ́снь но́вꙋ: хвале́нїе є҆гѡ̀ въ цр҃кви прпⷣбныхъ."}, {"num": "в҃.", "text": "Да возвесели́тсѧ і҆и҃ль ѡ҆ сотво́ршемъ є҆го̀, и҆ сы́нове сїѡ́ни возра́дꙋютсѧ ѡ҆ цр҃ѣ̀ свое́мъ:"}, {"num": "г҃.", "text": "Да восхва́лѧтъ и҆́мѧ є҆гѡ̀ въ ли́цѣ, въ тѷмпа́нѣ и҆ ѱалти́ри да пою́тъ є҆мꙋ̀."}, {"num": "д҃.", "text": "Ꙗ҆́кѡ бл҃говоли́тъ гдⷭ҇ь въ лю́дехъ свои́хъ, и҆ вознесе́тъ крѡ́ткїѧ во сп҃се́нїе."}, {"num": "є҃.", "text": "Восхва́лѧтсѧ прпⷣбнїи во сла́вѣ, и҆ возра́дꙋютсѧ на ло́жахъ свои́хъ."}, {"num": "ѕ҃.", "text": "Возношє́нїѧ бж҃їѧ въ горта́ни и҆́хъ, и҆ мечѝ ѻ҆бою́дꙋ ѻ҆стры̀ въ рꙋка́хъ и҆́хъ:"}, {"num": "з҃.", "text": "Сотвори́ти ѿмще́нїе во ꙗ҆зы́цѣхъ, ѡ҆бличє́нїѧ въ лю́дехъ:"}, {"num": "и҃.", "text": "Свѧза́ти цари̑ и҆́хъ пꙋ̑ты, и҆ сла̑вныѧ и҆́хъ рꙋчны́ми ѡ҆ко́вы желѣ́зными:"}, {"num": "ѳ҃.", "text": "Сотвори́ти въ ни́хъ сꙋ́дъ напи́санъ. сла́ва сїѧ̀ бꙋ́детъ всѣ̑мъ прпⷣбнымъ є҆гѡ̀. А҆ллилꙋ́їа, р҃н."}]}, "150": {"number": 150, "cu_numeral": "р҃н", "title": "Ѱало́мъ р҃н (150)", "subtitle": "А҆ллилꙋ́їа, р҃н.", "verses": [{"num": "а҃.", "text": "Хвали́те бг҃а во ст҃ы́хъ є҆гѡ̀, хвали́те є҆го̀ во ᲂу҆тверже́нїи си́лы є҆гѡ̀:"}, {"num": "в҃.", "text": "Хвали́те є҆го̀ на си́лахъ є҆гѡ̀, хвали́те є҆го̀ по мно́жествꙋ вели́чествїѧ є҆гѡ̀."}, {"num": "г҃.", "text": "Хвали́те є҆го̀ во гла́сѣ трꙋ́бнѣмъ,"}, {"num": "д҃.", "text": "хвали́те є҆го̀ во ѱалти́ри и҆ гꙋ́слехъ:"}, {"num": "є҃.", "text": "Хвали́те є҆го̀ въ тѷмпа́нѣ и҆ ли́цѣ, хвали́те є҆го̀ во стрꙋ́нахъ и҆ ѻ҆рга́нѣ: Хвали́те є҆го̀ въ кѷмва́лѣхъ доброгла́сныхъ, хвали́те є҆го̀ въ кѷмва́лѣхъ восклица́нїѧ."}, {"num": "ѕ҃.", "text": "Всѧ́кое дыха́нїе да хва́литъ гдⷭ҇а. Сла́ва, и҆ ны́нѣ: а҆ллилꙋ́їа."}]}, "151": {"number": 151, "cu_numeral": "рн҃а", "title": "Ѱало́мъ рн҃а (151)", "subtitle": "Се́й ѱало́мъ ѡсо́бь пи́санъ, дв҃довъ, и҆ внѣ̀ числа̀ р҃н ѱалмѡ́въ", "verses": [{"num": "а҃.", "text": "Ма́лъ бѣ́хъ въ бра́тїи мое́й, и҆ ю҆́ншїй въ домꙋ̀ ѻ҆тца̀ моегѡ̀, пасо́хъ ѻ҆́вцы ѻ҆тца̀ моегѡ̀:"}, {"num": "в҃.", "text": "Рꙋ́цѣ моѝ сотвори́стѣ ѻ҆рга́нъ, и҆ пе́рсты моѝ соста́виша ѱалти́рь."}, {"num": "г҃.", "text": "И҆ кто̀ возвѣсти́тъ гдⷭ҇еви моемꙋ̀; Са́мъ гдⷭ҇ь, са́мъ ᲂу҆слꙑ́шитъ."}, {"num": "д҃.", "text": "Са́мъ посла̀ а҆́гг҃ла своего̀, и҆ взѧ́тъ мѧ̀ ѿ ѻ҆ве́цъ ѻ҆тца̀ моегѡ̀, и҆ пома́за мѧ̀ є҆ле́емъ пома́занїѧ своегѡ̀."}, {"num": "є҃.", "text": "Бра́тїѧ моѧ̑ добрѝ и҆ вели́цы: и҆ не бл҃говолѝ въ ни́хъ гдⷭ҇ь."}, {"num": "ѕ҃.", "text": "И҆зыдо́хъ въ срѣ́тенїе и҆ноплеме́нникꙋ, и҆ проклѧ́тъ мѧ̀ і҆́дѡлы свои́ми."}, {"num": "з҃.", "text": "А҆́зъ же и҆сто́ргнꙋвъ ме́чь ѿ негѡ̀, ѡ҆безгла́вихъ є҆го̀, и҆ ѿѧ́хъ поноше́нїе ѿ сынѡ́въ і҆и҃левыхъ. Сла́ва:"}]}};
